window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-preventiva-pre-4"]={"block":"medcurso:medcurso-preventiva-pre-4","label":"Medcurso · PRE 4","count":464,"questions":[{"id":"medcurso-preventiva-pre-4-343795","number":"343795","sourceNumber":"343795","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo a lei 8142/90, que dispõe sobre a participação da comunidade na gestão do\nSistema Único de Saúde, define como instâncias colegiadas as Conferências de Saúde e os\nConselhos de Saúde. Os Conselhos de Saúde devem ser compostos por representantes do\ngoverno, prestadores de serviço, profissionais de saúde e usuários. Sobre a composição dos\nConselhos de Saúde é correto afirmar que:","options":{"A":"Deve ter 50% de representação de gestores.","B":"O número de profissionais de saúde deve ser igual ao número de usuários.","C":"A representação dos usuários é paritária em relação ao conjunto dos demais segmentos.","D":"Os gestores, trabalhadores e usuários devem ter o mesmo número de representantes."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343796","number":"343796","sourceNumber":"343796","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Neuza, 71 anos, comparece frequentemente à unidade de saúde. Apesar de ter boa\nsaúde insiste em fazer exames a cada 3 meses,\ninclusive Eletrocardiograma. É poliqueixosa e diz\nque tem se sentido muito mal, com uma sensação de \"perturbação na cabeça\", palpitações,\ncefaleia principalmente no fim da tarde e insônia. Sobre o caso acima, assinale a opção correta.","options":{"A":"Hiperutilizadores do sistema de saúde são comuns na Atenção Primária e em muitos casos\nrepresentam uma condição marcadora de transtornos de ansiedade.","B":"Por ser paciente idosa e de risco, devem ser solicitados os exames que a paciente pede a cada\n3 meses.","C":"Trata-se de um caso de sintomas mal definidos, comuns na Atenção Primária, devendo ser\nsempre encaminhados à atenção especializada.","D":"A paciente deve ser internada para investigação diagnóstica e tratamento mais intensivo dos\nsintomas."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343798","number":"343798","sourceNumber":"343798","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei 10.216, promulgada em 6 de abril de 2001, também conhecida como lei da\nreforma psiquiátrica, dispõe sobre a proteção e\nos direitos das pessoas portadoras de transtornos\nmentais e redireciona o modelo assistencial em saúde mental. Sobre os direitos das pessoas\nportadoras de transtornos mentais, assinale a alternativa correta.","options":{"A":"A pessoa deve ser tratada, preferencialmente, em serviços comunitários de saúde mental.","B":"Em caso de internação a pessoa deve receber vestimenta adequada, padronizada pelo hospital.","C":"É direito das pessoas receber as medicações psiquiátricas no horário correto.","D":"A pessoa deve ter livre acesso às Comunidades Terapêuticas, enquanto dispositivo central da\nRede de Atenção Psicossocial."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343800","number":"343800","sourceNumber":"343800","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As estratégias de telessaúde e telemedicina estão cada vez mais incorporadas na\nprática clínica, tendo sido impulsionadas de\nmaneira importante pelo isolamento social\nproporcionado pela Pandemia de Covid-19. Já em 2007, o Ministério da Saúde já havia implantado\num programa de telessaúde para apoio à Atenção Primária denominado Telessaúde Brasil Redes.\nEsse programa operou a partir de quatro (04) estratégias. Assinale abaixo a alternativa que contêm\nessas quatro estratégias.","options":{"A":"Tele consulta, Teleatendimento, Tele orientação e Disque-consultas.","B":"Tele chamadas, Call-center, tele parecer e 0800.","C":"Tele consultoria, Telediagnóstico, Tele-educação e Segunda Opinião Formativa.","D":"Telemedicina, tele enfermagem, tele odontologia e tele fisioterapia."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343801","number":"343801","sourceNumber":"343801","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os Distritos Sanitários Especiais Indígenas (DSEI) representam a estrutura territorial de\nabrangência do sub-sistema de saúde indígena, não havendo correspondência exata com a divisão\npolítica dos Estados, seguindo a distribuição das terras indígenas que podem pertencer a mais de\num Estado. No Brasil existem 32 DSEI, sendo que dois atendem os povos indígenas que vivem no\nEstado do Acre: o DSEI Alto Purus, que atende os povos que habitam o vale do Rio Purus no Acre\ne sul do Amazonas, e o DSEI Alto Juruá que atende os povos do vale do Rio do Juruá. Sobre o\nsubsistema de saúde indígena, marque das opções abaixo aquela em que os dois dispositivos\ncitados estão na estrutura dos DSEI.","options":{"A":"Pólo-base (tipos I e II) e Casa de Saúde Indígena (Casai).","B":"Unidade Básica de Saúde Indígena (UBSI) e Hospital do Índio (HI).","C":"Maloca da saúde indígena (MSI) e Aldeia da Saúde Indígena (ASI).","D":"Centro de Atenção Psicossocial Indígena (CAPSI) e Centro de Referência em Assistência Social\nindígena (CRASI)."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343803","number":"343803","sourceNumber":"343803","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Na prática clínica na Atenção Primária se dá muita importância aos fatores de risco de\ndoença, mas pouca ênfase a fatores associados à resiliência, entendida como capacidade de\nsuperação de agentes estressores do cotidiano. Sabe-se que o fortalecimento da resiliência pode\nagir como aspecto preventivo à ocorrência de determinadas doenças. Existem fatores internos e\nexternos ligados à resiliência. Marque a opção abaixo que representa um fator interno e um\nexterno.","options":{"A":"Ser capaz de cultivar a paz, a justiça e manter laços de amizade; não sofrer violência praticada\npor alguém significativo, como pais, marido e\nesposa, filhos, irmãos e avós.","B":"Visar sua posição social através de empenho para ganhar posições de destaque no trabalho; ter\npatrimônio financeiro elevado que proporcione uma vida luxuosa e sem privações.","C":"Respeitar e obedecer às pessoas com posição hierárquica mais alta; estudar em uma escola\nque proporcione o desenvolvimento da disciplina e o obedecimento a autoridades.","D":"Enfrentar a vida com seriedade e retidão; não contar com uma rede de apoio social\n(organizações sociais, igreja, associações comunitárias etc.)"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343805","number":"343805","sourceNumber":"343805","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"José das Neves, de 60 anos, chega à Unidade Básica de Saúde e fala ao enfermeiro\nque deseja marcar uma nova consulta, pois já\npassaram 3 meses da anterior. O enfermeiro, que já\nsabe que José é portador de diabetes e já se trata na Unidade há 4 anos, desde que se mudou\npara o bairro, marca a consulta para o dia seguinte na parte da tarde. No dia seguinte na hora\nmarcada, seu José comparece e o médico o recebe com simpatia, perguntando como ele tinha\npassado os meses anteriores. Fala que manteria o tratamento, mas que estava na hora de realizar\nnovos exames de sangue para acompanhar seu quadro, que vinha sendo controlado já há 3 anos,\nquando iniciou nova medicação. O caso clínico acima retrata um dos atributos essenciais da\nAtenção Primária. Assinale abaixo qual dos atributos.","options":{"A":"Acesso/primeiro contato.","B":"Longitudinalidade.","C":"Integralidade.","D":"Coordenação do cuidado."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343807","number":"343807","sourceNumber":"343807","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Método Clínico Centrado na Pessoa é uma importante ferramenta na prática da\nMedicina de Família e Comunidade. Na sua sistematização, Stewart et al. (2017) propõe 4\ncomponentes, sendo o primeiro intitulado \"Explorando a saúde, a doenças e a experiência de\ndoença\". Sobre esse componente, assinale a alternativa abaixo que representa os aspectos que\ndevem ser observados na experiência de doença.","options":{"A":"Sinais e sintomas.","B":"Subjetivo, objetivo, avaliação e plano.","C":"Estresse, angústia, resiliência e vitalidade.","D":"Sentimentos, ideias, função e expectativas."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345520","number":"345520","sourceNumber":"345520","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo o Caderno de Atenção Básica nº 28: Acolhimento à demanda espontânea,\nsobre o Sistema Único de Saúde (SUS),\nanalisar os itens abaixo: I. O SUS tem como princípios e\ndiretrizes a universalidade, a iniquidade, a integralidade, a centralização e o controle social. II.\nVários tipos de demandas podem ser acolhidos e satisfeitos na atenção básica, inclusive com as\nmodalidades de tecnologias leve-duras e duras, que podem e devem estar disponíveis nesse tipo\nde serviço.","options":{"A":"Os itens I e II estão corretos.","B":"Somente o item I está correto.","C":"Somente o item II está correto.","D":"Os itens I e II estão incorretos."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345521","number":"345521","sourceNumber":"345521","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo o Sistema Único de Saúde SUS, a diretriz da descentralização:","options":{"A":"É coerente com a concepção de um Estado federativo obediente a princípios constitucionais que\ndevem ser assegurados e exercidos em cada\nesfera de governo, corresponde à distribuição de\npoder político, de responsabilidades e de recursos da esfera federal para a estadual e municipal.","B":"Diz respeito a uma organização do sistema que deve focar a noção de território, onde se\ndeterminam perfis populacionais, indicadores\nepidemiológicos, condições de vida e suporte social,\nque devem nortear as ações e serviços de saúde de uma região.","C":"É uma diretriz da forma de organização e operacionalização do SUS em todas as suas esferas\nde gestão.","D":"Aproxima a gestão municipal dos problemas de saúde, das condições de vida e da cultura que\nestão presentes nos distritos ou regiões que compõem o município, deve ser norteada pela\nhierarquização dos níveis de complexidade requerida pelas necessidades de saúde das pessoas."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345522","number":"345522","sourceNumber":"345522","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Humanização (PNH) existe desde 2003 para efetivar os\nprincípios do SUS no cotidiano das práticas de\natenção e gestão, qualificando a saúde pública no\nBrasil e incentivando trocas solidárias entre gestores, trabalhadores e usuários. Assinale a\nalternativa que corresponde a um princípio na Política Nacional de Humanização no SUS:","options":{"A":"Transversalidade.","B":"Acolhimento.","C":"Gestão Participativa.","D":"Ambiência."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345523","number":"345523","sourceNumber":"345523","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Humanização tem como uma das características:","options":{"A":"Respeitar as diferentes especialidades e práticas de saúde para que discussões\ninterdisciplinares não interfiram na conduta de\ncada médico que goza de autonomia para suas\ndecisões.","B":"Estimular trabalhadores e usuários a buscarem o conhecimento da gestão dos serviços e da\nrede de saúde, sem, no entanto, interferir\nno processo de tomada de decisão nas organizações de\nsaúde e nas ações de saúde coletiva.","C":"Estimular redes de contato, incluindo usuários e suas relações sociofamiliares nos processos de\ncuidado, restringindo as conversas em torno somente de questões estritas de aspectos clínicos das\ndoenças.","D":"Buscar transformar as relações de trabalho a partir da ampliação do grau de contato e da\ncomunicação entre as pessoas e grupos, tirando-os do isolamento e das relações de poder\nhierarquizadas."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345524","number":"345524","sourceNumber":"345524","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre os serviços de saúde, no âmbito do SUS, assinale a alternativa INCORRETA:","options":{"A":"Serviços de atenção psicossocial são uma das portas de entrada do sistema de saúde.","B":"Os serviços de atenção hospitalar e os ambulatoriais especializados, entre outros de maior\ncomplexidade e densidade tecnológica, serão referenciados pelas secretarias municipais de saúde.","C":"Ao usuário será assegurada a continuidade do cuidado em saúde, em todas as suas\nmodalidades, nos serviços, hospitais e em outras unidades integrantes da rede de atenção da\nrespectiva região.","D":"O acesso universal e igualitário às ações e aos serviços de saúde será ordenado pela atenção\nprimária."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345526","number":"345526","sourceNumber":"345526","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As Práticas Integrativas e Complementares (PICS) são tratamentos que utilizam\nrecursos terapêuticos baseados em conhecimentos\ntradicionais, voltados para prevenir diversas\ndoenças ou como tratamento paliativo. Atualmente, o Sistema Único de Saúde (SUS) oferece, de\nforma integral e gratuita, diversos procedimentos de Práticas Integrativas e Complementares (PICS)\nà população. Os atendimentos começam na Atenção Básica, principal porta de entrada para o\nSUS. Evidências científicas têm mostrado os benefícios do tratamento integrado entre medicina\nconvencional e práticas integrativas e complementares. Além disso, há crescente número de\nprofissionais capacitados e habilitados e maior valorização dos conhecimentos tradicionais de onde\nse originam grande parte dessas práticas. Em relação a tais práticas, podemos afirmar:","options":{"A":"Contempla sistemas não médicos complexos e recursos terapêuticos, os quais são também\ndenominados pela Organização Mundial da Saúde (OMS) de medicina tradicional e\ncomplementar/alternativa.","B":"Envolvem abordagens que estimulam mecanismos naturais de prevenção de agravos e\nrecuperação da saúde por meios eficazes e\nseguros, com ênfase na escuta acolhedora e no\ndesenvolvimento do vículo terapêutico, contudo não visa a integração do ser humano com o meio\nambiente e a sociedade.","C":"Outros pontos compartilhados pelas diversas abordagens abrangidas nesse campo são a visão\nampliada do processo saúde-doença e a promoção global do cuidado humano, especialmente do\nauto cuidado.","D":"No Brasil, a legitimação e a institucionalização dessas abordagens de atenção à saúde se\niniciaram a partir do ano 2000, com a ascensão do populismo e o fortalecimento da Estratégia de\nSaúde da Família."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345527","number":"345527","sourceNumber":"345527","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Sistema Único de Saúde (SUS) é um dos maiores e mais complexos sistemas de\nsaúde pública do mundo, abrangendo desde o\nsimples atendimento para avaliação da pressão\narterial, por meio da Atenção Primária, até o transplante de órgãos, garantindo acesso integral,\nuniversal e gratuito para toda a população do país. (Fonte:\n\nhttp://www.saude.gov.br/sistema-único-de-saude). Em relação aos Subsistemas que Integram o\nSUS, marque a alternativa INCORRETA:","options":{"A":"A União deverá integrar os sistemas de informação da rede do SUS com os dados do\nSubsistema de Atenção à Saúde Indígena.","B":"Caberá exclusivamente aos municípios, com seus recursos próprios, financiar o Subsistema de\nAtenção à Saúde Indígena.","C":"O SUS servirá de retaguarda e referência ao Subsistema de Atenção à Saúde Indígena,\ndevendo, para isso, ocorrer adaptações na\nestrutura e organização do SUS nas regiões onde\nresidem as populações indígenas, para propiciar essa integração e o atendimento necessário em\ntodos os níveis, sem discriminações.","D":"O Subsistema de Atenção à Saúde Indígena deverá ser, como o SUS, descentralizado,\nhierarquizado e regionalizado."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345528","number":"345528","sourceNumber":"345528","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A competência constitucional do SUS para ordenar a formação de recursos humanos\nna área de Saúde (Art. 200) está\nregulamentada na Lei 8.080/1990, que estabelece a criação de\ncomissões permanentes de integração entre os serviços de saúde e as instituições de ensino\nprofissional e superior com a finalidade de:","options":{"A":"Estabelecer normais técnicas e programáticas para os modelos curriculares para o ensino\nprofissional no SUS.","B":"Estabelecer normais técnicas e programáticas para os modelos curriculares de educação\npermanente no SUS.","C":"Propor prioridades e modelos curriculares visando às ações interdisciplinares para a educação\ncontinuada, assim como aos Planos de Cargos, Carreiras e Salários do SUS.","D":"Propor prioridades, métodos e estratégias para a formação e educação continuada dos recursos\nhumanos no âmbito do SUS e em cada\ninstância governamental, assim como em relação à\npesquisa e à cooperação técnica entre as instituições."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345529","number":"345529","sourceNumber":"345529","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A unidade do Ministério da Saúde competente para realizar atividade de auditoria a fim\nde verificar a adequação das ações e serviços públicos de saúde e a sua regularidade quanto aos\naspectos técnico-científicos, contábeis, financeiros e patrimoniais da aplicação dos recursos do\nSUS é:","options":{"A":"O Denasus - Departamento Nacional de Auditoria do SUS.","B":"O CNS - Conselho Nacional de Saúde.","C":"O SNA - Sistema Nacional de Auditoria.","D":"A ANS - Agência Nacional de Saúde."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345530","number":"345530","sourceNumber":"345530","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em 2023 completam-se 33 anos desde a promulgação da Lei Orgânica da Saúde\n(LOS) no Brasil e 35 anos desde a aprovação\nda Constituição Federal, que estabeleceu a saúde\ncomo direito de todo cidadão e um dever do Estado. Sobre o Sistema Único de Saúde (SUS), é\nCORRETO afirmar que:","options":{"A":"O controle social, previsto na lei, foi uma das principais inovações do SUS, estabelecendo que\ncada esfera de governo deve contar com\nconferências e conselhos de saúde.","B":"Ao não incorporar a equidade entre suas diretrizes, uma das principais omissões da LOS, o SUS\ncontribui para a manutenção das desigualdades no país.","C":"Os seus múltiplos desafios estão mais relacionados à gestão dos serviços, uma vez que o\nfinanciamento público per capita da saúde no Brasil é semelhante ao observado entre os países da\nOCDE.","D":"Uma das mais importantes metas para o país nos próximos anos será ampliar a cobertura da\nESF, que não tem sido superior a um terço da população há uma década."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345531","number":"345531","sourceNumber":"345531","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre o processo de auditoria hospitalar na saúde suplementar e no SUS, é CORRETO\nafirmar que:","options":{"A":"O auditor de contas, da operadora e do hospital é absolutamente dispensável para manter o\nsistema em equilíbrio.","B":"A essência da auditoria seria simplesmente apontar se algo que está sendo cobrado na conta é\njusto, compatível, adequado, ou seja, ater-se ao aspecto técnico da assistência ao paciente.","C":"Na saúde suplementar, a presença de uma tabela de referência única, como o SIGTAP (Sistema\nde Gerenciamento da Tabela de Procedimentos Médicos\ne OPM do SUS), simplifica as etapas.","D":"O papel do auditor não é fundamental nos ajustes dos processos."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345532","number":"345532","sourceNumber":"345532","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Dentre os princípios do Sistema Único de Saúde (SUS), conforme a Lei n.º 8.080, de 19\nde setembro de 1990, estão:","options":{"A":"Igualdade da assistência à saúde, universalidade e austeridade.","B":"Universalidade, interdisciplinaridade e transcendência.","C":"Direito à informação sobre sua saúde, participação da comunidade e universalidade.","D":"Descentralização, segmentação e complexidade incremental."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345533","number":"345533","sourceNumber":"345533","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"NÃO Compete à direção municipal do Sistema de Saúde, (SUS) executar o seguinte\nserviço:","options":{"A":"Alimentação e nutrição.","B":"Saúde do trabalhador.","C":"Vigilância epidemiológica.","D":"Vigilância sócio-assistencial."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-345534","number":"345534","sourceNumber":"345534","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"É uma das instâncias colegiadas do Sistema Único de Saúde (SUS):","options":{"A":"Anvisa.","B":"Conselho de Saúde.","C":"Ministério da Saúde.","D":"Secretaria Municipal de Saúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291802","number":"291802","sourceNumber":"291802","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em março de 2020 a Organização Mundial de Saúde informou que a situação da\ndoença causada pelo Coronavírus no mundo havia\nganhado proporções de pandemia. Desde\nentão, todos os esforços mundiais têm sido no desenvolvimento de vacinas eficazes contra o\nSars-CoV-2. O Brasil tem participado efetivamente desse esforço. Os princípios de produção\n\nvacinal e de imunização são diversos. A despeito de não termos ainda formas de imunização ativa,\ntemos empregado no Brasil a imunização passiva para tratamento da COVID-19. A Anvisa é o\nórgão responsável pelo planejamento e acompanhamento dos esquemas de vacinação no Brasil,\nsegundo as normativas do Sistema Único de Saúde. Esse órgão é:","options":{"A":"Uma secretaria de estado, ligada ao Ministério da Saúde.","B":"Uma autarquia pública com regime especial de gestão.","C":"Uma secretaria especial ligada diretamente à Presidência da República.","D":"Um gabinete técnico indicado por órgãos de ciência e tecnologia ."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283349","number":"283349","sourceNumber":"283349","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No sua UBS, numa manhã de sexta-feira, aquele dia separado só para as visitas\ndomiciliares chega uma senhora desesperada,\nchorando muito, inconsolável; a equipe\ndesesperada e com medo já coloca a paciente em uma sala e chama o seu preceptor! Esse por\nsua vez, pensando esta ser uma excelente oportunidade para você demonstrar seus\nconhecimentos de saúde mental na atenção primária em saúde, com uma leve sudorese e um frio\nna barriga você se direciona a sala; A paciente em questão é Dona Joaquina, 65 anos, cliente\nantiga, conhecida por semanalmente ir na UBS renovar a receitinha de clonazepam 2mg e de\nnimesulida; a consulta se inicia: \"O que está se passando com a senhora Dona Joaquina?\" A\npaciente já um pouco recomposta inicia: \"Doutor, meu amado filho saiu de casa faz 1 mês! Desde\nentão todo dia tô tendo falta de ar sabe?! Meu peito dói, dá tipo um vazio, minha artrose do joelho\ntá atacada, meu corpo inteiro e qualquer coisa tô chorando sabe doutor?! Acho que tô com aquela\ntal de depressão sabe, porque é só eu passar no quartinho dele, e já vem essas coisas ruim tudim\ndenovo e o choro vem fácil! Vim aqui doutor pra ver se o senhor me passa algum remédio pra dar\nfim nesse choro sabe? Aquele tal de antidepressivo que o pessoal fala, podia ser até esse que\nminha vizinha toma, esse amitril de 25mg\". Diante o diálogo iniciado acima, qual seria a conduta\nadequada:","options":{"A":"Iniciar imediatamente a amitriptilina, tendo em vista a familiaridade da paciente com o fármaco e\na dose adequada do mesmo.","B":"Referenciar aos Leitos de Saúde Mental no HUERB (Hospital de Urgência e Emergência de Rio\nBranco), já que o sintoma \"\"vazio no peito\"\" é um clássico indicativo de um quadro depressivo grave\ne necessita internação pelo risco de suicídio.","C":"Continuar a consulta e realizar perguntas que permitam a paciente discorrer sobre o seu\nproblema à medida que se sente devidamente\nacolhida, pois o maior dos sintomas referidos é leve\ne com uma adequada intervenção breve e algumas consultas regulares os sintomas da paciente\nsejam controlados.","D":"Encaminhar a paciente em ao CAPS (Centro de Atenção Psicossocial), pois tendo em vista a\n\nnatureza dos sintomas, esse centro de atendimento especializada em saúde mental/psiquiatria será\no local mais indicado para o atendimento da\ncliente."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283351","number":"283351","sourceNumber":"283351","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um médico, ao iniciar seus trabalhos em uma nova equipe de saúde da família, é\nquestionado por seu colega enfermeiro sobre como deve formatar sua agenda. Para poder\nresponder à dúvida, o médico pergunta sobre os trabalhos comunitários desenvolvidos, tempo para\nvisitas e grupos. Seu colega fica sem atitude, afirmando que o médico anterior apenas atendia\nconsultas, 16 por turno e com isso ganhava uma tarde de liberação para estudo. Diante do exposto,\no médico iniciante, em conjunto com sua equipe, decide realizar um planejamento e um diagnóstico\nsituacional. Nesse caso seria essencial:","options":{"A":"Conhecer as patologias com menor prevalência presentes no seu território, no sentido de se\npreparar caso as mesmas apareçam.","B":"Realizar levantamento de dados epidemiológicos e sanitários do território e levar em conta os\ndeterminantes de saúde levantados pelas lideranças comunitárias.","C":"Pedir para os agentes comunitários de saúde realizarem a territorialização para que o médico\npossa centrar seus esforços no atendimento da livre demanda.","D":"Conhecer bem a clínica individual, uma vez que esta é a principal causa da demanda\nespontânea, responsável pela pressão assistencial das áreas limítrofes."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283352","number":"283352","sourceNumber":"283352","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No estabelecimento da rotina de trabalho de uma Equipe de Saúde da Família, levando\nem consideração a necessidade de atendimento de\npessoas com sintomas gripais que podem ser\nmanifestações clínicas da Covid - 19, é correto afirmar:","options":{"A":"Todos os pacientes devem ser recepcionados por membro da equipe e, após verificação do\nmotivo da procura, os que tiverem sintomas\ngripais devem ser acomodados em ambiente exclusivo\ne atendidos em fluxo separado dentro da USF.","B":"Pacientes com sintomas leves ou contactantes devem ser orientados a permanecer em suas\nresidências cumprindo isolamento social e em caso de piora clínica comunicar a equipe ou procurar\natendimento em unidade de referência se fora do expediente da USF.","C":"O acompanhamento domiciliar realizado pela equipe de saúde do território não inclui o\nmonitoramento da saturação de O2. Nestes\ncasos o paciente deve procurar a USF para realização\nda referida mensuração.","D":"A equipe de saúde deve utilizar os EPIs em todo período de permanência na USF\nindependentemente dos procedimentos e/ou\natividades que realiza incluindo o uso de EPIs também\nas visitas domiciliares."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283353","number":"283353","sourceNumber":"283353","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O programa brasileiro de HIV/AIDS é considerado modelo para o mundo em termos de\nações coordenadas direcionadas para promoção,\nprevenção, tratamento e reabilitação. Ele\nabrange desde a entrega de preservativos até a distribuição gratuita da medicação antiretroviral,\npassando pelas ações de aconselhamento e testagem diagnóstica. Esta característica do programa\npode ser considerada uma expressão prática de qual princípio doutrinário do SUS?","options":{"A":"Universalidade.","B":"Integralidade.","C":"Equidade.","D":"Participação social."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281173","number":"281173","sourceNumber":"281173","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O controle social previsto na regulação do Sistema de Saúde, com representação de\nusuários está presente na seguinte instância:","options":{"A":"Conselhos de Saúde.","B":"Comissão tripartite.","C":"Comissão bipartite.","D":"CONASS.","E":"CONASEM"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281175","number":"281175","sourceNumber":"281175","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. O Sistema Único\nde Saúde (SUS), na sua relação com o conjunto do cuidado médico na sociedade brasileira,...","options":{"A":"provê cuidado aos nascimentos apenas para uma minoria das gestantes, pois a rede hospitalar\ndas maternidades é, na maioria, privada.","B":"atende aproximadamente de 60% a 70% da população brasileira, conforme a região, e usa\nmenos da metade do gasto total com saúde no\nBrasil.","C":"oferece sobretudo atenção de baixa complexidade (atenção primária à saúde), ficando a alta\ncomplexidade dominada pelo setor privado.","D":"controla as vagas de residência médica no país visando aumentar a formação de especialistas\nnas áreas de maior necessidade da população.","E":"como sistema universal, integral, hierarquizado e estruturado pela atenção primária à saúde\n(APS), emprega quase metade dos médicos do país, à semelhança de países industrializados."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283358","number":"283358","sourceNumber":"283358","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O instrumento de avaliação familiar que se utiliza de representação gráfica, que\nidentifica todos os sistemas envolvidos e\nrelacionados com a pessoa, com a família e o meio onde\nvivem é o:","options":{"A":"Ecomapa.","B":"PRACTICE.","C":"FIRO.","D":"Genograma."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281179","number":"281179","sourceNumber":"281179","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Constituem função dos CAPS (Centro de Atenção Psicossocial) I - Organização da rede\nassistencial de saúde mental. II - Substituição das internações em hospitais psiquiátricos. III-\nPorta\nde entrada prioritária da rede assistencial de saúde. IV- Suporte/supervisão da atenção médica na\nEstratégia Saúde da Família. É correto apenas o que se afirma em:","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"II e IV.","E":"III e IV."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283360","number":"283360","sourceNumber":"283360","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Médico de Família e Comunidade deve ter sob seus cuidados, uma população em\ntorno de 1.800 e 2.200 pessoas, o que lhe permite manter resolutividade. Considerando os\nprincípios desta especialidade médica, marque a alternativa que embasa a referida informação:","options":{"A":"O Médico de Família e Comunidade é um recurso de uma população definida;","B":"O Médico de Família e Comunidade é um clínico qualificado;","C":"O Médico de Família é influenciado pela comunidade;","D":"A relação médico-pessoa é fundamental para o desempenho do Médico de Família e\nComunidade."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281180","number":"281180","sourceNumber":"281180","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei nº 8.080/90 define a vigilância epidemiológica como \"um conjunto de ações que\nproporciona o conhecimento, a detecção ou prevenção de qualquer mudança nos fatores\ndeterminantes e condicionantes de saúde individual ou coletiva, com a finalidade de recomendar e\nadotar as medidas de prevenção e controle das doenças ou agravos. São atividades de Vigilância\nEpidemiológica, EXCETO:","options":{"A":"Divulgação de informações pertinentes.","B":"Recomendação das medidas de prevenção e controle apropriadas.","C":"Avaliação de eficácia e efetividade das medidas adotadas.","D":"Inspeção sanitária.","E":"Coleta e processamento de dados."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281181","number":"281181","sourceNumber":"281181","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Agência Nacional de Vigilância Sanitária - ANVISA é uma instituição administrativa\nautônoma, criada por lei pelos entes federativos,\ncom personalidade jurídica de direito público, com\npatrimônio público e atribuições estatais determinadas. Essa modalidade de gestão do Sistema\nÚnico de Saúde, denomina-se:","options":{"A":"Fundação.","B":"Sociedade de economia mista.","C":"Empresa pública.","D":"Autarquia.","E":"Organização social."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283364","number":"283364","sourceNumber":"283364","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Medicina de Família e Comunidade é definida como especialidade médica que presta\nassistência à saúde de forma continuada, integral e abrangente para pessoas, suas famílias e\ncomunidade. Assim sendo, o Médico de Família e Comunidade assume algumas\nresponsabilidades, exceto:","options":{"A":"Atendimento e acompanhamento individual e/ou comunitário;","B":"Coordenação do cuidado e acompanhamento longitudinal;","C":"Atendimento qualificado.","D":"Chefia a equipe de saúde."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283365","number":"283365","sourceNumber":"283365","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Preceptor de Medicina de Família e Comunidade da Unidade Básica de Saúde\nUniversitário desenvolverá uma atividade acadêmica sobre Pneumonia Adquirida na Comunidade\n(PAC), programada para o dia 12 de Novembro, dia em alusão à Pneumonia, onde as instituições\nde saúde e os especialistas da área chamam a atenção para a importância do acesso global à\nprevenção, diagnóstico precoce e tratamento da pneumonia. Em relação a PAC, marque a\nalternativa que corresponde ao patógeno mais comum:","options":{"A":"Micoplasma. pneumoniae.","B":"Streptococus pneumoniae.","C":"Legionella sp.","D":"Bacilos gram-negativos."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281187","number":"281187","sourceNumber":"281187","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os Determinantes Sociais da Saúde - DSS são tratados, desde 2005, dentro de uma\ncomissão própria da Organização Mundial da Saúde (OMS). Segundo ela existem dois tipos de\nDSS, sendo","options":{"A":"estruturais aqueles que terão impacto na equidade em saúde e no bem-estar através da sua\nação sobre os determinantes intermediários.","B":"intermediários aqueles entendidos como motores das condições de vida e se aproximam ao\nconceito de determinantes distais, ou macrodeterminantes econômicos e sociais.","C":"intermediários os representados por mecanismos que geram e reforçam hierarquias sociais que\ndefinem o poder, prestígio e acesso a recursos por meio da educação, do trabalho e da renda.","D":"estruturais os que se referem ao conjunto de elementos categorizados em fatores\ncomportamentais e fatores biológicos,\ncircunstâncias materiais (condições de vida e de trabalho,\ndisponibilidade de alimentos, moradia etc.) e fatores psicossociais.","E":"intermediários os que incluem fatores contextuais, como: cultura e valores sociais, políticas\npúblicas em áreas como educação, atenção médica, água e saneamento."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-251900","number":"251900","sourceNumber":"251900","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre as Redes de Atenção à Saúde (RAS):","options":{"A":"São redes temáticas estruturadas a partir de níveis de complexidade.","B":"São organizadas através da articulação de pontos de atenção sem referência territorial.","C":"Os pontos de atenção devem incorporar tecnologia compatível com os serviços ofertados.","D":"A regulação do acesso aos diferentes pontos e níveis de atenção não é função essencial da\nrede."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-251901","number":"251901","sourceNumber":"251901","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre o Sistema Único de Saúde (SUS):","options":{"A":"Criado na Constituição de 1988, não faz parte da Rede de Proteção Social onde estão incluídas\na previdência e assistência social.","B":"O direito à saúde deve ser garantido através de políticas sociais e econômicas garantindo\nacesso universal e igualitário aos serviços de\nsaúde.","C":"A Agência Nacional de Saúde Complementar é responsável pela regulação dos serviços\nprivados de saúde.","D":"A participação popular, prevista na Lei Orgânica 8142/90, está presente em diversos níveis de\ngestão do SUS e tem caráter consultivo."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-251902","number":"251902","sourceNumber":"251902","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No mês de novembro de 2019 ocorreu um incidente em uma unidade de saúde de um\nmunicípio do interior do Acre. Ao chegar na Unidade para marcar seu exame preventivo do Câncer\nde Cólo do Útero, Dona Marcia deu de cara com um pequeno cartaz com os dizeres abaixo:\nDOCUMENTOS NECESSÁRIOS PARA A REALIZAÇÃO DO PCCU: - Carteira de Identidade. -\n\nCPF. - Comprovante de endereço. - Carteira de Trabalho comprovando ocupação atual. Indignada\nporque não poderia fazer o exame, pois\ntrabalhava em casa de família sem carteira assinada, Dona\nMárcia falou com a enfermeira que isso feria os princípios do SUS e que iria lutar pelos seus\ndireitos. Considerando esse caso, qual princípio do SUS (Lei 8.080) é desrespeitado e qual o\natributo da Atenção Primária (Starfield, 2004) é afetado.","options":{"A":"Universalidade e Acesso.","B":"Integralidade e Longitudinalidade.","C":"Equidade e Integralidade.","D":"Participação Popular e Coordenação."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-251904","number":"251904","sourceNumber":"251904","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Médica de Família e Comunidade da Unidade Básica de Saúde da Vila Ivonete,\npergunta a Maria, 45 anos, o que a traz a\numa consulta não agendada. Ela tira da bolsa um papel,\npara não esquecer de nada que a trouxe ao médico, e prossegue: \"dor nas costas, tontura,\nalteração na menstruação, dor na barriga de vez em quando, dificuldade para dormir, além da\nhipertensão e da minha obesidade, as quais já acompanho há 10 anos desde o nascimento do meu\núltimo filho.\" Qual alternativa relaciona a situação descrita com os princípios da medicina de\nfamília\ne comunidade?","options":{"A":"De acordo com a integralidade, é pertinente que o médico de família aborde, mesmo que\nparcialmente, todas as queixas da paciente no mesmo dia para solidificar o vínculo\n\nmédico-paciente.","B":"É um princípio da medicina de família e comunidade a competência de gerenciar\nsimultaneamente problemas agudos e crônicos de pessoas e\ncoletividades, apoiados em um\nconceito ampliado de saúde.","C":"A escolha da queixa a ser primeiramente abordada está a cargo do médico que possui melhor\ncritério de análise clínica para escalonar a ordem de importância das queixas.","D":"A queixa de dificuldade para dormir deve ser a eleita pelo médico para iniciar a abordagem\ndevido à grande chance de esta paciente,\npela quantidade de queixas, ter algum transtorno de\nhumor."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-247208","number":"247208","sourceNumber":"247208","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Uma das diretrizes do Sistema Único de Saúde (SUS) é a hierarquização das ações de\nsaúde, com ênfase no papel das unidades básicas de saúde (UBS). Pode-se afirmar que a unidade\nbásica de saúde deve","options":{"A":"Ofertar grande variedade de consultas especializadas e exames complementares.","B":"Desenvolver ações que prescindam de exames complementares.","C":"Ser a porta de entrada aos serviços de saúde não se ocupando de ações curativas.","D":"Implementar as ações básicas de saúde de natureza preventiva e curativa.","E":"Desenvolver ações programáticas para problemas de saúde pouco frequentes."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-247223","number":"247223","sourceNumber":"247223","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No Brasil, considera-se a atenção básica á saúde como centro ordenador das redes de\natenção à saúde do SUS. Para o Fortalecimento da atenção básica, é necessário.","options":{"A":"Assumir a estratégia de saúde da família como única porta de entrada do sistema de saúde,\ncomo um mesmo modelo de atenção em todo\nterritório nacional, desconsiderando-se as diferenças\nloco-regional.","B":"Desenvolver ações de qualificação dos profissionais da atenção básica por meio de estratégias\nde educação permanente e de oferta de curso de\nespecialização e residência multiprofissional e em\nmedicina da família.","C":"Ampliar as equipes, consolidar e qualificar a estratégia de saúde da família nos pequenos e\nmédios municípios, assumindo a impossibilidade de implantar e qualificar a estratégia de saúde da\nfamília nos grandes centros urbanos.","D":"Garantir infraestrutura necessária ao funcionamento das unidades básicas de saúde, dotando-se\nde recursos materiais e insumos suficientes para\nque estas executem um conjunto de ações de\nnível primário, secundário e terciário de assistência à saúde.","E":"Aprovar o financiamento da atenção básica como de responsabilidade única do poder municipal,\ne os demais níveis de atenção, como\nambulatórios e hospitais, como de responsabilidade das\nesferas estadual e federal de gestão do SUS."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-247227","number":"247227","sourceNumber":"247227","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Emenda Constitucional nº 29, de 13 de setembro de 2000, dispõe sobre\nfinanciamento do Sistema Único de Saúde,\nestabelecendo que este será financiado com recursos","options":{"A":"Da Seguridade Social, complementados por recursos dos tesouros nacional, estaduais e\nmunicipais, se necessário.","B":"Das três esferas de governo (União, estados e municípios).","C":"Da Seguridade Social, dos estados e dos municípios.","D":"Prioritariamente públicos, completados com recursos privados necessário.","E":"Provenientes da união, repassados a gestão financeira do orçamento municipal."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-247228","number":"247228","sourceNumber":"247228","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A lei Orgânica da Saúde (Lei nº 8.080, de 1990) estabelece que o Sistema Único deve\nassegurar à população um \"conjunto articulado e continuo de ações e serviços preventivos e\ncurativos, individuais e coletivos em todos os níveis do sistema\". Segundo o principio da","options":{"A":"Regionalização","B":"Equidade","C":"Integridade","D":"Universalidade","E":"Hierarquização"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-217682","number":"217682","sourceNumber":"217682","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Dentre as diversas dificuldades de se trabalhar em equipe, é CORRETO afirmar que\numa das principais é:","options":{"A":"O baixo grau de interação entre os profissionais das equipes, o que consequentemente pode\nculminar em maior ênfase às ações preventivas, em detrimento das curativas.","B":"A integralização de diversas atribuições e a regulamentação de novas profissões à equipe\nmínima da Estratégia de Saúde da Família.","C":"A alta rotatividade profissional, o que culmina em maior longitudinalidade e coordenação de\ncuidado.","D":"A dificuldade na construção dialógica de processos de trabalho que tracem planos estratégicos e\nconsiderem a dinâmica e necessidades populacionais."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-217684","number":"217684","sourceNumber":"217684","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Analise os tópicos abaixo:\n\nI. Elaborando um projeto comum de manejo;\n\nII. Incorporando a prevenção e promoção da saúde;\n\nIII. Sendo realista.\n\nÉ CORRETO afirmar que os itens acima são correspondentes do método:","options":{"A":"ASSIST.","B":"P.R.A.C.T.I.C.E.","C":"Clínico centrado na pessoa.","D":"Abordagem breve com cinco passos (5 As)."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-372067","number":"372067","sourceNumber":"372067","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"É pertinente prever ações de promoção da saúde nos instrumentos da prática do\ncuidado:","options":{"A":"Como protocolos em saúde; na carteira de serviços da unidade de saúde na Atenção Primária à\nSaúde; na educação permanente dos profissionais; nas linhas de cuidado com as quais possuem\nrelação; e não no perfil dos profissionais a serem contratados para compor equipes de saúde.","B":"Como protocolos em saúde; na carteira de serviços da unidade de saúde na Atenção Primária à\nSaúde; mas não na educação permanente dos profissionais ou nas linhas de cuidado com as quais\npossuem relação; e no perfil dos profissionais a serem contratados para compor equipes de saúde.","C":"Como protocolos em saúde; na carteira de serviços da unidade de saúde na Atenção Primária à\nSaúde; na educação permanente dos profissionais; nas linhas de cuidado com as quais possuem\nrelação; e no perfil dos profissionais a serem contratados para compor equipes de saúde.","D":"Exceto nos protocolos em saúde e na carteira de serviços da unidade de saúde na Atenção\nPrimária à Saúde; e sim na educação\npermanente dos profissionais; nas linhas de cuidado com as\nquais possuem relação; e no perfil dos profissionais a serem contratados para compor equipes de\nsaúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-372068","number":"372068","sourceNumber":"372068","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Cada estabelecimento prisional deve contar com equipe de saúde completa para\natendimento em nível de atenção básica,\ndimensionada proporcionalmente à sua população\nprisional, e preferencialmente capacitada para atendimento de doenças mentais mais prevalentes.\nSendo que:","options":{"A":"No próprio ambiente prisional poderia ser prestado atendimento a casos mais leves que não\nnecessitassem remoção para Hospitais Forenses e rede de média complexidade local.","B":"No próprio ambiente prisional poderia ser prestado atendimento a casos mais grave que\nnecessitassem remoção para Hospitais Forenses e rede de média complexidade local.","C":"No próprio ambiente prisional poderia ser prestado atendimento a casos mais leves que não\nnecessitassem remoção para Hospitais Forenses e não da rede de média complexidade local.","D":"No próprio ambiente prisional nunca pode ser prestado atendimento a casos mais leves que não\nnecessitassem remoção para Hospitais Forenses e rede de média complexidade local."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-369508","number":"369508","sourceNumber":"369508","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando o perfil clínico do paciente, a avaliação mais indicada, entre as\napresentadas, para investigar inicialmente na\nUnidade Básica de Saúde a causa da fadiga e tontura\né realizar:","options":{"A":"Eletrocardiograma.","B":"Monitorização Ambulatorial da Pressão Arterial (MAPA).","C":"Dosagem sérica de eletrólitos.","D":"Avaliação psicogeriátrica."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-341087","number":"341087","sourceNumber":"341087","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Mulher, 57 anos de idade, foi à Unidade Básica de Saúde onde foi solicitada\nultrassonografia pélvica para acompanhamento de\nmenopausa. O resultado de exame revelou\ncistos ovarianos bilaterais, sendo que o cisto à esquerda foi considerado como O-RADS 4. A\npaciente foi encaminhada ao ginecologista que solicitou uma ultrassonografia endovaginal com\nDoppler. Após o resultado desse ultimo exame houve indicação para internamento hospitalar no\nSUS. Com relação aos procedimentos para o internamento de um paciente em um leito do SUS, é\ncorreto afirmar:","options":{"A":"Qualquer serviço médico seja da rede própria do SUS, da rede complementar ou suplementar\npode solicitar o internamento.","B":"A solicitação do internamento hospitalar é atributo exclusivo de profissional médico, por ser\nregulamentada como Ato Médico.","C":"O profissional que solicitará a internação não pode ser o mesmo profissional que autorizará a\ninternação.","D":"O médico que autorizará a internação pode fazer parte da equipe de cuidados do paciente,\ndurante a internação."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-341092","number":"341092","sourceNumber":"341092","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A população em situação de rua no Brasil cresceu 38% entre 2019 e 2022, quando\natingiu 281.472 pessoas. A estimativa, que\nrevela o impacto da pandemia da COVID-19 nesse\nsegmento populacional, consta da publicação preliminar \"\"Estimativa da População em Situação de\nRua no Brasil (2012-2022)\"\". A estratégia Consultório na Rua foi instituída pela Política Nacional\nde\nAtenção Básica, em 2011, e visa ampliar o acesso da população em situação de rua aos serviços\nde saúde, ofertando, de maneira mais oportuna, atenção integral à saúde para esse grupo\npopulacional, o qual se encontra em condições de vulnerabilidade e com os vínculos familiares\ninterrompidos ou fragilizados. Quanto à atividade do Consultório de Rua, pode-se afirmar:","options":{"A":"A carga horária pode exigir trabalho noturno e aos fins de semana.","B":"Deve haver profissionais médicos, além dos demais profissionais, em todas as equipes.","C":"A equipe do Consultório de Rua não tem fixação a Unidades específicas de saúde.","D":"Mesmo com mobilidade, existe uma população e um território adstritos ao Consultório de Rua."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-341093","number":"341093","sourceNumber":"341093","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A população em situação de rua no Brasil cresceu 38% entre 2019 e 2022, quando\natingiu 281.472 pessoas. A estimativa, que\nrevela o impacto da pandemia da COVID-19 nesse\nsegmento populacional, consta da publicação preliminar \"\"Estimativa da População em Situação de\nRua no Brasil (2012-2022)\"\". A estratégia Consultório na Rua foi instituída pela Política Nacional\nde\nAtenção Básica, em 2011, e visa ampliar o acesso da população em situação de rua aos serviços\nde saúde, ofertando, de maneira mais oportuna, atenção integral à saúde para esse grupo\npopulacional, o qual se encontra em condições de vulnerabilidade e com os vínculos familiares\ninterrompidos ou fragilizados. Considerando-se a clientela do Consultório de Rua, pode se dizer\nque","options":{"A":"a proporção de homens e de mulheres é semelhante, com pouca variação de gênero.","B":"a maioria dos moradores de rua não é alfabetizada, o que dificulta o trabalho.","C":"a população de idosos supera a de adultos jovens, entre os moradores de rua.","D":"o uso de drogas supera, apenas ligeiramente, o desemprego como causa para morar na rua."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-341094","number":"341094","sourceNumber":"341094","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A população em situação de rua no Brasil cresceu 38% entre 2019 e 2022, quando\natingiu 281.472 pessoas. A estimativa, que\nrevela o impacto da pandemia da COVID-19 nesse\nsegmento populacional, consta da publicação preliminar \"\"Estimativa da População em Situação de\nRua no Brasil (2012-2022)\"\". A estratégia Consultório na Rua foi instituída pela Política Nacional\nde\nAtenção Básica, em 2011, e visa ampliar o acesso da população em situação de rua aos serviços\nde saúde, ofertando, de maneira mais oportuna, atenção integral à saúde para esse grupo\npopulacional, o qual se encontra em condições de vulnerabilidade e com os vínculos familiares\ninterrompidos ou fragilizados. Indique a principal estratégia utilizada pelas equipes dos\nConsultórios\nde Rua:","options":{"A":"Aceitar a inexistência de vínculo entre pacientes e equipes.","B":"Trabalhar na perspectiva de redução de danos.","C":"Buscar a adesão dos pacientes às agendas de atendimento.","D":"Buscar a adesão dos pacientes aos serviços de apoio (abrigos etc)."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-315177","number":"315177","sourceNumber":"315177","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O que preconiza o Estatuto da Criança e Adolescente (ECA):","options":{"A":"A criança como sujeito de direitos e com prioridade absoluta.","B":"A criança é defendida como adulto em miniatura e com deveres e obrigações.","C":"A atenção não deve ser prioritária e deve-se atender inicialmente ao idoso.","D":"Os recursos públicos devem ser distribuídos de forma igualitária entre os diversos seguimentos.","E":"Deve-se garantir recursos para a atenção a criança, quando houver sobra de recursos."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-315187","number":"315187","sourceNumber":"315187","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Territorialização, segundo Oliveira e Furlan (2008), é uma estratégia fundamental\npara o planejamento e execução das ações de\nSaúde, principalmente no que se refere a Saúde da\nFamília. A alternativa que descreve CORRETAMENTE essa estratégia é:","options":{"A":"Conhecer os dados epidemiológicos e a densidade demográfica da população e assim poder\navaliar os riscos em Saúde do território.","B":"Fazer uma cartografia do território, realizando uma adscrição populacional e conhecendo os\nlimites geográficos e condições sócio-ambientais do espaço.","C":"É um movimento de caráter constante e dinâmico que percebe para além das condições\nfísico-estruturais e da realidade aparente do cotidiano, aprofundando-se no conhecimento da\ndinâmica e das relações.","D":"Vai de encontro a Desterritorialização, que representa a resistência das equipes de Saúde.","E":"Todas as questões anteriores estão corretas."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-315188","number":"315188","sourceNumber":"315188","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No texto de BUSS & FILHO (2007), conhecemos as várias definições para\nDeterminantes Sociais da Saúde (DSS). De modo\ngeral, este campo de investigação e intervenção\nestreitamente relacionado ao campo da saúde remete sobretudo a:","options":{"A":"Elementos políticos e econômicos macroestruturais que influenciam na determinação das\ncondições e estrutura material dos serviços de saúde pública.","B":"Importância da participação da sociedade civil, considerada em suas diversas formas de\norganização, no controle social dos serviços de saúde ofertados pelo sistema público e privado.","C":"Percepção de que a situação de saúde é um importante determinante das condições de vida e\ntrabalho de indivíduos e grupos.","D":"Consideração das condições de vida e de trabalho dos indivíduos e de grupos da população\ncomo determinantes importantes de sua situação de\nsaúde.","E":"Importância do conhecimento acumulado na área Ciências Sociais para a construção de\nconhecimentos sobre a saúde."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-315189","number":"315189","sourceNumber":"315189","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Distrito Sanitário Especial Indígena (DSEI) é a unidade gestora descentralizada do\nSubsistema de Atenção à Saúde Indígena (SasiSUS). Trata-se de um modelo de organização de\nserviços ? orientado para um espaço etno-cultural dinâmico, geográfico, populacional e\nadministrativo bem delimitado ?, que contempla um conjunto de atividades técnicas, visando\nmedidas racionalizadas e qualificadas de atenção à saúde, promovendo a reordenação da rede de\nsaúde e das práticas sanitárias e desenvolvendo atividades administrativo-gerenciais necessárias à\nprestação da assistência, com controle social. Sobre os serviços presentes nesses distritos\nsanitários, marque a alternativa INCORRETA.","options":{"A":"Os postos de saúde das comunidades indígenas são a Base de atuação das equipes\nmultidisciplinares de saúde indígena, composta\npor médico, enfermeiro, odontólogo e auxiliares,\nalém dos Agentes Indígenas de Saúde (AIS) e dos Agentes Indígenas de Saneamento (AISAN). Os\nagentes moram nas aldeias.","B":"Os Polos-Base são a primeira REFERÊNCIA para os agentes indígenas de saúde que atuam\nnas aldeias. Podem estar localizados numa\ncomunidade indígena ou num município de referência.\nA maioria dos agravos à saúde deverão ser resolvidas nesse nível.","C":"A rede de atendimento do SUS deve ter sua localização geográfica definida e ser articulada e\nincentivada a atender os índios, levando em consideração a realidade socioeconômica e a cultura\nde cada povo indígena, sem a necessidade de financiamento extra.","D":"As Casas dos Índios (Casais) garante alojamento, alimentação e atendimento de enfermagem\naos pacientes e acompanhantes, respeitando as\nespecificidades culturais. Além disso, presta\nassistência farmacêutica e apoia o DSEI na articulação da rede de referência de Média e Alta\nComplexidade, bem como acompanha o agendamento e a realização de consultas, exames e\ninternações. A unidade realiza ainda o apoio logístico para retorno dos pacientes em alta médica e\nde seus acompanhantes aos locais de residência.","E":"Nenhumas das alternativas anteriores estão corretas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-315190","number":"315190","sourceNumber":"315190","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Sistema Único de Saúde (SUS) obedece a um conjunto de princípios que compõem\nsua filosofia. Assinale a alternativa\nINCORRETA, considerando os princípios de organização do\nSUS.","options":{"A":"Participação da comunidade significa que todo e qualquer cidadão tem direito de acesso aos\nserviços públicos de saúde na hora e da maneira que desejar, sem qualquer órgão\ninstitucionalizado de representação.","B":"Hierarquização significa a organização dos serviços de saúde em nível de complexidade.","C":"Resolubilidade significa a capacidade de resolução dos serviços, em todos os níveis de\nassistência.","D":"Descentralização significa um gerenciamento e financiamento que não ocorre unicamente pela\nesfera da Federação.","E":"Equidade significa dar mais atenção a grupos mais vulneráveis."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-315191","number":"315191","sourceNumber":"315191","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Projeto Terapêutico Singular (PTS) é um dispositivo de produção de cuidado em\nsaúde que contribui para a integralidade das\nações, assim, representa:","options":{"A":"Um conjunto de propostas de condutas terapêuticas elaboradas individualmente por cada\nespecialista membro da equipe de saúde.","B":"Um conjunto de propostas de condutas terapêuticas que se constitui independente da demanda\ndo usuário e que considera como prioritária a\nconsolidação das propostas das equipes envolvidas.","C":"Um conjunto de propostas de condutas terapêuticas articuladas, para um sujeito individual ou\ncoletivo, resultante da discussão entre a equipe interdisciplinar e matricial se necessário.","D":"Um conjunto de propostas de condutas terapêuticas desarticuladas, para um sujeito individual ou\ncoletivo, que resulta da discussão entre a equipe interdisciplinar e matricial se for necessário.","E":"Um conjunto de propostas de condutas terapêuticas estruturadas pelo profissional de saúde que\nprimeiro atendeu o usuário, e adotado como normativo pelos demais especialistas da equipe de\nsaúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-313466","number":"313466","sourceNumber":"313466","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A escuta ativa e a promoção de ambiente favorável ao diálogo sobre as práticas\nsexuais devem estar presentes na rotina dos serviços de saúde. Sendo correto que:","options":{"A":"Essa abordagem possibilita vínculos e facilita a adesão às tecnologias disponíveis ofertadas\npelos profissionais de saúde. A escuta qualificada\nnão deve ser realizada com atenção e respeito,\nlivre de preconceitos, possibilitando que a própria pessoa encontre soluções para suas questões.","B":"Essa abordagem possibilita vínculos e facilita a adesão às tecnologias disponíveis ofertadas\npelos profissionais de saúde. A escuta qualificada\ndeve ser realizada com atenção e desrespeito,\nlivre de preconceitos, possibilitando que a própria pessoa encontre soluções para suas questões.","C":"Essa abordagem possibilita vínculos e facilita a adesão às tecnologias disponíveis ofertadas\npelos profissionais de saúde. A escuta qualificada\ndeve ser realizada com atenção e respeito, livre\nde preconceitos, não possibilitando que a própria pessoa encontre soluções para suas questões.","D":"Essa abordagem possibilita vínculos e facilita a adesão às tecnologias disponíveis ofertadas\npelos profissionais de saúde. A escuta qualificada\ndeve ser realizada com atenção e respeito, livre\nde preconceitos, possibilitando que a própria pessoa encontre soluções para suas questões."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-313471","number":"313471","sourceNumber":"313471","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Embora, diversos ensaios clínicos tenham buscado o efeito da metformina sobre o\nsistema Cardiovascular (CV), baseados na fisiopatologia da resistência insulínica, o efeito dessa\nclasse diretamente na IC permanece inconclusivo. Podemos indicar que está correto que:","options":{"A":"Os estudos com insulina e sulfoniluréias mostraram atuação negativa sobre a IC, assim como\nagonistas/ análogos de GLP-155 e acarbose se mostraram neutros sobre o risco de hospitalizações\ne mortalidade por IC.","B":"Os estudos com insulina e sulfoniluréias mostraram atuação neutra sobre a IC, assim como\nagonistas/ análogos de GLP-155 e acarbose não se mostraram neutros sobre o risco de\nhospitalizações e mortalidade por IC.","C":"Os estudos com insulina e sulfoniluréias mostraram atuação neutra sobre a IC, assim como\nagonistas/ análogos de GLP-155 e acarbose se\nmostraram neutros sobre o risco de hospitalizações\ne mortalidade por IC.","D":"Os estudos com insulina e sulfoniluréias mostraram atuação neutra sobre a IC, assim como\nagonistas/ análogos de GLP-155 e acarbose se mostraram melhores sobre o risco de\nhospitalizações e mortalidade por IC."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314236","number":"314236","sourceNumber":"314236","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Fatores de risco de adoecimento pelo Mycobacterium tuberculosis são as doenças ou\ntratamentos imunossupressores, idade menor do que dois anos ou maior do que 60 anos, Diabetes\nmellitus e desnutrição. Sendo correto o item:","options":{"A":"Dentre os principais desafios está na redução do rastreio, diagnóstico e tratamento da Infecção\nLatente pelo Mycobacterium tuberculosis\n(tratado neste como ILTB) , exceto entre crianças\ncontatos menores de cinco anos e pessoas vivendo com HIV (PVHIV).","B":"Dentre os principais desafios está o aumento do rastreio, diagnóstico e tratamento da Infecção\nLatente pelo Mycobacterium tuberculosis\n(tratado neste como ILTB), principalmente entre crianças\ncontatos menores de cinco anos e pessoas vivendo com HIV (PVHIV).","C":"Dentre os principais desafios está o aumento do rastreio, diagnóstico e tratamento da Infecção\nLatente pelo Mycobacterium tuberculosis\n(tratado neste como ILTB), principalmente entre crianças\ncontatos menores de 14 anos e pessoas vivendo com HIV (PVHIV).","D":"Dentre os principais desafios está a redução do rastreio, diagnóstico e tratamento da Infecção\nLatente pelo Mycobacterium tuberculosis\n(tratado neste como ILTB), principalmente entre crianças\ncontatos menores de cinco anos e pessoas vivendo com HIV (PVHIV)."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-313472","number":"313472","sourceNumber":"313472","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A vigilância da Infecção Latente pelo Mycobacterium tuberculosis no Brasil (ILTB) se\nestrutura em pilares principais, indique o item errado:","options":{"A":"Identificação das pessoas com maior probabilidade de ter ILTB ou com menor risco de\nadoecimento.","B":"Identificação de pessoas com a ILTB.","C":"Indicação correta do tratamento e acompanhamento adequado.","D":"Notificação das pessoas que irão realizar o tratamento da ILTB."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314237","number":"314237","sourceNumber":"314237","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Toda ação, atividade e estratégia de vigilância, prevenção e controle de zoonoses de\nrelevância para a saúde pública, desenvolvidas e executadas pela área de vigilância de zoonoses,\nestá de acordo com o item:","options":{"A":"Devem ser precedidas por levantamento do contexto de impacto na saúde pública, por meio de\navaliação da magnitude, da transcendência, e não do potencial de disseminação, da gravidade, da\nseveridade e da vulnerabilidade referentes ao processo epidemiológico de instalação, transmissão\ne manutenção de zoonoses, considerando a população exposta, a espécie animal envolvida, a área\nafetada (alvo), em tempo determinado.","B":"Devem ser precedidas por levantamento do contexto de impacto na saúde pública, por meio de\navaliação da magnitude, da transcendência, do potencial de disseminação, da gravidade, da\nseveridade e da vulnerabilidade referentes ao processo epidemiológico de instalação, transmissão\ne manutenção de zoonoses, desconsiderando a população exposta, a espécie animal envolvida, a\nárea afetada (alvo), em tempo determinado.","C":"Não devem ser precedidas por levantamento do contexto de impacto na saúde pública, por meio\nde avaliação da magnitude, da transcendência, do potencial de disseminação, da gravidade, da\nseveridade e da vulnerabilidade referentes ao processo epidemiológico de instalação, transmissão\ne manutenção de zoonoses, considerando a população exposta, a espécie animal envolvida, a área\nafetada (alvo), em tempo determinado.","D":"Devem ser precedidas por levantamento do contexto de impacto na saúde pública, por meio de\navaliação da magnitude, da transcendência, do potencial de disseminação, da gravidade, da\nseveridade e da vulnerabilidade referentes ao processo epidemiológico de instalação, transmissão\ne manutenção de zoonoses, considerando a população exposta, a espécie animal envolvida, a área\nafetada (alvo), em tempo determinado."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-313473","number":"313473","sourceNumber":"313473","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A resistência da Neisseria gonorrhoeae é preocupação mundial, constando na lista de\n\n?patógenos prioritários\" resistentes aos antibióticos da Organização Mundial da Saúde (OMS). No\nBrasil, a realidade não é diferente. Em relação à rede nacional de vigilância para monitorar a\nresistência antimicrobiana da Neisseria gonorrhoeae, assinale a alternativa correta:","options":{"A":"É fundamental a contínua qualificação das informações epidemiológicas, visando a conhecer a\nmagnitude e não medir a tendência dos agravos para o planejamento das ações de vigilância,\nprevenção e controle. O sistema de saúde precisa estar preparado para implementar estratégias\npreventivas e de intervenção terapêutica imediata, garantindo a disponibilização de insumos, além\nda confidencialidade e da não discriminação.","B":"É fundamental a contínua qualificação das informações epidemiológicas, visando a conhecer a\nmagnitude e medir a tendência dos agravos para o planejamento das ações de vigilância,\nprevenção e controle. O sistema de saúde precisa estar preparado para implementar estratégias\npreventivas e de intervenção terapêutica imediata, garantindo a disponibilização de insumos, além\nda confidencialidade e da não discriminação.","C":"É fundamental a contínua qualificação das informações epidemiológicas, visando a conhecer a\nmagnitude e medir a tendência dos agravos para o planejamento das ações de vigilância,\nprevenção e controle. O sistema de saúde não precisa estar preparado para implementar\nestratégias preventivas e de intervenção terapêutica imediata, garantindo a disponibilização de\ninsumos, além da confidencialidade e da não discriminação.","D":"É fundamental a contínua qualificação das informações epidemiológicas, visando a conhecer a\nmagnitude e medir a tendência dos agravos para o planejamento das ações de vigilância,\nprevenção e controle. O sistema de saúde precisa estar preparado para implementar estratégias\npreventivas e de intervenção terapêutica imediata, não garantindo a disponibilização de insumos,\nalém da confidencialidade e da não discriminação."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307075","number":"307075","sourceNumber":"307075","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Município da zona norte de Sergipe, desprovido de hospital regional, costuma mandar\npacientes, em transporte coletivo, para serem atendidos em Arapiraca. Uma parte desses pacientes\nnecessita de atendimento ambulatorial especializado; outros têm complexidade que indica\ninternamento hospitalar. O financiamento desses atendimentos no SUS implica em definições\ncomplexas e inter articuladas, já que cada município recebe financiamento proporcional à sua\npopulação adstrita. Considerando o Plano Diretor Regional, expresso no Pacto pela Saúde de\n2006, os critérios para definição de Região de Saúde devem contemplar:","options":{"A":"Proximidade geográfica, com localização dentro da mesma unidade federativa.","B":"Ausência, significativa, de migração populacional ou de profissionais de saúde.","C":"Resolutividade para assistência na Atenção Básica e de Média complexidade.","D":"Densidade tecnológica capaz de garantir resolutividade de alta complexidade."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307077","number":"307077","sourceNumber":"307077","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Município da zona norte de Sergipe, desprovido de hospital regional, costuma mandar\npacientes, em transporte coletivo, para serem atendidos em Arapiraca. Uma parte desses pacientes\nnecessita de atendimento ambulatorial especializado; outros têm complexidade que indica\ninternamento hospitalar. O financiamento desses atendimentos no SUS implica em definições\ncomplexas e inter articuladas, já que cada município recebe financiamento proporcional à sua\npopulação adstrita. Indique os Princípios Gerais que permitem a solução do impasse descrito no\ncaso, a partir da pactuação dos gestores locais:","options":{"A":"Princípio da Regionalização e da Equidade.","B":"Princípio da Territorialização e da Participação.","C":"Princípio da Descentralização e da Regionalização.","D":"Princípio da Universalidade e da Territorialização."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307081","number":"307081","sourceNumber":"307081","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Homem, 63 anos de idade, internado em hospital privado com quadro de leucemia\nmiclocítica avançada, não responsiva ao\ntratamento disponível, verificou, na internet, que havia um\nnovo tratamento, ainda sem eficácia cientificamente comprovada, nos Estados Unidos. Para fazer\nparte do protocolo de tratamento de uso compassivo, o paciente teria de custear o medicamento e\nsua importação. As doses da nova medicação são semanais e o tempo de utilização indeterminado.\nO custo da dose é bastante elevado e o tratamento foi negado pelo Plano de Saúde do paciente,\ncom o argumento de que é experimental. A sugestão do médico assistente foi transferir o paciente\npara um hospital público e fazer judicialização do tratamento, sob alegação do Princípio de\nIntegralidade do SUS. Indique a instância que normatiza a extensão ou limitação da cobertura para\nesse tipo de tratamento nos planos privados de saúde, preservando o direito dos usuários.","options":{"A":"Agência Nacional de Vigilância Sanitária.","B":"Agência Nacional de Saúde.","C":"Conselho Federal de Medicina.","D":"Associação Brasileira de Planos de Saúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307082","number":"307082","sourceNumber":"307082","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Homem, 63 anos de idade, internado em hospital privado com quadro de leucemia\nmiclocítica avançada, não responsiva ao\ntratamento disponível, verificou, na internet, que havia um\nnovo tratamento, ainda sem eficácia cientificamente comprovada, nos Estados Unidos. Para fazer\nparte do protocolo de tratamento de uso compassivo, o paciente teria de custear o medicamento e\nsua importação. As doses da nova medicação são semanais e o tempo de utilização indeterminado.\nO custo da dose é bastante elevado e o tratamento foi negado pelo Plano de Saúde do paciente,\ncom o argumento de que é experimental. A sugestão do médico assistente foi transferir o paciente\npara um hospital público e fazer judicialização do tratamento, sob alegação do Princípio de\nIntegralidade do SUS. Com relação à judicialização das questões de saúde no Brasil, pode-se\nafirmar:","options":{"A":"Ainda é fenômeno incipiente para definir políticas públicas específicas.","B":"Decisões judiciais monocráticas, sem padronização, devem ser evitadas.","C":"O judiciário deve se abster de defender interesses individuais dos usuários.","D":"O interesse dos gestores públicos deve prevalecer nas análises judiciais."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307083","number":"307083","sourceNumber":"307083","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Homem, 63 anos de idade, internado em hospital privado com quadro de leucemia\nmiclocítica avançada, não responsiva ao\ntratamento disponível, verificou, na internet, que havia um\nnovo tratamento, ainda sem eficácia cientificamente comprovada, nos Estados Unidos. Para fazer\nparte do protocolo de tratamento de uso compassivo, o paciente teria de custear o medicamento e\nsua importação. As doses da nova medicação são semanais e o tempo de utilização indeterminado.\nO custo da dose é bastante elevado e o tratamento foi negado pelo Plano de Saúde do paciente,\ncom o argumento de que é experimental. A sugestão do médico assistente foi transferir o paciente\npara um hospital público e fazer judicialização do tratamento, sob alegação do Princípio de\nIntegralidade do SUS. O principal dilema referente à implementação das decisões judiciais, quanto\nà saúde no Brasil, decorre do fato de que","options":{"A":"as ações judiciais de primeira instância, referentes às liminares exaradas, são facilmente\nderrubadas.","B":"o conceito de saúde, para muitos juízes, é bastante amplo, envolvendo aspectos da ações\ncurativas e preventivas.","C":"o SUS não tem fontes previsíveis de recursos para financiamento da maior parte das decisões\njudiciais.","D":"o efeito das ações coletivas são maiores do que das ações individuais, implicando em pesados\nônus ao estado."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-276007","number":"276007","sourceNumber":"276007","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre os princípios éticos / doutrinários e organizacionais / operativos do SUS, assinale\na alternativa INCORRETA.","options":{"A":"Os princípios éticos / doutrinários do SUS são: Universalização, Integralidade e Equidade.","B":"Os princípios organizacionais / operativos do SUS são: Descentralização, Regionalização,\nHierarquização, Participação social, Resolubilidade e Complementariedade do setor privado.","C":"A Descentralização consiste na redistribuição das responsabilidades entre município, estado e\nunião.","D":"A Equidade consiste em abordagens diferentes para situações diferentes.","E":"A Hierarquização consiste na organização dos serviços em níveis de complexidade tecnológica\ndecrescente."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-276008","number":"276008","sourceNumber":"276008","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Atenção Básica é o conjunto de ações de saúde individuais,\nfamiliares e coletivas que envolvem promoção,\nprevenção, proteção, diagnóstico, tratamento,\nreabilitação, redução de dados, cuidados paliativos e vigilância em saúde, desenvolvida por meio\nde práticas de cuidado integrado e gestão qualificada, realizada com equipe multiprofissional e\ndirigida à população em território definido, sobre as quais as equipes assumem responsabilidade\nsanitária. Em relação aos princípios e diretrizes da PNAB, assinale a alternativa INCORRETA.","options":{"A":"A Resolutividade reforça a importância da Atenção Básica ser resolutiva, devendo ser capaz de\nresolver a maioria dos problemas de saúde da população.","B":"A Transversalidade do cuidado consiste na continuidade da relação do cuidado, construindo um\nvínculo entre os profissionais e os usuários ao longo do tempo.","C":"A Coordenação do cuidado consiste na elaboração, acompanhamento e organização do fluxo de\nusuários entre os pontos da Rede de Atenção à Saúde.","D":"A Integralidade é o conjunto de serviços realizados pela equipe multiprofissional atendendo às\nnecessidades da população adscrita nos campos do cuidado, promoção de saúde, prevenção de\ndoenças, cura, reabilitação e cuidados paliativos.","E":"A Universalidade possibilita o acesso universal e contínuo a serviços de saúde, caracterizando\ncomo a porta de entrada para a Rede de Atenção\nà Saúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-276009","number":"276009","sourceNumber":"276009","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A equipe da Atenção Básica dispõe de instrumentos de abordagem familiar que\nauxiliam a equipe a entender o indivíduo e\nsua relação com a família e a comunidade. Em relação a\nesses instrumentos, assinale a alternativa CORRETA.","options":{"A":"O F.I.R.O. é um instrumento de avaliação do funcionamento das famílias.","B":"O P.R.A.C.T.I.C.E. consiste em orientações fundamentais nas relações interpessoais.","C":"O A.P.G.A.R. Familiar corresponde a um instrumento de avaliação destinado a refletir a\nsatisfação de cada membro da família.","D":"O Ecomapa não permite mostrar a relação entre a família e o meio em que ela vive.","E":"Para ser construído corretamente, um Genograma precisa de, pelo menos, uma geração."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283757","number":"283757","sourceNumber":"283757","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em março de 2020 a Organização Mundial de Saúde informou que a situação da\ndoença causada pelo Coronavírus no mundo havia\nganhado proporções de pandemia. Desde\nentão, todos os esforços mundiais têm sido no desenvolvimento de vacinas eficazes contra o\n\nSars-Cov-2. O Brasil tem participado efetivamente desse esforço. Os princípios de produção vacinal\ne de imunização são diversos. A despeito de\nnão termos ainda formas de imunização ativa, temos\nempregado no Brasil a imunização passiva para tratamento da COVID-19. A Anvisa é o órgão\nresponsável pelo planejamento e acompanhamento dos esquemas de vacinação no Brasil,\nsegundo as normativas do Sistema Único de Saúde. Esse órgão é:","options":{"A":"Uma secretaria de estado, ligada ao Ministério da Saúde.","B":"Uma autarquia pública com regime especial de gestão.","C":"Uma secretaria especial ligada diretamente à Presidência da República.","D":"Um gabinete técnico indicado por órgãos de ciência e tecnologia."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283760","number":"283760","sourceNumber":"283760","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Homem, 62 anos de idade, comparece à Unidade Básica de Saúde, UBS, pois deseja\nfazer avaliação para neoplasia de próstata,\napós colega de trabalho ter tido a doença. Relata que\nacorda, eventualmente, uma vez à noite para urinar, mas nega outros sintomas. Mantém calibre do\njato urinário normal e nega gotejamento terminal. O paciente é casado, tem vida sexual ativa, sem\nproblemas. Tem antecedentes de uretrite na juventude, tratada com antibióticos. Nega história\nfamiliar de CA de Próstata, embora relate que sua mãe teve câncer de mama. Ex tabagista, tendo\nabandonado o hábito há 20 anos. Carga tabágica prévia: 16 anos/maço. Nega etilismo. Nunca fez\nexames para Câncer de próstata. Com relação às estratégias quanto à investigação de neoplasia\nde próstata nesse paciente, pode se afirmar que","options":{"A":"esse paciente está na faixa de triagem, que está indicada dos 60 aos 80 anos de idade.","B":"esse paciente já devia ter feito o toque retal desde os 50 anos de idade.","C":"a dosagem de PSA total e livre deve ser feita, pois é mais sensível que o toque retal.","D":"a triagem pode aumentar os agravos à saúde em decorrência de iatrogenia."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283762","number":"283762","sourceNumber":"283762","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Homem, 62 anos de idade, comparece à Unidade Básica de Saúde, UBS, pois deseja\nfazer avaliação para neoplasia de próstata,\napós colega de trabalho ter tido a doença. Relata que\nacorda, eventualmente, uma vez à noite para urinar, mas nega outros sintomas. Mantém calibre do\njato urinário normal e nega gotejamento terminal. O paciente é casado, tem vida sexual ativa, sem\nproblemas. Tem antecedentes de uretrite na juventude, tratada com antibióticos. Nega história\nfamiliar de CA de Próstata, embora relate que sua mãe teve câncer de mama. Ex tabagista, tendo\nabandonado o hábito há 20 anos. Carga tabágica prévia: 16 anos/maço. Nega etilismo. Nunca fez\nexames para Câncer de próstata. A carga tabágica de 16 anos/maço indica que esse paciente\nfumou:","options":{"A":"Dezesseis maços por ano no período em que fumou.","B":"Um maço por dia, durante 16 anos de tabagismo.","C":"Pelo menos um maço/dia desde os 16 anos de idade.","D":"Dez cigarros por dia por período de 8 anos."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-231352","number":"231352","sourceNumber":"231352","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O que preconiza o Estatuto da Criança e Adolescente (ECA)?","options":{"A":"A criança é defendida como adulto em miniatura e com deveres e obrigações","B":"A criança é sujeito de direitos e deve ter atenção com prioridade absoluta","C":"A atenção não deve ser prioritária a pesar de importante","D":"Os recursos públicos devem ser distribuídos de forma igualitária","E":"A atenção deve ser de acordo com as possibilidades de recursos"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-231383","number":"231383","sourceNumber":"231383","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Nos caminhos do direito a saúde, o movimento que assegurou a universalização do\nacesso aos serviços de saúde, a integração das\nações e a unificação dos serviços\nconcretizaram-se através:","options":{"A":"Sistema Único de Saúde ? SUS","B":"Ações Integradas de saúde - AIS","C":"Sistema único Descentralizado da saúde ? SUDS","D":"Programa nacional de serviços básicos de saúde ? PREV- Saúde","E":"Conselho Nacional de Administração da Saúde Previdenciária ? CONASP"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-231384","number":"231384","sourceNumber":"231384","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A epidemiologia pode ser definida como:","options":{"A":"Ciência que estuda a relação saúde-doença em uma comunidade, analisando a distribuição e os\nfatores determinantes dos agravos a saúde.","B":"Ciência que estuda a mortalidade e sua relação comm as zoonoses","C":"Serviço ambulatorial que fiscaliza e determina as vacinas que devem ser aplicadas no esquema\nbásico","D":"Estudo das morbidades e mortalidades evidenciadas no momento de uma comunidade","E":"Pratica de saúde pública em que os profissionais fiscalizam as condições sociais e ambientais\nda população"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-231391","number":"231391","sourceNumber":"231391","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre o processo de trabalho da Estratégia Saúde da Família, assinale V ou F e\nresponda: ( ) I. Promover assistência\nresolutiva à demanda livre e assistência plena ao atendimento\nas urgências por meio do acolhimento com escuta qualificada. ( ) II. Planejar ações que promovam\nassistência limitada a grupos de hipertensos, gestantes e idosos. ( ) III. Responsabilização\nsanitária\npara com os usuários e/ou famílias de um determinado território definido. ( ) IV. Realizar\nplanejamento em saúde impérvios para readequações. ( ) V. Realizar ações e atividades a serem\ndefinidas de acordo com as prioridades locais. ( ) VI. Prover atenção integral, contínua e\norganizada\nà população adscrita; Estão corretas APENAS:","options":{"A":"I, III, V","B":"I, III, IV, V","C":"II, IV, V","D":"III, V e VI","E":"III, IV, V"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-231392","number":"231392","sourceNumber":"231392","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Portaria G/SM n° 2.488, de 21 de outubro de 2011, estabelece revisão das diretrizes\ne normas para a organização da Atenção Básica.\nAssinale V(verdadeiro) ou F(falso) as assertivas,\ncom base nesta portaria. ( ) A Atenção Básica deve ser resolutiva: identificar riscos, necessidades\ne\ndemandas de saúde e utilizando de diferentes níveis de tecnologias de cuidado singular, bem como\ncoletivo. ( ) A Atenção Básica deve ser a modalidade de atenção e de serviço de saúde com o mais\nbaixo grau de descentralização, ocupando-se da gestão de redes. ( ) Em relação ao funcionamento\ndas Redes de Atenção à Saúde, a Atenção Básica deve ordenar a rede, a partir do reconhecimento\ndas necessidades de saúde da população sob sua responsabilidade. ( ) A Atenção Básica deve\nelaborar, acompanhar e gerir ações educativas, não lhe competindo acompanhar e organizar o\nfluxo dos usuários entre os pontos de atenção das Redes.","options":{"A":"V, F, F, F","B":"V, V, V, F","C":"F, V, V, F","D":"F, F, V, F","E":"V, V, V, F"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252935","number":"252935","sourceNumber":"252935","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No Brasil, o câncer do colo do útero é o segundo tipo de câncer mais frequente entre\nmulheres, após o câncer de mama, com alta mortalidade e faz, por ano, 4800 vítimas fatais. Em\n2012, as estimativas foram de 17540 casos novos, com risco estimado variando de 17 a 21 casos a\ncada 100 mil mulheres, com grandes iniquidades regionais, sendo maiores as incidências\nregistradas em estados com menor nível de desenvolvimento socioeconômico. BRASIL, Ministério\nda Saúde. Informe Técnico sobre a Vacina Papiloma Vírus Humano (HPV) na Atenção Básica. As\niniquidades regionais no desenvolvimento do câncer do colo de útero, descritas no texto, reforçam\no conceito teórico de determinação social de saúde desenvolvido após 2011. Esse conceito difere\ndo conceito de determinantes sociais de doença porque indica que","options":{"A":"existem fatores sociais específicos para uma doença, os quais podem ser modificados.","B":"há um processo social complexo do qual a saúde ou a doença são resultantes finais.","C":"com determinação da sociedade, várias condições mórbidas já podiam ter sido controladas.","D":"a prevenção é a abordagem mais efetiva, cuja implementação depende de facilitadores sociais."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-215224","number":"215224","sourceNumber":"215224","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Centro de Referência (CR) pode proceder à avaliação, ao acompanhamento e,\nquando for o caso, à administração dos medicamentos. Sua criação é preconizada em alguns\nprotocolos, com particularidades que deverão respeitar e adaptar-se a cada doença/condição ou\ncuidado especial requerido, como custo muito elevado, possibilidade de compartilhamento,\nnecessidade de armazenamento, estabilidade, etc. Está de acordo com o seguinte item:","options":{"A":"Tem como objetivo prestar assistência em saúde aos usuários do Sistema Único de Saúde\n(SUS), promovendo a efetividade do tratamento e o\nuso responsável e racional dos medicamentos\npreconizados nos Protocolos Clínicos e Diretrizes Terapêuticas PCDTs.","B":"Tem como objetivo prestar assistência em saúde aos usuários do Plano de Saúde apenas,\npromovendo a efetividade do tratamento e o uso responsável e racional dos medicamentos\npreconizados nos Protocolos Clínicos e Diretrizes Terapêuticas PCDTs.","C":"Tem como objetivo prestar assistência em saúde aos usuários do Sistema Único de Saúde\n(SUS), mesmo sem a efetividade do tratamento e o\nuso responsável e racional dos medicamentos\npreconizados nos Protocolos Clínicos e Diretrizes Terapêuticas PCDTs.","D":"Tem como objetivo prestar assistência em saúde aos usuários do Sistema Único de Saúde\n(SUS), promovendo a efetividade do tratamento e o\nuso responsável e irracional dos medicamentos\npreconizados nos Protocolos Clínicos e Diretrizes Terapêuticas PCDTs."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-362458","number":"362458","sourceNumber":"362458","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Assinale a alternativa onde estão relacionados somente os Atributos Derivados da\nAtenção Primária descritos por Bárbara Starfield:","options":{"A":"Competência cultural, longitudinalidade, coordenação do cuidado.","B":"Orientação familiar, orientação comunitária, competência cultural.","C":"Integralidade, competência cultural, longitudinalidade.","D":"Coordenação do cuidado, orientação familiar, integralidade."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-362457","number":"362457","sourceNumber":"362457","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As crises do ciclo de vida familiar podem ser previsíveis, esperadas, ou acidentais,\ninesperadas, por isso é importante conhecer as fases do ciclo de vida familiar. Assinale a\nalternativa onde tem somente fases do ciclo de vida familiar da classe popular.","options":{"A":"Saindo de casa: jovens solteiros, O novo casal, Famílias com filhos pequenos.","B":"Famílias com adolescentes, encaminhando os filhos e seguindo em frente, Famílias no estágio\ntardio de vida.","C":"Adolescente/Adulto jovem solteiro, A família com filhos, A família no estágio tardio da vida.","D":"A família no estágio tardio da vida, Famílias com filhos pequenos, Famílias com adolescentes."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327302","number":"327302","sourceNumber":"327302","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"F., 45 anos, homem, é seu paciente de longa data na sua UBS, realizando\nacompanhamento devido ao diagnóstico de\nDiabetes Mellitus do tipo 2 e Hipertensão Arterial\nSistêmica. Faz uso de forma irregular de metformina, e vem apresentando dificuldades no controle\nglicêmico. Durante a última consulta de rotina, ao ser questionado sobre hábitos e modificações de\nestilo de vida, respondeu ao médico que \"não tomava a medicação sempre pois não precisava,\numa vez que não sentia nada, e que estava comendo carne, sal, além de fumar, e nem tinha\ninteresse em parar pois era o prazer que ele tinha\". Seus exames e medidas antropométricas\nmostravam o seguinte: Altura: 1,61; Peso: 115 kg; Glic. de jejum: 238 mg/dl; Hb. Glic: 8,8 mg/dl;\nPA=170 x 100 PA=170x100; Você perguntou se o paciente gostaria de participar do grupo de\natividades físicas da UBS, ao que ele respondeu: \"doutor, eu não vou nesse grupo não porque não\nsou idoso e lá só tem velho (sic)\". Considerando os estágios motivacionais de Prochaska e\nDiclemente, pode-se concluir que o paciente se encontra em qual estágio?","options":{"A":"Preparação","B":"Ação","C":"Pré-contemplativo","D":"Contemplativo"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327307","number":"327307","sourceNumber":"327307","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Estratégia Saúde da Família (ESF) é a estratégia prioritária de expansão,\nconsolidação e qualificação da Atenção Básica\nno Brasil. Dentro da rede de atenção à saúde, a\nESF tem o desafio de funcionar como um centro de comunicação entre os diversos pontos de\natenção. Conforme a Política Nacional de Atenção Básica - PNA (2017), assinale a diretriz que\ncontempla esse papel:","options":{"A":"Territorialização e Adstrição","B":"Equidade","C":"Coordenação","D":"Integralidade"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327308","number":"327308","sourceNumber":"327308","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Para que a Estratégia Saúde da Família tenha seu funcionamento adequado,\ncumprindo seus princípios e diretrizes, é recomendado pela PNAB (2017), que:","options":{"A":"A população adscrita por equipe de saúde seja de 3500 a no máximo 5000 pessoas.","B":"A equipe mínima seja composta por um médico, preferencialmente da especialidade medicina de\nfamília e comunidade, um enfermeiro, um dentista e técnicos de enfermagem.","C":"As pessoas identificadas como fora da área de abrangência devem ser prontamente\nencaminhadas para unidades de saúde próximas ao\nendereço de residência a fim de garantir seu\nacolhimento adequado.","D":"Os profissionais da ESF deverão estar vinculados a apenas uma equipe de saúde da família,\ndevendo cumprir obrigatoriamente a carga horária de 40 horas semanais."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327309","number":"327309","sourceNumber":"327309","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Domiciliar na Atenção Básica pertence à modalidade AD1 sendo um cuidado\nque deve ser oferecido na seguinte situação:","options":{"A":"Pessoas que têm a necessidade frequente de exames de laboratório de alta complexidade.","B":"Pessoas que possuam problemas de saúde compensados e com dificuldade de locomoção até a\nunidade de saúde.","C":"Apenas às pessoas que se encontram permanentemente acamadas, e que, portanto, não\npodem se deslocar até a unidade de saúde.","D":"Pessoas com necessidade de visitas regulares, de frequência semanal, como a realização de\ncurativos complexos."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327310","number":"327310","sourceNumber":"327310","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A atenção à saúde do idoso é uma das práticas comuns em Atenção Primária à Saúde.\nSobre a saúde da população idosa, qual é a\nalternativa que melhor descreve os OBJETIVOS do\ncuidado e seguimento do idoso em APS?","options":{"A":"A busca da cura fisiopatológica de todas as condições presentes no idoso.","B":"A maior longevidade possível, independente da funcionalidade.","C":"A manutenção da autonomia, da independência funcional, com extensão da expectativa de vida\nativa e melhora na qualidade de vida.","D":"A obtenção do melhor manejo farmacológico possível, razão pela qual o cuidado ao idoso deve\nser exclusivamente médico."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327311","number":"327311","sourceNumber":"327311","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os Conselhos de Saúde são instâncias de participação permanente com caráter\ndeliberativo compostos por:","options":{"A":"50% de usuários, 25% de trabalhadores da saúde e 25% de gestores.","B":"70% de trabalhadores da saúde, 15% de gestores e 15% de usuários.","C":"50% de gestores, 25% de usuários e 25% de trabalhadores da saúde.","D":"70% de usuários, 15% de trabalhadores da saúde e 15% de gestores."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327312","number":"327312","sourceNumber":"327312","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"\"Atenção essencial à saúde baseada em tecnologia e métodos práticos, cientificamente\ncomprovados e socialmente aceitáveis, tornados universalmente acessíveis a indivíduos e famílias\nna comunidade a um custo que tanto a comunidade como o país possam arcar em cada estágio de\nseu desenvolvimento, um espírito de autoconfiança e autodeterminação\". O conceito descrito se\nrefere à:","options":{"A":"Prevenção Primária","B":"Método Clínico Centrado na Pessoa","C":"Estratégia Saúde da Família","D":"Atenção Primária à Saúde"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327313","number":"327313","sourceNumber":"327313","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Qual dos atributos da Atenção Primária à Saúde está relacionado com a existência de\numa fonte regular de atenção e seu uso ao\ndecorrer do tempo e tem vários benefícios, tais como,\nmenor utilização de serviços, melhor atenção preventiva, menos referenciamento de pacientes e\nmenos hospitalizações?","options":{"A":"Coordenação do Cuidado","B":"Longitudinalidade","C":"Integralidade","D":"Atenção ao Primeiro Contato"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327314","number":"327314","sourceNumber":"327314","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A decisão compartilhada é um processo no qual médico e pessoa decidem juntos sobre\ntratamentos, exames, manejo e suporte, levando em conta as preferências da pessoa e as\nmelhores evidências disponíveis. Em qual dos componentes do Método Clínico Centrado na\nPessoa podemos fazer uso da decisão compartilhada?","options":{"A":"Elaborando um Plano Conjunto de Manejo dos Problemas.","B":"Explorando a Saúde, a Doença e a Experiência da Doença.","C":"Entendendo a Pessoa como um todo.","D":"Intensificando a relação entre a pessoa e o médico."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327315","number":"327315","sourceNumber":"327315","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A atenção à saúde do idoso é uma das práticas comuns em Atenção Primária à Saúde.\nSobre a saúde da população idosa, qual é a\nalternativa que melhor descreve os OBJETIVOS do\ncuidado e seguimento do idoso em APS?","options":{"A":"A busca da cura fisiopatológica de todas as condições presentes no idoso.","B":"A maior longevidade possível, independente da funcionalidade.","C":"A manutenção da autonomia, da independência funcional, com extensão da expectativa de vida\nativa e melhora na qualidade de vida.","D":"A obtenção do melhor manejo farmacológico possível, razão pela qual o cuidado ao idoso deve\nser exclusivamente médico."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327318","number":"327318","sourceNumber":"327318","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Carlos, 32 anos, vai à UBS para uma consulta médica e o médico faz o seguinte\nregistro SOAP da consulta: S: Há 2 semanas\nvem sentindo dor de cabeça diariamente, com\ndiscreta melhora após uso de analgésico. Está com medo de ter pressão alta, pois sua mãe faleceu\nde infarto. O: BEG, LOTE; exame físico sem alterações. PA: 150x90; A: HAS? Cefaleia; Medo de\nter HAS; P: Controle ambulatorial de PA; Retorno após controle de PA; Orientações sobre HAS;\nSobre o registro acima, pode-se afirmar que o:","options":{"A":"S está incorreto","B":"O está correto","C":"A está correto","D":"P está incorreto"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-327320","number":"327320","sourceNumber":"327320","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com relação aos modelos Flexneriano e Dawsoniano complete a segunda coluna: 1-\nModelo Flexneriano; 2- Modelo Dawnsoniano; ( ) Integração da medicina curativa e medicina\npreventiva. ( ) Negação da determinação social da saúde. ( ) Visão centrada em partes do corpo\nhumano. ( ) Nível primário de atenção como porta de entrada. ( ) Modelo Hospitalocêntrico. ( )\nIntegração do cuidado. A sequência CORRETA é:","options":{"A":"1- 2 - 1 - 1 - 1 - 2","B":"2 - 2 - 2 - 1 - 1 - 1","C":"1 - 2 - 1 - 1 - 2 - 1","D":"2 - 1 - 1 - 2 - 1 - 2"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298269","number":"298269","sourceNumber":"298269","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considere o registro de consulta abaixo, realizado através do método SOAP (Subjetivo,\nObjetivo, Avaliação e Plano). S: E.S.P., 58 anos, diabético em uso de metformina 850mg duas\nvezes ao dia, apresenta tosse produtiva, perda de peso e febre vespertina há um mês. Conta que\nvem sentindo fraqueza e que a secreção da tosse é amarelada. Referiu também que vem\napresentando formigamento em membros inferiores, bilateralmente, com característica em ?bota?.\nTrouxe resultado de exames de controle. O: Ap.Resp: Murmúrio Vesicular reduzido em ápices;\nACV: s/alterações; Glicemia de Jejum 315 mg/dl; Hemoglobina glicada: 10,2 mg/dl A: Diabetes\nMellitus Tipo 2 Neuropatia Diabética Suspeita de Tuberculose P: Iniciado insulina NPH; solicitado\nteste rápido molecular para TB; iniciado amitriptilina 25mg VO à noite. Considerada a característica\nda informação registrada, há um dos itens do SOAP que está registrado de forma incorreta. Qual?","options":{"A":"Subjetivo","B":"Avaliação","C":"Objetivo","D":"Plano"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298270","number":"298270","sourceNumber":"298270","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O domínio de habilidades de comunicação é uma competência que todos os médicos\ndevem ser capazes de executar, sendo a Prevenção de Demandas Aditivas uma das principais\nhabilidades a serem desenvolvidas, possibilitando que todas as queixas e demandas do paciente\nsejam apresentadas no início da consulta. O questionamento mais apropriado que o médico deve\nfazer ao paciente para prevenir demandas aditivas é exemplificada corretamente pela pergunta:","options":{"A":"?Quer falar mais alguma coisa??","B":"?Quando começaram seus sintomas??","C":"?O que você espera que eu faça por você hoje??","D":"?Como posso lhe ajudar hoje?\"\""},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298272","number":"298272","sourceNumber":"298272","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A atuação do médico de família e comunidade no âmbito da Atenção Primária à Saúde\npossui características próprias. Uma das alternativas abaixo descreve corretamente uma dessas\ncaracterísticas. Qual?","options":{"A":"Abordagem centrada na doença.","B":"Capacidade de lidar com a incerteza clínica.","C":"Utilização de raciocínio clínico biomédico e reducionista.","D":"Planejamento terapêutico centrado na opinião do médico."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298273","number":"298273","sourceNumber":"298273","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O início de uma consulta médica é essencial para a obtenção de informações relativas\nao problema da pessoa que procura atendimento.\nUma técnica CORRETA a ser utilizada nos\nmomentos iniciais de uma consulta é:","options":{"A":"Delimitar o motivo da consulta somente dentro da queixa principal do paciente.","B":"Utilizar perguntas fechadas o mais precocemente possível a fim de direcionar a entrevista.","C":"Registrar as informações da história clínica em prontuário (digital ou físico) assim que o\npaciente\ncomeçar a falar.","D":"Deixar o paciente falar livremente sobre seu problema por pelo menos dois minutos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298274","number":"298274","sourceNumber":"298274","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A prática médica centrada na pessoa, característica principal do médico de família e\ncomunidade, deve ser capaz de fazer uma distinção entre doença (disease) e adoecimento\n(illness). Sobre doença e adoecimento é CORRETO afirmar que:","options":{"A":"Ao explorar um problema de saúde, é essencial que o médico compreenda a preocupação do\npaciente e o entendimento que ele tem sobre o seu problema, além do impacto do mesmo em sua\nvida e funcionalidade.","B":"O adoecimento ou experiência com a doença é um fenômeno que ocorre de forma semelhante\nem todos os indivíduos acometidos por\ndeterminada patologia.","C":"A doença, entendida como fenômeno em que há uma alteração da homeostasia do indivíduo, é\num processo analisado sob as seguintes características: sofrimento, idéias, função e expectativas.","D":"É primordial que o médico dê maior importância à fisiopatologia de uma doença do que àquilo\nque o paciente acredite que seja a causa de seus problemas de saúde."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298279","number":"298279","sourceNumber":"298279","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considere a seguinte interação a seguir: - Paciente: ?(...) essas manchas já tem uns 5\nanos, e isso tem me deixado muito preocupada.? - Médico: ?Entendi, você está me falando que já\ntem essas manchas há uns 5 anos, mas agora você tem ficado mais preocupada. Aconteceu\nalguma coisa diferente ou tem alguém que você conhece que tem ou teve essas manchas\ntambém?? - Paciente: ?Ah, doutor, minha mãe ficou com essas manchas um tempão e agora\ndescobriram um problema nos rins dela e ela vai precisar até de hemodiálise.? Considerando o\nMétodo Clínico Centrado na Pessoa, o principal componente aplicado a essa situação foi:","options":{"A":"Explorando a saúde, a doença e a experiência da doença.","B":"Conhecendo a pessoa como um todo.","C":"Fortalecendo a relação entre a pessoa e o médico.","D":"Elaborando um plano conjunto de manejo dos problemas."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298280","number":"298280","sourceNumber":"298280","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O prontuário do usuário é uma importante ferramenta na coordenação do cuidado como\natributo da Atenção Primária à Saúde. Sobre esta ferramenta, qual a alternativa CORRETA?","options":{"A":"Assegurado o entendimento do paciente de seus problemas por meio da verbalização dos\nmesmos, o registro em prontuário da lista de problemas torna-se facultativo.","B":"O prontuário deve ser de leitura fácil e rápida, por isso os registros devem ser da menor\nquantidade possível, devendo-se fazer uso\nfrequente de abreviaturas e a elaboração da lista de\nproblemas deve conter somente aqueles que o MFC considera essenciais.","C":"A elaboração de uma lista de problemas, sempre atualizada, é uma estratégia simples e de fácil\ntransmissão de informações sobre o usuário e seus problemas conhecidos.","D":"Cada profissional deve registrar seus atendimentos em prontuário de forma livre e sem uma\norganização mínima, uma vez que o formato SOAP foi criado para uso exclusivamente hospitalar."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298281","number":"298281","sourceNumber":"298281","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Uma das competências que médicos de família devem desenvolver é a coordenação do\ncuidado. Assinale a alternativa que melhor define essa competência:","options":{"A":"Ser o primeiro serviço a ser procurado quando uma pessoa apresenta uma necessidade de\nsaúde nova ou recorrência de um problema de\nsaúde antigo.","B":"Incluir a busca por informações a respeito dos problemas e ações realizadas nos diferentes\npontos de atenção, integrando as intervenções\ne reconhecendo a pertinência da informação para o\natendimento atual.","C":"Ter como essência uma relação de confiança ao longo do tempo e exigir a existência de uma\nfonte regular de atenção e a recorrência à mesma.","D":"Ter a capacidade de identificar e lidar com o leque completo das necessidades de saúde de um\nindivíduo, seja resolvendo esses problemas ou orientando onde eles devem ser resolvidos."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298283","number":"298283","sourceNumber":"298283","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As populações ribeirinhas possuem diversas especificidades na atenção às suas\nnecessidades de saúde, sendo o uso de ervas\ne plantas medicinais algo corriqueiro na vida destas\npessoas. Com relação ao uso de ervas e plantas medicinas pelos ribeirinhos, pode-se afirmar que:","options":{"A":"A transmissão desse conhecimento é um procedimento feito com registros escritos, sendo\nrepassado para as novas gerações.","B":"É um conhecimento construído na vivência dos indivíduos, nas relações pessoais, sociais e com\no meio ambiente.","C":"A sua prática se faz por meio do tratamento com rezadores (benzedeiros) e curadores (pajés),\nsomente quando há falha na terapia alopática.","D":"O uso de ervas e plantas medicinais é recomendado, tanto pelas benzedeiras quanto pelos\nmoradores mais novos das comunidades ribeirinhas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298286","number":"298286","sourceNumber":"298286","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Entre as competências clínicas do médico no âmbito da Atenção Primária à Saúde está\na realização de procedimentos, sendo um dos\nmais comuns relacionados ao manejo da unha\nencravada. Sobre o tratamento da unha encravada, assinale a alternativa CORRETA:","options":{"A":"Na cantoplastia, não se deve realizar sutura.","B":"Não há forma de se prevenir a ocorrência de unha encravada.","C":"A cantoplastia é o único tratamento para a unha encravada.","D":"Na técnica de Bartlett, não há manipulação da unha."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298287","number":"298287","sourceNumber":"298287","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A queixa de dor torácica é bastante frequente na Atenção Primária à Saúde (APS),\nsendo motivo de preocupação por parte dos\npacientes. A principal causa de dor torácica na APS é:","options":{"A":"Doença arterial crônica","B":"Distúrbios musculoesqueléticos","C":"Transtornos de ansiedade e pânico","D":"Doença do refluxo gastresofágico"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298288","number":"298288","sourceNumber":"298288","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A desprescrição de medicamentos é o processo sistemático de identificação e\ndescontinuação de um ou mais fármacos por parte de um médico, fazendo parte de um processo\ncontínuo de boa prescrição que inclui o início da terapia, a escolha da dose apropriada, a troca ou\nadição de medicamentos ao esquema e a mudança ou interrupção de terapias farmacológicas.\n\nSobre a abordagem da desprescrição, assinale a alternativa CORRETA:","options":{"A":"A falta de alterações significativas ao ser retirada uma medicação é sinal de que a\ndesprescrição, ou ao menos a troca/ajuste de medicamentos, é necessária.","B":"A suspensão de várias medicações de uma vez permite melhor esclarecimento sobre o fármaco\nque pode estar causando evento adverso.","C":"Após a suspensão de uma medicação, não é preciso avaliar continuamente os pacientes para\nresultados positivos da desprescrição, pois o problema já foi solucionado.","D":"Ao iniciar o uso de um fármaco, não se deve fornecer ao paciente todas as informações sobre o\nseu tratamento, com o objetivo de poupá-lo de\nmais preocupações."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286780","number":"286780","sourceNumber":"286780","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com Barbara Starfield, os elementos abaixo são princípios da Atenção\nPrimária à Saúde, EXCETO:","options":{"A":"Integralidade","B":"Longitudinalidade","C":"Equidade","D":"Coordenação do Cuidado"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286781","number":"286781","sourceNumber":"286781","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Ricardo realizou uma visita domiciliar com o ACS e a enfermeira da equipe na\nresidência da senhora K.O.S., 44 anos,\nacompanhada em serviço hospitalar devido à neoplasia\ninvasiva de colo uterino. A paciente queixava-se de intensas dores abdominais e pélvicas, fazendo\nuso regular de opióides prescritos pelo ambulatório de terapia da dor. Considerando o quadro\nclínico apresentado, Ricardo deveria prescrever associadamente:","options":{"A":"Laxativos e dieta rica em fibras, para alívio da constipação.","B":"Anti-histamínicos orais, considerando o prurido como efeito colateral e melhorando o sono da\npaciente.","C":"Antieméticos para evitar vômitos.","D":"Antipsicóticos, para controle do delirium."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286782","number":"286782","sourceNumber":"286782","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A atuação do Médico de Família e Comunidade (MFC) possui características próprias.\nA alternativa que descreve CORRETAMENTE uma dessas\ncaracterísticas é:","options":{"A":"Frequente construção de hipóteses diagnósticas.","B":"Foco prioritário na prevenção de doenças.","C":"Lidam com problemas de saúde restritos a grupos programáticos (ex: Hiperdia).","D":"Realizam encaminhamento ao especialista focal com a maior brevidade possível."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286784","number":"286784","sourceNumber":"286784","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Declaração Universal dos Direitos Humanos diz que a vontade do povo será a base\nda autoridade do governo. Sobre a participação\npopular no SUS, selecione a alternativa\nCORRETA.","options":{"A":"Os Conselhos de Saúde são formados por 50% de gestores, 25 % de trabalhadores e 25% de\nusuários.","B":"A base legal para a participação popular na gestão do SUS é a Lei 8.142/90.","C":"A Ouvidoria Geral do SUS por estar ligada ao Ministério da Saúde não faz parte dos\nmecanismos de participação popular na construção do SUS.","D":"Os Conselhos de Saúde são formados por 25% de gestores, 50% de trabalhadores e 25% de\nusuários."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286785","number":"286785","sourceNumber":"286785","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Qual dos itens está contemplado no componente ?elaborando um projeto comum para\no manejo dos problemas? da Abordagem Centrada\nna Pessoa?","options":{"A":"Centralizar a elaboração do plano de manejo clínico na figura do médico.","B":"Enfatizar a responsabilidade do paciente em cumprir rigorosamente o plano terapêutico.","C":"Definir os problemas a serem manejados com base na experiência profissional do médico.","D":"Obter consenso nos objetivos do manejo do problema clínico."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286786","number":"286786","sourceNumber":"286786","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O ciclo de vida familiar de classe popular é caracterizado por um menor número de\netapas de desenvolvimento decorrentes do\nprocesso de adaptação. Esse contexto exige que as\npessoas exerçam tarefas que não são específicas para a fase da vida em que se encontram e sim\nexigidas em uma determinada situação. Todas as etapas abaixo caracterizam o ciclo de vida\nfamiliar da classe popular, EXCETO:","options":{"A":"Casal jovem sem filhos.","B":"Família com filhos pequenos.","C":"Ninho vazio.","D":"Famílias em estágio tardio de vida."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286795","number":"286795","sourceNumber":"286795","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O programa Previne Brasil foi instituído pela Portaria no 2.979, de 12 de novembro de\n2019. O novo modelo brasileiro de financiamento da Atenção Primária à Saúde altera algumas\nformas de repasse das transferências para os municípios, que passam a ser distribuídas com base\nem três critérios:","options":{"A":"PAB variável, PAB fixo e PMAQ.","B":"Capitação ponderada, pagamento por desempenho e incentivo para ações estratégicas.","C":"Pagamento por território adscrito, capitação ponderada e PAB fixo.","D":"Pagamento por desempenho, PAB variável e incentivo para ações estratégicas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286796","number":"286796","sourceNumber":"286796","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Lúcia, filha de dona Nair que tem 75 anos, solicita uma visita domiciliar para Dra.\nLilian,\nvisto que está preocupada com sua mãe. Após a ida ao domicílio juntamente com a ACS\nFrancinara, Dra. Lilian faz seu registro da consulta no formato SOAP. S = Filha refere que dona\nNair vem apresentando dificuldade para reconhecer algumas pessoas e que este sintoma está\npresente há aproximadamente cinco anos. Atualmente, apenas lembra-se claramente de coisas da\nsua infância e adolescência. Tem trocado o nome da neta. Perguntada sobre sua história de vida,\ndona Nair focou seu relato no relacionamento de amor com o marido já falecido. Não apresenta\nsintomas cardiovasculares nem pulmonares, tem incontinência urinária de longa evolução\n(geralmente ligada a esforços e tosse). Não faz uso de medicações contínuas. Filha demonstra\nexpectativa quanto aos possíveis ?remédios? para a situação de sua mãe e refere que dona Nair\nse queixa de dores nos dentes e que tem dificuldade em se alimentar devido ao problema. O =\nCorada, hidratada, sem edemas; PA = 130 x 80 mmHg; FC = 88 bpm; sem sinais neurológicos\nfocais; bulhas cardíacas sem alterações; murmúrio vesicular fisiológico sem ruídos adventícios;\nabdômen sem alterações à palpação; lesões nas comissuras labiais. A = Suspeita de demência;\nlesões em boca; dor nos dentes a esclarecer; dificuldade para se alimentar. P = Plano de\nacompanhamento longitudinal e coordenado em equipe; orientações de segurança e risco de\nqueda; discutir em equipe maneiras de incluir outros membros da equipe no cuidado,\nprincipalmente a equipe de saúde bucal; discutir formas de ampliar a rede de cuidadores de dona\nNair; apoiar Lúcia no cuidado a dona Nair. Em relação ao registro acima, o item do SOAP que foi\nregistrado de forma INCORRETA foi:","options":{"A":"S.","B":"A.","C":"O.","D":"P."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-286797","number":"286797","sourceNumber":"286797","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Mulher, 24 anos, G1P0A0, teve diagnóstico de infecção por toxoplasmose recente,\natravés de exames do pré-natal. Foi\nreferenciada ao pré-natal de alto risco; no entanto, orientada\npela equipe de saúde, também comparece às consultas na UBS, fazendo acompanhamento\nconjunto. Nesse caso, aplicou-se o atributo da Atenção Primária à Saúde denominado:","options":{"A":"Longitudinalidade","B":"Integralidade","C":"Equidade","D":"Coordenação do cuidado"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-256616","number":"256616","sourceNumber":"256616","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Analise o genograma abaixo e marque a alternativa CORRETA:","options":{"A":"Ana Célia é o caso índice do genograma.","B":"Carlos e Raysa apresentam relações conflitantes.","C":"Pedro Silva e Graça Silva tiveram 06 filhos.","D":"Pedro (15 anos de idade) mora com Carlos e Maria Clara."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-256620","number":"256620","sourceNumber":"256620","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em relação aos atributos da atenção primária à saúde (segundo Bárbara Starfield),\nmarque a resposta em que está corretamente associado o atributo com o conceito:","options":{"A":"Longitudinalidade ? percepção probabilística de um futuro.","B":"Universalidade ? assistência para todos como dever do Estado.","C":"Integralidade ? atuação de forma biopsicossocial e espiritual.","D":"Municipalização ? transferência da responsabilidade da APS para os municípios."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252289","number":"252289","sourceNumber":"252289","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Fernando é um Médico de Família e Comunidade que iniciou recentemente sua\natuação em uma Unidade Básica de Saúde\nrecém-inaugurada no bairro do Puraquequara, em\nManaus. Em sua primeira semana sua principal atividade foi a territorialização. Sobre o processo de\nterritorialização, é CORRETO afirmar que:","options":{"A":"Possibilita a identificação de grupos, famílias e indivíduos sujeitos à riscos e\nvulnerabilidades,\npossibilitando ações apropriadas e\nresolutivas.","B":"É uma ação de prevenção de doenças e promoção da saúde das pessoas da área de\nabrangência da Unidade.","C":"O médico não deveria participar deste processo uma vez que o mesmo é atribuição dos Agentes\nComunitários de Saúde.","D":"Seu principal objetivo é determinar a divisão do território em áreas e microáreas."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252291","number":"252291","sourceNumber":"252291","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"M.P.T., 52 anos, sexo masculino, veio à consulta querendo fazer exames de rotina.\nEncontra-se sem queixas. É hipertenso e usa\nhidrocolorotiazida 25mg pela manhã. Divorciou-se há\num ano e começou novo relacionamento fixo há 7 meses, contudo antes disso tinha relações\nsexuais eventuais com diferentes parceiras, sem uso de preservativo. Nega tabagismo e etilismo.\n\nNunca fez tatuagens ou recebeu transfusão. Apresentou cartão de vacina com esquema completo\npara Hepatite B. Na história familiar conta que\nos pais são hipertensos e a mãe teve câncer\ncolorretal aos 72 anos. PA=120x80, Peso=82kg, Altura=1,76m. Ausculta cardíaca e respiratória\nnormais. Considerando as recomendações de rastreamento e a preocupação com iatrogenias, além\ndos exames de rotina para HAS (lipidograma, glicemia, creatinina, potássio e EAS), o médico\ndeveria solicitar:","options":{"A":"PSA, pesquisa de sangue oculto nas fezes e sorologias para HIV e sífilis.","B":"PSA e pesquisa de sangue oculto nas fezes.","C":"Sorologias para HIV, sífilis e hepatite C.","D":"Pesquisa de sangue oculto nas fezes e sorologias para HIV e sífilis."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252294","number":"252294","sourceNumber":"252294","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Glória, 21 anos, procedente da Venezuela, está no Brasil há apenas 15 dias e ainda\nnão possui o visto. Vem à Unidade Básica de\nSaúde (UBS) relatando estar gestante e deseja iniciar\no pré-natal. A equipe de saúde realiza o cadastro de Glória e a mesma é agendada para sua\nprimeira consulta com a enfermeira no dia seguinte. Assinale a alternativa que apresenta o princípio\ndo SUS que está sendo levado em consideração no atendimento a essa pessoa:","options":{"A":"Regionalização e hierarquização.","B":"Participação social.","C":"Universalidade.","D":"Descentralização."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252295","number":"252295","sourceNumber":"252295","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo a Política Nacional de Atenção Básica, são atribuições comuns a todos os\nprofissionais das equipes de Atenção Básica, EXCETO:","options":{"A":"Indicar, de forma compartilhada com outros pontos de atenção, a necessidade de internação\nhospitalar ou domiciliar, mantendo a responsabilização pelo acompanhamento do usuário.","B":"Participar do processo de territorialização e mapeamento da área de atuação da equipe,\nidentificando grupos, famílias e indivíduos expostos a riscos e vulnerabilidades.","C":"Realizar busca ativa e notificar doenças e agravos de notificação compulsória e de outros\nagravos e situações de importância local.","D":"Manter atualizado o cadastramento das famílias e dos indivíduos no sistema de informação\nindicado pelo gestor municipal."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252296","number":"252296","sourceNumber":"252296","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre o sistema de saúde no Brasil, assinale a alternativa INCORRETA:","options":{"A":"A equidade significa que o acesso aos serviços de saúde deve ser garantido a toda população\nem condições de igualdade e que a prioridade deve\nser dada a quem tem mais necessidade.","B":"A universalidade é a garantia de que todos os cidadãos devem ter acesso aos serviços de saúde\npúblicos e privados conveniados, em todos os níveis do sistema de saúde.","C":"Apesar da integralidade ser um dos princípios do SUS, muitos profissionais que atuam na\nestratégia de saúde da família ainda têm o enfoque do atendimento centrado na doença.","D":"O controle social é uma diretriz que cabe exclusivamente à comunidade e aos movimentos\nsociais."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252297","number":"252297","sourceNumber":"252297","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Você está em seu consultório, é o décimo quinto paciente, por volta de 12h15, todo\npaciente que entra reclama da espera e\n?vomita? suas demandas: ?é meu direito!?. E você pensa\nem ceder o que se pede: não há tempo nem disposição de informar ou ir de encontro com a\npessoa. Até que uma senhora, de oitenta e poucos, trazida pelas mãos de uma adulta jovem, talvez\nfilha, tateia o assento, pois não enxerga: ?oi doutor. Não está nada bem. É tanta coisa que não sei\nnem por onde começar...? ? ?comece do começo e ande, pois já terminou meu tempo de\natendimento.? ? ?...certo doutor! Eu que temo pelo meu tempo...?. Nessa relação citada, fica\nevidente que:","options":{"A":"O médico agiu certo em não deixar a pessoa discorrer sobre seus problemas, pois não havia\ntempo hábil para isso.","B":"O médico se utilizou apenas da técnica desenvolvendo uma atitude exclusivamente biomédica,\ncentrada na doença, o que prejudica sua relação com os pacientes.","C":"O afastamento emocional do médico faz com que se evite contratransferência, evitando que a\npessoa use afeições erroneamente.","D":"A grande quantidade de consultas não prejudica o atendimento, pois temos de ser\nextremamente assertivos e considerar apenas as evidências científicas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252299","number":"252299","sourceNumber":"252299","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Dentre os itens abaixo qual NÃO é uma função rotineira da visita domiciliar (modelo\nAD1)?","options":{"A":"Consolidação de vínculos.","B":"Aproximação do contexto familiar.","C":"Procedimentos invasivos em pacientes em internação domiciliar.","D":"Prevenção de agravos."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252301","number":"252301","sourceNumber":"252301","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Método Clínico Centrado na Pessoa (MCCP) surgiu da demanda das pessoas por um\natendimento que contemplasse de maneira mais integral suas necessidades, preocupações e\nvivências relacionadas à saúde ou às doenças. O componente que NÃO faz parte do MCCP é:","options":{"A":"Explorando a saúde, a doença e a experiência com a doença.","B":"Realizando atendimento domiciliar de acordo com a necessidade.","C":"Entendendo a pessoa como um todo ? o indivíduo, a família e contexto.","D":"Elaborando um plano conjunto de manejo dos problemas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252302","number":"252302","sourceNumber":"252302","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Assinale o atributo da Atenção Primária à Saúde (APS) descrito por Bárbara Starfield\nque é essencial para a obtenção dos outros\naspectos da APS, envolve a continuidade de\ninformação dentro do sistema, seja pela continuidade do profissional, seja via prontuário médico e\ntem como ferramentas essenciais a referência e contrarreferência:","options":{"A":"Atenção ao primeiro contato/acesso.","B":"Longitudinalidade.","C":"Integralidade.","D":"Coordenação do cuidado."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252303","number":"252303","sourceNumber":"252303","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Analise o genograma abaixo e marque a alternativa CORRETA:","options":{"A":"José e Sofia tiveram 06 filhos.","B":"José é o caso índice do genograma.","C":"Sofia e Luiza têm uma relação sem conflitos.","D":"Todos os filhos de José e Sofia moram juntos."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-252304","number":"252304","sourceNumber":"252304","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"João, 32 anos, vem para consulta médica na UBS. Verifica-se no prontuário que é a\nterceira consulta e que na lista de problemas principal do prontuário consta: ALERGIA À DIPIRONA\n(história de angiodema). O registro da consulta é realizado como descrito abaixo. S: Há 2 dias\napresenta quadro de coriza hialina acompanhada de tosse com expectoração clara e febre\nintermitente de até 38 graus. Nega dispneia ou outras queixas. Nega comorbidades prévias. O:\nBom estado geral, eupneico, hidratado. Ausculta cardíaca: ritmo cardíaco regular, sem sopros.\n\nAusculta pulmonar: murmúrio vesicular positivo bilateralmente, sem ruídos adventícios. Oroscopia:\nhiperemia de orofaringe, sem presença de placas em amígdalas. Otoscopia: membranas\ntimpânicas e condutos sem alterações. PA= 125x80 mmHg, FC=92 bpm, FR=18 mrpm,\nTemperatura Axilar=37,7°C. A: Infecção de vias aéreas superiores. P: Orientação quanto a sinais e\nsintomas de gravidade; paracetamol 500mg 1 comprimido de 6 em 6 horas se dor ou febre maior\nque 38,2°C; hidratação e solução fisiológica nasal. Em relação ao registro acima, no formato SOAP,\né CORRETO afirmar que:","options":{"A":"O registro está adequado, obedecendo ao método SOAP.","B":"O P (Plano) do SOAP está inadequado, pois deveria se ater à menção da terapia farmacológica\ninstituída.","C":"Infecção de vias aéreas superiores é um termo genérico e está sendo usando inadequadamente\nno A (Avaliação) do SOAP.","D":"O S (Subjetivo) do SOAP está inadequado pela menção de febre, que, por ser um sinal, deveria\naparecer exclusivamente no O (Objetivo) do SOAP."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208301","number":"208301","sourceNumber":"208301","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em 2017, a Política Nacional de Atenção Básica (PNAB) foi reformulada,\nestabelecendo que:","options":{"A":"Há outras estratégias de ABS além da Estratégia Saúde da Família (ESF), que devem atuar em\ncaráter permanente.","B":"Apenas as Unidades Básicas de Saúde do modelo (ESF) são campo de ensino em potencial.","C":"Será composta por uma equipe mínima (médico, enfermeiro, técnico de enfermagem, e agente\nde endemias).","D":"Os termos Atenção Primária à Saúde e Atenção Básica à Saúde (ABS) são equivalentes,\npassando a serem usados como sinônimos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208361","number":"208361","sourceNumber":"208361","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando as especificidades da Atenção Básica à Saúde no Brasil e nossa enorme\ndiversidade populacional, podemos afirmar que:","options":{"A":"Arranjos organizacionais especiais como as Equipes Saúde da Família Fluviais (ESFF) são\nvoltados para populações da Amazônia Legal e do Pantanal Sul-Mato-Grossense.","B":"Outro arranjo organizacional especial são as Equipes Saúde da Família Ribeirinhas (ESFR),\nunidades construídas à beira de rios, lagos ou mares para atender suas populações adscritas.","C":"A equipe mínima nas ESFF é composta por médico, enfermeiro, odontólogo, técnico em saúde\nbucal, farmacêutico, técnico de enfermagem, microscopista, agente de endemias e agente\ncomunitário de saúde.","D":"A ESFR deve prestar atendimento a sua população no mínimo durante 20 dias por mês e podem\ncontar com o apoio ocasional de embarcações\nmenores, se custeadas pelo gestor municipal."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208379","number":"208379","sourceNumber":"208379","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Básica, mais especificamente a Estratégia Saúde da Família (ESF), a porta\nde entrada do sistema de saúde brasileiro, é\nresponsável pelo acompanhamento da população em\nvários momentos de vida. Referente às atribuições da ESF em relação aos idosos, o Cadernos de\nAtenção Básica n°.19 preconiza que EXCETO:","options":{"A":"Compete à equipe o preenchimento e atualização da caderneta de Saúde da Pessoa Idosa,\nregistrando as medicações em uso.","B":"Compete à equipe o gerenciamento do cuidado ao idoso, exceto quando em internação\ndomiciliar, cabendo esta ação à atenção especializada.","C":"Compete à equipe a avaliação do grau de sobrecarga do cuidador e a avaliação da\nfuncionalidade familiar, através do Apgar familiar.","D":"Compete à equipe a elaboração das redes de cuidado ao idoso através dos instrumentos\nGenograma e Ecomapa."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208398","number":"208398","sourceNumber":"208398","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Saúde Integral das Populações do Campo e da Floresta\n(PNSIPCF) está regulamentada pela Portaria n°\n2.866, de 2011. Tal portaria traz como avanços,\nEXCETO:","options":{"A":"Incentivar a pesquisa e a produção de conhecimento sobre os riscos, a qualidade de vida e a\nsaúde das populações do campo e da floresta,\nrespeitando as especificidades de geração,\nraça/cor, gênero, etnia e orientação sexual.","B":"Incentivar o desenvolvimento das ações de educação permanente para os trabalhadores de\nsaúde, voltadas para as especificidades de saúde das populações do campo e da floresta.","C":"Contribuir para a melhoria da qualidade de vida das populações do campo e da floresta,\nincluindo articulações intersetoriais para promover a\nsaúde, envolvendo ações de saneamento e\nmeio ambiente, especialmente para a redução de riscos sobre a saúde humana.","D":"Discernir as práticas biomédicas das de conhecimentos tradicionais, valorizando e fortalecendo\naquelas, prevendo que sejam mais presentes na\nvida coletiva e social destas populações."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208407","number":"208407","sourceNumber":"208407","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As Práticas Integrativas e Complementares (PICS) já estão devidamente normatizadas\npor portarias do Ministério da Saúde. Referente às\nPICS e aos seus objetivos delineados, assinale\na CORRETA.","options":{"A":"Estimular as ações referentes ao controle/participação social, promovendo o envolvimento\nresponsável e continuado dos usuários, gestores e trabalhadores nas diferentes instâncias de\nefetivação das políticas de saúde.","B":"Promover com forte ênfase, a racionalização das ações de saúde, estimulando alternativas\ninovadoras e socialmente contributivas ao desenvolvimento sustentável de comunidades.","C":"Contribuir para o aumento da resolubilidade do sistema e ampliação do acesso à Política\nNacional de Práticas Integrativas e Complementares (PNPIC), garantindo qualidade, eficácia,\neficiência e segurança no uso.","D":"Incorporar e implementar a PNPIC no SUS, na perspectiva da prevenção de agravos e da\npromoção e recuperação da saúde, com ênfase\nna atenção especializada, voltada para o cuidado\ncontinuado, humanizado e integral em saúde."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208418","number":"208418","sourceNumber":"208418","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O controle social no Sistema Único de Saúde (SUS) é representativo das lutas por\nespaços mais democráticos, dialogados e construídos com inúmeras representatividades da\nsociedade civil. Assinale a alternativa CORRETA.","options":{"A":"As reuniões dos Conselhos de Saúde são abertas ao público, obrigatoriamente acontecendo\nsemanalmente, nas secretarias de saúde.","B":"Os Conselhos de Saúde atuam exclusivamente no controle da execução das políticas públicas\nde saúde.","C":"Os conselhos de saúde são instâncias do Sistema Único de Saúde (SUS), deliberativas,\ncolegiadas e permanentes.","D":"As vagas para os CS deverão ser distribuídas: trabalhadores da saúde (50%), usuários (25%) e\nrepresentantes do governo e prestadores privados (25%)."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208436","number":"208436","sourceNumber":"208436","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em ano eleitoral temos candidatos e partidos políticos colocando em pauta a saúde do\npaís, dos estados e dos municípios. Nesta conjuntura, além do uso da epidemiologia, para ajudar a\n\"ver os cenários\" distintos, algumas bases do Sistema Único de Saúde (SUS) podem ajudar a\npensar em planos de governo condizentes, alinhados com a realidade e com base legal. O que\nvocê recomendaria?","options":{"A":"Que a Lei 8.080/90 ressalta que as ações e serviços de saúde executados pelo setor privado e\ncontratado pelo SUS não precisam obedecer aos princípios organizativos previstos nesta Lei.","B":"A Constituição Federal nos remete a saúde como um direito fundamental do ser humano,\ndevendo o Estado prover as condições indispensáveis ao seu pleno exercício.","C":"Que a Lei 8.142/90 versa sobre os recursos para a área da saúde. Para receberem os recursos,\nos Municípios, Estados e Distrito Federal devem\ncontar: Fundo de Saúde e a Vigilância\nEpidemiológica implantada.","D":"Que a Lei 8.080, em seu art. 7 versa sobre os princípios e diretrizes do SUS, sendo entendido\nque a rede de saúde deverá ser regionalizada e\ncentralizada."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208310","number":"208310","sourceNumber":"208310","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Helena, 68 anos, comparece à consulta na UBS trazendo resultado de exames\nlaboratoriais. Ela é diabética, em uso de\ninsulina NPH na dose de 20 unidades pela manhã e 10\nunidades à noite. Seus exames de controle revelam uma glicemia de jejum de 212 mg/dL e\nhemoglobina glicada de 8,7 mg/dL. Considerando que na Atenção Primária à Saúde utiliza-se o\nRegistro de Saúde Orientado por Problemas (RCOP), os resultados dos exames laboratoriais\ndevem se anotados no item:","options":{"A":"Subjetivo","B":"Avaliação","C":"Plano","D":"Objetivo"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208315","number":"208315","sourceNumber":"208315","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"São características da atenção primária à saúde, EXCETO:","options":{"A":"Municipalidade.","B":"Coordenação do cuidado.","C":"Cuidado de primeiro contato.","D":"Integralidade."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208327","number":"208327","sourceNumber":"208327","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Quando médico e paciente estabelecem conjuntamente um plano de manejo dos\nproblemas de saúde do indivíduo podemos concluir que foram utilizados princípios da:","options":{"A":"Estratégia Saúde da Família","B":"Abordagem Centrada na Pessoa","C":"Política Nacional da Atenção Básica","D":"Abordagem Comunitária"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208423","number":"208423","sourceNumber":"208423","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a Portaria N° 2.436, de 21 de setembro de 2017, que regulamenta a\nPolítica Nacional de Atenção Básica, são atribuições comuns a todos os membros das Equipes que\natuam na Atenção Básica, EXCETO:","options":{"A":"Participar do processo de territorialização e mapeamento da área de atuação da equipe,\nidentificando grupos, famílias e indivíduos expostos a riscos e vulnerabilidades.","B":"Indicar a necessidade de internação hospitalar ou domiciliar, mantendo a responsabilização pelo\nacompanhamento da pessoa.","C":"Cadastrar e manter atualizado o cadastramento e outros dados de saúde das famílias e dos\nindivíduos no sistema de informação da Atenção Básica vigente, utilizando as informações\nsistematicamente para análise da situação de saúde, considerando as características sociais,\neconômicas, culturais, demográficas e epidemiológicas do território, priorizando as situações a\nserem acompanhadas no planejamento local.","D":"Realizar o cuidado integral à saúde da população adscrita, prioritariamente no âmbito da\nUnidade Básica de Saúde, e quando necessário,\nno domicílio e demais espaços comunitários\n(escolas, associações, entre outros), com atenção especial às populações que apresentem\nnecessidades específicas (em situação de rua, em medida socioeducativa, privada de liberdade,\nribeirinha, fluvial, etc)."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-208426","number":"208426","sourceNumber":"208426","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em relação aos atributos da atenção primária à saúde (segundo Bárbara Starfield),\nmarque a resposta que está corretamente associado o atributo com o conceito:","options":{"A":"Integralidade - atuação de forma biopsicossocial e espiritual.","B":"Longitudinalidade - percepção probabilística de um futuro.","C":"Universalidade - assistência para todos como dever do Estado.","D":"Municipalização - transferência da responsabilidade da APS para os municípios."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-324698","number":"324698","sourceNumber":"324698","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A proposição da Política Nacional de Atenção Integral à Saúde do Homem visa\nqualificar a saúde da população masculina na\nperspectiva de linhas de cuidado que resguardem a\nintegralidade da atenção. Um dos problemas para estabelecer uma política de saúde adequada ao\nhomem é a via de acesso aos serviços de saúde. No caso dos homens, o acesso aos serviços de\nsaúde ocorre por meio da","options":{"A":"atenção especializada.","B":"urgência/ emergência.","C":"saúde do trabalhador.","D":"saúde da família."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-324704","number":"324704","sourceNumber":"324704","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Regulação de pacientes é uma ferramenta de democratização do acesso que\npossibilita, por exemplo, a um paciente do\nmunicípio de Barreiras, oeste da Bahia, ter o mesmo\ndireito de ser internado no Hospital Geral do Estado, localizado em Salvador, na capital do Estado,\nque um paciente que está na emergência do hospital. A decisão de internação será pautada na\ngravidade do caso e não pela proximidade do paciente. É um sistema criado para gerir vagas\nhospitalares e outras necessidades de pacientes dentro do Sistema Único de Saúde (SUS),\nutilizando critérios internacionalmente estabelecidos. O critério de Manchester, utilizado\nuniversalmente para priorizar os pacientes, considera:","options":{"A":"O tempo de espera para internação, ordenando com números.","B":"A gravidade geral do caso, classificando com cores.","C":"As necessidades de cuidados especiais, estadiando em letras.","D":"O número de comorbidades associadas, classificando com cores."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-324705","number":"324705","sourceNumber":"324705","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Regulação de pacientes é uma ferramenta de democratização do acesso que\npossibilita, por exemplo, a um paciente do\nmunicípio de Barreiras, oeste da Bahia, ter o mesmo\ndireito de ser internado no Hospital Geral do Estado, localizado em Salvador, na capital do Estado,\nque um paciente que está na emergência do hospital. A decisão de internação será pautada na\ngravidade do caso e não pela proximidade do paciente. É um sistema criado para gerir vagas\nhospitalares e outras necessidades de pacientes dentro do Sistema Único de Saúde (SUS),\nutilizando critérios internacionalmente estabelecidos. Quanto às definições de urgência e\nemergência, para fins de Regulação, pode se dizer que:","options":{"A":"A urgência indica necessidade de atendimento imediato, em agravo de saúde pré-existente.","B":"A emergência indica reconhecimento de agravo com risco de vida ou sofrimento intenso.","C":"A emergência indica aparecimento súbito de agravo imprevisto com necessidade de\natendimento imediato.","D":"A urgência indica agravo súbito com risco iminente de vida, necessitando de socorro médico."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-324706","number":"324706","sourceNumber":"324706","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Regulação de pacientes é uma ferramenta de democratização do acesso que\npossibilita, por exemplo, a um paciente do\nmunicípio de Barreiras, oeste da Bahia, ter o mesmo\ndireito de ser internado no Hospital Geral do Estado, localizado em Salvador, na capital do Estado,\nque um paciente que está na emergência do hospital. A decisão de internação será pautada na\ngravidade do caso e não pela proximidade do paciente. É um sistema criado para gerir vagas\nhospitalares e outras necessidades de pacientes dentro do Sistema Único de Saúde (SUS),\nutilizando critérios internacionalmente estabelecidos. Por contrarreferência no sistema de\nRegulação em saúde entende-se a transferência do paciente, saindo da Unidade de Referência","options":{"A":"por falta de recursos para o atendimento pretendido.","B":"por dispensar maior complexidade de atendimento.","C":"por resolutividade completa do caso, após atendimento.","D":"por erro no perfil de gravidade do paciente referenciado."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-284627","number":"284627","sourceNumber":"284627","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A incerteza no tratamento da COVID-19 gerou inúmeros trabalhos científicos e\nprotocolos. Temos assistido muitas\ncontrovérsias quanto ao uso criterioso de medicações para\ntratamento eficaz. As bases científicas prevêem princípios da Epidemiologia Clínica para a seleção\nde fármacos e de protocolos de tratamento. Quando recomendamos o uso compassivo de um\nfármaco, estamos nos referindo à utilização de fármaco:","options":{"A":"Sem potencial de cura, para melhorar a qualidade de vida.","B":"Em protocolo de pesquisa, sem liberação comercial, na inexistência de outro tratamento.","C":"Em pacientes graves, sem liberação comercial, na inexistência de outro tratamento.","D":"Liberado para uso em outras doenças graves, na inexistência de tratamento testado."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-358786","number":"358786","sourceNumber":"358786","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Para exercer uma boa prática médica o (a) Médico (a) de Família e Comunidade deve\nconsiderar os diversos territórios existenciais e as pluralidades humanitárias que se manifestam em\ncrenças, valores, princípios e ideologias distintas. Buscando o fazer médico humanitário e inclusivo\né correto afirmar:","options":{"A":"O capacitismo é a leitura que se faz a respeito de pessoas com deficiência, assumindo que a\ncondição corporal destas é algo que, naturalmente, as define como menos capazes.","B":"O racismo institucional é o fracasso das instituições e organizações em prover um serviço\nprofissional e adequado às pessoas em virtude\nde sua cor, cultura, origem racial ou étnica. Ele se\nmanifesta em normas, práticas e comportamentos discriminatórios adotados no cotidiano do\ntrabalho, os quais são resultantes do preconceito racial, uma atitude que combina estereótipos\nracistas, falta de atenção e ignorância.","C":"A heteronormatividade impõe padrões e normas sociais excludentes que produzem\nadoecimentos e violência.","D":"O epistemicídio é o silenciamento sistemático dos saberes produzidos por grupos historicamente\noprimidos. O conceito de epistemicídio foi\nelaborado, originalmente, pelo sociólogo português\nBoaventura Souza Santos e pode ser compreendido como um processo que anula e desqualifica o\nconhecimento dos povos subjugados e, além disso, é responsável pelos efeitos de deslegitimação\ndos povos oprimidos.","E":"Todas alternativas anteriores estão corretas."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-358776","number":"358776","sourceNumber":"358776","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O método clínico centrado na pessoa (MCCP) é um modelo de abordagem que facilita a\ncompreensão e a execução das competências essenciais ao MFC. Nessa abordagem o acrônimo\nSIFE permite a identificação de quatro dimensões importantes na utilização desse método. Assinale\na alternativa que exemplifica o componente do MCCP que pode ser melhor compreendido através\ndo acrônimo SIFE.","options":{"A":"Explorando a saúde, a doença e a experiência da doença.","B":"Entendendo a pessoa como um todo ? o indivíduo, a família e o contexto.","C":"Elaborando um plano conjunto de manejo dos problemas.","D":"Intensificando a relação entre a pessoa e o médico.","E":"Sendo Realista."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-358791","number":"358791","sourceNumber":"358791","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Você chega à unidade e a primeira consulta de hoje é com a Dona Magda, matriarca de\numa família bem grande e antiga da cidade.\nEla possui 64 anos e não procura frequentemente a\nassistência em saúde porque sua mãe é uma das moradoras mais antigas da cidade e todos os\ntratamentos dos filhos, ela que assiste, pois acredita que a ?medicina desses moços novos? não\ntinham tanto efeito quanto as plantas e chás que ela usa, pois essas receitas passam de geração\npara geração. A consulta, segundo Dona Magda, é porque a mesma gostaria de realizar exames\npara ver como está sua diabetes. Relata que faz uso de metformina e chás medicinais porque\nacredita que estes ajudam o remédio da diabetes a fazer efeito. Você verifica que os chás em uso\nnão fazem mal para o diabetes e para a saúde dela, concorda com o uso e propõe os exames de\nacompanhamento. Ao final, verifica se Dona Magda concorda com a conduta, ao que responde\npositivamente com um sorriso no rosto. Qual é o atributo da Atenção Primária à Saúde\ncaracterizado no caso?","options":{"A":"Longitudinalidade.","B":"Coordenação do Cuidado.","C":"Competência Cultural.","D":"Orientação para a comunidade.","E":"Hierarquização."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332610","number":"332610","sourceNumber":"332610","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Milene, 17 anos, veio à unidade de saúde do bairro Estrelinha, acompanhada de sua\nfilha, dona Albertina, 65 anos, para consulta\nagendada com sua médica de família, doutora Juliana.\nDona Albertina relata que trouxe a filha \"para fazer preventivo (citopatológico)?, pois ela se\nenvolveu com um rapaz. Dona Albertina, por vergonha, nunca fez exame citopatológico. Milene\ntambém queixa de fluxo vaginal branco com prurido e nega história prévia de doenças ou\ncomorbidades. Seguindo as recomendações de rastreamento do câncer de colo uterino, assinale\nqual conduta da doutora Juliana está correta.","options":{"A":"Orientar sobre a prevenção de infecções sexualmente transmissíveis, realizar coleta de\ncitopatológico e avaliar a queixa clínica da Milene.","B":"Informar que as recomendações atuais de rastreamento do câncer de colo uterino são a partir de\n25 anos de idade e avaliar a queixa da\npaciente.","C":"Aproveitar que a paciente Milene tem queixa de fluxo vaginal e agendar para coleta de exame\ncitopatológico com enfermeira na próxima semana.","D":"Informar à dona Albertina que ela não precisa fazer exame colpocitológico, pois a recomendação\nde rastreamento é até 64 anos.","E":"Questionar dona Albertina a veracidade dos fatos, pois Milene é muito jovem."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332611","number":"332611","sourceNumber":"332611","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Rebeca, 37 anos, médica de família e comunidade, hoje se deparou com cinco\natendimentos em que julgou necessário ou foi questionada quanto a orientações nutricionais. A\nseguir segue a descrição breve de cada atendimento e a orientação que foi dada. Assinale qual\nalternativa indica a orientação nutricional mais adequada.","options":{"A":"Reinaldo, 1 ano e 1 mês: consulta de rotina, puericultura sem queixas ou alterações no exame\nfísico para estimular consumo de suco de frutas entre as refeições.","B":"Gabriela, 27 anos: consulta de rotina, puerpério de 38 dias sem queixas, em aleitamento\nmaterno exclusivo - evitar uso de leite de vaca,\nvisando prevenção de alergia à proteína do leite de\nvaca","C":"Flávio, 30 anos: refere fazer uma única refeição ao dia por desejar emagrecer - orientar o\nconsumo de sopa low carb para o momento da refeição","D":"Marília, 3 anos e 2 meses: trazida por queixa de \"\"não querer comer\"\", embora sem outras\nqueixas e com bom ganho pondero-estatural - incentivar recompensas, como direito a tela, se\ncomer bem.","E":"Roberto, 25 anos: saudável, mas preocupado, pois pai teve diagnóstico de hipertensão arterial\nsistêmica aos 53 anos - privilegiar o consumo de alimentos in natura ou minimamente processados."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332613","number":"332613","sourceNumber":"332613","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paciente com queixa de incômodo em ouvido há uma semana, nega dor ou outros\nsintomas. Na otoscopia, o médico encontra um inseto. A melhor conduta para este caso é:","options":{"A":"o encaminhamento do paciente para serviço de urgência com referência em otorrinolaringologia.","B":"a retirada com pinça kocher na própria unidade.","C":"a realização de lavagem otológica na própria unidade.","D":"a utilização de técnica de aspiração com sugador odontológico se disponível na unidade.","E":"o encaminhamento do paciente para agendamento de consulta em otorrinolaringologia\nambulatorial."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332617","number":"332617","sourceNumber":"332617","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Janaína traz o filho, Ivan, de 8 anos, para consulta. Há uns dois meses, ele tem tido\ncrises de dor abdominal em toda a barriga\nque duram de 10 a 15 minutos e passam\nespontaneamente. Não apresenta outros sintomas, sempre foi saudável e tem desenvolvimento\nadequado. A mãe diz que a alimentação é a mesma, apesar de terem mudado de cidade\nrecentemente. Ao exame físico, Ivan não apresenta dor, nem outro achado relevante. Como\nconduta, o médico solicita exames (hemograma completo, parasitológico de fezes e exame de urina\n\n? elementos e sedimentos anormais) e orienta manter a dipirona para as crises de dor. Faltou na\nconduta do médico:","options":{"A":"aprofundar mais a investigação de doenças graves, como apendicite e obstrução intestinal.","B":"solicitar a glicemia de jejum porque o diabetes tipo I é a causa mais frequente de dor abdominal\nnessa idade.","C":"explorar mais as ideias e sentimentos do paciente em relação à dor e o contexto em que ela\nsurgiu.","D":"dada a gravidade do caso, encaminhar diretamente para o gastroenterologista ou emergência\nhospitalar para investigação.","E":"além dos exames laboratoriais, seria recomendado solicitar uma radiografia simples do abdome\nnessa primeira consulta."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332618","number":"332618","sourceNumber":"332618","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O residente de MFC Rodrigo teve recentemente uma aula sobre Medicina Centrada na\nPessoa e está tentando incorporar seu\naprendizado às suas consultas. Ele está preocupado pois\ntem dificuldades em manejar o tempo de consulta e acredita que se praticar a Medicina Centrada\nna Pessoa suas consultas durarão muito mais tempo. Rodrigo pede ajuda para um MFC mais\nexperiente. Sobre a preocupação de Rodrigo, assinale a alternativa correta.","options":{"A":"Um tempo de consulta reduzido não é compatível com a Medicina Centrada na Pessoa, por isso\no ideal é ao menos 30 minutos por consulta para que se possa perguntar sobre os sentimentos,\nideias e expectativas do paciente.","B":"Um Método Centrado na Pessoa não leva necessariamente a consultas mais longas e a Atenção\nPrimária tem como ponto forte a possibilidade de usar diversas consultas ao longo do tempo para\naprofundar as questões subjetivas mais complexas.","C":"A organização do tempo de consulta tende a ser melhor se o médico escolher somente um\nproblema por consulta e então fazer perguntas sobre as ideias, preocupações e expectativas do\npaciente sobre o problema.","D":"O paciente tem maior satisfação se o tempo de consulta é maior, independentemente de usar ou\nnão técnicas de abordagem centrada na pessoa.","E":"A Medicina Centrada na Pessoa é útil e viável em consultas programadas como consultas de\npré-natal e puericultura. Em consultas de demanda espontânea é recomendada a abordagem\ncentrada no problema."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332619","number":"332619","sourceNumber":"332619","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Dona Florinda, 77 anos, viúva, aposentada, vive em um sobrado de dois quartos com\nseus dois filhos, uma nora e dois netos.\nApresenta hipertensão arterial sistêmica e está em uso\ndiário de losartana 100 mg, atenolol 100 mg, hidroclorotiazida 25 mg e sinvastatina 40 mg. É\nportadora também de perda auditiva de 70% no ouvido esquerdo, e refere zumbido persistente e\nepisódios de tontura, além de dor muscular com piora nos últimos dias. Há dois dias, ao tentar\nlevantar de sua cama de manhã, apresentou síncope e permaneceu desacordada por alguns\ninstantes. Ao acordar, tinha muita dor e edema no antebraço direito e foi levada ao serviço de\nemergência clínica por um de seus filhos, onde foi constatada fratura no punho direito. Foram\nrealizadas analgesia e imobilização locais, assim como relatório de alta, que foi direcionado para a\nUnidade de Atenção Primária onde a paciente é acompanhada. O agente comunitário de saúde\n(ACS) mostra o relatório de alta do serviço de emergência ao médico e avisa que a paciente em\nquestão está na Unidade, solicitando avaliação médica. A conduta correta a ser proposta pelo\nmédico é:","options":{"A":"considerando que não há espaço em sua agenda para atendimento nos próximos dias,\nreferenciar a paciente para especialistas em\ncardiologia e geriatria, uma vez que é uma paciente\ncomplexa e necessita de atenção especial.","B":"recomendar aos filhos por meio de um bilhete que restrinjam as atividades da paciente por conta\nde suas limitações físicas e não a deixem\nsair desacompanhada e solicitar exames\ncomplementares para investigar possível causa da queda.","C":"avaliar a paciente no mesmo dia. Prescrever anti-inflamatórios para dor caso necessário e\nreagendar uma consulta para reavaliação da hipertensão em seis meses.","D":"avaliar a paciente no mesmo dia. Suspender atenolol e sinvastatina, visando a diminuir o risco\nde queda. Reagendar consulta nos próximos dias\npara que a paciente retorne acompanhada de um\nde seus filhos visando a pactuar intervenções conjuntas com a família.","E":"Encaixar uma consulta para Dona Florinda para uma breve avaliação, manter os medicamentos\nanti-hipertensivos e referenciá-la para otorrinolaringologista para que esse profissional\ninvestigue\n\npossíveis causas de queda e solicitar que ela vá à consulta acompanhada de algum familiar."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332620","number":"332620","sourceNumber":"332620","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Cláudia é médica de família em um município no interior de Minas Gerais. Uma das\npacientes cuidadas por Cláudia teve diagnosticado câncer de mama e faleceu aos 37 anos. Essa\nsituação teve grande repercussão no bairro. Porém, neste mesmo mês a Força Tarefa Americana\nlançou uma revisão importante orientando que o rastreio com mamografia tem grau de\nrecomendação B para mulheres entre 50 e 74 anos e grau de recomendação C antes dos 50 anos.\nA melhor conduta para Cláudia com suas pacientes é:","options":{"A":"realizar uma prática clínica orientada para a comunidade na qual está inserida e solicitar\nmamografia anual para todas as mulheres a partir dos 35 anos.","B":"solicitar mamografia a cada dois anos para as mulheres a partir dos 30 anos e anual após os 50\nanos.","C":"solicitar mamografia a cada dois anos para as mulheres a partir dos 40 anos e anual após os 50\nanos.","D":"realizar um seminário com a comunidade e orientar que só a partir dos 40 anos é recomendado\no rastreio e que esse foi um caso isolado na\ncomunidade.","E":"ouvir os medos individuais, explicar o que é o processo de rastreamento e sugerir mamografia\ndos 50 a 74 anos."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332621","number":"332621","sourceNumber":"332621","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um senhor de 71 anos procura o Médico de Família e Comunidade na unidade de\nsaúde onde é cadastrado, porque apresentou\npalpitação de início súbito na noite anterior, sem\nprecordialgia. A ausculta cardíaca revela um ritmo irregular e uma frequência de 120 batimentos por\nminuto, compatível com fibrilação atrial. O paciente é hipertenso e vinha apresentando um controle\nadequado da pressão arterial com o uso de hidroclorotiazida 25 mg uma vez ao dia e captopril 25\nmg duas vezes ao dia. Entre as alternativas abaixo, assinale a que apresenta a melhor conduta\npara este caso.","options":{"A":"Substituir captopril por propranolol.","B":"Prescrever varfarina.","C":"Encaminhar o paciente para a emergência a fim de que se avalie a possibilidade de\ncardioversão.","D":"Prescrever digoxina.","E":"Adotar conduta expectante, reavaliando o paciente em 7 dias."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332625","number":"332625","sourceNumber":"332625","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Educação Popular em Saúde no âmbito do Sistema Único de\nSaúde (PNEPS-SUS) tem como princípios o diálogo,\namorosidade; problematização; construção\ncompartilhada do conhecimento; emancipação; e compromisso com a construção do projeto\ndemocrático e popular. A PNEPS-SUS fundamenta-se, principalmente, em aportes teóricos do\neducador Paulo Freire, assim, assinale a alternativa que melhor define a educação popular:","options":{"A":"uma concepção prático/teórica e uma metodologia de educação bancária que articula diferentes\nsaberes e práticas valorizando as\ndimensões da soberania cultural, assim como o compromisso\ncom o autoritarismo e protagonismo das classes populares nas transformações sociais.","B":"pode ser considerada um movimento contra-hegemônico aos processos de colonização e\nsilenciamento de vozes historicamente oprimidas: seja pela resistência às formas coloniais de\ndominação cultural, política e econômica; pela produção de um pensamento que rompa com a\nsubalternização dos saberes e experiências de sujeitos sociais historicamente marginalizados;","C":"a educação popular se caracterizou, ao longo dos anos, como uma alternativa às pedagogias e\npráticas liberais a serviço da manutenção das estruturas de poder político, favorecendo o poder\nmédico e da ciência.","D":"o uso das práticas integrativas e complementares nas unidades de saúde é uma ação de\neducação popular;","E":"todas as alternativas anteriores estão incorretas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332626","number":"332626","sourceNumber":"332626","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Através da Portaria no 2.979/GM/MS, de 12 de novembro de 2019, o Ministério da\nSaúde institui o Programa Previne Brasil, e\nestabelece novo modelo de financiamento de custeio da\nAtenção Primária à Saúde no âmbito do Sistema Único de Saúde. Os indicadores do pagamento\npor desempenho para 2022, no âmbito do Programa Previne Brasil (Portaria GM/MS n° 102/2022)\nsão:","options":{"A":"proporção de gestantes com pelo menos 6 (seis) consultas pré-natal realizadas, sendo a 1a\n(primeira) até a 12a (décima segunda) semana de gestação; proporção de gestantes com\nrealização de exames para sífilis e HIV; proporção de gestantes com atendimento odontológico\nrealizado; proporção de mulheres com coleta de citopatológico na APS; proporção de crianças de 1\n(um) ano de idade vacinadas na APS contra Difteria, Tétano, Coqueluche, Hepatite B, infecções\ncausadas por haemophilus influenzae tipo b e Poliomielite inativada; proporção de pessoas com\nhipertensão, com consulta e pressão arterial aferida no semestre; e proporção de pessoas com\ndiabetes, com consulta e hemoglobina glicada solicitada no semestre.","B":"proporção de gestantes com pelo menos 6 (seis) consultas pré-natal realizadas, sendo a 1a\n(primeira) até a 12a (décima segunda) semana de gestação; proporção de gestantes com\nrealização de exames para sífilis e HIV; proporção de gestantes com atendimento odontológico\nrealizado; proporção de mulheres com coleta de citopatológico na APS; proporção de pessoas\nacamadas com visita domiciliar mensal; proporção de pessoas com hipertensão, com consulta e\npressão arterial aferida no semestre; e proporção de pessoas com diabetes, com consulta e\nhemoglobina glicada solicitada no semestre.","C":"proporção de gestantes com pelo menos 6 (seis) consultas pré-natal realizadas, sendo a 1a\n(primeira) até a 12a (décima segunda) semana de gestação; proporção de gestantes com\nrealização de exames para sífilis e HIV; proporção de homens com exame PSA realizado;\nproporção de mulheres com coleta de citopatológico na APS; proporção de crianças de 1 (um) ano\nde idade vacinadas na APS contra Difteria, Tétano, Coqueluche, Hepatite B, infecções causadas\npor haemophilus influenzae tipo b e Poliomielite inativada; proporção de pessoas com hipertensão,\n\ncom consulta e pressão arterial aferida no semestre; e proporção de pessoas com diabetes, com\nconsulta e hemoglobina glicada solicitada no semestre.","D":"proporção de gestantes com pelo menos 6 (seis) consultas pré-natal realizadas, sendo a 1a\n(primeira) até a 12a (décima segunda) semana de gestação; proporção de gestantes com\nrealização de USG por mês; proporção de gestantes com atendimento odontológico realizado;\nproporção de mulheres com coleta de citopatológico na APS; proporção de crianças de 1 (um) ano\nde idade vacinadas na APS contra Difteria, Tétano, Coqueluche, Hepatite B, infecções causadas\npor haemophilus influenzae tipo b e Poliomielite inativada; proporção de pessoas com hipertensão,\ncom consulta e pressão arterial aferida no semestre; e proporção de pessoas com diabetes, com\nconsulta e hemoglobina glicada solicitada no semestre.","E":"proporção de gestantes com pelo menos 6 (seis) consultas pré-natal realizadas, sendo a 1a\n(primeira) até a 12a (décima segunda) semana de gestação; proporção de gestantes com\nrealização de USG por mês; proporção de gestantes com atendimento odontológico realizado;\nproporção de mulheres com coleta de citopatológico na APS; proporção de crianças de 1 (um) ano\nde idade vacinadas na APS contra Difteria, Tétano, Coqueluche, Hepatite B, infecções causadas\npor haemophilus influenzae tipo b e Poliomielite inativada; proporção de pessoas com hipertensão,\ncom consulta e eletrocardiograma realizado no semestre; e proporção de pessoas com diabetes,\ncom consulta e hemoglobina glicada solicitada no semestre."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332627","number":"332627","sourceNumber":"332627","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Transtorno do Espectro Autista (TEA) pode ser compreendido como uma síndrome\ncomportamental complexa que possui etiologias múltiplas, fatores maternos, genéticos,\ncomplicações no parto, período neonatal e riscos ambientais (RUTTER, 2011). Rutter M. Progress\nin understanding autism: 2007 ?2010. Journal of Autism and Developmental Disorders. 41, 395\n\n?404 [Internet]. 2011 [cited 2018 Dec 01]. Além das pessoas que convivem com TEA, diversas\noutras convivem em territórios existenciais\npróprios que necessitam de cuidado pela equipe de\nsaúde da família. Nesse sentido, os movimentos sociais em favor das pessoas com deficiência e\nestudiosas, como a antropóloga Débora Diniz (2007), defendem o conceito de deficiência social,\nlogo, sobre o modelo de deficiência social é correto afirmar: DINIZ, D. O que é deficiência São\nPaulo: Editora Brasiliense. 2007.","options":{"A":"Trata-se da experiência de opressão em um contexto corponormativo pouco sensível à variação\ncorporal humana;","B":"Diz respeito a produção social a partir de interações discriminatórias e preconceituosas;","C":"A deficiência deixa de ser um problema médico para ser uma questão econômica, social, de\ndireitos humanos, cultural etc.","D":"A deficiência é uma experiência opressiva em um ambiente que viola direitos e exclui aqueles\nque possuem algum tipo de impedimento sensorial,\nfísico ou intelectual.","E":"Todas as alternativas anteriores estão corretas."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-332628","number":"332628","sourceNumber":"332628","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em 21 de setembro de 2017, o Ministério da Saúde publica a Portaria n. 2.436 que\naprova a Política Nacional de Atenção Básica\n(PNAB), estabelecendo a revisão de diretrizes para a\norganização da Atenção Básica, no âmbito do Sistema Único de Saúde (SUS). Entre as principais\nalterações trazidas pela nova PNAB (2017) estão:","options":{"A":"financiamento federal de equipes de saúde da família e equipes de atenção básica (eAB);\npresença facultativa dos agentes comunitários de\nsaúde (ACS) nas eAB; inserção do gerente de\nunidade básica nas equipes; organização das ações e serviços em essenciais e ampliados; criação\ndo Núcleo Ampliado de Saúde da Família e Atenção Básica (NASF-AB).","B":"financiamento federal de equipes de saúde da família e equipes de atenção básica (eAB);\npresença facultativa dos agentes comunitários de\nsaúde (ACS) nas eAB; integração da equipe de\nsaúde bucal à equipe mínima de Saúde da Família; inserção do gerente de unidade básica nas\nequipes; organização das ações e serviços em essenciais e ampliados.","C":"financiamento federal de equipes de saúde da família e equipes de atenção básica (eAB);\npresença facultativa dos agentes comunitários de\nsaúde (ACS) nas eAB; inserção do gerente de\nunidade básica nas equipes; criação do Núcleo Ampliado de Saúde da Família e Atenção Básica\n(NASF-AB), mas suspensão do repasse federal para esse tipo de equipe.","D":"financiamento federal de equipes de saúde da família e equipes de atenção básica (eAB);\npresença facultativa dos agentes comunitários de\nsaúde (ACS) nas eAB; estabelecimento do\nPREVINE BRASIL como nova forma de financiamento da atenção básica; organização das ações e\nserviços em essenciais e ampliados; criação o Núcleo Ampliado de Saúde da Família e Atenção\nBásica (NASF-AB).","E":"financiamento federal de equipes de saúde da família e equipes de atenção básica (eAB);\npresença facultativa dos agentes comunitários de\nsaúde (ACS) nas eAB; inserção do gerente de\nunidade básica nas equipes; organização das ações e serviços em essenciais e ampliados; criação\ndo Núcleo Ampliado de Saúde da Família e Atenção Básica (NASF-AB); obrigatoriedade de\nprontuário eletrônico do cidadão."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314271","number":"314271","sourceNumber":"314271","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"\"As famílias, diante de problemas de saúde, articulam mecanismos próprios de\nenfrentamento, baseados nas suas crenças e\nvalores culturalmente instalados, assim como na\noferta e disponibilização de recursos sanitários\" (CHAPADEIRO, 2011, p.14). Dessa forma, é\nfundamental que o sistema de saúde e as políticas públicas para o setor atuem de forma a\nminimizar as possíveis vulnerabilidades existentes. Em relação à família e a relação com o sistema\nde saúde, analise as assertivas e identifique com V as verdadeiras e com F as falsas. ( ) O sistema\nde saúde deve reafirmar a família como sujeito do processo de cuidado, garantindo o acesso pleno\nàs políticas públicas de saúde, enquanto direito de cidadania. ( ) As políticas sociais e os\nprogramas assistenciais são irrelevantes para a redução de vulnerabilidades, não interferindo\nefetivamente nos níveis de saúde das famílias. ( ) Aspectos como saneamento básico, condições\nde moradia, trabalho, renda familiar e acesso aos serviços de saúde devem ser considerados na\norganização das ações de saúde. ( ) As ações e serviços de saúde direcionados para famílias e a\ncomunidade se constituem em intervenções coletivas, fragilizando o olhar para as demandas\nindividuais dos usuários. A alternativa que contém a sequência correta, de cima para baixo, é:","options":{"A":"V F V F","B":"V F F V","C":"V V F F","D":"F F V V","E":"F V V F"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314272","number":"314272","sourceNumber":"314272","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A organização das ações de saúde pressupõe uma adequada apropriação do território,\nsobretudo na atenção primária. Dessa forma, é fundamental considerar toda a pluralidade que\nenvolve tanto as dimensões socioeconômicas, políticas e epidemiológicas, quanto os aspectos\nculturais, os valores e símbolos que permeiam as relações e que geram impacto nos níveis de\nsaúde das pessoas e na produção de cuidado (LACERDA et al, 2010). Sobre as dimensões do\nterritório e suas relações com a cidadania e a saúde, analise as assertivas e identifique com V as\nverdadeiras e com F as falsas. ( ) Para organizar as ações de cuidado, as equipes de saúde devem\ncompreender o território como um espaço social em contínua transformação. ( ) Realizar a atenção\nem saúde a partir da identificação dos problemas presentes no território fragiliza a participação\npopular e o controle social por parte da comunidade. ( ) A visualização do espaço território e o\nacompanhamento das características sociossanitárias devem ser tomados como instrumentos de\ntrabalho pelas equipes de saúde. ( ) As atividades de reconhecimento do território e a construção\nde mapas inteligentes são irrelevantes para a atuação das equipes que possuem agentes\ncomunitários de saúde. A alternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"F V F V","B":"F V V F","C":"V V F F","D":"V F F V","E":"V F V F"},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314273","number":"314273","sourceNumber":"314273","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As famílias são consideradas sistemas abertos, dinâmicos e complexos. Ao atuarem na\nperspectiva do território, as equipes de Atenção Primária à Saúde (APS) podem compreender de\nforma mais adequada o contexto de vida e de saúde das famílias acompanhadas, bem como as\npossíveis disfuncionalidades que prejudicam o bem-estar biopsicossocial dos seus membros\n(BRASIL, 2012). Em relação à família enquanto objeto de intervenção, é correto afirmar que","options":{"A":"as equipes de atenção primária à saúde devem organizar as ações de cuidado às famílias,\ntomando por base uma abordagem essencialmente tecnicista.","B":"o chamado \"\"ciclo vital\"\" diz respeito às diversas etapas pelas quais as famílias passam, assim\ncomo aos desafios e tarefas a serem cumpridos em cada etapa.","C":"o estudo do chamado \"\"ciclo vital\"\" das famílias impede que as equipes e profissionais de saúde\nconstruam uma visão panorâmica e focal, simultaneamente.","D":"as famílias que possuem muitas conexões com a comunidade e entre seus membros são\naquelas que necessitam de maior investimento das equipes de saúde.","E":"o contexto social, econômico e político no qual a família e seus membros estão inseridos são\nirrelevantes na organização do cuidado por parte das equipes de saúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314274","number":"314274","sourceNumber":"314274","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Apoio Matricial, também chamado de matriciamento, propõe um arranjo na\norganização dos serviços que complementa as\nequipes de referência. Sendo assim, se constitui em\n\"[...] um modo de realizar a atenção em saúde de forma compartilhada com vistas à integralidade e\nà resolubilidade da atenção, por meio do trabalho interdisciplinar [...]\" (BRASIL, 2004, p.1). Em\nrelação ao Apoio Matricial, é correto afirmar que","options":{"A":"a organização do Apoio Matricial no âmbito da Atenção Primária à Saúde reduz a capacidade de\nintervenção sobre os problemas, em termos clínicos e sanitários.","B":"o Apoio Matricial é uma forma de organizar a oferta de cuidado na qual o usuário, uma vez\nencaminhado, deixa de ser acompanhado pela equipe de referência.","C":"o modelo proposto pelo Apoio Matricial reúne profissionais de diferentes áreas do conhecimento,\nembora impeça que estes atuem de modo\ntransdisciplinar.","D":"o modelo de atendimento proposto pelo Apoio Matricial fragiliza a construção de vínculos\nterapêuticos com os usuários e a responsabilização por parte das equipes.","E":"na Atenção Primária em Saúde, o Apoio Matricial pode se conformar através da relação entre\nequipes de Saúde da Família e Núcleos Ampliados de Saúde da Família (NASF)."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314275","number":"314275","sourceNumber":"314275","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Promoção da Saúde (PNPS) tem como base \"[...] um conjunto de\nestratégias e formas de produzir saúde, no âmbito individual e coletivo [...]\" (BRASIL, 2017, p.1).\n\nTal política foi atualizada pelo Ministério da Saúde (MS) por meio da Portaria de Consolidação nº2,\nde 28 de setembro de 2017, que trata das\nnormas sobre as políticas nacionais de saúde do\nSistema Único de Saúde (SUS). Em relação às diretrizes da Política Nacional de Promoção da\nSaúde (PNPS), analise as opções a seguir e identifique com V as verdadeiras e com F as falsas. ( )\nBusca estimular a cooperação intra e intersetorial para ampliar a atuação sobre os determinantes e\ncondicionantes da saúde. ( ) Incentiva uma gestão pautada pela verticalidade entre os sujeitos de\nforma a garantir a implementação da política junto aos usuários do SUS. ( ) Propõe a incorporação\ndas intervenções de promoção da saúde no modelo de atenção à saúde, especialmente no\ncotidiano dos serviços da atenção especializada. ( ) Busca apoiar a formação e a educação\npermanente em promoção da saúde a fim de ampliar o compromisso e a capacidade crítica e\nreflexiva dos gestores e trabalhadores da saúde. A alternativa que contém, a sequência correta, de\ncima para baixo, é","options":{"A":"V F F V","B":"V F V V","C":"V V F F","D":"F V F V","E":"F F V V"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314278","number":"314278","sourceNumber":"314278","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Vigilância em Saúde, por meio dos seus diferentes componentes, deve realizar ações\nque contemplem toda a população em território\nnacional, buscando priorizar, no entanto, territórios,\npessoas e grupos em situação de maior risco e vulnerabilidade, com vistas à superação das\ndesigualdades sociais e de saúde (BRASIL, 2010). Em relação à Vigilância em Saúde e seus\ncomponentes, é correto afirmar que","options":{"A":"a atuação da Vigilância Ambiental não prevê ações relacionadas à qualidade da água para\nconsumo humano e aos desastres de origem natural.","B":"a Vigilância em Saúde tem como um dos seus aspectos fundamentais o cuidado integral com a\nsaúde das pessoas por meio da promoção da\nsaúde.","C":"a Vigilância em Saúde do Trabalhador deve concentrar sua atuação exclusivamente nas ações\nde reabilitação voltadas aos trabalhadores\nadoecidos.","D":"a Vigilância Sanitária fornece orientação técnica àqueles que têm a responsabilidade de decidir\nacerca da execução das ações de controle de doenças e agravos.","E":"a atuação da Vigilância Epidemiológica está relacionada, sobretudo, a produção e circulação de\nbens, além da prestação de serviços de interesse da saúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314279","number":"314279","sourceNumber":"314279","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Saúde da Criança é uma das áreas programáticas mais relevantes no âmbito do\nSistema Único de Saúde (SUS). Nesse sentido,\na Atenção Primária à Saúde (APS) possui papel\nfundamental e deve conduzir as ações de cuidado com um olhar biopsicossocial não apenas\nvoltado à criança, mas também, ao contexto de vida e de saúde na qual ela está inserida (BRASIL,\n2012). Em relação à Saúde da Criança no âmbito da APS, analise as assertivas e identifique com V\nas verdadeiras e com F as falsas. ( ) Em todas as visitas domiciliares, é fundamental que o\nprofissional de saúde saiba identificar sinais de perigo à saúde da criança. ( ) No caso de ser a\nporta de entrada ou o primeiro contato, as equipes de atenção básica devem notificar as situações\nde suspeita ou confirmação de violência contra a criança. ( ) É desaconselhável que as equipes de\nsaúde visitem as crianças e suas famílias após a primeira semana de vida, de forma a estimular o\ncomparecimento ao serviço de saúde. ( ) A participação paterna assume papel secundário no\ndesenvolvimento da criança e, portanto, é irrelevante estimular o engajamento dos pais nas ações\nrelacionadas à saúde infantil. A alternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"V V F F","B":"V F V F","C":"V F F V","D":"F V F V","E":"F V V F"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314280","number":"314280","sourceNumber":"314280","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"\"A natureza multidimensional do ser humano requer práticas profissionais\ninterdisciplinares [...]\" (SCHERER; PIRES;\nJEAN, 2013, p.3204) que possam contemplar a\ncomplexidade do processo saúde-doença\". Nesse contexto, a atenção centrada na família,\nentendida e percebida a partir do seu ambiente físico e social, possibilita realizar intervenções\nque\nvão além de práticas curativas. Em relação às práticas interdisciplinares no cuidado e sua relação\ncom a família, é correto afirmar que","options":{"A":"a interdisciplinaridade, enquanto prática imposta às equipes de saúde contribui para fragilizar o\ncuidado ofertado às famílias.","B":"no âmbito da atenção primária, as práticas interdisciplinares conduzem a uma perda da\nautonomia e individualidade dos profissionais.","C":"a interdisciplinaridade no cuidado exige a integração de diferentes saberes e práticas e\ncontribui\npara qualificar o cuidado ofertado às\nfamílias.","D":"a interdisciplinaridade no cuidado se apresenta como um processo complexo e que demanda\nmúltiplos recursos, tornando inviável a sua efetivação na prática.","E":"no âmbito da atenção primária, a interdisciplinaridade deve ser desestimulada, considerando o\ncenário de disputa entre as diversas categorias profissionais."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314281","number":"314281","sourceNumber":"314281","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Saúde da Pessoa Idosa (PNSPI) tem como finalidade \"[...]\nrecuperar, manter e promover a autonomia e a\nindependência dos indivíduos idosos [...]\" (BRASIL,\n2006, p.3). Para tanto, esta política traz em seus conteúdos um conjunto de diretrizes que devem\nnortear sua implementação no âmbito do Sistema Único de Saúde (SUS). Em relação às diretrizes\npreconizadas pela PNSPI, analise as assertivas e identifique com V as verdadeiras e com F as\nfalsas. ( ) Na atenção básica, deve-se buscar a incorporação de mecanismos que promovam a\nmelhoria da qualidade e o aumento da resolutividade da atenção à pessoa idosa. ( ) A prática de\ncuidados às pessoas idosas exige abordagem global, interdisciplinar e multidimensional, que\nconsidere os fatores físicos, psicológicos e sociais. ( ) As ações intersetoriais que visam a\nintegralidade da atenção à saúde da pessoa idosa devem ser desestimuladas, ainda que\nconsiderem as características e necessidades locais. ( ) A atenção integral à saúde da pessoa\nidosa dispensa a estruturação de uma linha de cuidados devido à complexidade das demandas de\nsaúde apresentadas por este grupo etário. A alternativa que contém a sequência correta, de cima\npara baixo, é","options":{"A":"F V F V","B":"F V V F","C":"V F V F","D":"V V F F","E":"V F F V"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314282","number":"314282","sourceNumber":"314282","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A utilidade dos sistemas de informação em saúde depende da \"[...] disponibilidade de\ninformação apoiada em dados válidos e confiáveis\" (BRASIL,2021, p.1). Nesse sentido, o Sistema\nde informação do Programa Nacional de Imunizações (SI-PNI) emerge como um sistema\nfundamental, possibilitando aos gestores envolvidos no programa a tomada de decisões baseadas\nem evidências. Em relação ao Sistema de informação do Programa Nacional de Imunizações\n\n(SI-PNI), é correto afirmar que","options":{"A":"as funcionalidades do SI-PNI são limitadas à realização do cálculo acerca da cobertura vacinal\npor estados e municípios.","B":"o SI-PNI impede que seja feita uma avaliação dinâmica do risco quanto à ocorrência de surtos\nou epidemias, a partir do quantitativo\npopulacional vacinado.","C":"o SI-PNI não permite o acompanhamento de casos de reação adversa ocorridos pós-vacinação,\ntampouco a identificação e localização de\nlotes de vacinas.","D":"as funcionalidades do SI-PNI são limitadas à consolidação do quantitativo populacional\nvacinado, organizado por faixa etária e em determinada área geográfica.","E":"o SI-PNI possibilita o controle do estoque de imunobiológicos, gerando informações necessárias\npara que sejam programados os processos de\naquisição e distribuição."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314283","number":"314283","sourceNumber":"314283","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"\"A vigilância em saúde tem por objetivo a observação e análise permanentes da\nsituação de saúde da população,\narticulando-se em um conjunto de ações destinadas a controlar\nos determinantes, riscos e danos à saúde de populações [...] \" (BRASIL, 2010, p.16). Estas ações\ntêm papel fundamental no âmbito do Sistema Único de Saúde (SUS), contribuindo para a\nintegralidade do cuidado. Em relação à Vigilância em Saúde, analise as assertivas e identifique com\nV as verdadeiras e com F as falsas. ( ) A Vigilância em Saúde deve estar inserida na construção\ndas redes de atenção à saúde, coordenadas pela Atenção Especializada. ( ) As ações da Vigilância\nem Saúde possuem especificidades que as tornam incompatíveis com as práticas das equipes da\natenção primária no território. ( ) As ações da Vigilância em Saúde devem estar cotidianamente\ninseridas em todos os níveis de atenção, abrangendo os serviços de saúde públicos e privados. ( )\nNa atenção primária, a Vigilância em Saúde contribui para as ações de planejamento, de maneira a\norganizar os serviços com ações programadas de atenção à saúde das pessoas. A alternativa que\ncontém a sequência correta, de cima para baixo, é","options":{"A":"V F V F","B":"V F F V","C":"F V F V","D":"F F V V","E":"F V V F"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314284","number":"314284","sourceNumber":"314284","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Básica (AB) compreende um \"[...] conjunto de ações de saúde individuais,\nfamiliares e coletivas que envolvem\npromoção, prevenção, proteção, diagnóstico, tratamento,\nreabilitação, redução de danos, cuidados paliativos e vigilância em saúde [...]\" (BRASIL, 2017,\np.2).\nNesse contexto, a Estratégia Saúde da Família (ESF) emerge como a estratégia prioritária para\nexpandir e fortalecer a AB. Sobre a ESF e a AB, analise as assertivas e identifique com V as\nverdadeiras e com F as falsas. ( ) O cuidado centrado na pessoa é uma das diretrizes da AB e\naponta para o desenvolvimento de ações de cuidado de forma singularizada. ( ) A equipe de Saúde\nda Família deve ser composta, no mínimo, por médico, enfermeiro, nutricionista, técnico de\nenfermagem e agente comunitário de saúde (ACS). ( ) Na AB, os Núcleos Ampliados de Saúde da\nFamília (NASF) são serviços com unidades físicas independentes, sendo de livre acesso para\natendimento individual e coletivo. ( ) A longitudinalidade do cuidado pressupõe a continuidade da\nrelação de cuidado, com construção de vínculo e responsabilização entre profissionais e usuários\nao longo do tempo. A alternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"V F V F","B":"V V F F","C":"V F F V","D":"F V F V","E":"F V V F"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314285","number":"314285","sourceNumber":"314285","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Na Atenção Básica (AB), os cuidados direcionados à Saúde da Mulher devem buscar\nsuperar a restrição de realizar tão\nsomente ações programáticas, investindo no desenvolvimento de\nações abrangentes de saúde, de acordo com as necessidades de saúde das usuárias (BRASIL,\n2016). Em relação à Saúde da Mulher no âmbito da AB, é correto afirmar que","options":{"A":"a construção de vínculo terapêutico produz dependência com relação à equipe de saúde,\nreduzindo a autonomia das usuárias diante do processo saúde-doença.","B":"é dispensável a operacionalização de uma clínica ampliada que aborde a usuária para além de\nsuas doenças e queixas, devido ao vínculo\nexistente com a equipe.","C":"se deve buscar a humanização das relações entre profissionais de saúde e usuárias no que se\nrefere à forma de escutar as usuárias em seus problemas e demandas.","D":"na AB, as ações voltadas para a Saúde da Mulher devem estar concentradas apenas na saúde\nreprodutiva e na prevenção dos cânceres de colo de útero e de mama.","E":"as situações de violência contra a mulher são encaminhadas aos serviços de referência pela AB\nque deixa, a partir de então, de acompanhar a\nusuária de forma regular."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314290","number":"314290","sourceNumber":"314290","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a Lei nº 8.080, de 19 de setembro de 1990 e alterações posteriores,\n\"[...] as ações e serviços públicos de saúde\ne os serviços privados contratados ou conveniados que\nintegram o Sistema Único de Saúde (SUS) [...]\" (BRASIL, 1990, p.3) devem ser norteados pelas\ndiretrizes previstas na Constituição Federal, além de obedecer a determinados princípios. Em\nrelação aos princípios do SUS, previstos pela Lei nº 8.080/1990 e alterações posteriores, é correto\nafirmar que","options":{"A":"é prevista a organização dos serviços públicos de modo que seja garantida a duplicidade de\nmeios para fins idênticos.","B":"o direito das pessoas de terem informações sobre a própria saúde deve ser garantido enquanto\nprincípio do SUS.","C":"são previstas a regionalização e a hierarquização da rede de serviços de saúde, além da\ndescentralização, que deve ocorrer com ênfase para os estados.","D":"a participação da comunidade não é trazida entre os princípios contemplados nesta normativa,\npois seria objeto de legislação específica\nposteriormente.","E":"a utilização da epidemiologia para o estabelecimento de prioridades assume papel secundário\nno que diz respeito à alocação de recursos e à\norientação programática."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283852","number":"283852","sourceNumber":"283852","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Domiciliar se constitui numa modalidade de atenção à saúde garantida pelo\nSistema Único de Saúde (SUS). O chamado \"Melhor em Casa\" é uma iniciativa do Ministério da\nSaúde e compreende um conjunto de ações prestadas em domicílio, que visam à integralidade do\ncuidado ofertado e que deve ocorrer de forma integrada às redes de atenção à saúde (BRASIL,\n2013). Sobre a Atenção Domiciliar no âmbito do SUS, é correto afirmar que","options":{"A":"deve ser estruturada na perspectiva das Redes de Atenção à Saúde, coordenando as ações\nrealizadas pela atenção básica.","B":"a ampliação da autonomia dos usuários e o incremento da demanda por atendimento hospitalar\nestão entre os objetivos da Atenção\nDomiciliar.","C":"tem como um dos seus objetivos a reorganização do processo de trabalho das equipes que\nprestam cuidado domiciliar na atenção básica.","D":"embora tenha como princípios o acolhimento e a humanização, esta modalidade reduz o acesso\ndos usuários aos demais pontos das redes de\natenção à saúde.","E":"as ações da Atenção Domiciliar são realizadas de forma independente dentro das redes de\natenção e, portanto, dispensam articulações com as linhas de cuidado."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283853","number":"283853","sourceNumber":"283853","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Vigilância em Saúde se refere ao \"[...] processo contínuo e sistemático de coleta,\nconsolidação, análise de dados e disseminação de informações sobre eventos relacionados à\nsaúde [...]\" (BRASIL, 2018, p. 2). As ações da vigilância são fundamentais no âmbito do Sistema\nÚnico de Saúde (SUS) e contribuem para o planejamento, a gestão e a implementação de medidas\nem saúde pública (BRASIL, 2018). Em relação à Vigilância em Saúde, é correto afirmar que","options":{"A":"a vigilância epidemiológica realiza ações que abrangem a prestação de serviços e o controle de\nbens de consumo que se relacionem com a\nsaúde.","B":"as ações da vigilância em saúde abrangem exclusivamente os serviços de saúde pública e são\ninerentes a todos os níveis e formas de atenção à saúde.","C":"as ações da vigilância sanitária compreendem um conjunto de medidas voltadas para a\nprevenção e o controle das doenças transmissíveis e agravos à saúde.","D":"a análise de situação de saúde e as ações laboratoriais são atividades transversais e assumem\npapel secundário no processo de trabalho da Vigilância em Saúde.","E":"as ações da vigilância em saúde ambiental se relacionam às mudanças nos fatores\ndeterminantes e condicionantes do meio ambiente, que interferem na saúde humana."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283859","number":"283859","sourceNumber":"283859","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A chamada Clínica Ampliada aponta para o enfrentamento de uma prática clínica ainda\nhegemônica atualmente e deve ser entendida como uma das diretrizes impostas pelos princípios do\nSistema Único de Saúde (SUS). Nesse contexto, é fundamental repensar e implementar mudanças\nnos modelos de atenção e de gestão dos processos de trabalho em saúde (BRASIL, 2010). Em\nrelação à Clínica Ampliada, é correto afirmar que","options":{"A":"tem como objetivo produzir saúde e reduzir o grau de autonomia dos sujeitos.","B":"a doença e o sintoma são seus principais objetos, sendo a cura seu objetivo principal.","C":"define a intervenção terapêutica considerando exclusivamente os aspectos orgânicos.","D":"realiza a avaliação diagnóstica reduzindo esta prática à necessária objetividade clínica.","E":"preconiza uma prática clínica que aposta nas equipes multiprofissionais e transdisciplinares."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283860","number":"283860","sourceNumber":"283860","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O processo de trabalho das equipes que atuam na Estratégia Saúde da Família (ESF)\nocorre na perspectiva do território. Dessa\nforma, a proposta conhecida como Programação e\nPlanejamento Local em Saúde (PPLS) contribui para que as equipes possam intervir de forma\nqualificada e oportuna frente às demandas de saúde da população sob sua responsabilidade\nsanitária (COSTA; PINHO, 2014). Em relação à PPLS, analise as assertivas e identifique com V as\nverdadeiras e com F as falsas. ( ) O primeiro passo para que seja realizada uma programação local\nem saúde é o conhecimento do território por meio da análise de situação de saúde. ( ) A\nplanificação diante de um problema identificado pela equipe de saúde se traduz pela\nsistematização das decisões e estratégias de enfrentamento. ( ) O enfrentamento dos problemas na\nPPLS deve preceder à análise de situação de saúde, a fim de resolver com rapidez as demandas\nde saúde da população. ( ) É dispensável a participação social no planejamento das ações em\nsaúde, considerando o caráter técnico desta área do conhecimento, inerente aos gestores. A\nalternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"V F V F","B":"V V F F","C":"V F F V","D":"F V F V","E":"F V V F"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283861","number":"283861","sourceNumber":"283861","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Atenção Integral à Saúde do Homem (PNAISH) foi lançada pelo\nMinistério da Saúde com o intuito de promover a melhoria das condições de saúde da população\nmasculina brasileira. Em seus conteúdos são abordadas as diretrizes que devem nortear os planos,\nprogramas, projetos e ações de saúde voltados para esta população (BRASIL, 2009). Em relação\nàs diretrizes da PNAISH, é correto afirmar que","options":{"A":"a assistência à saúde do homem nos diversos pontos de atenção da rede dispensa a\nperspectiva de uma linha de cuidado.","B":"a implementação desta política deve ocorrer de forma hierarquizada, priorizando as ações da\natenção especializada e hospitalar.","C":"a execução desta política deve ser feita de forma dissociada das demais políticas do Ministério\nda Saúde, devido as especificidades do tema\ntratado.","D":"é proposta uma reorganização das ações de saúde de forma que os homens considerem os\nserviços de saúde também como espaços masculinos.","E":"a compreensão acerca da complexidade dos modos de vida e da situação social do indivíduo\nassume papel secundário em se tratando de saúde do homem."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283864","number":"283864","sourceNumber":"283864","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Humanização da Atenção e Gestão no Sistema Único de Saúde\n(HumanizaSUS) entende que a humanização se traduz na valorização dos sujeitos envolvidos nas\npráticas de produção de saúde. Nesta perspectiva, a humanização deve ser vista não como\nprograma, mas como uma política pública que transversaliza as diferentes ações e instâncias\ngestoras do SUS (BRASIL, 2010). Em relação ao HumanizaSUS, analise as assertivas e identifique\ncom V as Verdadeiras e com F as Falsas. ( ) Defende que deve ser feito um trabalho coletivo para\nque o SUS seja mais acolhedor, mais ágil, ainda que suas ações sejam menos resolutivas. ( )\nPropõe o estabelecimento de vínculos solidários e de participação coletiva no processo de gestão,\nfomentando a autonomia e o protagonismo de sujeitos e coletivos. ( ) Preconiza mudanças nos\nmodelos de atenção e gestão com foco nas necessidades dos cidadãos, na produção de saúde e\nno próprio processo de trabalho em saúde. ( ) Propõe mudanças a fim de que a atenção e a gestão\ndo SUS possam atuar de forma dissociada, com o intuito de garantir a autonomia e o protagonismo\ndos sujeitos e coletivos. A alternativa que contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"F-V-F-V.","B":"F-V-V-F.","C":"F-F-V-V.","D":"V-F-V-F.","E":"V-F-F-V."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283865","number":"283865","sourceNumber":"283865","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As ações de educação em saúde são inerentes às práticas de produção em saúde e se\nconstituem num processo que deve ser sistemático, contínuo e permanente. Estas ações\ncontribuem de maneira fundamental para a promoção de saúde, a prevenção e o controle de\ndoenças e agravos, na busca pela melhoria da qualidade de vida da população (BRASIL, 2007).\n\nEm relação à educação em saúde, é correto afirmar que","options":{"A":"a prática educativa parte do princípio de respeitar o universo cultural das pessoas e as formas\nde\norganização da comunidade.","B":"as experiências, valores, crenças e conhecimentos populares são irrelevantes nesse contexto,\ndevido ao seu caráter técnico e científico.","C":"a educação em saúde contribui para a formação da consciência crítica das pessoas, embora não\npossa ser considerada uma prática social.","D":"o objetivo da educação em saúde é a transformação, e este processo dispensa a participação\npopular, devendo ser conduzido pelo poder\npúblico.","E":"as ações de educação em saúde devem ser realizadas de forma verticalizada junto à população\nna medida em que aborda temas técnicos da área\nda saúde."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283866","number":"283866","sourceNumber":"283866","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As ações da vigilância em saúde são fundamentais na operacionalização do Sistema\nÚnico de Saúde (SUS). Devem orientar o\nmodelo de atenção nos territórios, sendo transversais a\ntodos os níveis e formas de atenção, compreendendo a articulação de diferentes saberes,\nprocessos e práticas (BRASIL, 2011). Em relação à vigilância em saúde, analise as assertivas e\nidentifique com V as verdadeiras e com F as falsas. ( ) A vigilância em saúde ambiental intervém\nsobre a prestação de serviços e o controle de bens de consumo que, direta ou indiretamente, se\nrelacionem com a saúde. ( ) A vigilância epidemiológica contribui para o conhecimento e a detecção\nde mudanças nos fatores determinantes e condicionantes da saúde individual e coletiva. ( ) A\nvigilância sanitária propicia o conhecimento e a detecção de mudanças nos fatores determinantes e\ncondicionantes do meio ambiente, que interferem na saúde humana. ( ) A vigilância em saúde do\ntrabalhador intervém nas doenças e agravos e seus determinantes, decorrentes dos modelos de\ndesenvolvimento, de processos produtivos e de trabalho. A alternativa que contém a sequência\ncorreta, de cima para baixo, é","options":{"A":"V F V F","B":"V V F F","C":"F V V F","D":"F F V V","E":"F V F V"},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283868","number":"283868","sourceNumber":"283868","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Promoção da Saúde (PNPS) foi redefinida pelo Ministério da\nSaúde (MS) por meio da Portaria nº 2.446, de\n11 de novembro de 2014. Em seu conteúdo são\nencontrados, além dos seus objetivos, princípios e diretrizes, os eixos operacionais e os chamados\ntemas prioritários que devem orientar a implementação da referida política no âmbito do SUS\n(BRASIL, 2014). É considerado tema prioritário de acordo com a PNPS:","options":{"A":"a equidade, ao basear as práticas e as ações de promoção de saúde, considerando as\nespecificidades dos indivíduos e dos grupos.","B":"a integralidade, quando as intervenções são pautadas no reconhecimento da complexidade,\npotencialidade e singularidade de indivíduos, grupos e coletivos.","C":"a formação e a educação permanente, que compreende mobilizar, sensibilizar e promover\ncapacitações para gestores, trabalhadores da saúde e de outros setores.","D":"a autonomia, que se refere à identificação de potencialidades e ao desenvolvimento de\ncapacidades, possibilitando escolhas conscientes de sujeitos e comunidades.","E":"a intrassetorialidade, que diz respeito à desfragmentação das ações e serviços ofertados por um\nsetor, visando à construção e articulação de redes cooperativas e resolutivas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283869","number":"283869","sourceNumber":"283869","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As equipes de Saúde da Família atuam na perspectiva do território, ofertando cuidados\naos indivíduos, às famílias e à comunidade sob\nsua responsabilidade sanitária. Tomar a família\ncomo objeto de intervenção, requer que os profissionais compreendam a família que está\nrecebendo estes cuidados, sua estrutura e funcionalidade (BRASIL, 2012). Em relação à família\nenquanto objeto de intervenção, analise as assertivas e identifique com V as verdadeiras e com F\nas falsas. ( ) A abordagem às famílias é um elemento de gestão do cuidado e, também, de prática\ndiagnóstica e terapêutica. ( ) As interações, os conflitos e as desagregações fazem parte do\nuniverso da família, interferindo diretamente na saúde de seus membros. ( ) Uma família que tem\npoucas conexões com a comunidade e entre seus membros necessita menor investimento por\nparte da equipe de saúde. ( ) A família deve ser entendida a partir de suas relações e, dessa forma,\no contexto social, econômico e político não influenciam no bem-estar da família e de seus\nmembros. A alternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"V V F F","B":"V F V F","C":"V F F V","D":"F F V V","E":"F V V F"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283870","number":"283870","sourceNumber":"283870","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Básica (AB) se constitui na principal porta de entrada para o Sistema Único\nde Saúde (SUS). Deve ser o contato\npreferencial dos usuários com o sistema de saúde e atua\ncomo coordenadora do cuidado e ordenadora para as Redes de Atenção à Saúde (RAS). A\nEstratégia Saúde da Família (ESF) foi escolhida como estratégia prioritária para a expansão,\nconsolidação e qualificação da AB (BRASIL, 2017). Em relação à ESF e a AB, analise as assertivas\ne identifique com V as verdadeiras e com F as falsas. ( ) A equipe de saúde da família deve ser\ncomposta no mínimo por médico, enfermeiro, agente comunitário de saúde e fisioterapeuta. ( ) A\nESF atua na perspectiva do território, com equipes multiprofissionais, sendo pautada pela\nlongitudinalidade do cuidado ofertado às pessoas com as quais constrói vínculos. ( ) O número de\nagentes comunitários de saúde presente em cada equipe de saúde da família é definido pelo gestor\nlocal a despeito de critérios demográficos e epidemiológicos. ( ) A AB deve ser capaz de resolver a\nmaioria dos problemas de saúde da população, coordenando o cuidado do usuário em outros\npontos das RAS, quando necessário. A alternativa que contém a sequência correta, de cima para\nbaixo, é","options":{"A":"F V F V","B":"F V V F","C":"F F V V","D":"V F V F","E":"V F F V"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283871","number":"283871","sourceNumber":"283871","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os Modelos Assistenciais em Saúde se constituem em formas de organizar a atenção à\nsaúde e articular os diferentes recursos\nfísicos, tecnológicos e humanos, tendo em vista o\nfuncionamento das Redes de Atenção à Saúde, as relações entre os componentes da rede e as\nintervenções sanitárias para enfrentamento das demandas de saúde da população (BRASIL, 2004).\nEm relação aos Modelos Assistenciais em Saúde, é correto afirmar que","options":{"A":"o modelo médico assistencial privatista propõe a incorporação de novos sujeitos nas práticas de\nprodução de saúde, envolvendo a população organizada.","B":"o modelo sanitarista se concretiza nos hospitais e unidades de saúde do SUS, nas quais se\nreproduz a lógica de atendimento à demanda espontânea.","C":"o modelo sanitarista organiza a prestação de serviços de saúde através do atendimento\nindividual e curativo prestado pelo médico e outros profissionais da saúde.","D":"o modelo de vigilância em saúde estimula a mobilização, a organização e a atuação dos\ndiversos grupos na promoção e na defesa das condições de vida e saúde.","E":"o modelo de vigilância em saúde se concretiza por meio das campanhas e programas de saúde\npública, sendo predominante no SUS como forma de organização das ações."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283872","number":"283872","sourceNumber":"283872","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Projeto Terapêutico Singular (PTS) se constitui numa ferramenta tecnológica de\napoio à atenção em saúde. Trata-se de \"um\nconjunto de propostas de condutas terapêuticas\narticuladas, para um sujeito individual ou coletivo, resultado da discussão coletiva de uma equipe\ninterdisciplinar, com apoio matricial, se necessário\" (BRASIL, 2010, p. 27). Em relação ao PTS,\nanalise as assertivas e identifique com V as Verdadeiras e com F as Falsas. ( ) O PTS pode ser\nelaborado para grupos ou famílias, e não só para indivíduos; ( ) O PTS é uma variação da\ndiscussão de \"caso clínico\", sendo dedicado às situações de menor complexidade; ( ) No momento\nde reavaliação do PTS, deve ser discutida a evolução do caso e serem feitas as devidas correções\ndos rumos tomados; ( ) Na definição de metas do PTS, a negociação deve ser feita,\npreferencialmente, pelo membro da equipe que não tiver vínculos com o usuário. A alternativa que\ncontém a sequência CORRETA, de cima para baixo, é:","options":{"A":"F ? V ? F ? V.","B":"F ? V ? V ? F.","C":"V ? V ? F ? F.","D":"V ? F ? V ? F.","E":"V ? F ? F ? V."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283873","number":"283873","sourceNumber":"283873","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Saúde da Pessoa Idosa se constitui numa das áreas programáticas mais relevantes\nno contexto do Sistema Único de Saúde (SUS).\nNesta perspectiva, a Política Nacional de Saúde da\nPessoa Idosa (PNSPI) foi lançada pelo Ministério da Saúde (MS) com a finalidade de recuperar,\nmanter e promover a autonomia e a independência dos indivíduos idosos (BRASIL, 2006). De\nacordo com a PNSPI, é correto afirmar que","options":{"A":"as intervenções curativas são sempre preferíveis a uma abordagem preventiva e à intervenção\nprecoce.","B":"a atenção integral e integrada à saúde da pessoa idosa dispensa os moldes de uma linha de\ncuidados.","C":"a prática de cuidados às pessoas idosas exige uma abordagem global, interdisciplinar e\nmultidimensional.","D":"a identificação e o reconhecimento da rede de suporte social são irrelevantes na avaliação\nsistemática da pessoa idosa.","E":"nas intervenções e orientações à pessoa idosa, a autonomia e a independência funcional devem\nser desencorajadas, a fim de prevenir acidentes e\nquedas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281907","number":"281907","sourceNumber":"281907","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O objetivo no indivíduo idoso diabético deve ser definido entre duas opções,\nadequadamente posicionadas no item:","options":{"A":"Controle glicêmico rigoroso e menor progressão das complicações crônicas; ou controle\nglicêmico não rigoroso, apenas evitar sintomas de hiperglicemia e complicações agudas.","B":"Controle glicêmico rigoroso e maior progressão das complicações crônicas; ou controle\nglicêmico não rigoroso, apenas evitar sintomas de hiperglicemia e complicações agudas.","C":"Controle glicêmico rigoroso e menor progressão das complicações agudas; ou controle glicêmico\nnão rigoroso, apenas evitar sintomas de\nhiperglicemia e complicações agudas.","D":"Controle glicêmico rigoroso e menor progressão das complicações crônicas; ou controle\nglicêmico rigoroso, apenas evitar sintomas de hiperglicemia e complicações agudas."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-281908","number":"281908","sourceNumber":"281908","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No caso de realização de exames em consultórios ou clínicas que não tenham os\nprotocolos instituídos, recomenda-se:","options":{"A":"Realizar limpeza e desinfecção para qualquer patógeno transmissível na barra de apoio do\nergômetro, tapete da esteira, selim do cicloergômetro, manguito do esfigmomanômetro,\nestetoscópio e não em outras superfícies de contato utilizando um ou mais dos produtos\nrecomendados.","B":"Realizar limpeza e desinfecção para qualquer patógeno transmissível na barra de apoio do\nergômetro, tapete da esteira, selim do cicloergômetro, manguito do esfigmomanômetro,\nestetoscópio e outras superfícies de contato utilizando um ou mais dos produtos não\nrecomendados.","C":"Realizar limpeza e desinfecção para qualquer patógeno transmissível na barra de apoio do\nergômetro, tapete da esteira, selim do cicloergômetro, manguito do esfigmomanômetro,\nestetoscópio e outras superfícies de contato utilizando um ou mais dos produtos recomendados.","D":"Nunca realizar limpeza e desinfecção para qualquer patógeno transmissível na barra de apoio\ndo ergômetro, tapete da esteira, selim do cicloergômetro, manguito do esfigmomanômetro,\nestetoscópio e outras superfícies de contato utilizando um ou mais dos produtos recomendados."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249708","number":"249708","sourceNumber":"249708","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Ministério da Saúde lançou, em 2003, a Política Nacional de Humanização da\nAtenção e da Gestão do SUS (PNH). Seus\nconteúdos devem transversalizar as diferentes ações e\ninstâncias gestoras, corresponsabilizando todos os envolvidos nas práticas de produção de saúde.\nAlém disso, apresenta princípios, a partir dos quais se desdobra enquanto política de saúde\n(BRASIL, 2010). Em relação aos princípios da PNH, analise as assertivas e identifique com V as\nverdadeiras e com F as falsas. ( ) O protagonismo, a corresponsabilidade e a autonomia dos\nsujeitos e coletivos são preconizados nas praticas de produção de saúde.; ( ) A transversalidade\npropõe o aumento da comunicação intra e intergrupos, embora não inclua neste processo os\ngestores da saúde.; ( ) A transversalidade propõe uma desestabilização das fronteiras dos saberes,\ndos territórios de poder e dos modos instituídos na constituição das relaç~ies de trabalho.; ( ) A\nindissociabilidade entre atenção e gestão entende que clínica e política devem atuar\nseparadamente, pois a produção de saúde não interfere na produção de sujeitos. A alternativa que\ncontém a sequencia correta, de cima para baixo, é","options":{"A":"V F F F","B":"V V F V","C":"V F V F","D":"F V V V","E":"F F V F"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249709","number":"249709","sourceNumber":"249709","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Atenção Integral à Saúde do Homem foi instituída pelo Ministério\nda Saúde por meio da Portaria nº 1.944, de 27\nde agosto de 2009. Tal normativa tem como objetivo\nprimordial a busca pela melhoria das condições de saúde da população masculina brasileira\n(BRASIL, 2009). Em relação às diretrizes que norteiam a Política Nacional de Atenção Integral à\nSaúde do Homem, analise as assertivas e identifique com V as Verdadeiras e com F as Falsas. ( )\nOs serviços públicos de saúde devem estar organizados de modo a acolher e fazer com que o\nhomem se sinta integrado. ( ) É prevista a reorganização das ações de saúde, priorizando as ações\nvoltadas à saúde do homem, em detrimento dos demais grupos populacionais. ( ) Deve-se buscar\ncompreender os agravos e a complexidade dos modos de vida e da situação social do indivíduo,\ncom vistas à integralidade do cuidado. ( ) Deve-se priorizar a atenção especializada, com foco nas\nações de média e alta complexidade, tendo em vista as especificidades das demandas do público\nmasculino. A alternativa que contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"V-F-F-V.","B":"V-F-V-F.","C":"V-V-F-F.","D":"F-V-F-V.","E":"F-V-V-F."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249711","number":"249711","sourceNumber":"249711","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Promoção da Saúde (PNPS) foi redefinida por meio da Portaria\nnº 2.446, de 11 de novembro de 2014, trazendo,\nem seus conteúdos, os valores, princípios,\ndiretrizes e eixos operacionais que devem nortear e garantir a sua implementação no âmbito do\nSistema Único de Saúde - SUS (BRASIL, 2014). Em relação às diretrizes da PNPS, é correto\nafirmar que","options":{"A":"é proposta uma redução da governança, a fim de garantir o desenvolvimento de ações de\npromoção da saúde que sejam sustentáveis.","B":"busca fomentar o planejamento de ações territorializadas de promoção da saúde, a despeito do\nreconhecimento de contextos locais e respeito às diversidades.","C":"a PNPS busca incorporar intervenções de promoção da saúde no modelo de atenção à saúde,\nespecialmente no cotidiano dos serviços de atenção especializada.","D":"há um incentivo aos modelos de gestão verticalizados para garantir a hierarquização como\nprincípio do SUS, embora reconheça a importância do controle social.","E":"incentiva a formação e a educação permanente em promoção da saúde para ampliar o\ncompromisso e a capacidade crítica e reflexiva dos gestores e trabalhadores da saúde."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249713","number":"249713","sourceNumber":"249713","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os Modelos Assistenciais em Saúde se constituem em combinações de tecnologias\nque contribuem para organizar a assistência e o\nfuncionamento das redes de atenção à saúde, com\no objetivo de intervir sobre as demandas e necessidades de saúde da população. No Brasil, é\nobservada a coexistência de diferentes modelos com propostas e perspectivas distintas entre si\n(BRASIL, 2004). Em relação aos Modelos Assistenciais em Saúde, é correto afirmar que","options":{"A":"o modelo conhecido como \"\"sanitarista\"\" privilegia o atendimento individual e curativo, prestado\npelo médico e outros profissionais da saúde.","B":"o modelo chamado \"\"vigilância em saúde\"\" é constituído pelas campanhas e programas de\nsaúde pública voltados ao controle de doenças.","C":"o modelo \"\"médico-assistencial privatista\"\" é considerado o mais resolutivo frente às demandas\nde saúde da população devido ao seu caráter\ntecnicista.","D":"o modelo da \"\"vigilância em saúde\"\" estimula a mobilização, a organização e a atuação dos\ndiversos grupos na promoção e na defesa das condições de vida e saúde.","E":"o modelo \"\"sanitarista\"\" considera, além das determinações clínico-epidemiológicas no âmbito\nindividual e coletivo, os determinantes sociais que afetam as pessoas."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249726","number":"249726","sourceNumber":"249726","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As equipes de Saúde da Família (eSF) encontram, na apropriação do território, a lógica\nnecessária para organizar suas ações e intervenções. Os indivíduos e famílias pertencentes ao\nterritório sob sua responsabilidade sanitária compõem uma população adscrita, com a qual são\nconstruídos vínculos, buscando a oferta de um cuidado integral e longitudinal em saúde (LACERDA\ne cols, 2010). Em relação aos aspectos do território e à atuação das eSF, é correto afirmar que","options":{"A":"para uma atuação eficaz das eSF, o território deve ser tomado como um físico acabado, definido\napenas por critérios geográficos.","B":"a delimitação espacial do território deve ser definida previamente pela gestão, sendo orientada a\npartir da lógica burocrático-administrativa.","C":"um mapa inteligente, com a identificação dos domicílios, precisa ser constantemente atualizado\ne exposto na recepção da unidade de saúde.","D":"o mapeamento do território deve levar em consideração, além de critérios geográficos, os\naspectos econômicos, políticos, culturais e epidemiológicos.","E":"para a atuação das eSF, a visualização do espaço territorial e o acompanhamento de suas\ncaracterísticas sociossanitárias possuem pouca relevância."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249727","number":"249727","sourceNumber":"249727","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Saúde da Família se constitui na estratégia prioritária para expansão e consolidação\nda Atenção Básica no âmbito do Sistema Único\nde Saúde (SUS). Seus processos de trabalho\nincluem a atuação de equipes multiprofissionais na perspectiva do território, acompanhando de\nforma longitudinal a população sob sua responsabilidade sanitária e buscando a resolutividade para\nas demandas de saúde apresentadas (BRASIL, 2017). Em relação à Atenção Básica (AB) e à\nEstratégia de Saúde da Família (ESF), analise as assertivas e identifique com V as verdadeiras e\ncom F as falsas. ( ) A ESF considera que a família, a comunidade e outras formas de coletividade\nsão elementos relevantes e, muitas vezes, determinantes na oferta de cuidado. ( ) A AB preconiza\na dicotomia e a oposição entre a assistência e a promoção da saúde, considerando que a saúde\npossui múltiplos determinantes e condicionantes. ( ) A ESF favorece uma reorientação dos\nprocessos de trabalho em saúde, com maior potencial de ampliar a resolutividade, embora tenha\nbaixo impacto na situação de saúde das pessoas. ( ) A AB é responsável por ser a coordenadora\ndo cuidado nas Redes de Atenção à Saúde elaborando, acompanhando e organizando o fluxo dos\nusuários entre os pontos de atenção. A alternativa que contém a sequência correta, de cima para\nbaixo, é","options":{"A":"V F F V","B":"V F V F","C":"V V F F","D":"F V F V","E":"F V V F"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249730","number":"249730","sourceNumber":"249730","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As ações de Vigilância em Saúde incluem um processo contínuo e sistemático de\ncoleta, consolidação e análise de dados, além da\ndisseminação de informações sobre eventos\nrelacionados à saúde. É essencial às ações de planejamento e à implementação de medidas de\nsaúde pública, subsidiando a tomada de decisão e a alocação de recursos nos processos de\ntrabalhado da gestão em saúde (BRASIL, 2018). Em relação aos aspectos da vigilância em saúde,\nanalise as assertivas e identifique com V as verdadeiras e com F as falsas. ( ) A análise de\nsituação\nde saúde e as ações laboratoriais são atividades transversais e essenciais no processo de trabalho\nda Vigilância em Saúde. ( ) A vigilância epidemiológica abrange a prestação de serviços e o\ncontrole de bens de consumo que, direta ou indiretamente, se relacionem com a saúde. ( ) A\nvigilância em saúde ambiental propicia a detecção de mudanças nos fatores determinantes e\ncondicionantes do meio ambiente que interferem na saúde humana. ( ) As ações da vigilância\nsanitária embasam a recomendação e a adoção de medidas de prevenção e controle das doenças,\ntransmissíveis e não-transmissíveis, e agravos à saúde. A alternativa que contém a sequência\ncorreta, de cima para baixo, é","options":{"A":"V F F V","B":"V F V F","C":"V V F F","D":"F V F V","E":"F V V F"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-249731","number":"249731","sourceNumber":"249731","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Primária à Saúde (APS) se constitui na principal porta de entrada e contato\npreferencial dos usuários com o Sistema Único de Saúde (SUS). Deve atuar como coordenadora e\nordenadora do cuidado para as redes de atenção à saúde, ofertando cuidado longitudinal à\npopulação sob sua responsabilidade sanitária. Dentre as ações pertinentes à APS estão aquelas\nque se relacionam à Saúde do Trabalhador (BRASIL, 2002). Em relação às ações da APS voltadas\npara a Saúde do Trabalhador, analise as assertivas e identifique com V as verdadeiras e com F as\nfalsas. ( ) É papel da APS planejar e executar ações de vigilância nos locais de trabalho,\nconsiderando as informações colhidas em visitas domiciliares. ( ) Em casos de maior complexidade,\na APS deve interromper o acompanhamento e encaminhar a situação para serviços especializados\nem Saúde do Trabalhador. ( ) Em situações de menor complexidade, a APS deve fazer a condução\nclínica dos casos, estabelecendo os mecanismos de referência e contrarreferência necessários. ( )\nAs ações direcionadas à Saúde do Trabalhador e desenvolvidas pela APS pressupõem que as\nunidades de saúde estejam organizadas no modelo da Estratégia Saúde da Família. A alternativa\nque contém a sequência correta, de cima para baixo, é","options":{"A":"V F V V","B":"V V F F","C":"V F V F","D":"F F V F","E":"F V F V"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-218149","number":"218149","sourceNumber":"218149","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"?Atenção Básica é o conjunto de ações de saúde individuais, familiares e coletivas que\nenvolvem promoção, prevenção, proteção, diagnóstico, tratamento, reabilitação, redução de danos,\ncuidados paliativos e vigilância em saúde, desenvolvida por meio de práticas de cuidado integrado\ne gestão qualificada, realizada com equipe multiprofissional e dirigida à população em território\ndefinido, sobre as quais as equipes assumem responsabilidade sanitária? (BRASIL 2017, p. 2).\n\nConsiderando a Política Nacional de Atenção Básica (PNAB), analise as assertivas e identifique\ncom V as verdadeiras e com F as falsas. (\n) A PNAB tem na Saúde da Família sua estratégia\nprioritária para expansão e consolidação da Atenção Básica, sendo reconhecidas outras estratégias\nde Atenção Básica. ( ) A universalidade, uma das diretrizes da Atenção Básica, compreende a\noferta do cuidado, reconhecendo as diferenças e de acordo com as necessidades das pessoas. ( )\nA resolutividade é uma das diretrizes da atenção básica e pressupõe a continuidade da relação de\ncuidado com construção de vínculo e responsabilização entre profissionais e usuários. A alternativa\nque contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"F, V, V.","B":"F, F, V.","C":"V, F, F.","D":"V, F, V.","E":"V, V, F."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-218141","number":"218141","sourceNumber":"218141","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Projeto Terapêutico Singular (PTS) é urna ferramenta que viabiliza o diálogo\ninterativo entre os profissionais da Atenção\nBásica, permitindo o compartilhamento de casos e o\nacompanhamento longitudinal de responsabilidade destas equipes (BRASIL, 2011). A respeito do\nPTS, é CORRETO afirmar que:","options":{"A":"É uma ferramenta, considerada como proposta de ação, que não deve ser utilizada com famílias\nou grupos específicos, mas apenas corn\nindivíduos, possibilitando traçar um plano terapêutico.","B":"Pode criar um espaço para a efetivação da clínica ampliada e de uma prática de cuidado não\nsegmentada ou isoladamente desenvolvida pelo profissional, extinguindo, assim, a referência e a\ncontrarreferência.","C":"Na construção do PTS, os profissionais de saúde devem escutar as demandas dos usuários de\nmaneira qualificada e estabelecer vínculos, o que torna dispensável a participação dos usuários no\nprocesso de planejamento das ações.","D":"O PTS tem foco no cuidado à saúde dos indivíduos, sendo uma ferramenta estritamente para\nauxiliar a prática do cuidado, que objetiva ações preventivas e curativas às doenças a partir do\ncompartilhamento de saberes e práticas entre os profissionais.","E":"Cada profissional contribui com os saberes de sua formação, na troca de experiências, no\ncompartilhamento de ideias e no aprendizado com o olhar do outro, proporcionando que a\ncomplementaridade dos saberes contribua para uma assistência resolutiva."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-218146","number":"218146","sourceNumber":"218146","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Saúde da pessoa com deficiência ?[...] caracteriza-se por\nreconhecer a necessidade de implementar o\nprocesso de respostas às complexas questões que\nenvolvem a atenção à saúde das pessoas com deficiência no Brasil? (BRASIL, 2010, p. 7). Em\nrelação ao processo saúde-doença e cuidado das pessoas com deficiência na atenção primária à\nsaúde (APS), é CORRETO afirmar que:","options":{"A":"Dentre as principais causas que levam à deficiência estão as hereditárias ou as congênitas, que\nnão são evitáveis.","B":"A atenção integral à saúde das pessoas com deficiência não inclui ações voltadas para saúde\nsexual e reprodutiva.","C":"As equipes de reabilitação devem desenvolver seu trabalho sem precisar envolver as unidades\nbásicas de saúde.","D":"Ao trabalhar com áreas territorializadas, a APS capilariza o cuidado à saúde e ao adoecimento\ndas pessoas com deficiência.","E":"As deficiências, que são consequência de doenças transmissíveis, são evitáveis com uso de\nmedicamentos apropriados."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-218158","number":"218158","sourceNumber":"218158","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"\"As ações e os serviços para a Atenção Integral à Saúde da Criança são coordenados\npela Atenção Básica, a partir da avaliação do\nrisco individual e coletivo, observadas as\nespecificidades previstas para crianças que necessitam de proteção especial\" (BRASIL, 2018, p.\n113). Considerando o cuidado à criança no âmbito da Atenção Primária à Saúde (APS), é\nCORRETO afirmar que:","options":{"A":"As ações do Programa Saúde na Escola (PSE) desenvolvidas pelas equipes das Unidades\nBásicas de Saúde destinam-se aos escolares.","B":"O atraso vacinal deve ser visto como um indicativo de dificuldades de acesso ou outras\nsituações de vulnerabilidade enfrentadas pela família.","C":"O acesso à saúde bucal deve ter início no período pré-escolar e será incorporado no\nacompanhamento do crescimento e no desenvolvimento da criança.","D":"A educação em saúde é a maneira mais eficiente de evitar diversas doenças imunopreveníveis,\ncomo a varíola, a poliomielite/paralisia\ninfantil, sarampo, tuberculose, entre outras.","E":"Em situações em que a criança tem necessidade de suporte de pediatra, a Equipe de Saúde da\nFamília faz o encaminhamento e se desresponsabiliza pelo acompanhamento da criança."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-218192","number":"218192","sourceNumber":"218192","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paulo, usuário que havia se mudado há uma semana para a área da Unidade Básica\nde Saúde, compareceu ao acolhimento com\nqueixa de insônia há três dias. Após a escuta inicial, foi\nencaminhado para consulta com Daiane. Disse a ela que tem 24 anos, é casado, tem duas\ncrianças, com 8 e 3 anos, e está sem emprego fixo: tem um vínculo de emprego intermitente, mas\nnão tem sido chamado e faz \"bicos\" para garantir a renda da família. Perguntado por ela o que ele\nachava que estava levando à insônia, ele atribuiu a ter retornado, naquela semana, a busca por\nempregos, mas sem sucesso. Relata que há uma semana tem estado muito angustiado, precisa ir\nem busca do trabalho, mas está desanimado em sair de casa e anda muito preocupado com o\nfuturo de sua família e, também, do país e do mercado de trabalho. Quanto à situação apresentada\npor Paulo, é CORRETO afirmar que:","options":{"A":"Pode ser o início de um quadro agorafobia. Assim, deve-se considerar introduzir um inibidor\nseletivo da receptação de serotonina.","B":"É importante garantir um alívio mais imediato ao usuário para que ele possa focar em seu\nobjetivo: conseguir emprego, portanto, deve ser\nprescrito benzodiazepínico por um período de teste\ne, depois, avaliar a situação.","C":"O quadro de Paulo poderá evoluir para algo mais grave, como uma depressão, tendo em vista a\nmelhora do prognóstico quando o tratamento é introduzido precocemente, evitando o\ndesenvolvimento da doença. Assim, deverá iniciar o tratamento com antidepressivos.","D":"Há evidentemente um quadro de problemas com saúde mental em Paulo com um fator\ndesencadeante de difícil solução. Uma\nintervenção medicamentosa isolada não é o mais eficaz.\nAssim, recomenda-se o encaminhamento para o Centro de Atenção Psicossocial (CAPS) para ser\ntratado de maneira mais ampla e integral.","E":"Paulo apresenta mudanças e alguns fatores estressantes em seu relato que parecem estar\nproduzindo o quadro relatado. Antes de se\niniciar qualquer medicação, deve ser acompanhado,\napoiado e tentar com ele alternativas, tais como: disponibilizar-se para dialogar sobre esses\nfatores\ne a possibilidade de lidar com eles e enfrentá-los; higiene do sono; prática de atividades fisícas;\n\nmudanças em comportamentos e no estilo de vida; psicoeducação; técnicas de solução do\nproblema e motivação, entre outros."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-218179","number":"218179","sourceNumber":"218179","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre os Modelos Assistenciais em Saúde, analise as assertivas com V as verdadeiras\ne com F as falsas. ( ) Um dos principais\nelementos da clínica ampliada, tal como trabalhada em\ndiversas obras de Gestão Wagner Campos, é deixar de considerar somente a doença (sua\nnosologia) e colocar em foco o sujeito havendo a necessidade de usar os recursos disponíveis e\ntecnologias em função da atenção às necessidades de saúde desse sujeito. Este deve ser\nconsiderado desde uma perspectiva integral, na qual sejam considerados elementos biológicos,\npsíquicos, sociais, culturais, históricos etc, como sujeito com experiências sempre singulares com\nrelação às suas necessidades de saúde, como portador de direitos e com o qual se deve dialogar e\ntomar as decisões conjuntamente. ( ) A ideia de processo de trabalho usuário-centrado, conforme\ndesenvolvida em obras de Emerson Merhy, vem perdendo sua base teórica e uso nos últimos anos,\ntanto pelo advento de medicina centrada na pessoa quanto pela complexidade do processo de\ntrabalho exigir vários focos e não apenas um. Assim, além do usuário, em diversas situações,\nprecisa-se centrar no procedimento, em outras no serviço de saúde, em outras nas necessidades\ndos trabalhadores de saúde e mesmo nas da gestão do serviço. Deve ser analisado cada caso e\nfeito o que é mais recomendado com base nas evidências sem eleger a priori um centro ou foco.\n\nPor desconsiderar isso, o cuidado centrado no usuário perdeu espaço. ( ) O método clínico\ncentrado na pessoa, sistematizado por\nStewart, Mc William e outros, que conta com estudos\ninternacionais que mostram vantagens em termos de satisfação do usuário, eficiência e resultados\nem saúde, pode ser operacionalizado desde o modo de fazer a consulta até na relação e\ncomunicação a ser estabelecida com o usuário. Esse método pode ser um dos importantes modos\nde operacionalizar parte do que é a clínica ampliada e apresenta dentre seus elementos clássicos:\na exploração da doença e também da experiência que a pessoa tem com a doença, a necessidade\nde entender a pessoa como um todo, a elaboração de um plano conjunto (usuário e profissional) de\nmanejo dos problemas e a incorporação nesse plano da promoção e da prevenção. A alternativa\nque contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"V, V, F.","B":"V, F, V.","C":"V, F, F.","D":"F, V, V.","E":"F, V, F."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-215623","number":"215623","sourceNumber":"215623","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Brasil assumiu o compromisso dos Objetivos de Desenvolvimento do Milênio,\nproposto junto à Organização das Nações\nUnidas (ONU), sendo uma de suas metas combaterem e\nreverterem a tendência atual de propagação do HIV/AIDS. Sendo, entretanto FORA desses\nconceitos, que:","options":{"A":"O país busca, como parte das ações de enfrentamento à epidemia de HIV, atingir a meta\n90-90-90.","B":"Até 2020, 90% das pessoas com HIV sejam diagnosticadas (ampliando o acesso ao diagnóstico\ndo HIV).","C":"Das pessoas com HIV diagnosticadas, 90% estejam em tratamento antirretroviral (ampliando o\nacesso à TARV).","D":"Os compromissos assumidos exijam somente que novas metodologias de cuidado e de gestão\nsejam implantadas, independente de um\ncomprometimento da sociedade para o sucesso e alcance\ndesses propósitos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-350812","number":"350812","sourceNumber":"350812","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Lana, de 3 anos, é trazida para atendimento na UBS por sua avó, dona Benzarina. A\navó relata que a criança falta\nrecorrentemente à escola por ?estar sempre gripada?. Queixa-se de\nque ?a menina está sempre com nariz escorrendo e tossindo?, que ?toda noite ela dorme mal, com\ncrises de tosse?, que ?a menina está tossindo todos o dias há pelo menos um mês uma tosse seca\nhorrível?, que ?o tempo não pode mudar que a criança começa a espirrar e tossir? e que ?só esse\nano ela já precisou ficar internada três vezes por gripe mal curada?. Dona Benzarina refere que\nmuitas crianças da escola de Lana também têm faltado à escola desde a instalação de uma fábrica\nde tijolos na comunidade. Assinale a alternativa que traz o eixo da Vigilância em Saúde\ncorrespondente ao caso relatado.","options":{"A":"Vigilância Sanitária.","B":"Vigilância Ambiental.","C":"Vigilância Epidemiológica","D":"Vigilância em Saúde do Trabalho."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-350810","number":"350810","sourceNumber":"350810","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Tales, de 17 anos, procura atendimento médico referindo tosse diária há quatro meses,\nenquanto cumpria pena de privação provisória de liberdade em instituição socioeducativa. Refere\nuso diário de cigarro por tabaco e por cannabis. Quando questionado sobre o uso do cigarro,\nrelatou ?O cigarro para mim não é problema, mas solução. Eu fui preso por coisa que não fiz e\ndesde que isso aconteceu eu não consigo relaxar. Eu estou assustado o tempo todo. Se eu escuto\numa sirene, acho que é alguém vindo me pegar. De noite eu não prego os olhos. A única coisa que\nme acalma é fumar. Eu consigo organizar as ideias.? Assinale a alternativa que traz o Estágio\nMotivacional de Tales em relação ao fumo.","options":{"A":"Pré-contemplação.","B":"Contemplação.","C":"Preparação.","D":"Ação."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-350806","number":"350806","sourceNumber":"350806","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em uma das consultas de acompanhamento por seu quadro de sofrimento mental,\nTales questiona a origem dos seus sintomas\nansiosos. Inicialmente, você começa a explicar o\nquadro clínico utilizando jargões médicos e termos técnicos, mas percebe que Tales encontra-se\ninquieto e com dificuldade de acompanhar seu discurso. Você, então, muda o vocabulário do seu\ndiscurso, utilizando expressões mais próximas da realidade psicossocial de Tales. O atendimento é\nconcluído com Tales satisfeito com uma melhor compreensão de seu próprio processo de\nadoecimento. Assinale a alternativa sobre o Atributo da Atenção Primária contemplado na postura\ndo médico.","options":{"A":"Acesso.","B":"Coordenação.","C":"Orientação comunitária.","D":"Competência cultural."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-350805","number":"350805","sourceNumber":"350805","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Durante o acompanhamento clínico de Tales pelo quadro de tosse crônica, o médico de\nfamília assistente identificou outras questões, tais como o fumo recorrente e o sofrimento mental\nassociado ao contexto em que Tales estava inserido. O acompanhamento de saúde se deu\nconsiderando todos os aspectos biopsicossociais de Tales, sem esquecer de que ele coabitava\ncom Lana, sua sobrinha de 3 anos, que estava em acompanhamento por ILTB e apresentava piora\ndos sintomas respiratórios devido ao tabagismo de Tales. Assinale a alternativa que traz o princípio\ndoutrinário do SUS representado nesse caso clínico.","options":{"A":"Equidade.","B":"Integralidade.","C":"Universalidade.","D":"Orientação familiar."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-350803","number":"350803","sourceNumber":"350803","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Durante o atendimento de Lana, de 3 anos, você fica preocupado com o relato da avó\nda criança, dona Benzarina, de que muitas\ncrianças da escola de Lana também têm faltado à\nescola por quadros respiratórios, desde a instalação de uma fábrica de tijolos na comunidade. A\nequipe de saúde decide se reunir ao término do turno de atendimento, para discutir sobre o relato\nde Benzarina, pois a situação não era de conhecimento da equipe. Assinale a alternativa que\ncorresponde a uma ferramenta clínica possível para abordagem comunitária do problema relatado.","options":{"A":"Ecomapa.","B":"PRACTICE.","C":"Territorialização.","D":"APGAR familiar das famílias com crianças com alta taxa de absenteísmo."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321339","number":"321339","sourceNumber":"321339","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em seu turno de demanda espontânea na sua UBS, você atende Cleodécio, de 54\nanos, que refere estar fazendo uma consulta\nde retorno. Ele relata que ?o pé esquerdo está morto,\no olho esquerdo está muito seco e há manchas na pele? e traz o resultado de um exame de\nbaciloscopia de raspado intradérmico para pesquisa de BAAR que foi solicitado por outro médico. O\nresultado do exame é negativo. Em seu exame físico, apresenta face infiltrada e madarose. Há oito\nlesões papulares escuras, endurecidas, não dolorosas e não pruriginosas em tórax, dorso e\nmembros inferiores. Em membro inferior esquerdo, você observa espessamento do nervo fibular\ncomum. O exame dermatoneurológico mostra alteração de sensibilidade em face, região medial do\nantebraço à direita, região lateral da perna esquerda e dorso de pé esquerdo. A avaliação de\nfunções motoras evidencia garra ulnar à direita e perda da dorsiflexão de pé esquerdo. Quando\nCleodécio procurou atendimento médico pelo quadro de reação hansênica, você estava realizando\natendimentos programados. O enfermeiro de sua equipe agendou Cleodécio em uma das vagas\ndisponibilizadas na sua agenda para atendimentos de urgência naquele mesmo turno. Qual atributo\nnuclear da Atenção Primária à Saúde fundamenta a organização de turnos de atendimento com\nvagas para consultas de urgência?","options":{"A":"Acesso / Atenção ao primeiro contato.","B":"Integralidade / Cuidado abrangente.","C":"Longitudinalidade.","D":"Coordenação."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321340","number":"321340","sourceNumber":"321340","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Durante a reunião estratégica da sua equipe na UBS, foi relatado que não constavam\npessoas em tratamento para tuberculose em\nnenhuma das microáreas sob sua responsabilidade. A\nbase de dados do seu município indicava uma prevalência de tuberculose pulmonar bacilífera de 80\ncasos a cada 100.000 habitantes e a população adscrita nas suas microáreas era de 10.000\nhabitantes. Diante disso, os agentes comunitários foram capacitados para realizar busca ativa,\natravés da aplicação de questionário para identificação de Sintomáticos Respiratórios (SR),\ndetectando a presença de 100 SR. Qual ferramenta de abordagem comunitária a equipe de saúde\npoderia utilizar para abordar a falta de dados sobre a população adscrita da UBS?","options":{"A":"Ecomapa.","B":"Genograma.","C":"Territorialização.","D":"Orientações Fundamentais nas Relações Interpessoais (F.I.R.O.)"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321346","number":"321346","sourceNumber":"321346","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Uma agente de saúde procura você trazendo a demanda de uma família. Ela relata que\nDona Benzarina, de 102 anos, recebeu alta do\nhospital municipal ?para morrer em casa, pois não\ntinham mais o que fazer por ela?. A equipe da UBS de referência não recebeu comunicação do\nServiço Social do referido hospital. A família está muito angustiada, pois a paciente ?está\nagonizando? e por isso solicita uma visita domiciliar. Assinale a alternativa que traz os termos na\nordem que preenche CORRETAMENTE as lacunas do texto abaixo.\n\n?A visita domiciliar é um exemplo prático do Princípio Ordinário do SUS da . Ao\ndesospitalizar a paciente sem informar a equipe da APS, não houve observância ao Atributo\nNuclear da Atenção Primária da . Ao prestar assistência a Dona Benzarina em\num contexto de terminalidade, a equipe da ESF está praticando o Atributo Nuclear da Atenção\nPrimária da . Diante da finitude, cuidar de Dona Benzarina significa ter\nsensibilidade aos aspectos bioéticos, técnicos, religiosos e culturais: assim, coloca-se em prática\no\nAtributo Nuclear da Atenção Primária da .?","options":{"A":"Equidade / Coordenação / Longitudinalidade / Integralidade.","B":"Integralidade / Coordenação / Longitudinalidade / Integralidade.","C":"Universalidade / Coordenação / Longitudinalidade / Integralidade.","D":"Territorialização / Integralidade / Coordenação / Longitudinalidade."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321356","number":"321356","sourceNumber":"321356","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Assinale a alternativa que contempla os objetivos principais do Pacto pela Saúde, de\n2006.","options":{"A":"Promover reformas institucionais, com pacto entre as três esferas (União, Estados e Municípios),\npara inovar processos e instrumentos de gestão\nda atenção básica à saúde e alcançar maior\neficiência e qualidade no SUS.","B":"Garantir a universalidade do direito à saúde, oficializado na Constituição Federal de 1988 e a\ncriação do Sistema Único de Saúde (SUS).","C":"Firmar compromisso entre os gestores do SUS em torno de prioridades básicas que apresentam\nimpacto sobre a situação de saúde da\npopulação brasileira.","D":"Consolidar e qualificar a Estratégia Saúde da Família (ESF) como modelo de atenção básica à\nsaúde e centro ordenador das redes de\natenção à saúde no SUS."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292849","number":"292849","sourceNumber":"292849","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Correlacione a Tabela A, com Princípios e Diretrizes do SUS, e a Tabela B, que traz\nsituações típicas da atuação médica na Atenção Primária. Tabela A: (I) Longitudinalidade; (II)\nHierarquização; (III) Territorialização; (IV) Equidade. Tabela B: ( ) O médico da Atenção Primária\nrecebe paciente contrarreferenciado da Atenção Terciária, após alta hospitalar, constando relatório\npara o seguimento do cuidado do paciente na Atenção Básica. ( ) A visita domiciliar é uma\nferramenta utilizada na Atenção Primária para garantir atendimento a pacientes na área adscrita\nque não podem se deslocar para a Unidade de Saúde. ( ) O médico da Atenção Primária percebe\nque muitas famílias de uma mesma microárea apresentam quadro de diarreia aguda nas\ntemporadas de chuvas. Durante a reunião ordinária de equipe, coleta informações com sua agente\nde saúde sobre o saneamento e acesso a água tratada da microárea. ( ) Durante o turno de\nHiperDia de sua ESF, o médico se depara com um paciente com quadro clínico complexo, com\nmultimorbidade e resposta inadequada às propostas terapêuticas instituídas. Após afastar má\nadesão, decide por encaminhar o paciente para ambulatório especializado. Assinale a opção que\ntraz a correlação CORRETA, de cima para baixo.","options":{"A":"I, IV, II, III.","B":"I, IV, III, II.","C":"II, I, III, IV.","D":"II, I, IV, III."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292850","number":"292850","sourceNumber":"292850","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Correlacione a Tabela A, com os Atributos Nucleares da Atenção Primária, e a Tabela\nB, com exemplos de situações vivenciadas\npelo médico na Atenção Primária. Tabela A; (I)\nAcesso/Atenção ao primeiro contato; (II) Coordenação; (III) Longitudinalidade; (IV)\nIntegralidade/Cuidado Abrangente; Tabela B; ( ) O médico acompanha suas famílias adscritas\ndurante todos os ciclos de vida daquela família: desde a chegada de um novo membro através do\nnascimento, até as crises decorrentes do falecimento de familiares. ( ) Durante um caso clínico\ncomplexo na APS, o médico referencia o paciente para ambulatório especializado. Após dois\nmeses, o paciente retorna com a contrarreferência do especialista focal trazendo o plano\nterapêutico e a programação dos futuros atendimentos no ambulatório de especialidades. ( ) O\natendimento clínico na APS contempla o paciente com suas multimorbidades e a experiência\nsubjetiva do paciente em relação ao seu adoecimento. ( ) Durante a reunião ordinária de equipe, é\npactuado que sejam garantidas vagas de demanda espontânea mesmo nos turnos de demanda\nprogramada. A intenção é organizar a dinâmica da UAPS de forma a garantir atendimento de casos\nagudos. Assinale a alternativa que traz a ordem correta, de cima para baixo.","options":{"A":"II; III; I; IV","B":"II; III; IV; I","C":"III; II; I; IV","D":"III; II; IV; I"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292851","number":"292851","sourceNumber":"292851","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Participação da Comunidade é uma das Diretrizes do SUS. A Lei N° 8142, de 28 de\ndezembro de 1990, dispôs sobre a participação da comunidade. Sobre Conselhos e Conferências\nde Saúde, assinale a alternativa correta.","options":{"A":"Os Conselhos e Conferências de Saúde terão sua organização e normas definidas pelo Poder\nLegislativo e autorizadas pelo Poder Executivo.","B":"Os Conselhos de Saúde têm poder consultivo e de vistas em relação à prestação de contas.\n\nQuaisquer vetos em relação a prestações de conta implicam a dissolução do Conselho e a\nformação de um novo, de modo que as contas possam ser aprovadas.","C":"Os Conselhos e Conferências de Saúde são formados por representantes de entidades e dos\nmovimentos sociais dos usuários do SUS, de entidades de profissionais de saúde, do governo, de\nentidades de prestadores de serviços de saúde, do CONASS, do CONASEMS e de entidades\nempresariais com atividade na área da saúde. Todos esses membros em mesma proporção.","D":"Conferência de Saúde é instância colegiada que se reúne a cada quatro anos, com a\nrepresentação dos vários segmentos sociais,\npara avaliar a situação de saúde e propor as diretrizes\npara a formulação da política de saúde nos níveis correspondentes."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292852","number":"292852","sourceNumber":"292852","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Atenção Básica (PNAB) foi formulada pela primeira vez em 2006,\nsendo considerada um marco histórico na Atenção Primária à Saúde no Brasil. Assinale a\nalternativa que contempla o principal objetivo da PNAB de 2006.","options":{"A":"Consolidar e qualificar a Estratégia Saúde da Família (ESF) como modelo de atenção básica à\nsaúde e centro ordenador das redes de\natenção à saúde no SUS.","B":"Firmar compromisso entre os gestores do SUS, em torno de prioridades básicas que apresentam\nimpacto sobre a situação de saúde da\npopulação brasileira.","C":"Garantir a universalidade do direito à atenção básica à saúde, oficializado na Constituição\nFederal de 1988, e com a criação do Sistema\nÚnico de Saúde (SUS).","D":"Promover reformas institucionais, com pacto entre as três esferas (União, Estados e Municípios),\npara inovar processos e instrumentos de gestão\nda atenção básica à saúde e alcançar maior\neficiência e qualidade no SUS."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292853","number":"292853","sourceNumber":"292853","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os conceitos de Território e Territorialização estão intimamente relacionados às\nDiretrizes Organizacionais do SUS, tais como\nHierarquização e Descentralização, sendo também\numa das Diretrizes da Atenção Básica. Assinale a alternativa que traz um conceito de território e um\nexemplo prático.","options":{"A":"Território-Distrito: Um paciente grave é atendido no setor de urgência de um hospital municipal\nde baixa complexidade e, após estabilização, é\ntransferido para um hospital de referência de outro\nmunicípio.","B":"Território-Área: Durante uma reunião de uma equipe de saúde da família em uma UBS, uma\nagente comunitária traz a demanda de realizar\numa atividade de educação em saúde com famílias\nacompanhadas por ela, pois há um surto de escabiose em uma determinada rua.","C":"Território-Microárea: Um médico programa uma visita domiciliar, para avaliar um caso de um\npaciente que abandonou o tratamento para Tuberculose Pulmonar por diversas vezes, para\nentender fatores que possam estar impactando na adesão ao tratamento.","D":"Território-Moradia: Durante a quadra chuvosa, médicos de uma UBS realizam atendimentos de\ndemanda espontânea de pacientes de todas as\nequipes da estratégia saúde da família da unidade."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292855","number":"292855","sourceNumber":"292855","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considere o texto abaixo para responder à questão. ?As mulheres são atingidas pela\nviolência interpessoal de modo singular, na maioria das vezes, por parceiros íntimos ou familiares,\nenvolvendo agressões físicas, sexuais e também danos psíquicos. [...] [...] Estudos nacionais e\ninternacionais apontam entre os usuais fatores associados à violência por parceiro íntimo o\nconsumo de substâncias psicoativas. [...] Adicionalmente relevante se torna o consumo de\nmedicamentos, realizado especialmente por mulheres, e sua relação com os episódios de violência\nentre parceiros íntimos, o que pode ser considerado um novo desafio para os profissionais de\nsaúde, [...] devido ao risco de corroborar para uma medicalização excessiva. Na América Latina,\n[...] o uso de álcool pelo parceiro íntimo se insere entre as demais características apresentadas\npelas mulheres agredidas, a saber: coabitação com o parceiro sem casamento formal; muitos filhos;\nnão compartilhamento da tomada de decisão; disparidade no nível de instrução. Assim, o consumo\nde álcool, especificamente, está incluído entre os riscos para a violência doméstica, principalmente\nse o padrão de consumo for elevado. [...].? SILVA, Valéria Nanci. ?Violência e uso de substância\npsicoativas: um estudo com mulheres usuárias de um serviço de Atenção Primária à Saúde de São\nPaulo / Valéria Nanci Silva. ? São Paulo, 2008. O texto faz referência a que fenômeno observado\nna saúde pública?","options":{"A":"Carga de doença.","B":"Cascata de prescrição.","C":"Determinantes Sociais de Saúde.","D":"Barreiras geográficas da Atenção Primária."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292859","number":"292859","sourceNumber":"292859","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em seu atendimento com Vanessa, com a finalidade de estabelecer um vínculo com\numa paciente com contexto familiar e social\ntão complexo, você resolve confeccionar um\nGenograma de Vanessa. Considerando que o relato da Vanessa trouxe as mesmas informações\npreviamente já passadas pelo Dr. Marcos Júlio, assinale a alternativa que traz uma informação não\ncontemplada pelo Genograma ilustrado na Figura 1.","options":{"A":"Histórico obstétrico de Vanessa.","B":"Relação conflituosa entre Vanessa e seus pais.","C":"Relação conflituosa entre Vanessa e Ubiratan.","D":"Histórico familiar de AVCs na família de Vanessa."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292861","number":"292861","sourceNumber":"292861","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Durante a consulta de pré-natal, Vanessa informa que fuma tabaco, ocasionalmente, e\nque pretende parar de fumar durante a\ngestação, mas que vai voltar a fumar após o nascimento da\ncriança. Considerando a redução de riscos, como orientar uma mulher que amamenta e que faz\nuso de tabaco?","options":{"A":"Realizar abordagem cognitivo comportamental básica e orientar a reduzir o consumo o máximo\npossível. Se não for possível a cessação do tabagismo por completo, orientar procurar fumar pouco\ntempo antes da amamentação, para que o leite produzido não tenha vestígios de nicotina.","B":"Realizar abordagem cognitivo comportamental básica e orientar a reduzir o consumo o máximo\npossível. Se não for possível a cessação do tabagismo por completo, orientar procurar fumar após\na amamentação e não fumar no mesmo ambiente em que a criança se encontra.","C":"Informar que o tabagismo é contraindicação absoluta para a amamentação e, considerando a\nredução de riscos, orientar a oferta de leite artificial.","D":"Realizar abordagem cognitivo comportamental básica e contraindicar amamentação até que\npaciente cesse completamente o tabagismo."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-292862","number":"292862","sourceNumber":"292862","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Após você realizar as orientações de redução de risco, quanto ao fumo, durante o\naleitamento, você explora as motivações de Vanessa de planejar voltar a fumar após o término da\ngravidez. Vanessa informa que fuma ?para fazer companhia ao Edberto?. Após identificar Edberto\ncomo um personagem chave para abordar o tabagismo de Vanessa, você agenda uma consulta\npara Edberto. Durante a consulta com Edberto, através da entrevista motivacional, você identifica\nque ele se encontra no estágio Contemplativo. Qual abordagem, a partir da entrevista motivacional,\né a mais adequada nesse caso?","options":{"A":"Tirar dúvidas e ajudar na escolha de melhor estratégia em busca da mudança.","B":"Ajudar a perceber gatilhos para prevenir recaídas. Construir estratégias para enfrentar eventuais\ngatilhos.","C":"Levantar dúvidas sobre sintomas e queixas do paciente sobre possível relação com tabagismo e\naumentar a percepção sobre riscos do hábito.","D":"Desfazer a postura de ambivalência, inclinando a balança ao evocar riscos de não mudar e\nnumerar motivos para mudar. Fortalecer a autossuficiência."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-259750","number":"259750","sourceNumber":"259750","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Mulher, 65 anos, acompanhada por hipertensão, diabetes, obesidade comparece à\nunidade de atenção primária à saúde com queixa de febre baixa, dor de garganta, tosse, cefaleia e\nastenia há 7 dias. Na oximetria de pulso apresentou saturação de oxigênio de 89% em ar ambiente.\nO SAMU foi acionado e a paciente foi transferida na UPA e em seguida para hospital, onde ficou\nem leito de terapia intensiva por 5 dias. A sua equipe de saúde da família (ESF) manteve contato\ncom os profissionais da UPA e do hospital e realizou acompanhamento remoto por telefone e\nmensagens de aplicativo até a alta hospitalar, quando agendou visita domiciliar. Qual princípio da\natenção primária à saúde está representado pela ação de sua ESF?","options":{"A":"Coordenação do cuidado.","B":"Longitudinalidade.","C":"Integralidade.","D":"Equidade."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-259751","number":"259751","sourceNumber":"259751","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Na reunião semanal de uma equipe da Estratégia de Saúde da Família, uma ACS se\nqueixa que vem sendo realizado atendimento preferencial a população residente em uma das\nmicroáreas e solicita uma readequação do serviço, de modo que os atendimentos sejam prestados\nigualmente a todas as microáreas. Como forma de melhor compreender a situação, a médica da\nequipe sugere que os ACS forneçam alguns dados de cada microárea, os quais foram\napresentados na reunião de equipe na semana seguinte. As informações fornecidas pelos ACS\nforam apresentadas no quadro abaixo: Considerando que o planejamento das ações em saúde\nrequer informações atualizadas sobre os determinantes e as condições de saúde de uma\ncomunidade, escolha a alternativa que evidencia o plano de ação que deve ser adotado pela\nequipe com o objetivo de fornecer um atendimento que atenda as necessidades de saúde da\npopulação:","options":{"A":"Direcionar o atendimento das crianças de zero a dois anos para o Pediatra.","B":"Priorizar o atendimento à microárea 4 em respeito ao princípio da equidade.","C":"Realizar visitas domiciliares mensais na microárea 2 e trimestrais nas demais microáreas.","D":"Organizar a agenda de modo a fornecer turnos de atendimentos para os grupos populacionais."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-259752","number":"259752","sourceNumber":"259752","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Durante reunião de equipe semanal, o médico da equipe verde, da Unidade de Saúde\nda zona rural do município de Flores, é\nquestionado acerca da organização de agenda que vem\nadotando. Assim, informa que realiza 16 atendimentos previamente agendados, por turno, de\npessoas portadoras de doenças crônicas, crianças, idosos e gestantes. Caso alguma pessoa\nagendada falte à consulta, a vaga pode ser preenchida com um atendimento não agendado que\nchegue à unidade de saúde naquele dia. A enfermeira da equipe expressa preocupação com essa\nestratégia de organização, tendo em vista a dificuldade relatada pelos pacientes no acesso às\nconsultas médicas, principalmente em situações não programadas. A partir do caso acima descrito,\ncomo deve proceder a equipe no que diz respeito à organização da agenda?","options":{"A":"Implementar agendamento com horário marcado.","B":"Reservar um turno na semana para demanda espontânea.","C":"Realizar abertura da agenda do médico para os próximos 3 meses.","D":"Reservar um percentual de consultas para demandas do dia em todos os turnos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-259760","number":"259760","sourceNumber":"259760","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Durante uma visita domiciliar de um paciente acamado, você percebe um certo \"clima\npesado\" entre os integrantes da família. É perceptível que a cuidadora está mais áspera nas suas\nrespostas, afinal de contas já são 3 anos cuidando, praticamente só do paciente. Qual ferramenta\nde abordagem familiar ajudará, de maneira mais específica, a equipe de saúde da família em traçar\nestratégias para este caso?","options":{"A":"Ecomapa.","B":"Genograma.","C":"PRACTICE.","D":"Apgar familiar."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-259764","number":"259764","sourceNumber":"259764","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Adolescente de 13 anos compareceu à consulta no ambulatório do adolescente\nacompanhada da irmã de 16 anos. A queixa\nprincipal foi ?receber remédios para vermes?. Durante\na consulta o médico observou que Joana é tratada por ?porcaria? pela irma?. Quando questionada\nsobre o ?apelido? a irma? relatou que todos na família a tratam por esse apelido desde criança. Ao\nexaminar Joana, observou cortes superficiais em antebraços, poupando os punhos. Joana relatou\nque constantemente corta os braços com a faca para \"diminuir a angústia\". Considerando o caso\nacima e a atenção à saúde da criança e do adolescente em situação de violência, assinale a\nalternativa com a hipótese diagnóstica provável e conduta mais adequada.","options":{"A":"Trata-se de violência física e o caso deve ser notificado ao conselho tutelar.","B":"Trata-se de violência psicológica e a adolescente deve ser acompanhada por equipe\nmultiprofissional e interdisciplinar.","C":"Trata-se de síndrome de Münchausen por procuração e deve analisar a saúde mental materna\ncom referência ao CAPs ou matriciamento com\npsiquiatra.","D":"Trata-se de automutilação e configura violência física contra a adolescente e deve-se notificar o\ncaso ao conselho tutelar e realizar o acompanhamento multiprofissional."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-259767","number":"259767","sourceNumber":"259767","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paciente masculino, 82 anos, compareceu à unidade de atenção primária para consulta\ncom sua médica de família, a última\nconsulta foi há 1 ano, quando compareceu acompanhado de\nseu filho. Hoje comparece desacompanhado para o atendimento e apresenta pressão arterial de\n160 x 100 mmHg e glicemia capilar pós-prandial de 200 mg/dL. No prontuário, havia uma lista de\nmedicamentos com hidroclorotiazida, losartana, anlodipino, metformina e insulina NPH. Ao ser\nquestionado, refere que usava as medicações sem ajuda de familiares, mas não sabia os nomes\ndos medicamentos e não tinha segurança para explicar a posologia. Referiu que não retornou na\ndata programada pois estava assintomático. Estava muito triste com a perda do filho de 33 anos de\nidade, que foi assassinado há 3 meses em disputa de facções do bairro. Após discussão sobre a\nsituação, a equipe de saúde da família realizou uma conferência familiar no domicílio com\nelaboração do genograma e ecomapa. Qual componente do método clínico centrado na pessoa foi\nabordado na visita domiciliar?","options":{"A":"Entendendo a pessoa como um todo.","B":"Intensificando a Relação entre a pessoa e o médico.","C":"Explorando a saúde, a doença e a experiência da doença.","D":"Elaborando um plano conjunto de manejo dos problemas."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-259768","number":"259768","sourceNumber":"259768","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um médico de família e comunidade realiza visita domiciliar a uma paciente de 86 anos\nque vive com a filha e a bisneta. A bisneta\nestuda em horário integral e faz cursinho pré-vestibular a\nnoite, a filha cuida das tarefas domésticas e dedica-se ?24 horas? aos cuidados da ma?e. A\npaciente está acamada há 10 anos devido queda da própria altura e fratura de fêmur. O nível de\nconsciência alterna lucidez com períodos de confusão. É acompanhada devido doença de\nParkinson, síndrome demencial, catarata, diabetes melitus. Necessita de ajuda para alimentar-se e\npara higiene. A dieta é pastosa (dificuldade para ingerir sólidos), recebe cinco refeições ao dia e\no\napetite é preservado. Não possui controle de esfíncteres, necessitando uso de fraldas. Em uso de\nlevodopa\\ benserazida, glicazida, carbonato de cálcio, alendronato, risperidona. Utilizando a escala\nde risco e vulnerabilidade para atenção domiciliar, qual a classificação da paciente e o\nplanejamento para a periodicidade de visitas domiciliares?","options":{"A":"Médio risco e as visitas devem ser semestrais.","B":"Muito alto risco e as visitas devem ser mensais.","C":"Alto risco e as visitas devem ser a cada 2 a 3 meses.","D":"Não é possível classificar o risco, pois são necessários exames complementares."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-234064","number":"234064","sourceNumber":"234064","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Mulher de 50 anos comparece em sua UBS para consulta de retorno com sua médica\nde família que lhe faz as seguintes perguntas:\n?Sobre o que você gostaria de conversar comigo\nhoje? Sobre a sua falta de ar devido ao seu problema do pulmão, sobre a dor nos joelhos ou sobre\na dificuldade de visão? Podemos falar só sobre um deles ou sobre mais de um. E se você tiver\noutra ideia sobre o que fazer na consulta de hoje, me diga, por favor. Então, o que você gostaria de\nfazer??. Qual componente do método clínico centrado na pessoa foi utilizado pela médica?","options":{"A":"Entendendo a pessoa como um todo.","B":"Elaborando um projeto comum de manejo de problemas.","C":"Explorando a saúde e a doença e a experiência da pessoa com a doença.","D":"Intensificando o relacionamento entre a pessoa e o profissional de saúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-234065","number":"234065","sourceNumber":"234065","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em reunião de Equipe de Saúde da Família (ESF), a Agente Comunitária de Saúde\n(ACS) solicita receita de anti-hipertensivo\npara o Sr. Ageu, 86 anos, pois ele não virá à consulta\nagendada para esse mês por impossibilidade de locomoção. Ao todo são 6 medicações prescritas,\nentre anti-hipertensivos, antidiabéticos, antiplaquetários e hipolipemiante. A ACS relata que há\nquinze dias o paciente sofreu uma queda no banheiro, o que aumentou sua dificuldade de\ndeambulação. Diante da situação apresentada, qual o melhor plano terapêutico para o Sr. Ageu?\nLEGENDA: Equipe Multiprofissional de Atenção Domiciliar (EMAD).","options":{"A":"Classificá-lo como modalidade AD1 e agendar visita da ESF.","B":"Classificá-lo como modalidade AD1 e acionar equipe EMAD.","C":"Classificá-lo como modalidade AD2 e agendar visita da ESF.","D":"Classificá-lo como modalidade AD2 e acionar equipe EMAD."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-234076","number":"234076","sourceNumber":"234076","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Município de 21.000 habitantes, em região metropolitana de uma grande capital\nbrasileira, no qual dois terços da população\nestá em uma zona urbana, com boas condições de\nhabitação e sociosanitárias, e um terço habita território sujeito a alagamentos periódicos e alta\nincidência de doenças infecto-parasitárias. Em uma reunião de planejamento, abre-se um debate\nsobre o número de equipes de saúde da família (ESF) e de equipes de atenção básica (EAB)\nnecessárias para o município. De acordo com a Política Nacional de Atenção Básica qual é a\nmelhor proposta para a organização da atenção primária à saúde do município em questão?","options":{"A":"2 EAB no território mais vulnerável e 4 ESF para o restante do território.","B":"2 ESF no território mais vulnerável e 3 EAB para o restante do território.","C":"3 ESF no território mais vulnerável e 4 EAB para o restante do território.","D":"3 EAB no território mais vulnerável e 3 ESF para o restante do território."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-349718","number":"349718","sourceNumber":"349718","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um senhor de 58 anos comparece à consulta em unidade básica de saúde e queixa-se,\npara seu médico de família e comunidade, de\ndores nos joelhos. O paciente relata que \"as dores o\npreocupam muito, pois o atrapalham a trabalhar diariamente\". O médico, além de fazer perguntas,\nrealiza o exame físico e conclui que se trata de caso de artrose dos joelhos, bilateralmente. Diante\nda preocupação do paciente, qual é a atitude esperada desse profissional de saúde?","options":{"A":"A atitude adequada é esclarecer ao paciente que se trata de quadro crônico e que ele deverá\nconviver com a dor.","B":"A atitude adequada é demonstrar, empaticamente, que compreende a seriedade do\nadoecimento, apesar de se tratar de doença que não ameaça a vida.","C":"A atitude adequada é esclarecer que se trata de quadro que não ameaça a vida, tranquilizando o\npaciente e orientando que esse quadro não impede seu trabalho.","D":"A atitude adequada é encaminhar o paciente prontamente ao especialista devido à gravidade da\nsituação.","E":"A atitude adequada é recomendar ao paciente afastamento da sua atividade laboral, uma vez\nque ela é diretamente responsável pelo seu\nadoecimento."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-365597","number":"365597","sourceNumber":"365597","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considere que um jovem tenha viajado de Belém (Pará) para Brasília a fim de competir\nnos jogos paraolímpicos que seriam sediados\nno Distrito Federal naquele ano. Durante a\ncompetição, o esportista fraturou seu braço, sendo levado de ambulância ao hospital mais próximo.\nNa recepção, foi informado ao paciente que ele não poderia ser atendido, pois não possuía\nendereço em Brasília. Qual princípio do Sistema Único de Saúde está sendo violado nesse caso?","options":{"A":"Regionalização","B":"Universalidade","C":"Integralidade","D":"Hierarquização"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-365596","number":"365596","sourceNumber":"365596","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Acerca da Lei n° 8142/1990, no âmbito do Sistema Único de Saúde (SUS), assinale a\nalternativa correta.","options":{"A":"É referente à participação da iniciativa privada como setor complementar ao SUS.","B":"Os conselhos de saúde são órgãos de caráter temporário e consultivo.","C":"A representação dos usuários dos serviços de saúde nos conselhos de saúde é paritária em\nrelação ao conjunto dos demais segmentos.","D":"As conferências de saúde ocorrem uma vez por mês."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-349709","number":"349709","sourceNumber":"349709","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Uma mulher de 35 anos, PCD (paralisia dos membros inferiores após trauma), com\nquadro depressivo, compulsão alimentar e\ninsuficiência familiar, mora com a mãe, que tem 70 anos\ne está apresentando alguns sinais de demência em fase inicial. O médico de família está\napreensivo na reunião de equipe, preocupado com a filha PCD, pois esta tem dores crônicas e\nresponde mal às intervenções médicas propostas (analgesia e antidepressivos). Durante a reunião\nde equipe, estão presentes os ACSs (Agentes Comunitários de Saúde), bem como profissionais de\npsicologia, nutrição e fisioterapia. Diante dessas informações, assinale a alternativa que melhor\napresenta uma intervenção multiprofissional e interdisciplinar.","options":{"A":"O médico de família orienta a equipe sobre o que pode ou não ser feito dentro da realidade da\nfilha, enquanto os outros profissionais traçam intervenções com base nessa orientação.","B":"O médico de família compartilha seu conhecimento do caso, buscando possíveis redes de apoio\nna comunidade com os ACSs e também traçar um projeto terapêutico singular, cooperando com a\nnutrição e psicologia.","C":"O médico de família encaminha o caso durante a reunião para que atendimentos de psicologia e\nnutrição sejam realizados - enfatizando a urgência do caso e orientando ao ACS para levar os\nencaminhamentos à casa do paciente.","D":"O médico de família compreende que, devido aos determinantes sociais desse caso, não há\nintervenções possíveis pela equipe complementar.","E":"O médico de família compreende que, devido ao quadro familiar, o principal objetivo deve ser\ncuidar da mãe, sugerindo sua\ninstitucionalização precoce, pois essa intervenção está alinhada com\na Política Nacional de Atenção Básica (PNAB)."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-365591","number":"365591","sourceNumber":"365591","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com Portaria nº 2.436/2017, que aprova a Política Nacional de Atenção\nBásica (PNAB), assinale a alternativa correspondente a atribuição específica do médico.","options":{"A":"Encaminhar, quando necessário, usuários a outros pontos de atenção, respeitando fluxos locais,\nmantendo sob sua responsabilidade o acompanhamento do plano terapêutico prescrito.","B":"Participar do processo de territorialização e mapeamento da área de atuação da equipe\nidentificando grupos, famílias e indivíduos expostos a riscos e vulnerabilidades.","C":"Realizar o cuidado integral à saúde da população adscrita, prioritariamente no âmbito da\nunidade básica de saúde, e, quando necessário,\nno domicílio e nos demais espaços comunitários.","D":"Realizar ações de atenção à saúde conforme a necessidade de saúde da população local, bem\ncomo aquelas previstas nas prioridades, nos\nprotocolos, e nas diretrizes clínicas e terapêuticas."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-365590","number":"365590","sourceNumber":"365590","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Para o sucesso da Atenção Domiciliar, é fundamental que o profissional da saúde\ncompreenda a família que está recebendo\nesse cuidado, sua estrutura e funcionalidade. Dessa\nforma, torna-se necessária a apropriação pelos profissionais de saúde de algumas ferramentas\nespecíficas para abordar familiares. Considerando os instrumentos que sistematizam a abordagem\nfamiliar, assinale a alternativa equivalente ao conteúdo que trata do instrumento de avaliação\ndestinado a refletir a satisfação de cada membro da família, por meio do qual, a partir de um\nquestionário predeterminado, as famílias são classificadas como funcionais e\nmoderadamente/gravemente disfuncionais.","options":{"A":"PRACTICE","B":"FIRO","C":"Apgar familiar","D":"Tipologia familiar"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-365588","number":"365588","sourceNumber":"365588","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito do Programa Aqui tem Farmácia Popular, assinale a alternativa correta.","options":{"A":"Consiste no fornecimento de medicamentos em unidades de farmácias próprias.","B":"Fornece medicamentos gratuitos para diabetes, asma, hipertensão, osteoporose e\nanticoncepcionais.","C":"Incluiu, em junho de 2023, o medicamento formoterol + budesonida na lista de medicamentos a\nserem disponibilizados gratuitamente.","D":"Disponibiliza gratuitamente os medicamentos para osteoporose, mas, para serem fornecidos, o\npaciente deve levar o resultado de densitometria óssea comprovando o diagnóstico."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-365587","number":"365587","sourceNumber":"365587","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Assinale a alternativa que indica o princípio operacional do Sistema Único de Saúde\n(SUS), o qual determina que haja redistribuição da gestão entre município, estado e Governo\nFederal, além de definir que as ações de saúde sejam de responsabilidade principalmente do\nmunicípio, com direção única em cada esfera de governo.","options":{"A":"Hierarquização","B":"Regionalização","C":"Descentralização","D":"Resolubilidade"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-322224","number":"322224","sourceNumber":"322224","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paciente, 50 anos, procura atendimento em UBS próxima a sua residência com queixa\nde mal-estar e é acolhido pela equipe de\nenfermagem, sendo aferida pressão arterial de 160 x 100\nmmHg. Nesse caso, o médico da unidade deve:","options":{"A":"Realizar o atendimento, prescrever e solicitar exames e retorno para acompanhamento.","B":"Solicitar que o paciente agende consulta após ter encaminhamento do pronto atendimento.","C":"Realizar atendimento, encaminhá-lo ao cardiologista e orientar que o seguimento será no serviço\nsecundário.","D":"Realizar atendimento e medicar a situação atual, sem criar vínculo de seguimento.","E":"Encaminhar o paciente ao serviço de urgência e emergência."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305346","number":"305346","sourceNumber":"305346","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Ana é médica de uma equipe de Estratégia Saúde da Família cuja área de abrangência\né majoritariamente composta por uma favela. O\nrestante do seu território é considerado como de\nbaixa vulnerabilidade socioeconômica, evidenciando grande desigualdade social. Devido a\nescassez de recursos humanos na atenção primária à saúde em seu município e ao mal\ndimensionamento da área, a equipe de Ana é responsável por uma população estimada de\naproximadamente 4.500 pessoas, tornando inviável o cuidado programático recomendado para as\npopulações prioritárias, como gestantes e crianças. Diante do exposto e considerando a Política\nNacional de Atenção Básica e os princípios da Bioética, assinale a alternativa correta.","options":{"A":"Ana deve interromper os atendimentos de demanda programática de sua área, devido ao\nsuperdimensionamento do tamanho de sua área.","B":"A oferta de um número maior de consultas de pré-natal para as gestantes residentes nas áreas\nmais vulneráveis é justificável.","C":"O princípio da equidade apresentado na PNAB é descrito como a oferta igualitária do cuidado\nentre as pessoas, sem qualquer\ndiscriminação.","D":"Ana deve interromper os atendimentos ao território de baixa vulnerabilidade de sua área, devido\nao superdimensionamento do tamanho de sua área.","E":"Ana deve interromper os atendimentos à demanda espontânea de sua área, devido ao\nsuperdimensionamento do tamanho de sua área."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305355","number":"305355","sourceNumber":"305355","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Sistema Único de Saúde (SUS), apesar de constar na Constituição Federal de 1988,\nsomente é regulamentado a partir de 1990, inicialmente pela Lei nº 8080/90. As Normas\nOperacionais Básicas (NOB) trouxeram importantes mudanças ao SUS ao longo do tempo. Foi uma\ndefinição da NOB 01/96:","options":{"A":"Descentralizar a gestão do sistema, definindo três níveis de gestão: incipiente, parcial e\nsemiplena.","B":"Alocar recursos para custeio de serviços segundo sua capacidade instalada, independentemente\nda decisão dos gestores estaduais e municipais.","C":"Transferir aos municípios, de forma automática, fundo a fundo, os recursos para custeio de\natividades ambulatoriais e hospitalares.","D":"Criar o Piso Assistencial Básico (PAB); por meio de um valor per capita nacional para o custeio\ndos serviços da Atenção Básica.","E":"Determinar às secretarias estaduais de saúde a responsabilidade de elaborar o Plano Diretor de\nRegionalização com um \"conjunto mínimo de ações e serviços\"."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305356","number":"305356","sourceNumber":"305356","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei nº 13.097/2015 deu nova redação à Lei Orgânica do SUS nº 8080/90 em seu Art.\n23, permitindo \"a participação direta ou indireta, inclusive controle, de empresas ou de capital\nestrangeiro na assistência à saúde\". São casos permitidos para essa participação previstos na lei,\nEXCETO:","options":{"A":"Doações de entidades de cooperação técnica e de financiamento e empréstimo.","B":"Doações de organismos internacionais vinculados à Organização das Nações Unidas.","C":"Pessoas jurídicas destinadas a instalar, operacionalizar ou explorar centros de pesquisa com\nseres humanos.","D":"Pessoas jurídicas destinadas a instalar, operacionalizar ou explorar ações e pesquisas de\nplanejamento familiar.","E":"Pessoas jurídicas destinadas a instalar, operacionalizar ou explorar hospital geral, hospital\nespecializado, policlínica, clínica geral e clínica especializada."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305357","number":"305357","sourceNumber":"305357","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Dr. João é médico da Estratégia Saúde da Família e está atendendo Maria, 36 anos,\npela terceira vez em dois meses, devido a quadro de dores de cabeça recorrentes. Após nova\navaliação clínica, João descarta sinais de alarme e conclui se tratar de cefaleia tensional.\n\nPreocupado devido à resposta insatisfatória até então com o tratamento prescrito, Dr. João resolve\nentender um pouco mais do contexto familiar e comunitário de Maria, quando descobre que ela\npossui diversos estressores sociais, incluindo dificuldades econômicas e violência doméstica. Com\nbase nesse caso e nas políticas de saúde vigentes, assinale a alternativa CORRETA.","options":{"A":"O caso exemplifica que a prática clínica é ineficaz para o cuidado em saúde da população.","B":"A aplicação do método clínico centrado na pessoa amplia a capacidade de compreensão e\nresolução de problemas.","C":"A atuação do médico foi superficial, já que o caso descrito apresenta elevado risco de\ncomplicações e demanda exames mais específicos.","D":"Cefaleia é um motivo infrequente de consultas na Atenção Primária à Saúde, devendo essa\npaciente ser encaminhada ao nível secundário.","E":"A atuação do médico foi exagerada, já que a responsabilidade profissional com o paciente se\nlimita ao diagnóstico clínico."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305358","number":"305358","sourceNumber":"305358","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"É uma sexta-feira, véspera de carnaval, e Júnia traz seu filho, Tomás, de 6 anos, ao\npronto atendimento devido a quadro de dor de\ngarganta iniciada há 1 dia. A criança apresenta-se\nafebril, sem linfonodos palpáveis, sem exsudato em amígdalas e presença de tosse. Pela avaliação\ndos critérios de Centor, o médico assistente avalia que se trata de uma faringite viral e orienta\nJúnia\na tratar Tomás com sintomáticos e levá-lo à Unidade Básica de Saúde em caso de ausência de\nmelhora em 3 dias. Júnia insiste na prescrição de antibiótico, lembrando que, na última vez que\nTomás teve o mesmo sintoma, a melhora só ocorreu após início do uso de amoxicilina. Nessa\nsituação, o médico assistente","options":{"A":"deve prescrever o antibiótico, já que o paciente tem autonomia para escolher seu tratamento\nindependentemente da avaliação clínica.","B":"deve prescrever o antibiótico, já que o retorno para uma reavaliação na Unidade Básica de\nSaúde será inviável durante o feriado de\nCarnaval.","C":"pode considerar a prescrição antecipada de antibiótico, compartilhando a decisão de acordo com\nos valores e crenças das pessoas.","D":"não deve prescrever o antibiótico, já que o quadro é comprovadamente viral e seu uso serviria\napenas para aumento da resistência bacteriana.","E":"não deve prescrever o antibiótico, já que o médico tem autonomia para escolher o tratamento\nindependentemente da opinião do paciente."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305359","number":"305359","sourceNumber":"305359","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Metade da população mundial vive em áreas rurais, mas menos de 25% dos\nprofissionais médicos atuam nessas áreas. No\nBrasil, estima-se que 30% da sua população seja\nrural. Para além da carência de profissionais nesse ambiente, raramente se abordam as\nespecificidades do cuidado dessa população ao longo da formação médica. Assinale a alternativa\nCORRETA sobre o cuidado a populações rurais.","options":{"A":"A rede de atenção à saúde deve ter a mesma conformação das áreas urbanas, com base no\nprincípio da equidade do SUS.","B":"Os riscos ocupacionais são muito distintos dos urbanos, o que leva a um padrão de adoecimento\ndiferente na comunidade.","C":"Os atendimentos em saúde devem ser direcionados para os centros urbanos mais próximos.","D":"Os atendimentos em saúde, sejam básicos ou especializados, precisam ser descentralizados a\ntodas as áreas rurais.","E":"O cuidado em saúde da população rural muito pouco se distingue do cuidado à população\nurbana, justificando a formação prioritariamente\nvoltada a essa última."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305361","number":"305361","sourceNumber":"305361","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A organização dos sistemas de saúde geralmente reflete os valores e as preferências\ndas sociedades onde estão implantados. O estudo dos\ndiferentes tipos de financiamento dos\nsistemas de saúde ao redor do mundo identificou três formas principais: tipo Beveridge, tipo\nBismarck e tipo Semashko. Considerando essas formas de financiamento de sistemas de saúde,\nassinale a alternativa CORRETA:","options":{"A":"Sistemas de saúde tipo Beveridge são financiados por fundos de previdência social associados\nao trabalho (seguros).","B":"Países como Canadá e Reino Unido são exemplos de países com sistema de saúde tipo\nBeveridge.","C":"Sistemas de saúde do tipo Semashko são financiados pelos gastos privados em saúde.","D":"Sistemas de saúde do tipo Bismarck são financiados por impostos gerais.","E":"Países comunistas geralmente possuem sistemas de saúde do tipo Bismarck."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305363","number":"305363","sourceNumber":"305363","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Luís é médico rural em uma área de difícil acesso na região amazônica. Responsável\npelo cuidado à saúde de ribeirinhos, vem\nacompanhando, ao longo dos últimos anos, o\nagravamento progressivo dos períodos de seca na região, antigamente raras, com impactos diretos\ne significativos na subsistência e no transporte daquelas populações. Essa mudança climática\ncoincide com o avanço do desmatamento na região. Diante do caso e considerando os conceitos\nrelacionados à Vigilância Ambiental e às Diretrizes Curriculares Nacionais do Curso de Medicina,\nassinale a alternativa correta.","options":{"A":"Luís deve se manter distante dos aspectos relacionados à realidade socioambiental da\ncomunidade, uma vez que seu engajamento nessas\nquestões pode comprometer seu juízo clínico.","B":"O problema identificado foge da governabilidade de Luís, cuja formação é clínica e, portanto,\ndeve estar fora do seu escopo de atuação.","C":"A seca é um fenômeno climático natural e independente, portanto sem relação com o estado de\nsaúde de indivíduos e comunidades.","D":"Luís deve se responsabilizar por encontrar a solução ao problema apresentado, já que é o\nresponsável pela saúde daquela comunidade.","E":"Os efeitos da seca na saúde da comunidade devem gerar uma reação empática de Luís, na\nbusca de soluções compartilhadas para a\npreservação do meio ambiente."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305365","number":"305365","sourceNumber":"305365","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Triple Aim (Tripla Meta) foi uma proposta criada pelo Institute for Healthcare\nImprovement para identificação dos pilares para\no sucesso e a sustentabilidade de um sistema de\nsaúde. Com o passar do tempo, foi acrescido a essa proposta um quarto elemento,\n\ndenominando-se então Quadruple Aim (Quadrupla Meta). Assinale a alternativa que apresenta\ncorretamente esse quarto elemento.","options":{"A":"Melhor experiência do profissional.","B":"Melhor experiência do paciente.","C":"Melhores indicadores de saúde.","D":"Maior segurança do paciente.","E":"Menores custos."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298937","number":"298937","sourceNumber":"298937","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um paciente de 35 anos de idade compareceu à consulta na unidade básica de saúde\n(UBS) com queixa de disúria e presença de\nsecreção peniana há dois dias. Relata relações sexuais\ndesprotegidas nas últimas duas semanas. Ao exame físico, observou-se presença de drenagem de\nsecreção mucopurulenta na uretra. Foram realizados testes rápidos, na UBS, para HIV, hepatites B\ne C e sífilis, obtiveram-se resultados não reagentes. Considerando esse caso clínico e com base\nnos conhecimentos médicos correlatos, julgue o item a seguir. Nesse caso, o paciente deveria ter\nprocurado diretamente atendimento em atenção secundária, visto que, conforme Decreto Federal\nnº 7.508, a atenção primária não é classificada como serviço de atendimento inicial à saúde do\nusuário no Sistema Único de Saúde (SUS).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298939","number":"298939","sourceNumber":"298939","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um paciente de 73 anos de idade, diagnosticado com câncer retal, retornou ao\natendimento médico na unidade básica de saúde\npara conversar com seu médico de família, pois\nestá muito nervoso e não sabe se deve realizar os procedimentos propostos pelo especialista, visto\nque, para ele, \"é melhor morrer do que usar uma bolsinha para o resto da vida\" (colostomia). Com\nrelação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. É importante acolher o paciente quanto à questão de saúde mental e avaliar a necessidade\nde tratamento psicoterápico e (ou) medicamentoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-298945","number":"298945","sourceNumber":"298945","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um paciente de 72 anos de idade possui diagnóstico de osteoporose há um ano, em\ntratamento, e histórico de fratura de quadril há cerca de sete meses. Procurou atendimento na\nequipe Estratégia Saúde da Família (ESF) por ter apresentado torção do tornozelo direito em sua\ncaminhada matinal, com queixa de intensa dor local e dificuldade para deambular. Ao exame físico,\ndemonstra dor à palpação, limitação da movimentação articular e discreto edema local. Tendo em\nvista esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. É de grande\nimportância continuar o acompanhamento dessa paciente, em vistas de manter a longitudinalidade\ndo atendimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274421","number":"274421","sourceNumber":"274421","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Assinale a alternativa CORRETA sobre a abordagem familiar.","options":{"A":"A abordagem familiar consiste em confirmar as informações trazidas pelo paciente no ambiente\nda consulta com outros familiares, visto que tais\ninformações podem ser imprecisas ou inverídicas,\naumentando a certeza do histórico do paciente.","B":"A abordagem familiar consiste em levantar o histórico completo das doenças presentes na\nfamília, visando identificar os riscos à saúde\ndo indivíduo e selecionar os exames e orientações que\nsão importantes para ele.","C":"A abordagem familiar consiste em triagem de doenças genéticas, em que os indivíduos de uma\nmesma família realizam exames em busca de\ngenes que causem ou aumentem o risco de doenças\ndiversas.","D":"A compreensão da abordagem familiar sistêmica contribui no plano de prevenção, investigação\nclínica e do tratamento de casos simples e\ncomplexos.","E":"Não há contraindicações em convidar a família e realizar a consulta em conjunto, tendo em vista\na grande importância que o ambiente familiar\nexerce no processo de adoecimento e suporte no\ntratamento e recuperação dos indivíduos doentes."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274422","number":"274422","sourceNumber":"274422","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em relação à Atenção Primária à Saúde (APS), assinale a alternativa INCORRETA.","options":{"A":"É um tipo altamente personalizado de prestação de cuidado.","B":"Inclui a continuidade, pelo fato de cuidar de pessoas na doença e na saúde ao longo de um\nperíodo.","C":"É o cuidado de primeiro contato, servindo como ponto de entrada de uma pessoa com o serviço\nde saúde.","D":"Tem a função de servir e coordenar todas as necessidades de saúde da pessoa.","E":"A APS é uma medicina simplificada, atendendo apenas condições mais básicas de saúde."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274429","number":"274429","sourceNumber":"274429","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Método Clínico Centrado na Pessoa (MCCP) é um dos modelos de abordagem à\nconsulta, sendo considerado um método que engloba e sistematiza diversos aspectos positivos das\ndiferentes formas de abordagem aos problemas de saúde. Quanto ao MCCP, assinale a alternativa\ncorreta.","options":{"A":"Seu primeiro componente é ?sendo realista?, o que pode ser exemplificado pela consciência do\nmédico que seus recursos são limitados e que não será possível resolver todos os problemas que\nlhe forem apresentados ao longo dos atendimentos.","B":"Um dos seus componentes é ?considerar a pessoa como um todo?, ou seja, realizar exame\nfísico completo em todas as consultas sem esquecer qualquer órgão ou sistema.","C":"Trata-se de um checklist a ser realizado a cada consulta, a fim de abarcar todos os\ncomponentes e realizar adequada revisão de sintomas e sistemas, bem como os fatores\nsocioeconômicos relacionados ao agravo à saúde.","D":"Seu primeiro componente é ?explorando a doença e a experiência da doença?, em que são\nabordados os sentimentos, ideias, impacto na\nfuncionalidade e quais as expectativas do paciente\nno processo de adoecimento.","E":"Tal método é exclusivo no atendimento de pacientes com queixas de saúde mental, tendo pouco\nou nenhum valor no acompanhamento de problemas\norgânicos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274432","number":"274432","sourceNumber":"274432","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Para adequado controle dos agravos crônicos à saúde, é de fundamental importância a\ncorresponsabilização da pessoa. Para tanto, nem sempre a educação em saúde é suficiente, sendo\núteis, por exemplo, as estratégias motivacionais. Tendo tal conceito em mente, considere a\nseguinte situação clínica: Senhor João é um homem de 55 anos, em acompanhamento por\nhipertensão há cerca de 2 anos, com bom controle. Nunca fumou e é aderente ao tratamento\nmedicamentoso, porém mantém- se sedentário. Ao conversar com ele novamente, seu médico\nidentifica que o senhor João reconhece que o sedentarismo é um problema e ele está considerando\niniciar atividade física, porém diz não ter tempo. Acha que conseguirá iniciar caminhadas quando\ntirar férias do trabalho, o que deve ocorrer em cerca de 4 meses. Tendo em vista tal situação e os\nEstágios de Mudança de Comportamento do Modelo Transteórico, em qual estágio motivacional o\nsenhor João está, no que diz respeito à prática de atividade física?","options":{"A":"Pré-contemplação, pois, embora tenha identificado o sedentarismo como problema, ainda não\ntem uma data exata para iniciar a prática de atividade física.","B":"Contemplação, pois admite que há um problema, porém apresenta um comportamento\nambivalente e considera adotar mudanças eventualmente.","C":"Preparação, pois já definiu quando deve iniciar atividade física e criou condições para mudar o\ncomportamento.","D":"Ação, pois o planejamento para a prática de atividade física é a primeira mudança necessária na\nmudança do comportamento.","E":"Manutenção, pois não alterou seu comportamento sedentário, mantendo-se inativo."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274433","number":"274433","sourceNumber":"274433","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A promoção da alimentação saudável é fundamental para a saúde pública, e ações que\nvisem promovê-la devem levar em conta os nutrientes e as especificidades nutricionais de cada\nfaixa etária, sendo diferentes conforme idade, sexo, grau de atividade física e diferentes situações\nda vida, como a gestação. Nesse contexto, em relação às seguintes orientações essenciais em\nnutrição, assinale a alternativa correta.","options":{"A":"As mulheres que desejam engravidar devem ser aconselhadas a comer alimentos ricos em\nferro-heme, como carnes e ovos. Além de consumir alimentos fontes de ferro na forma férrica,\nassociados ao consumo de alimentos fontes de vitamina C, o que reduz a forma férrica à ferrosa e\nmelhora a absorção. O período mais crítico em relação às necessidades nutricionais de ferro é o\nprimeiro trimestre.","B":"Os cuidadores das crianças devem ser orientados a evitar a oferta de alimentos com alta\ndensidade calórica, como bebidas pobres em\nnutrientes (refrigerantes, sucos artificiais), açúcar,\ndoces em geral, salgadinhos, achocolatados, gelatinas e outras guloseimas antes dos dois anos de\nvida. O consumo de alimentos ricos em gordura, como frituras, bolachas recheadas, sorvetes e\nembutidos, embora desaconselhável, não está relacionado ao fato das crianças preferirem esses\nalimentos em substituição à alimentação básica.","C":"No período da adolescência, há um crescimento rápido e aumento da necessidade energética,\nporém não nas necessidades de cálcio ou\nferro.","D":"Na avaliação do adulto, existem alguns métodos para avaliação da gordura abdominal. A OMS\norienta a medida da circunferência abdominal no ponto médio entre o último rebordo costal e a\ncrista ilíaca. A relação cintura/quadril consiste em um bom indicador complementar que tem boa\ncorrelação com a gordura abdominal e associação com o risco de morbimortalidade. Considera-se\ncomo risco para doenças cardiovasculares valores de relação cintura/quadril > 1 para mulheres e >\n0,85 para homens.","E":"Existem evidências de que a absorção de certos nutrientes diminui com a idade. No entanto\nainda não existem evidências suficientes de\nque os valores recomendados de nutrientes devam ser\n\ndiminuídos ou aumentados para idosos. Os pontos de corte de IMC, entretanto, são diferentes para\na população idosa, sendo IMC < 22 classificado\ncomo baixo peso, de 22 a 27 como eutrófico e > 27\ncomo sobrepeso."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274434","number":"274434","sourceNumber":"274434","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A atenção primária à saúde tem grande potencial para estimular a prática de atividade\nfísica. Sobre esse assunto, assinale a\nalternativa correta.","options":{"A":"O sedentarismo é um fator de risco importante para doenças cardiovasculares.","B":"Várias doenças apresentam melhora com a prática de atividade física, como diabetes melito e\nhipertensão arterial, porém outras, como osteoporose e câncer, não são afetadas por essa prática.","C":"Os benefícios da atividade física são sustentados, ou seja, mesmo com a sua interrupção, seus\nefeitos são permanentes.","D":"Não é necessária qualquer avaliação médica na atenção primária previamente à prática de\natividade física, sendo que a imposição dessa condição diminui a aderência e dificulta o início da\nprática de exercícios.","E":"Vários estudos demonstram o benefício da prática de atividade física moderada, 30 minutos por\ndia, 5 vezes por semana. Não havendo benefício adicional no aumento dessa quantidade."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274435","number":"274435","sourceNumber":"274435","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Senhor José, 70 anos, IMC 38 kg/m2, sedentário, hipertenso (controlado com\nmedicação), sofreu um acidente vascular\nencefálico (AVE) há 9 meses, apresentando como\nsequela redução da força em dimídio esquerdo. Desde o AVE, tem caminhado com dificuldade e\nrefere perda de equilíbrio e algumas quedas. Nega alterações na sensibilidade. Além disso, tem\nqueixa de lombalgia há cerca de 20 anos. Nunca realizou fisioterapia. Tendo em vista esse caso,\nassinale a alternativa correta.","options":{"A":"O senhor José não deve ser encaminhado à fisioterapia, pois esta é destinada especialmente\nem casos agudos, não tendo benefício para as suas\ncondições.","B":"O senhor José pode ser encaminhado à fisioterapia, mas apenas para controle da dor lombar,\npois não há benefícios na realização de\nfisioterapia após 6 meses de AVE.","C":"O senhor José pode ser encaminhado à fisioterapia, podendo obter como benefícios melhora da\ndor, do equilíbrio, fortalecimento muscular e ganho de autonomia.","D":"O senhor José pode ser encaminhado à fisioterapia, porém isso apenas evitará a progressão do\ncaso, não sendo possível a sua melhoria.","E":"O senhor José não deve ser encaminhado à fisioterapia, pois, antes disso, é necessário que\ndeixe de ser sedentário e inicie a prática de caminhadas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274437","number":"274437","sourceNumber":"274437","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre os indicadores de saúde e as internações por condições sensíveis à atenção\nprimária (ICSAP), assinale a alternativa correta.","options":{"A":"A lista das ICSAP é definida internacionalmente, sendo a mesma nos mais diversos países do\nmundo.","B":"As ICSAP variam conforme a idade, sendo que, nos extremos de idade, as hospitalizações por\nICSAP tendem a diminuir.","C":"A associação entre ICSAP e piores condições socioeconômicas é consistente, porém seu\nimpacto não é muito importante, de acordo com estudos.","D":"Nos municípios com alta cobertura da Estratégia da Saúde da Família (ESF), os estudos\ndemonstram redução significativa das ICSAP.","E":"A lista das ICSAP não inclui doenças imunizáveis."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274438","number":"274438","sourceNumber":"274438","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Referente à terapia comunitária e grupos na atenção primária à saúde (APS), assinale\na alternativa correta.","options":{"A":"Os grupos na APS são de grande valor para as condições de saúde mental, porém não auxiliam\nno manejo de condições crônicas, como\nhipertensão e diabetes.","B":"Na construção de grupos de crianças, é importante a manutenção de critérios de\nhomogeneidade no que diz respeito à faixa\netária e ao tipo de patologia. Também é importante um\nacompanhamento paralelo com os pais, sendo de preferência individual.","C":"Os grupos de educação em saúde devem, preferencialmente, ser focados no facilitador, pois,\nalém deste deter mais conhecimento, é uma\nforma de evitar divagações desnecessárias e melhorar\na eficiência do grupo.","D":"A terapia comunitária dá ênfase em trazer para a comunidade o saber científico adequado, com\nfoco nessas orientações, tendo pouco espaço para autonomia dos membros.","E":"Grupos homogêneos podem ser altamente favoráveis ao processo terapêutico, pois\nnormalmente os membros identificam-se uns com os outros."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-261318","number":"261318","sourceNumber":"261318","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O rastreio e o diagnóstico precoce de neoplasias fazem parte do atendimento na Rede\nde Atenção Primária. Considerando isso,\nsuponha que uma mulher de 53 anos de idade procure\numa unidade básica de saúde para realização de exames de rotina, e o médico da Atenção\nPrimária perceba, na face dela, uma pequena lesão papulosa, de cor rósea, aspecto \"perolado\",\ncom finos vasos em sua superfície. Ao ser questionada, a paciente informa que essa lesão\napresentou crescimento lento e progressivo. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. O atendimento realizado, que leva em conta a\nprevenção, a cura e a reabilitação de doenças, respeita o princípio da integralidade do Sistema\nÚnico de Saúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-261319","number":"261319","sourceNumber":"261319","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O rastreio e o diagnóstico precoce de neoplasias fazem parte do atendimento na Rede\nde Atenção Primária. Considerando isso,\nsuponha que uma mulher de 53 anos de idade procure\numa unidade básica de saúde para realização de exames de rotina, e o médico da Atenção\nPrimária perceba, na face dela, uma pequena lesão papulosa, de cor rósea, aspecto \"perolado\",\ncom finos vasos em sua superfície. Ao ser questionada, a paciente informa que essa lesão\napresentou crescimento lento e progressivo. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Entre os princípios da Atenção Primária, estão a\nlongitudinalidade, a regionalização, a hierarquização e a coordenação do cuidado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-261320","number":"261320","sourceNumber":"261320","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O rastreio e o diagnóstico precoce de neoplasias fazem parte do atendimento na Rede\nde Atenção Primária. Considerando isso,\nsuponha que uma mulher de 53 anos de idade procure\numa unidade básica de saúde para realização de exames de rotina, e o médico da Atenção\nPrimária perceba, na face dela, uma pequena lesão papulosa, de cor rósea, aspecto \"perolado\",\ncom finos vasos em sua superfície. Ao ser questionada, a paciente informa que essa lesão\napresentou crescimento lento e progressivo. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Na Atenção Primária, o princípio da longitudinalidade\ntrata da criação de vínculo e do acompanhamento da saúde do indivíduo ao longo da vida dele.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-250161","number":"250161","sourceNumber":"250161","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito dos princípios fundamentais e das diretrizes organizativas do Sistema Único\nde Saúde (SUS), estabelecidos pela Lei\nOrgânica da Saúde, julgue o item a seguir. O princípio da\nequidade estabelece que o acesso aos serviços e às ações de saúde deve ser igualitário a todas as\npessoas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-250162","number":"250162","sourceNumber":"250162","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito dos princípios fundamentais e das diretrizes organizativas do Sistema Único\nde Saúde (SUS), estabelecidos pela Lei Orgânica da Saúde, julgue o item a seguir. A garantia de\nacesso a ações de promoção, prevenção, proteção e recuperação da saúde é dada pelo princípio\nda universalidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-250163","number":"250163","sourceNumber":"250163","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito dos princípios fundamentais e das diretrizes organizativas do Sistema Único\nde Saúde (SUS), estabelecidos pela Lei Orgânica da Saúde, julgue o item a seguir. Em nível\nfederal, o comando do SUS é exercido pelo Ministério de Saúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-250164","number":"250164","sourceNumber":"250164","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito dos princípios fundamentais e das diretrizes organizativas do Sistema Único\nde Saúde (SUS), estabelecidos pela Lei Orgânica da Saúde, julgue o item a seguir. Entre os\nprincípios fundamentais do SUS, está a participação social e a complementariedade do setor\nprivado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-250165","number":"250165","sourceNumber":"250165","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito dos princípios fundamentais e das diretrizes organizativas do Sistema Único\nde Saúde (SUS), estabelecidos pela Lei Orgânica da Saúde, julgue o item a seguir. A organização\ndo SUS estabelece que os serviços de saúde devem ser hierarquizados por níveis de atenção e\ncomplexidade para atender às diferentes necessidades da população.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-250166","number":"250166","sourceNumber":"250166","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito dos princípios fundamentais e das diretrizes organizativas do Sistema Único\nde Saúde (SUS), estabelecidos pela Lei\nOrgânica da Saúde, julgue o item a seguir. A\ndescentralização é uma diretriz organizativa do SUS que prevê a cooperação entre os três níveis de\ngoverno na execução dos serviços e das ações de saúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-211998","number":"211998","sourceNumber":"211998","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Constituição Federal de 1988 define três grandes referências para o sistema de\nsaúde brasileiro: um conceito ampliado de saúde,\na saúde como direito do cidadão e dever do\nEstado e a instituição de um Sistema Único de Saúde (SUS). (SAMPAIO; MENDONÇA; LERMEN\nJÚNIOR, 2012). LOPES, J.M.C.; GUSSO, G. Tratado de medicina de família e comunidade:\nprincípios, formação e prática. Vol. 1 e 2. São Paulo: Artmed, 2012. Considerando a Atenção\nPrimária à Saúde no Brasil, assinale a alternativa correta.","options":{"A":"O Piso de Atenção Básica (PAB) foi responsável por uma forte indução de mudanças no modelo\nassistencial, com grande aumento do acesso da população aos serviços de saúde.","B":"A implantação do Programa de Agentes Comunitários de Saúde está intimamente relacionada\ncom as boas experiências na implantação da\nEstratégia Saúde da Família.","C":"A Atenção Primária à Saúde é a única porta de entrada e centro de comunicação da Rede de\nAtenção à Saúde, coordenadora do cuidado e ordenadora das ações e dos serviços\ndisponibilizados na rede.","D":"O território de responsabilidade das equipes proporciona ações exclusivas do setor da saúde.","E":"Os resultados da saúde da família em diversos estudos ainda não confirmam o impacto positivo\nda estratégia em aspectos e atributos da Atenção\nPrimária à Saúde."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-211993","number":"211993","sourceNumber":"211993","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando que a competência cultural é uma das características da Atenção\nPrimária à Saúde, o médico de família e comunidade tem a tarefa de lidar com a diversidade\ncultural. Com base no exposto, assinale a alternativa correta.","options":{"A":"A cultura deve ser hipervalorizada ao ser identificada como problema principal de saúde.","B":"Nesse caso, uma aproximação entre as ciências da saúde e a antropologia deve ser evitada\npara facilitar as ações da equipe de saúde.","C":"A competência cultural resume-se em conhecer as crenças do outro a respeito dos fenômenos\nrelacionados à saúde.","D":"A preocupação com integralidade e visão ampla do processo saúde-doença é característica para\numa maior adequação do cuidado da saúde em\ndiferentes contextos.","E":"Os fenômenos relacionados à saúde e à doença só podem ser compreendidos dentro de um\ncontexto histórico e social que se resuma a uma concepção biomédica."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-212001","number":"212001","sourceNumber":"212001","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os preceitos da integralidade são importantes em todos os níveis de atenção, porém\nsão essenciais no campo da Atenção Primária à\nSaúde. A respeito desse tema, assinale a\nalternativa correta.","options":{"A":"O ser humano se resume a uma totalidade biológica e psicológica.","B":"A complexidade do binômio saúde-adoecimento está somente na multiplicidade dos fatores\nenvolvidos com ele.","C":"Quando um componente da rede biopsicossocial é afetado (seja no plano individual, familiar ou\ncomunitário), há repercussão na totalidade orgânica.","D":"O referencial básico da medicina centrada no modelo apresentado é simplesmente prevenir a\neclosão de doenças.","E":"Uma abordagem centrada no indivíduo é recomendada, tendo em vista que família ou\ncomunidade não interferem no quadro biológico deste."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-211996","number":"211996","sourceNumber":"211996","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo a Portaria nº 2.436/2017, que aprova a Política Nacional de Atenção básica,\nestabelecendo a revisão de diretrizes para a organização da Atenção Básica, no âmbito do Sistema\nÚnico de Saúde (SUS), é atribuição comum a todos os membros das equipes que atuam na\nAtenção Básica participar do processo de territorialização e mapeamento da área de atuação da\nequipe, identificando grupos, famílias e indivíduos expostos a riscos e vulnerabilidades. Acerca da\nterritorialização, assinale a alternativa correta.","options":{"A":"A unidade operacional do agente comunitário de saúde é o módulo assistencial.","B":"Corresponde ao município capaz de ser referência para outros municípios, em qualquer nível de\natenção.","C":"É o processo de análise territorial visando a uma base organizativa dos sistemas de saúde e do\nplanejamento da vigilância em saúde.","D":"Trata-se de uma rede de ações e serviços de saúde de um município de uma região de saúde, a\nfim de garantir o cumprimento dos princípios constitucionais.","E":"Consiste em um espaço ilimitado político-administrativamente ou por ação de um grupo social,\nem que se edificam e exercitam os poderes do\nEstado e dos cidadãos."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-212010","number":"212010","sourceNumber":"212010","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um artesão não especializado, de 20 anos de idade e portador de erupção cutânea\nobscura, foi encaminhado a um dermatologista\npor um cirurgião oftalmológico. O paciente foi\ntratado sem sucesso por muitas semanas, até que foi examinado pelo respectivo clínico geral, que\nconfirmou que o paciente dividia a cama com o próprio irmão. O irmão também tinha uma erupção,\ne ambos se coçavam mais à noite. O clínico geral foi, assim, capaz de diagnosticar e controlar a\nsarna subjacente. STARFIELD B. Atenção primária: equilíbrio entre necessidades de saúde,\nserviços e tecnologia. Editora UNESCO, 2002, com adaptações. A respeito desse caso clínico e\ncom base nos conhecimentos médicos correlatados, assinale a alternativa correta.","options":{"A":"O contexto familiar, na avaliação dos problemas, acaba dificultando o diagnóstico diferencial.","B":"A centralização na família representa o alcance da universalidade, fornecendo uma base para\nconsideração dos pacientes dentro dos respectivos ambientes.","C":"A centralização na família é avaliada apenas por meio de exame clínico dos membros da família.","D":"A utilização da família como parte integrante do manejo clínico é infração ética porque fere o\nprincípio da confidencialidade e o respeito à privacidade.","E":"O caso indica a necessidade de entender-se melhor as contribuições que são feitas por uma\norientação para a família, com reconhecimento da importância do biológico, social e ambiental que\nagrupam as famílias."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-212016","number":"212016","sourceNumber":"212016","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Ontem uma paciente veio e me falou que sentia dores, desconfortos, dores de cabeça e\nproblemas em todas as partes do corpo, e ela tinha certeza que não era gripe e que havia algo\nerrado com ela que ela não sabia o que era. Eu a examinei, mas não encontrei nada anormal.\n\nEntão a encorajei a falar a respeito do que estava sentindo. Percebi que ela apresentava um olhar\nansioso e observei-a. Finalmente, ela rendeu e disse: \"Olha, eu estou usando drogas\". Então\ntornou-se claro que os problemas que ela estava apresentando eram sintomas de abstinência.\n\nSTARFIELD B. Atenção primária: equilíbrio entre necessidades de saúde, serviços e tecnologia.\nEditora UNESCO, 2002, com adaptações. Com relação\na esse caso clínico e considerando os\nconhecimentos médicos correlatos, assinale a alternativa correta.","options":{"A":"O profissional tem a responsabilidade de reconhecer os problemas, as necessidades ou as\npreocupações do paciente e de formular essas necessidades em um diagnóstico.","B":"As interações entre profissionais e pacientes desfavorecem o estabelecimento de relações de\nlonga duração e dificultam a efetividade na Atenção Primária.","C":"Na interação médico-paciente, o paciente deve assumir atitude de passividade, enquanto o\nmédico deve tomar as decisões, uma vez que possui preparo técnico-científico para isso.","D":"A adequação da interação paciente-médico inclui a simples transferência de informações.","E":"A franqueza no aconselhamento factual é, certamente, a melhor abordagem na interação entre\nprofissionais e pacientes."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-212015","number":"212015","sourceNumber":"212015","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Denota a extensão da relação com um profissional ou unidade de saúde no decorrer do\ntempo, que não tem base na presença de tipos específicos de diagnósticos ou problemas de\nsaúde. As classificações mais altas são atribuídas onde a relação tem base no cadastramento ou\nregistro com um profissional específico. STARFIELD,B. Atenção primária: equilíbrio entre\nnecessidades de saúde, serviços e tecnologia. Editora UNESCO, 2002, com adaptações. A\ndefinição apresentada refere-se ao (à)","options":{"A":"Primeiro contato.","B":"Coordenação (ou integração).","C":"Abrangência.","D":"Longitudinalidade.","E":"Integralidade."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-212014","number":"212014","sourceNumber":"212014","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Quanto à acessibilidade em saúde e ao primeiro contato, denominado porta de entrada,\nassinale a alternativa correta.","options":{"A":"Um ponto de entrada facilmente acessível faz com que a atenção adequada possa ser obtida,\nincorrendo em gastos adicionais.","B":"A solicitação de uma consulta a um ponto de entrada antes de uma consulta está associada à\nutilização reduzida de serviços especializados.","C":"Pesquisas apontam para o aumento de custos em saúde quando pessoas são encaminhadas a\nespecialistas por médicos da Atenção Primária, pelo fato de estarem sujeitas a uma cadeia de\nexames diagnósticos.","D":"O uso dos profissionais especialistas para a atenção ao primeiro contato leva a uma atenção\nmais apropriada e a melhores resultados de saúde.","E":"Médicos da Atenção Primária lidam com problemas mais afastados do próprio contexto social."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-352350","number":"352350","sourceNumber":"352350","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Clara, uma adolescente de 16 anos, comparece à unidade básica de saúde (UBS) em\nbusca de atendimento médico. Na recepção,\no atendente responsável pelo acolhimento verifica o\nendereço de Clara, confirma que ela reside na área de abrangência da UBS e a encaminha para a\nsala da equipe de saúde da família de sua área. Lá, ela é atendida por uma enfermeira da equipe,\nque, após coletar informações sobre a queixa e sua duração, bem como aferir os sinais vitais,\nreconhece sinais de gravidade. Diante disso, a enfermeira aloca a paciente em uma maca na sala\nde medicação e chama imediatamente o médico da equipe, que a atende prontamente. Clara relata\nque está sentindo dor na região hipogástrica e disúria há cerca de três dias, com uma piora\ngradual. Ela teve calafrios durante a última noite, mas não percebeu que poderia estar com febre. A\npaciente está mais preocupada com as dores e com um atraso menstrual. Ela não consegue\nfornecer a data da última menstruação, mas acredita que tenha ocorrido antes do nascimento de\nseu irmão, que hoje tem três meses. Ao realizar o exame físico, a equipe de saúde observa que\nClara está sonolenta, febril, eupneica, sudoreica, com livedo e mal perfundida. Os pulsos estão\nsimétricos, as bulhas cardíacas são normofonéticas, mas a paciente apresenta taquicardia e um\nsopro sistólico. O exame abdominal revela dor à palpação na região hipogástrica. Além disso, foram\nidentificadas equimoses em diferentes estágios de evolução em seu tórax e abdome. Quando\nquestionada sobre as lesões equimóticas, Clara começa a chorar e pede para não abordar mais o\nassunto. Tendo como base o caso acima, a política nacional de humanização, os atributos e\nfunções da atenção primária e conhecimentos correlatos, julgue o item a seguir. O acolhimento da\ndemanda espontânea de Clara foi realizado de forma correta, priorizando o devido reconhecimento\nda equipe responsável por sua área e assim preservando a característica diferencial da atenção\nprimária: a longitudinalidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-366204","number":"366204","sourceNumber":"366204","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Acerca do Sistema Único de Saúde (SUS), sua estrutura, seus princípios e conceitos\ncorrelatos julgue o próximo item. São legislações basilares do SUS a Constituição Federal (CF) e\nas chamadas leis orgânicas da saúde: Lei n.º? 8.080 e 8.142, ambas de 1990.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-366202","number":"366202","sourceNumber":"366202","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Acerca do Sistema Único de Saúde (SUS), sua estrutura, seus princípios e conceitos\ncorrelatos julgue o próximo item. Uma das\ngrandes novidades da Lei n.° 8.142/1990 foi a\ninstitucionalização da participação comunitária, instituindo-se conselhos de saúde e conferências de\nsaúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-352347","number":"352347","sourceNumber":"352347","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Clara, uma adolescente de 16 anos, comparece à unidade básica de saúde (UBS) em\nbusca de atendimento médico. Na recepção,\no atendente responsável pelo acolhimento verifica o\nendereço de Clara, confirma que ela reside na área de abrangência da UBS e a encaminha para a\nsala da equipe de saúde da família de sua área. Lá, ela é atendida por uma enfermeira da equipe,\nque, após coletar informações sobre a queixa e sua duração, bem como aferir os sinais vitais,\nreconhece sinais de gravidade. Diante disso, a enfermeira aloca a paciente em uma maca na sala\nde medicação e chama imediatamente o médico da equipe, que a atende prontamente. Clara relata\nque está sentindo dor na região hipogástrica e disúria há cerca de três dias, com uma piora\ngradual. Ela teve calafrios durante a última noite, mas não percebeu que poderia estar com febre. A\npaciente está mais preocupada com as dores e com um atraso menstrual. Ela não consegue\nfornecer a data da última menstruação, mas acredita que tenha ocorrido antes do nascimento de\nseu irmão, que hoje tem três meses. Ao realizar o exame físico, a equipe de saúde observa que\nClara está sonolenta, febril, eupneica, sudoreica, com livedo e mal perfundida. Os pulsos estão\nsimétricos, as bulhas cardíacas são normofonéticas, mas a paciente apresenta taquicardia e um\nsopro sistólico. O exame abdominal revela dor à palpação na região hipogástrica. Além disso, foram\nidentificadas equimoses em diferentes estágios de evolução em seu tórax e abdome. Quando\nquestionada sobre as lesões equimóticas, Clara começa a chorar e pede para não abordar mais o\nassunto. Tendo como base o caso acima, a política nacional de humanização, os atributos e\nfunções da atenção primária e conhecimentos correlatos, julgue o item a seguir. A transferência\nimediata da paciente para uma unidade hospitalar de referência se faz necessária independente de\nsua estabilidade hemodinâmica, uma vez que atendimento de emergências não faz parte da\natribuição da atenção primária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-366247","number":"366247","sourceNumber":"366247","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Acerca da Medicina de Família e Comunidade (MFC) e da Atenção Primária a Saúde\n(APS) no Brasil e no mundo e suas\ntecnologias, julgue o item seguinte. A forma de pagamento do\nmédico de família por capitação aliado ao monopólio do acesso ao especialista é, em países como\no Reino Unido, um ponto importante para o controle do gasto sanitário e obtenção de excelentes\nresultados do sistema como um todo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-366260","number":"366260","sourceNumber":"366260","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Acerca da Medicina de Família e Comunidade (MFC) e da Atenção Primária a Saúde\n(APS) no Brasil e no mundo e suas\ntecnologias, julgue o item seguinte. O financiamento da atenção\nprimária por capitação ponderada vigente no país determina ao Governo Federal repasses de\nverba conforme o número de pessoas cadastradas, com pesos diferentes para pessoas em\nvulnerabilidade social, que inclui beneficiários do bolsa família, mas exclui aposentados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334904","number":"334904","sourceNumber":"334904","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com Barbara Starfield (2002), corresponde aos atributos da Atenção\nPrimária à Saúde o (a)","options":{"A":"primeiro contato, a coordenação do cuidado e a competência cultural.","B":"integralidade, a competência cultural e a capilaridade.","C":"centralidade na família, o primeiro contato e a humanização.","D":"universalidade, a orientação para a comunidade e a coordenação do cuidado.","E":"humanização, a longitudinalidade e a integralidade."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334905","number":"334905","sourceNumber":"334905","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Portaria no 2.979/2019 instituiu o Programa Previne Brasil, estabelecendo um novo\nmodelo de financiamento de custeio da Atenção Primária à Saúde (APS) no âmbito do Sistema\nÚnico de Saúde (SUS). Acerca da referida Portaria, assinale a alternativa correta.","options":{"A":"A capitação ponderada corresponde ao extinto Piso de Atenção Básica variável (PAB variável).","B":"A capitação ponderada leva em conta a vulnerabilidade socioeconômica e o perfil demográfico\nda população, além da classificação geográfica do\nmunicípio.","C":"O pagamento por desempenho será executado apenas para as equipes de Saúde da Família,\nficando excluída a produtividade das equipes de APS.","D":"A lógica de pagamento por desempenho na atenção básica é inédita no SUS, sendo destaque\npara a ampliação do financiamento neste\nnível de complexidade.","E":"O pagamento para ações estratégicas corresponde ao extinto Piso de Atenção Básica fixo (PAB\nfixo)."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334907","number":"334907","sourceNumber":"334907","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em seu clássico texto O nascimento da medicina social, Michel Foucault apresenta,\n\"grosso modo\", três etapas na formação da\nmedicina social e, para tanto, traz exemplos de três\npaíses europeus, associando-os a cada uma dessas etapas. Com base nisso, assinale a alternativa\nque apresenta o país e as características correlacionados de maneira correta.","options":{"A":"Alemanha - Medicina da força de trabalho. Lei dos pobres. Vacina obrigatória. Localização e\ndestruição de lugares insalubres. Controle da saúde e dos corpos dos mais pobres, tornando-os\nmais aptos ao trabalho.","B":"Inglaterra - Medicina de estado. Polícia sanitária. Normalização da prática da atividade dos\nmédicos. Organização administrativa da atividade dos médicos.","C":"Portugal - Medicina da força de trabalho. Lei dos pobres. Vacina obrigatória. Controle da\ncirculação da água e do ar. Emigração de cemitérios para a periferia da cidade.","D":"França - Medicina urbana. Modelo médico e político da quarentena. Controle da circulação da\nágua e do ar. Emigração de cemitérios para\na periferia da cidade.","E":"Espanha - Medicina de estado. Polícia sanitária. Normalização da prática e do saber médicos.\n\nControle da saúde e dos corpos dos mais pobres, tornando-os mais aptos ao trabalho."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334908","number":"334908","sourceNumber":"334908","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Proposta de um programa específico destinado a populações e regiões pobres a quem\nse oferece, exclusivamente, um conjunto de\ntecnologias simples e de baixo custo, provido por\npessoal de baixa qualificação profissional e sem a possibilidade de referência a níveis de atenção\nde maior densidade tecnológica. A descrição apresentada é característica da","options":{"A":"Atenção Primária seletiva.","B":"Clínica Ampliada.","C":"Medicina Centrada na Pessoa.","D":"Estratégia Saúde da Família.","E":"Promoção da Saúde."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343466","number":"343466","sourceNumber":"343466","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Acerca dos Sistemas de Saúde no Brasil, é INCORRETO afirmar:","options":{"A":"O financiamento do Sistema Supletivo de Assistência Médica ocorre por meio de dois\nmecanismos: desembolso direto ou por renúncia fiscal,\nna qual há abatimento do imposto devido\npara pessoa física ou jurídica.","B":"Para cumprir todas as suas atribuições constitucionais, o Sistema Único de Saúde conta com\ndiversos organismos espalhados pelas instituições nas três esferas de gestão: os órgãos de\nvigilância epidemiológica, bem como os de planejamento, gestão de controle e avaliação de\nserviços.","C":"O segmento lucrativo tem como sua parcela mais expressiva o chamado Sistema Supletivo de\nAssistência Médica, abarcando, apenas, as cooperativas médicas e os planos de administração.","D":"A matriz gerencial do Sistema Único de Saúde permite a coexistência do nível técnico e político\ncom mecanismos de participação direta."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343468","number":"343468","sourceNumber":"343468","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com o artigo 198 da CF/88, são diretrizes do Sistema Único de Saúde\n(SUS):","options":{"A":"Descentralização, com direção única em cada esfera de governo.","B":"Atendimento integral, com prioridade exclusiva para as atividades preventivas.","C":"Ações e serviços de saúde organizados de forma universal e independente dos níveis de\ncomplexidade.","D":"Não participação da comunidade, exceto por meio das conferências e conselhos de saúde."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343472","number":"343472","sourceNumber":"343472","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Programa Saúde da Família (PSF) é uma estratégia desenvolvida pelo Ministério da\nSaúde com o objetivo de oferecer a atenção\nbásica/primária de forma mais resolutiva e\nhumanizada, sendo fundamental à consolidação do Sistema Único de Saúde. Acerca deste\nprograma, é CORRETO afirmar:","options":{"A":"Visa a ampliação da necessidade de leitos hospitalares.","B":"Não prevê encaminhamento para consultas especializadas.","C":"Prevê o cadastramento de famílias, segundo a definição da área territorial pré-estabelecida para\na adscrição.","D":"Centraliza o atendimento nos agentes comunitários de saúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343473","number":"343473","sourceNumber":"343473","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O conjunto de ações capaz de eliminar, diminuir ou prevenir riscos à saúde e de intervir\nnos problemas sanitários decorrentes do meio\nambiente, da produção e circulação de bens e da\nprestação de serviços de interesse da saúde, abrangendo o controle de bens de consumo que,\ndireta ou indiretamente, se relacionem com a saúde, compreendidas todas as etapas e processos,\nda produção ao consumo, e o controle da prestação de serviços que se relacionam direta ou\nindiretamente com a saúde é denominação da:","options":{"A":"Vigilância Sanitária.","B":"Vigilância da Saúde do Trabalhador.","C":"Vigilância Ambiental em Saúde.","D":"Vigilância Epidemiológica."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-343479","number":"343479","sourceNumber":"343479","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Primária à Saúde (APS) é o primeiro nível de atenção em saúde, oferecendo\natendimento abrangente, acessível e baseado na comunidade, que pode atender de 80% a 90%\ndas necessidades de saúde de uma pessoa ao longo de sua vida. A APS tem como atributos\nessenciais, EXCETO:","options":{"A":"Longitudinalidade.","B":"Coordenação.","C":"Integralidade.","D":"Orientação familiar."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307130","number":"307130","sourceNumber":"307130","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Resolução do Ministério da Saúde n. 1/2021 dispõe a respeito do Estatuto da\nAgência para o Desenvolvimento da Atenção\nPrimária à Saúde (Adaps) e foi publicada no último\ndia 15 de outubro, sendo duramente criticada por entidades que tradicionalmente defendem o\nSistema Único de Saúde (SUS), como é o caso da Associação Brasileira de Saúde Coletiva\n(Abrasco), Centro Brasileiro de Estudos em Saúde (Cebes) e Sociedade Brasileira de Bioética\n(SBB). Acerca desse tema, é correto afirmar que pode ser considerada uma competência da Adaps\nAlternativas:","options":{"A":"prestar serviços de atenção primária à saúde no âmbito do SUS, em caráter substitutivo à\natuação dos entes federativos.","B":"extinguir o Programa Médicos pelo Brasil.","C":"monitorar e avaliar os resultados das atividades desempenhadas pelos municípios denunciados\npela ouvidoria.","D":"firmar contratos, convênios, acordos, ajustes e outros instrumentos congêneres com órgãos,\ndesde que privados.","E":"desenvolver atividades de ensino, pesquisa e extensão, mediante a integração entre o ensino e\no serviço."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307131","number":"307131","sourceNumber":"307131","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As alterações identificadas entre as versões de 2011 e 2017 da Política Nacional de\nAtenção Básica (PNAB) foram alvo não apenas\nde críticas, mas também de defesa por diferentes\natores sociais. Receberam destaque as modificações que envolveram a criação da equipe de\nAtenção Básica (eAB) e aquelas na equipe de Saúde da Família (eSF). Em relação à PNAB, versão\nde 2017, é correto afirmar que Alternativas:","options":{"A":"o médico é o único profissional da eSF que pode cumprir carga horária inferior a 40 horas\nsemanais.","B":"a população adscrita para uma eAB é de 3.500 pessoas a 5.000 pessoas.","C":"a equipe de saúde bucal é obrigatória somente na eSF.","D":"a equipe de Consultório na Rua é considerada uma equipe de atenção básica para populações\nespecíficas.","E":"um agente comunitário de saúde pode se responsabilizar, no máximo, por 2.000 pessoas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307132","number":"307132","sourceNumber":"307132","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A saúde trabalha com diferentes tipos de tecnologia, classificando-as em tecnologias\nleves, duras e leve-duras. MERHY, E. E. Saúde: a\ncartografia do trabalho vivo. 2. ed. São Paulo:\nHucitec, 2005, com adaptações. A esse respeito, assinale a alternativa que indica um exemplo de\ntecnologia leve Alternativas:","options":{"A":"Acolhimento","B":"Clínica médica","C":"Epidemiologia","D":"Diretriz terapêutica","E":"Estetoscópio"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307133","number":"307133","sourceNumber":"307133","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Decreto n. 7.508/2011 regulamenta a Lei Federal n. 8.080/1990, para dispor acerca\nda organização do Sistema Único de Saúde (SUS), o\nplanejamento da saúde, a assistência à\nsaúde e a articulação interfederativa, dando também outras providências. Segundo esse Decreto,\num Contrato Organizativo da Ação Pública da Saúde (Coap) pode ser estabelecido entre um ou\nmais entes federativos. No que se refere ao Coap, assinale a alternativa correta. Alternativas:","options":{"A":"Tem como função a identificação das necessidades de saúde em todo o território nacional,\npropondo plano nacional de saúde.","B":"É responsável por definir a Relação Nacional de Ações e Serviços de Saúde (Renases).","C":"Coordena o processo de votação para ampliação da Relação Nacional de Medicamentos\nEssenciais (Rename).","D":"Define as responsabilidades individuais e solidárias dos entes federativos, com relação aos\nelementos necessários à implementação integrada das ações e serviços de saúde.","E":"Organiza a divisão das regiões e, quando existirem, das macrorregiões de saúde nos estados da\nFederação."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307134","number":"307134","sourceNumber":"307134","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Na história da saúde pública, alguns documentos produzidos se tornam referências\nimportantes, propagando-se para além das fronteiras\ndo país em que foi produzido e também de\nseu tempo. Um exemplo desses documentos é o Relatório Flexner. Em relação a esse relatório, é\ncorreto afirmar que ele Alternativas:","options":{"A":"propôs, na Inglaterra, alterações na estrutura do modelo de atenção à saúde, organizando os\nserviços de saúde de acordo com seu nível de complexidade (atenção básica, média e alta\ncomplexidade) e custos do tratamento.","B":"no Japão, estabeleceu os fundamentos que oportunizaram a assinatura do primeiro tratado\ninternacional para controle da emissão dos gases que causam o efeito estufa na atmosfera.","C":"apresentou, no Canadá, uma série de contribuições para a construção de políticas públicas\nsaudáveis em todo o mundo, de forma equânime e\nuniversal, consolidando os trabalhos da Primeira\nConferência Internacional sobre Promoção da Saúde.","D":"avaliou cursos de Medicina nos EUA e no Canadá, propondo alterações no modelo educacional\nda Medicina, por exemplo, indicando a necessidade\nde realização de ciclo básico antes do ciclo\nclínico.","E":"defendeu, em Alma Ata (Cazaquistão), que a saúde é direito dos povos e dever dos governos,\nestimulando a criação de metas para que, até os anos de 2000, toda a população mundial pudesse\natingir um nível adequado de saúde."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307135","number":"307135","sourceNumber":"307135","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Rede de Atenção Psicossocial (Raps) desenvolve a lógica do cuidado centrado nas\nnecessidades das pessoas com transtornos mentais, incluídos os decorrentes do uso de\nsubstâncias psicoativas, buscando a construção de serviços diferentes para as diversas\nnecessidades dessas pessoas. No que concerne aos Centros de Atenção Psicossocial (Caps) que\ncompõem a Raps, é correto afirmar que Alternativas:","options":{"A":"o Caps I tem capacidade operacional para atendimento em municípios com população entre\n\n70.000 habitantes e 200.000 habitantes.","B":"uma das atividades que diferencia o Caps II do Caps I é a visita domiciliar que acontece somente\nno Caps I.","C":"o Caps III tem acolhimento noturno, nos feriados e nos fins de semana, e equipe composta por\ndois médicos psiquiatras, além de outros profissionais de nível superior e médio.","D":"o Caps i II é exclusivo para crianças e adolescentescom transtornos mentais, e o atendimento\nindividual é limitado a orientações ou psicoterapia.","E":"O Caps ad II tem equipe técnica minimamente composta por dois médicos psiquiatras, um\nenfermeiro clínico, um médico pneumologista, quatro profissionais de nível superior e seis de nível\nmédio."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-307136","number":"307136","sourceNumber":"307136","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Portaria do Ministério da Saúde n. 529/2013 instituiu o Programa Nacional de\nSegurança do Paciente (PNSP) que tem por\nobjetivo geral contribuir para a qualificação do cuidado\nem saúde em todos os estabelecimentos de saúde do território nacional. Considerando os\nconceitos-chave da Classificação Internacional de Segurança do Paciente, da Organização Mundial\nda Saúde, ?evento adverso? pode ser definido como incidente com (que) Alternativas:","options":{"A":"acompanhantes ou profissionais de saúde.","B":"potencial dano ou lesão.","C":"não atingiu o paciente.","D":"atingiu o paciente, mas não lhe causou dano.","E":"resulta em dano ao paciente."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-301336","number":"301336","sourceNumber":"301336","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em relação à saúde dos homens, julgue os itens de 93 à 96. Tradicionalmente, o\nsistema de saúde tem dada prioridade à\natenção a crianças e a mulheres-e, mais recentemente,\ntambém aos idosos - considerando-os como estratos mais frágeis da sociedade, sendo que os\nhomens, de forma geral, habituam-se a evitar o contato com os espaços da saúde, orgulhando-se\nda própria invulnerabilidade, avessos à prevenção e ao autocuidado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-263341","number":"263341","sourceNumber":"263341","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Uma mulher com 35 anos de idade exerce prostituição há 8 anos em hotéis da cidade\npara seu sustento e de seus filhos. Em\nvirtude da pandemia da COVID-19, há 6 meses não\ntrabalha e vem apresentando grave dificuldade financeira. Ao consultar na Unidade Básica de\nSaúde (UBS) do bairro, queixa-se de preocupações excessivas, nervosismo, tremores, palpitações\ne tonturas. Nesse caso, qual é a conduta adequada do médico de família e comunidade?","options":{"A":"Investigar o uso de drogas ilícitas, prescrever benzodiazepínico e encaminhar para psiquiatria.","B":"Evitar prescrever medicamentos, recomendar uso de chás e o abandono definitivo da atividade\nprofissional.","C":"Oferecer escuta ativa, pactuar plano terapêutico singular e agendar retorno programado na UBS.","D":"Prescrever benzodiazepínico e antidepressivo tricíclico e agendar retorno em 30 dias."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291465","number":"291465","sourceNumber":"291465","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um paciente de 36 anos de idade, masculino, procura a Unidade de Saúde da Família\ncom queixa de dor lombar baixa, há 10 dias,\nirradiada para face posterior da coxa, de moderada\nintensidade, mas que tem interferido no seu trabalho. Refere que a dor teve início após ter\ncarregado peso durante a mudança de casa. O paciente relata que já apresentou episódios\nsemelhantes anteriormente e que têm se tornado mais frequentes. Ao exame físico, o médico\nidentifica uma banda muscular tensa em região glútea, com a presença de pontos-gatilho, que,\nquando pressionados, reproduziam a dor referida pelo paciente. Diante da situação apresentada, é\ncorreto afirmar que","options":{"A":"o paciente deve ser referenciado ao ortopedista para a avaliação cirúrgica de uma provável\nhérnia de disco.","B":"o paciente deve ser referenciado ao acupunturista do NASF para ser avaliado, acompanhado e\ntratado.","C":"o médico de família pode, em conjunto com o acupunturista do NASF, elaborar um plano\nterapêutico para o paciente.","D":"o médico de família deve prescrever relaxantes musculares, pois o agulhamento seco deve ser\nrealizado pelo acupunturista do NASF."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-263346","number":"263346","sourceNumber":"263346","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um homem com 19 anos de idade, motorista de aplicativo, procura a Unidade de\nSaúde da Família (USF) por tristeza e\ninsônia há uma semana, desde que sua mãe faleceu por\nacidente ciclístico. O pai faleceu em um acidente de moto há 5 anos. Relata que tem estado muito\npreocupado com o futuro, pois agora está morando apenas com sua irmã de 15 anos de idade. Nos\núltimos dias, ele tomou 3 comprimidos de diazepam que achou na bolsa da mãe e pede uma\nreceita para pegar mais dessa medicação na USF. Nega histórico de transtornos mentais. Nesse\ncaso, a conduta médica inicial deve ser","options":{"A":"suspender benzodiazepínico e encaminhar ao psiquiatra.","B":"manter o uso da medicação e orientar o paciente a fazer a redução gradual.","C":"oferecer escuta ativa, técnicas de higiene do sono e terapia cognitivo-comportamental.","D":"trocar por um benzodiazepínico em gotas para facilitar a redução gradual da medicação."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291470","number":"291470","sourceNumber":"291470","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Promulgada em 2017, a Política Nacional da Atenção Básica (PNAB) estabelece que a\nTerritorialização e Adstrição da Clientela permitem o planejamento, a programação descentralizada\ne o desenvolvimento de ações setoriais e intersetoriais com foco em um território específico. A\norganização da Estratégia da Saúde da Família está baseada no preceito de responsabilidade\nsanitária sobre a população do território definido. Nesse sentido, é correto afirmar que","options":{"A":"a atualização dos dados de condições socioeconômicas das famílias é feita no sistema de\ninformação de agravos de notificação de forma contínua, e sob responsabilidade dos ACS.","B":"a delimitação da população adscrita da equipe, processo realizado por todos os membros da\nequipe, obedece estritamente aos limites geográficos e administrativos dos bairros de grandes\ncidades.","C":"o processo de territorialização finaliza com o cadastramento das famílias da área e é uma\natribuição dos agentes comunitários.","D":"a territorialização tem início com a definição do território, área e microárea, seguida pelo\ncadastramento de familias, que é uma responsabilidade de toda a equipe."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291474","number":"291474","sourceNumber":"291474","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Uma paciente, de 66 anos de idade, vem em consulta com médico de família e\ncomunidade de uma equipe de Saúde da\nFamília Fluvial, referindo estar preocupada com o\ncontrole de seu diabetes mellitus. Como a equipe ficou um longo período sem visitar a comunidade\ndevido a condições climáticas desfavoráveis, a paciente refere ter associado o uso de algumas\nplantas medicinais aos medicamentos prescritos em última consulta. Ela informa que a curandeira\nda comunidade orientou quais chás ela deveria tomar. O médico, então, identifica que essas\nplantas medicinais não interagem com os medicamentos prescritos, nem pioram o diabetes ou\ncausam risco à saúde; concorda com seu uso, reforçando a prescrição realizada por ele e solicita\nexames para avaliação do controle do diabetes. Diante do que foi apresentado, qual atributo da\natenção primária é apresentado no caso?","options":{"A":"Longitudinalidade.","B":"Integralidade.","C":"Competência cultural.","D":"Orientação para a comunidade."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274605","number":"274605","sourceNumber":"274605","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A assistência domiciliar é uma modalidade continuada de prestação de serviços na área\nda saúde que visa à continuidade do\ntratamento hospitalar no domicílio, reduzindo os gastos com\ninternações, bem como trazendo vantagens do ponto de vista de humanização do atendimento a\npessoas consideradas vulneráveis. Nesse sentido, diversos termos foram encontrados para\ndesignar a atuação no domicílio. Dentre eles se encontram as ações de promoção à saúde,\nprevenção, tratamento de doenças e reabilitação desenvolvidas em domicílio, que se\nconsubstanciam em:","options":{"A":"Atendimento domiciliar.","B":"Assistência domiciliar.","C":"Atenção domiciliar.","D":"Visita domiciliar."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274608","number":"274608","sourceNumber":"274608","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A adesão ao tratamento, medicamentoso ou não, é fundamental para o sucesso da\nterapia instituída pelo médico e pela equipe\nde saúde. Algumas pessoas apresentam-se relutantes\nna concordância ao tratamento médico ou às medidas não farmacológicas devido a fatores como: a\nduração do tratamento, os efeitos colaterais dele ocasionados, a insegurança quanto ao\ntratamento, dentre outros. De outro lado, fatores como a relação médico-paciente, relacionados às\ndoenças, à própria pessoa do doente, as questões socioeconômicos e ao próprio tratamento,\nmostram-se como viáveis à sua adesão. Quanto as estratégias para melhorar a adesão ao\ntratamento médico, é CORRETO afrmar:","options":{"A":"Quanto ao aspecto comportamental, há instruções e orientações ao paciente sobre a doença e o\ntratamento.","B":"A educação, embora de grande importância, por si só, representa uma abordagem frágil no\nincremento da adesão ao tratamento.","C":"Abrangem programas de autocuidado que incluem somente estratégias educacionais.","D":"As estratégias educacionais utilizam técnicas como a lembrança e o reforço da importância da\nadesão ao tratamento."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291487","number":"291487","sourceNumber":"291487","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em uma reunião de equipe da Estratégia de Saúde da Família, o médico expõe sua\npreocupação com o aumento no número de atendimentos de cuidadores de idosos, em virtude de\nproblemas de saúde decorrentes de estresse físico e emocional. Sugere que seja realizada\nintervenção de apoio e suporte aos cuidadores e para isso propõe aplicar escala que tem por\nobjetivo \"avaliar a sobrecarga dos cuidadores de idosos\". Trata-se da.","options":{"A":"Escala de Zarit.","B":"Escala de Barthel.","C":"Escala de Desempenho de Karnofsky.","D":"Escala de Avaliação Multidimensional do Idoso."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-268921","number":"268921","sourceNumber":"268921","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Objetiva identificar, no território, pessoas idosas, vulneráveis ou em processo de\nfragilização, para que se possa instalar um plano de cuidados adequados e individualizados por\nmeio de preenchimento contínuo; criado em 2006 e reformulado em 2014, tem como função\nqualificar o cuidado em saúde da pessoa idosa na Atenção Primária, sendo parte de um conjunto\nde iniciativas. Esse instrumento é o (a)","options":{"A":"Caderno de Atividade da Atenção Básica do Idoso.","B":"Prontuário Eletrônico do Idoso na Atenção Primária.","C":"Manual de Visita Domiciliar ao Idoso.","D":"Miniexame do Estado Mental.","E":"Caderneta de Saúde da Pessoa Idosa."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-268922","number":"268922","sourceNumber":"268922","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em 1986, aconteceu a 8a Conferência Nacional de Saúde (CNS), cujo tema\n\"democracia e saúde\" constituiu-se em fórum\nde luta pela descentralização do sistema de saúde e\npela implantação de políticas sociais que defendessem e cuidassem da vida. Foi um momento\nchave do Movimento da Reforma Sanitária e da afirmação da indissociabilidade entre a garantia da\nsaúde como direito social irrevogável e a garantia dos demais direitos humanos e de cidadania. O\nrelatório final da 8a CNS lançou os fundamentos da proposta do(a)","options":{"A":"Instituto Nacional de Previdência Social.","B":"Instituto Nacional de Assistência Médica da Previdência Social.","C":"Sistema Único de Saúde.","D":"Sistema Unificado e Descentralizado de Saúde.","E":"Sistema Nacional de Previdência e Assistência Social."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-268923","number":"268923","sourceNumber":"268923","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A visita domiciliar é fundamental para a dinâmica do processo de trabalho da atenção\nbásica. (MENDES, Eugênio Vilaça et al. (org.).\nDistrito Sanitário: o processo social de mudança das\npráticas sanitárias do Sistema Único de Saúde (SUS).3. ed. São Paulo/Rio de Janeiro.\n\nHucitec/ABRASCO, 1993, 310 p, com adaptações.) A partir do trecho apresentado e considerando\na divisão territorial proposta por Mendes\n(1993), destaca-se, como uma das divisões territoriais de\natuação direta da visita domiciliar, o território:","options":{"A":"área.","B":"microárea.","C":"distrito.","D":"moradia.","E":"subárea."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-268924","number":"268924","sourceNumber":"268924","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em relação aos princípios do Sistema Único de Saúde e aos respectivos conceitos,\nassinale a alternativa correta.","options":{"A":"A universalidade garante que todo cidadão terá acesso aos serviços de saúde públicos ou\nprivados conveniados, sem privilégios e nem barreiras, independentemente de cor, raça ou etnia.","B":"A integralidade da Atenção trata da garantia constitucional de que a população, por meio de\nsuas entidades representativas, poderá participar\nda gestão desse sistema de saúde.","C":"A descentralização com direção única de governo não prevê a descentralização do poder\ndecisório do governo federal para as instâncias estaduais e municipais, considerando uma\nredistribuição das responsabilidades.","D":"Equidade é o princípio que define um dos atributos da Atenção Básica à saúde e consiste no\nacompanhamento do usuário ao longo do tempo, na qual se espera uma relação terapêutica que\nenvolva a responsabilidade por parte do profissional de saúde e a confiança por parte do usuário.","E":"A participação popular diz respeito à garantia de acesso a um conjunto articulado e contínuo de\nações e serviços preventivos e curativos,\nindividuais e coletivos, exigidos para cada caso."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-268925","number":"268925","sourceNumber":"268925","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando a Reforma Psiquiátrica no Brasil, que dispõe a respeito do\nreordenamento do modelo assistencial às\npessoas com sofrimento psíquico, assinale a alternativa\ncorreta.","options":{"A":"Seu objetivo visa melhorar as condições dos leitos em hospitais psiquiátricos, diminuindo o\nnúmero de leitos por enfermaria e humanizando a assistência.","B":"As pessoas atendidas nos Centros de Atenção Psicossocial (CAPS) devem ser aquelas que\napresentam sofrimento psíquico de moderado a grave, que lhes impossibilita de viver e realizar os\nrespectivos projetos de vida.","C":"Os CAPS III funcionam 24 horas por dia, mas apenas recebem pacientes para acolhimento\nnoturno até as 19 horas.","D":"A Rede de Atenção Psicossocial (RAPS) será formada por serviços de diferentes hierarquias,\nnão contratando leitos, mas ampliando os recursos dos\nhospitais psiquiátricos.","E":"Os serviços ofertados que não atenderem ao perfil da RAPS serão fechados e poderão ser\nsubstituídos, como, por exemplo, o hospital psiquiátrico será substituído pela unidade de pronto\natendimento psiquiátrico."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291505","number":"291505","sourceNumber":"291505","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a portaria n. 2.436, de 21 de setembro de 2017, que aprovou a Política\nNacional de Atenção Básica, estabelecendo a revisão de diretrizes para a organização da Atenção\nBásica, no âmbito do Sistema Único de Saúde (SUS), é diretriz do SUS e da Rede de Atenção à\nSaúde a ser operacionalizada na Atenção Básica","options":{"A":"regionalização.","B":"adaptação.","C":"integralidade.","D":"determinação."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-268929","number":"268929","sourceNumber":"268929","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito da história da assistência farmacêutica vista como política pública de saúde\nno Brasil, é correto afirmar que o marco\nlegal inicial foi a","options":{"A":"Lei Orgânica da Saúde n. 8080/1990.","B":"Política Nacional de Medicamentos de 1998.","C":"Política Nacional de Assistência Farmacêutica de 2011.","D":"Lei n. 8142/1990.","E":"Normativa Operacional de Assistência (NOAS) de 2003."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-263396","number":"263396","sourceNumber":"263396","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em reunião dos membros da Unidade de Saúde da Família (USF), a médica da equipe\ncoloca em pauta o atendimento feito a um pescador não cadastrado naquela USF para retirada de\nanzol em polegar direito, questionando se o pescador deveria ter sido encaminhado para\natendimento na USF onde é cadastrado ou para Unidade de Pronto Atendimento. Nessa situação,\nconsiderando as diretrizes para a organização da Atenção Primária à Saúde (APS) no SUS, a\nconduta adequada da equipe deve ser","options":{"A":"solicitação de transferência para Unidade de Pronto Atendimento pelo Serviço de Atendimento\nMóvel de Urgência (SAMU), pois a remoção de\nanzol não é um procedimento previsto para a APS.","B":"encaminhamento do pescador para a USF de origem, observando-se as diretrizes de\nterritorialização e adscrição de usuários.","C":"atendimento do usuário fora de sua área de cobertura após pactuação e negociação entre\ngestão e equipe de saúde.","D":"acolhimento do usuário pela equipe, pois é de sua competência classificar riscos e definir\ncondutas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-263414","number":"263414","sourceNumber":"263414","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um médico presta atendimento domiciliar a um paciente de 69 anos de idade, já\nacompanhado há um ano, com hipertensão e diabete melito compensados, com hemiplegia direita\npor acidente vascular encefálico (AVE) isquêmico há 10 anos, parcialmente independente para as\natividades de vida diária e em uso de andador. A filha e cuidadora do idoso refere que o pai está\napresentando noctúria há alguns meses e que isso a preocupa devido ao risco de queda. O\npaciente nega incômodo com a noctúria e não refere outros sintomas urinários. Nega\nemagrecimento e não tem história familiar de câncer de próstata. Ao exame físico, o idoso\napresenta-se lúcido, orientado e com diminuição de força à direita. Ao ser questionado, ele se\nrecusa a realizar exame de toque retal e Antígeno Prostático Específico (PSA) para investigar a\npossibilidade de câncer de próstata. Entretanto, sua filha insiste na realização de exames,\nafirmando \"receio de ser algo mais grave\". Considerando a situação descrita, qual é a conduta\nmédica adequada?","options":{"A":"Explicar ao paciente a necessidade do rastreamento de câncer de próstata (PSA e\nultrassonografia de vias urinárias), pelo\nrisco da neoplasia, pois o diagnóstico precoce\ncomprovadamente diminui a mortalidade por essa doença, e solicitar anuência da filha, responsável\npelo paciente, para realização dos exames de rastreamento.","B":"Explicar ao paciente e à filha que a noctúria se deve ao AVE isquêmico prévio e ao\nenvelhecimento; orientar ser desnecessário o\nrastreamento de câncer de próstata e recomendar\nque o paciente evite, à noite, a ingesta hídrica e o consumo de cafeína; avaliar suspensão de\ndiuréticos e prescrever medicação para aumento do tônus vesical.","C":"Explicar ao paciente que o câncer de próstata é o mais prevalente em homens, com alta\nmortalidade e que somente seu diagnóstico precoce evita complicações e óbitos; convencer o\npaciente a realizar o toque retal e encaminhá-lo ao urologista; se o toque retal e o PSA se\nmostrarem alterados, encaminhá-lo para realização de biópsia prostática.","D":"Explicar ao paciente e à filha que o rastreamento de câncer de próstata depende de uma\ndecisão compartilhada entre o médico, paciente e família; oferecer explicações, em linguagem\n\nacessível, sobre os benefícios e riscos desse rastreamento; respeitar a decisão compartilhada com\no paciente para prosseguimento ou não do\nrastreamento."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274669","number":"274669","sourceNumber":"274669","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Os sistemas de saúde são compostos por estruturas com atividades distintas, porém\ncompatíveis, classificadas em dois agrupamentos: as estruturas assistenciais e as voltadas para a\nrealização das suas funções. No tocante às estruturas assistenciais, estas possuem como\nprincipais ocupações o acesso e a produção de serviços de saúde e são constituídas por:","options":{"A":"Hospitais, ambulatórios, consultórios, laboratórios clínicos e radiológicos, dentre outros, e por\nprofissionais e técnicos com formação específica em saúde e trabalhadores da saúde.","B":"Hospitais, ambulatórios, laboratórios clínicos e radiológicos, dentre outros, e por técnicos com\nqualquer formação e trabalhadores da segurança pública.","C":"Apenas por hospitais e por profissionais e técnicos com formação não específica em saúde e\ntrabalhadores da saúde.","D":"Hospitais, consultórios, laboratórios clínicos e radiológicos, dentre outros, e por apenas\nprofissionais com formação específica em saúde não se admitindo técnicos."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274670","number":"274670","sourceNumber":"274670","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A epidemiologia é constantemente considerada a ciência básica da medicina preventiva\ne da saúde pública, mas seus princípios têm\nsido cada vez mais incorporados à pesquisa e à\nprática clínica. A epidemiologia é conceituada por diferentes autores do ramo médico, científico,\nbem como por dicionários e pesquisas de sites de navegação. Entretanto, de um modo geral, todas\nas definições a ela concernentes traduzem a epidemiologia como:","options":{"A":"O ramo da medicina que estuda cientificamente os fatores que afetam a saúde das populações,\nsó fornecendo os fundamentos e a lógica para as\nintervenções de prevenção e tratamento das\ndoenças.","B":"O ramo da medicina que estuda os diferentes fatores que intervêm na propagação de doenças\ndas populações, não só fornecendo os fundamentos e\na lógica para as intervenções de prevenção\ne tratamento das doenças, mas também avaliando sua eficácia.","C":"O ramo da medicina que estuda os diferentes fatores que intervêm na propagação de doenças\ndas populações, não apenas fornecendo os\nfundamentos e a lógica para as intervenções de\ntratamento das doenças, mas também avaliando sua eficácia.","D":"O ramo da medicina que estuda cientificamente os fatores que afetam a saúde das populações,\nnão só fornecendo os fundamentos e a lógica\npara as intervenções de tratamento das doenças,\nmas também avaliando sua eficácia."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266493","number":"266493","sourceNumber":"266493","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Determinada UBS organizou o seu processo de trabalho de forma a priorizar o\natendimento de casos suspeitos de covid-19,\nreduzindo a oferta de ações e as consultas\nprogramadas típicas da atenção primária à saúde (APS), tais como hiperdia, pré-natal, puericultura,\nentre outras. Considerando essa situação hipotética, julgue o item que se segue, a respeito da\norganização dos serviços de APS, do Sistema Único de Saúde (SUS) e dos seus princípios\nnorteadores. A Lei n.º 8.142/1990 estabelece que, no exercício do controle social, a participação\npopular, no que tange à formulação e ao acompanhamento da execução de políticas públicas de\nsaúde, está garantida principalmente por meio de audiências públicas e pelas ouvidorias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266494","number":"266494","sourceNumber":"266494","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Determinada UBS organizou o seu processo de trabalho de forma a priorizar o\natendimento de casos suspeitos de covid-19,\nreduzindo a oferta de ações e as consultas\nprogramadas típicas da atenção primária à saúde (APS), tais como hiperdia, pré-natal, puericultura,\nentre outras. Considerando essa situação hipotética, julgue o item que se segue, a respeito da\norganização dos serviços de APS, do Sistema Único de Saúde (SUS) e dos seus princípios\nnorteadores. De acordo com o princípio da longitudinalidade, as equipes de APS devem priorizar o\natendimento das chamadas ações programáticas, realizando o atendimento da demanda\nespontânea de forma minoritária na agenda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266495","number":"266495","sourceNumber":"266495","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Determinada UBS organizou o seu processo de trabalho de forma a priorizar o\natendimento de casos suspeitos de covid-19,\nreduzindo a oferta de ações e as consultas\nprogramadas típicas da atenção primária à saúde (APS), tais como hiperdia, pré-natal, puericultura,\nentre outras. Considerando essa situação hipotética, julgue o item que se segue, a respeito da\norganização dos serviços de APS, do Sistema Único de Saúde (SUS) e dos seus princípios\nnorteadores. É responsabilidade da APS, com vistas à resolutividade, o atendimento dos casos de\nurgência e emergência desde que primeiramente respeitados os limites da adscrição de clientela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274677","number":"274677","sourceNumber":"274677","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Por meio da pesquisa científica é possível dar visibilidade à violência em termos da\nmagnitude do problema e dos impactos na saúde das pessoas. A violência presente nas mais\ndiversas sociedades se consubstancia em diversas formas, tais como a violência física, sexual,\npsicológica, por negligência, assédio moral, dentre outras. Considerando tais formas, NÃO diz\nrespeito à violência por negligência ou privação:","options":{"A":"Negação de recursos financeiros.","B":"Rasgar ou quebrar objetos queridos.","C":"Abandono de dependente.","D":"Cárcere privado."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266497","number":"266497","sourceNumber":"266497","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Alice, com 16 anos de idade, questionou, durante consulta médica, sobre a\npossibilidade de colocar um DIU na UBS,\npois tivera relação sexual desprotegida havia cerca de\nquatro dias. Ao médico ela relatou que a sua última menstruação havia ocorrido 15 dias atrás e que\no seu ciclo menstrual era irregular, de 20 a 28 dias, com 7 dias de fluxo normal, sem cólicas. Tendo\ncomo referência esse caso clínico hipotético, julgue o item subsecutivo. Com base no método\nclínico centrado na pessoa (MCCP), o médico pode perguntar a Alice qual é a expectativa dela em\nrelação ao DIU.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274679","number":"274679","sourceNumber":"274679","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com a ampliação dos limites da cidadania e a adoção de garantias sociais, houve o\ndesenvolvimento e a consolidação dos sistemas de saúde em diversos países. São fatores\npolíticos, dos quais dependem a cobertura populacional, o acesso e a oferta de bens e serviços:","options":{"A":"A inserção na economia capitalista mundial e o grau de organização social.","B":"A inserção na economia capitalista mundial e o grau da riqueza, expresso pelo PIB ou PNB.","C":"O tipo de estado e o grau da riqueza, expresso pelo PIB ou PNB.","D":"O tipo de estado e o grau de organização social."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274681","number":"274681","sourceNumber":"274681","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O sistema de saúde brasileiro é constituído por pelo menos dois subsistemas: um\ngovernamental, o SUS, e outro privado, o Sistema Supletivo de Assistência Médica (SSAM). A\nalternativa que se refere CORRETAMENTE ao SUS é:","options":{"A":"O financiamento do SUS conta com recursos das três esferas de governo, portanto, não há\nsolidariedade dos entes federados, mas sim cooperação.","B":"O financiamento do SUS é subsidiado exclusivamente pela União, com recursos do orçamento\nda seguridade social, que os repassam aos estados e\nmunicípios preservando a utilização de\nimpostos estaduais e municipais, que são direcionados exclusivamente para a educação.","C":"Por determinação de lei complementar, cada esfera de governo está obrigada a destinar um\npercentual de recursos mínimos para o financiamento das ações e serviços do SUS.","D":"A gestão do SUS se funda no comando de uma única esfera de governo, a União, nos estados e\nmunicípios o comando é do Ministério da Saúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266501","number":"266501","sourceNumber":"266501","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Marta, de 69 anos de idade, acompanhava seu esposo em uma consulta médica de\nrotina. O casal aguardava o atendimento\nquando, de repente, Marta começou a passar mal. O\nesposo dela, então, pediu ajuda, aos gritos, afirmando \"Marta está tendo uma bilora, não fala nada\ncom nada!\" (sic). A médica Joana prontamente atendeu Marta e iniciou a avaliação dela. Na\navaliação clínica da paciente, constatou-se hemiparesia à esquerda, anisocoria, afasia, nível 14 na\nescala de Glasgow (AO4/RV 4/RM6), pressão arterial de 190 mmHg x 120 mmHg, frequência\ncardíaca de 52 bpm e glicemia capilar de 294 mg/dL. Considerando o caso clínico precedente,\njulgue o próximo item. A internação por doença cerebrovascular é considerada uma internação por\ncondição sensível à atenção primária (ICSAP), um indicador que serve para avaliar o desempenho\nda APS.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274682","number":"274682","sourceNumber":"274682","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A noção de sistema de saúde exige organização desse aparato, tendo como seu\nelemento direcionador a integração e/ou a\narticulação das unidades. Considerando a estruturação\ndo sistema de saúde, os locais de atendimento referentes às esferas de atendimento terciário são:","options":{"A":"Hospitais gerais e ambulatórios especializados.","B":"Hospitais especializados.","C":"Centro de saúde, UBS e consultórios.","D":"Domicílios."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-274683","number":"274683","sourceNumber":"274683","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Para cumprir todas as suas atribuições constitucionais, além da rede de serviços\nassistenciais, o SUS conta com diversos\norganismos espalhados pelas instituições nas três esferas\nde gestão. A alternativa cujo conteúdo se refere aos intergestores estaduais é:","options":{"A":"Conselho Estadual.","B":"Conferência Estadual da Saúde.","C":"Comissão Bipartite.","D":"Secretarias de Saúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266505","number":"266505","sourceNumber":"266505","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com relação à Política Nacional de Humanização (PNH) e aos projetos terapêuticos\nsingulares (PTS), julgue o item seguinte. O\necomapa é composto pela junção do familiograma com\no genograma e funciona como instrumento de abordagem familiar que busca identificar a rede de\napoio social e familiar da pessoa em situação de cuidado em saúde, sendo, ainda, útil na\nelaboração do PTS.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291556","number":"291556","sourceNumber":"291556","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em 2006, foi implantada a Política Nacional de Práticas Integrativas e Complementares\n(PNPIC) no SUS. De acordo com essa\npolítica, é correto afirmar que","options":{"A":"o seu campo de atuação envolve sistemas médicos simplificados com a utilização de recursos\nterapêuticos simples.","B":"estimula mecanismos naturais de tratamento de algumas doenças e recuperação da saúde com\nutilização de tecnologias frágeis e nem sempre seguras.","C":"Limita o acesso à tecnologia de ponta e aumenta o número de atendimentos nas unidades,\ncontribuindo para ampliar a resolubilidade do sistema.","D":"compartilha da visão ampliada do processo saúde-doença e a promoção global do cuidado\nhumano, especialmente do autocuidado."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-263436","number":"263436","sourceNumber":"263436","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em uma reunião da Unidade de Saúde da Família, com a presença dos membros das\ncinco equipes de Saúde da Família, incluindo os Agentes Comunitários de Saúde (ACS), decidiu-se\nque, em razão do aumento do número de usuários sem cadastro que passaram a procurar a\nunidade para atendimento, seria iniciado o processo de atualização da territorialização, que inclui\nvárias etapas e principia pela fase preparatória. Considerando-se essa situação, que conjunto de\nações e/ou atividades está incluído na etapa preparatória do processo de territorialização?","options":{"A":"Fazer o levantamento dos dados populacionais e socioeconômicos, analisar os dados, adquirir\nmapa do território, identificar os equipamentos sociais com base no tamanho da população e\ndelimitar o território de acordo com os dados obtidos.","B":"Indagar às lideranças comunitárias sobre fatores facilitadores ou dificultadores do trabalho\ndesenvolvido pela equipe de saúde e acerca do\nfuncionamento da unidade de saúde, além de obter\ninformações sobre dificuldades de acesso à unidade.","C":"Realizar entrevistas para levantar informações sobre o território e a vida das famílias e da\ncomunidade, aspectos geográficos, políticos, econômicos, sociais e culturais percebidos e de\nrelevância para a comunidade.","D":"Levantar a documentação (incluindo plano diretor do município, projetos e estudos), dados\ndemográficos, econômicos e sociais; adquirir mapa-base e definir responsabilidades,\nprincipalmente dos ACS (Agente Comunitário de Saúde) e dos profissionais mais antigos e/ou\nmoradores na área."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266506","number":"266506","sourceNumber":"266506","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com relação à Política Nacional de Humanização (PNH) e aos projetos terapêuticos\nsingulares (PTS), julgue o item seguinte. A\nreunião da equipe de referência e o apoio matricial, na\ndiscussão de casos complexos e na elaboração de PTS, são dispositivos da diretriz clínica\nampliada e compartilhada da PNH.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-244498","number":"244498","sourceNumber":"244498","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O novo modelo de financiamento para a atenção primária, aprovado pela Comissão\nIntergestores Tripartite em 30 de outubro de 2019, tem como objetivo aumentar a qualidade do\natendimento das demandas de saúde apresentadas pela população. A esse respeito, assinale a\nalternativa CORRETA.","options":{"A":"A correlação entre a melhora de indicadores epidemiológicos e de relevância clínica pouco\ninterfere na obtenção de mais recursos.","B":"A existência de residências multiprofissionais e médicas nos municípios é indiferente ao\nrecebimento de mais recursos.","C":"A adesão a programas como Academia da Saúde e (ou) Saúde na Escola pode prejudicar o\nalcance de metas, prejudicando o recebimento de mais recursos.","D":"O recebimento de recursos está atrelado à capacitação ponderada; por exemplo, famílias em\nsituação de vulnerabilidade e (ou) faixas etárias que dispendem maiores gastos.","E":"O cadastramento das famílias na atenção primária tem baixa influência no recebimento dos\nrecursos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-244499","number":"244499","sourceNumber":"244499","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Decreto nº 7.508/2011, que regulamenta a Lei nº 8.080/1990, define que o acesso\nuniversal, igualitário e ordenado a ações e\nserviços de saúde se inicia pelas portas de entrada do\nSistema Único de Saúde (SUS) e se completa na rede regionalizada e hierarquizada. A atenção\nbásica é a ordenadora do cuidado; para tanto, faz-se necessário que ela trabalhe com ferramentas.\nAssinale a alternativa que indica essas ferramentas.","options":{"A":"Apoio matricial para as equipes do Núcleo de Apoio à Saúde da Família (NASF) e\nmicrorregulação.","B":"Protocolos de encaminhamento e microrregulação.","C":"Sistema de gestão da agenda da atenção especializada e protocolos clínicos.","D":"Acesso aos serviços de informação em saúde e telemedicina.","E":"Organização das áreas segundo critérios estabelecidos pela gestão municipal e (ou) estadual."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-244500","number":"244500","sourceNumber":"244500","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Acerca da Política Nacional de Atenção Básica (PNAB), de 2017, e do funcionamento\ndas Unidades Básicas de Saúde da Família, assinale\na alternativa correta.","options":{"A":"A população adscrita por equipe deve estar em território determinado e ser composta de 2.000 a\n\n3.500 pessoas.","B":"A equipe de atenção básica (eAB) deve ser composta por médico, enfermeiro, auxiliar e (ou)\ntécnico de enfermagem e agente comunitário de saúde (ACS).","C":"Não há a necessidade de incorporação de profissionais de nível médio, como técnicos em\nenfermagem, saúde bucal e (ou) administrativos.","D":"O funcionamento das unidades será exclusivamente no horário comercial, com intervalo de\nalmoço de duas horas, preservando o momento de descanso da equipe.","E":"Os profissionais de saúde bucal descritos na modalidade 2 são cirurgião-dentista e auxiliar em\nsaúde bucal (ASB) ou técnico em saúde bucal\n(TSB)."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-244501","number":"244501","sourceNumber":"244501","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No que tange ao Núcleo de Apoio à saúde da Família (NASF) na nova Política Nacional\nde Atenção Básica (PNAB), de 2017, assinale a\nalternativa correta.","options":{"A":"Constituem-se como serviços com unidades físicas independentes e especiais.","B":"É facultativa a participação do NASF no planejamento das unidades dos que atuam.","C":"Deve atuar de maneira integrada às equipes, prestando suporte clínico, sanitário e pedagógico.","D":"Os seguintes profissionais podem estar vinculados ao NASF: médico veterinário e\nmusicoterapeuta.","E":"Os atendimentos do NASF devem ser realizados a partir da busca ativa, independentemente da\ndemanda repassada pela equipe."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-244504","number":"244504","sourceNumber":"244504","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A respeito dos Conselhos de Saúde, assinale a alternativa correta.","options":{"A":"Possuem caráter exclusivamente deliberativo.","B":"Analisam os gastos da gestão somente de maneira consultiva.","C":"Têm como característica serem provisórios.","D":"Respeitam o princípio da paridade.","E":"Reúnem-se de quatro em quatro anos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-227446","number":"227446","sourceNumber":"227446","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis, julgue o\nitem que se segue. Embora ainda não exista\nmétodo de proteção especificamente desenvolvido para o sexo entre vaginas nem para o sexo\n\noral-vaginal, o médico da família e comunidade (MFC) pode indicar a casais de mulheres lésbicas a\nadaptação de preservativos masculinos e femininos e o uso de dental dam, por exemplo, como\nmétodos eficazes na proteção contra infecções sexualmente transmissíveis (IST).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-227460","number":"227460","sourceNumber":"227460","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com relação às competências do médico da família e comunidade, ao trabalho na APS\ne às políticas de saúde, julgue o item\nsubsequente. O modelo de acesso avançado é um método de\nagendamento que permite maior absorção da demanda espontânea, por meio da triagem coletiva\ndos casos, priorizando-se o atendimento a portadores de doenças crônicas e reserva de vagas\npara grupos prioritários, em convergência com o princípio de equidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-227461","number":"227461","sourceNumber":"227461","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com relação às competências do médico da família e comunidade, ao trabalho na APS\ne às políticas de saúde, julgue o item\nsubsequente. A gestão da interface com outras\nespecialidades, de forma a ofertar ao usuário um conjunto de serviços e informações que\nrespondam a suas necessidades de saúde de forma integrada, tem como fundamento o atributo da\nAPS denominado coordenação do cuidado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203087","number":"203087","sourceNumber":"203087","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A nova Política Nacional de Atenção Básica (Portaria n° 2.436/2017) \"[...] define a\norganização em Redes de Atenção à Saúde (RAS) como estratégia para um cuidado integral e\ndirecionado às necessidades de saúde da população [...]\". Partindo desse pressuposto e quanto à\nconstituição e aos atributos das Redes de Atenção à Saúde (RAS), assinale a alternativa\nCORRETA.","options":{"A":"A atenção básica é primeiro ponto de atenção e porta de entrada preferencial do sistema, além\nde realizar a articulação com outros pontos da RAS.","B":"São importantes os arranjos organizativos formados por ações e serviços de saúde com\nconfigurações tecnológicas e missões assistenciais semelhantes, que não diferem entre si.","C":"A ordenação da RAS é feita pelo ponto de atenção hospitalar, partindo das necessidades de\nsaúde dos profissionais de saúde.","D":"A desconexão entre os pontos de atenção à saúde dentro da RAS é necessária, para que\naumente a resolutividade, com capacidade clínica e de cuidado.","E":"O ponto de atenção hospitalar é prioritário para o acesso, evitando encaminhamentos\ndesnecessários para a atenção básica."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203119","number":"203119","sourceNumber":"203119","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As atribuições dos profissionais das equipes que atuam na Atenção Básica deverão\nseguir normativas específicas do Ministério da\nSaúde, bem como as definições de escopo de\npráticas, protocolos, diretrizes clínicas e terapêuticas, além de outras normativas técnicas\nestabelecidas pelos gestores federal, estadual, municipal ou Distrito Federal. Com base no exposto,\né correto afirmar que cabe ao profissional médico, no âmbito da Atenção Básica:","options":{"A":"Acompanhar, apoiar e desenvolver atividades referentes à saúde com os demais membros da\nequipe, buscando aproximar saúde bucal e integrar ações de forma multidisciplinar.","B":"Realizar diagnóstico com a finalidade de obter o perfil epidemiológico para o planejamento e a\nprogramação em saúde bucal no território.","C":"Implementar e manter atualizados rotinas, protocolos e fluxos relacionados à respectiva área de\ncompetência na Unidade Básica de Saúde (UBS).","D":"indicar a necessidade de internação hospitalar ou domiciliar, mantendo a responsabilização pelo\nacompanhamento da pessoa.","E":"participar e orientar o processo de territorialização, diagnóstico situacional, planejamento e\nprogramação das equipes, avaliando resultados e propondo estratégias para o alcance de metas\nde saúde, junto aos demais profissionais."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203095","number":"203095","sourceNumber":"203095","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Ofertar o cuidado, reconhecendo as diferenças nas condições de vida e saúde e de\nacordo com as necessidades das pessoas,\nconsiderando que o direito à saúde passa pelas\ndiferenciações sociais e deve atender a diversidade. Ficando proibida qualquer exclusão baseada\nem idade, gênero, cor, crença, nacionalidade, etnia, orientação sexual, identidade de gênero,\nestado de saúde, condição socioeconômica, escolaridade ou limitação física, intelectual, funcional,\nentre outras, com estratégias que permitam minimizar desigualdades, evitar exclusão social de\ngrupos que possam vir a sofrer estigmatização ou discriminação; de maneira que impacte na\nautonomia e na situação de saúde. A portaria nº 2.436/2017 determina que os princípios e as\ndiretrizes, a caracterização e a relação de serviços ofertados na Atenção Básica serão orientadores\npara organização desta nos municípios. Considerando essas informações, assinale a alternativa\nque indica o princípio descrito no trecho apresentado.","options":{"A":"Regionalização e hierarquização.","B":"Resolutividade.","C":"Equidade.","D":"Integralidade.","E":"Universalidade."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203105","number":"203105","sourceNumber":"203105","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"\"Pressupõe a continuidade da relação de cuidado, com construção de vínculo e\nresponsabilização entre profissionais e usuários ao longo do tempo e do modo permanente e\nconsistente, acompanhando os efeitos das intervenções em saúde e de outros elementos na vida\ndas pessoas, evitando a perda de referências e diminuindo os riscos de iatrogenia que são\ndecorrentes do desconhecimento das histórias de vida e da falta de coordenação do cuidado.\"\nAcerca do exposto, assinale a alternativa que corresponde à diretriz descrita no trecho\napresentado.","options":{"A":"População adscrita.","B":"Coordenar o cuidado.","C":"Ordenar as redes.","D":"Participação da comunidade.","E":"Longitudinalidade do cuidado."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203067","number":"203067","sourceNumber":"203067","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"12% das mortes por câncer de mama no Brasil são atribuíveis ao sedentarismo.\nEstudo, que teve colaboração do Ministério\nda Saúde, ainda aponta que álcool, alto teor de açúcar\ne excesso de peso aumentam a mortalidade em 6,5% por câncer de mama. Pesquisa foi publicada\nna Revista Nature. Uma em cada 10 mulheres vítimas do câncer de mama (cerca de 12%)\npoderiam ter a vida poupada se praticassem atividade física regularmente (150 minutos por\nsemana). É o que aponta o artigo científico Mortality and years of life lost due to breast cancer\nattributable to physical inactivity in the Brazilian female population (1990-2015), divulgado na\nrevista\nNature, que contou com a participação do Ministério da Saúde. De acordo com a pesquisa, no ano\nde 2015, 2.075 mortes poderiam ter sido evitadas se as pacientes realizassem ao menos uma\ncaminhada de 30 minutos por dia, cinco vezes por semana. Atividade física como prevenção ao\ncâncer de mama O incentivo para uma alimentação saudável e balanceada e a prática de\natividades físicas é prioridade do Governo Federal. Desde 2011, os municípios recebem recursos\nfinanceiros para implantar o programa Academia da Saúde. Atualmente, o programa conta com\nmais 3.800 polos habilitados. Nesses locais, a população pode contar com infraestrutura e\nequipamentos adequados; e profissionais qualificados para promover práticas corporais e atividade\nfísica, promoção da alimentação saudável e educação em saúde. BRASIL. Ministério da Saúde.\n\nDisponível em: <http://portalms.saude.gov,br/>. Acesso em: 20 out. 2018, com adaptações.\nConsiderando que a Academia da Saúde tem\nrelação especial com um dos pilares da promoção de\nsaúde, preconizados na Carta de Ottawa (1986), assinale a alternativa que indica esse pilar.","options":{"A":"Construindo políticas públicas saudáveis.","B":"Reforçando a ação comunitária.","C":"Desenvolvendo habilidades pessoais.","D":"Fatores ambientais desarticulados dos biológicos.","E":"Provimentos de serviços clínicos e de urgência."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203102","number":"203102","sourceNumber":"203102","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"É certo que o diagnóstico de uma doença sempre parte de um princípio universalizante,\ngeneralizável para todos, ou seja, ele supõe alguma regularidade e produz uma igualdade. Mas\nesta universalidade é verdade apenas em parte. Com base no exposto e com relação à clinica\nampliada, assinale a alternativa CORRETA.","options":{"A":"A máxima organizacional cada um faz a sua parte refere-se ao que está proposto quanto à\natuação de um único profissional na proposta da clínica ampliada.","B":"A pessoa hipertensa, se está desempregada, não interfere no sinal da doença.","C":"O objeto de trabalho de qualquer profissional de saúde deve ser as doenças e as epidemias.","D":"Problemas, como a baixa adesão a tratamentos, as iatrogenias (danos), os pacientes refratários\n(ou poliqueixosos) e a dependência dos usuários dos\nserviços de saúde evidenciam a\ncomplexidade dos sujeitos.","E":"Basta o diagnóstico para definir todo o tratamento para o paciente, o que corresponde ao velho\nditado cada caso é um caso."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203125","number":"203125","sourceNumber":"203125","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Espaços onde se ofertam determinados serviços de saúde, por meio de uma produção\nsingular, como uma unidade ambulatorial\nespecializada, uma unidade de atenção domiciliar, uma\nunidade de atenção paliativa. A Política Nacional de Atenção Hospitalar (PNHOSP) no âmbito do\nSistema único de Saúde (SUS) está instituída na Portaria de Consolidação nº 2/2017, que instituiu\na consolidação das normas acerca das políticas nacionais de saúde do SUS, estabelecendo as\ndiretrizes para a organização do componente hospitalar da Rede de Atenção à Saúde (RAS). Essa\nPNHOSP considera, para a respectiva execução: acessibilidade hospitalar, acolhimento, apoio\nmatricial, auditoria clínica, classificação de risco, clínica ampliada, diretrizes terapêuticas,\ngerência,\ngestão, gestão da clínica, gerenciamento de leitos, horizontalização do cuidado, linha de cuidado,\nNúcleo Interno de Regulação, Núcleo de Acesso e Qualidade Hospitalar, Modelo de Atenção, Plano\nTerapêutico, Ponto de Atenção, Prontuário Único, Portas Hospitalares de Urgência e Emergência,\nProtocolo Clínico, Rede de Atenção à Saúde (RAS), e visita aberta. Considerando essas\ninformações, é correto afirmar que o trecho apresentado refere-se ao (à):","options":{"A":"Núcleo Interno de Regulação.","B":"Ponto de Atenção.","C":"Núcleo de acesso e qualidade hospitalar.","D":"Linha de cuidado.","E":"Visita aberta."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-203139","number":"203139","sourceNumber":"203139","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Primária à Saúde é uma forma de organizar os serviços, na qual há uma\nporta de entrada ao sistema, configurada\ncomo espaço de coordenação das respostas às\ndemandas dos usuários, individual ou coletivamente. Nesse contexto, a Política Nacional de\nAtenção Básica considera que a Estratégia Saúde da Família é a forma de organização da Atenção\nPrimária no Brasil, por promover uma reorientação no processo do trabalho e produzir, de forma\ncusto-eficaz, um maior impacto da situação de saúde das pessoas. Com relação às funções da\nEstratégia Saúde da Família no que tange à função de ordenadora das Redes de Atenção à Saúde,\nassinale a alternativa correta.","options":{"A":"Trata-se da oferta de serviços de saúde, por meio das unidades básicas de saúde, com o mais\nelevado grau de descentralização e capilaridade, isto é, o mais próximo possível das pessoas e\ncomunidades.","B":"Significa indetificar riscos, doenças, necessidades e demandas de saúde, respondendo a estas\nda forma o mais efetiva possível, buscando,\nsempre que possível, ampliar a autonomia das\npessoas.","C":"Implica em reconhecer e mensurar as necessidades em saúde da população sob a respectiva\nresponsabilidade, organizando as respostas dos demais serviços de saúde, contribuindo para que a\nprogramação destes parta das necessidades dos usuários.","D":"Manifesta a elaboração, o acompanhamento e a gerência do plano terapêutico das pessoas,\nassim como acompanha e organiza o fluxo delas\nentre os pontos de atenção nas Redes de\nAtenção à Saúde, assumindo o papel de centro de comunicação dessas redes.","E":"Sinaliza o ordenamento legal da descentralização estabelecido pela Lei nº 8.080/1990, que\ndefine a participação da União, dos estados\ne dos municípios no financiamento da saúde nos casos\nem que há gestão plena em saúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-206125","number":"206125","sourceNumber":"206125","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Para cumprir seus objetivos, o Serviços de Atenção Especializada (SAE) deve ser\nprojetado e construído com infraestrutura\nadequada às atividades desenvolvidas, de acordo com as\nnormas vigentes (RDC no 50/2002; Lei n° 6.360/1976, e suas atualizações). Somente podemos\nconcordar que:","options":{"A":"Os projetos para construção, mas não de adaptação de ambientes para atendimento de pessoas\nvivendo com HIV/AIDS - PVHA, levando em consideração os riscos de transmissão de tuberculose,\ndevem envolver profissionais de arquitetura/engenharia e profissionais de saúde que conheçam o\nfluxo e o tipo de paciente atendido.","B":"/Os projetos para construção ou adaptação de ambientes para atendimento de pessoas vivendo\ncom HIV/AIDS - PVHA, levando em consideração os\nriscos de transmissão de tuberculose, devem\nenvolver profissionais de arquitetura/engenharia e profissionais de saúde que conheçam o fluxo e o\ntipo de paciente atendido.","C":"Os projetos para construção ou adaptação de ambientes para atendimento de pessoas vivendo\ncom HIV/AIDS - PVHA, levando em consideração os riscos de transmissão de tuberculose, não\ndevem envolver profissionais de arquitetura/engenharia e profissionais de saúde que conheçam o\nfluxo e o tipo de paciente atendido.","D":"Os projetos para construção ou adaptação de ambientes para atendimento de pessoas vivendo\ncom HIV/AIDS - PVHA, levando em consideração os riscos de transmissão de tuberculose, devem\nenvolver profissionais de arquitetura/engenharia, mas não profissionais de saúde que conheçam o\nfluxo e o tipo de paciente atendido."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-351596","number":"351596","sourceNumber":"351596","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Analise as afirmativas a seguir sobre o que dispõe a Lei Federal nº 8.080 e assinale V\npara as afirmativas verdadeiras e F para as falsas. ( ) A execução de ações de vigilância sanitária,\nde vigilância epidemiológica, de saúde do trabalhador, de saúde bucal e de assistência terapêutica\nintegral estão incluídas no campo de atuação do SUS. ( ) A integralidade de assistência pode ser\nentendida como as ações e serviços preventivos e coletivos, exigidos para cada comunidade no\nnível de atenção primária à saúde. ( ) As ações e serviços de saúde, executados pelo SUS,\nmediante participação complementar da iniciativa privada, serão organizados de forma a atender a\ndemanda do financiador. ( ) As Comissões Intergestores Bipartite e Tripartite são reconhecidas\ncomo foros de negociação e pactuação entre gestores, quanto aos aspectos operacionais do SUS.\nAssinale a alternativa com a sequência CORRETA.","options":{"A":"V ? V ? F - F","B":"F - F - V - V","C":"V - F ? F - V","D":"V - F - V - F"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-351597","number":"351597","sourceNumber":"351597","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A territorialização e a definição do território como responsabilidade de cada equipe\nestão entre as diretrizes da Política Nacional\nde Atenção Básica (PNAB). Sobre territorialização, é\nINCORRETO afirmar que:","options":{"A":"O processo de territorialização deve ser considerado um meio operacional para o\ndesenvolvimento do vínculo entre os serviços de saúde e a população.","B":"É responsabilidade do agente comunitário de saúde (ACS) realizar todo o processo de\nterritorialização e mapeamento da área de\natuação da equipe, devendo atualizar as informações e\nser responsável por quaisquer mudanças.","C":"Para a realização do processo de territorialização, sugere-se as seguintes ferramentas:\ndiagnóstico comunitário, classificação de risco\ncomunitário, divisão de áreas por risco, cartografia.","D":"A territorialização norteia as ações de atenção, assistência e vigilância em saúde de acordo com\nas diversas realidades das comunidades das\náreas de responsabilidades das equipes."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-351598","number":"351598","sourceNumber":"351598","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considere o texto a seguir: A vigilância em saúde deve estar cotidianamente inserida\nem todos os níveis de atenção da saúde. Uma\ndas estratégias indutoras de fortalecimento das\nações de vigilância em saúde, junto às equipes de saúde da família é a incorporação dos\n\n. Assinale a alternativa que preenche CORRETAMENTE a lacuna do texto.","options":{"A":"técnicos em saúde bucal","B":"médicos generalistas","C":"agentes de combate às endemias","D":"gerentes de unidades"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-373589","number":"373589","sourceNumber":"373589","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A cobertura de exame Papanicolau apresentou-se estável durante todo o período\nanalisado, variando de 82,2% em 2010 a 81,5% em 2019. Salienta-se que:","options":{"A":"desde o lançamento do Plano, a meta de aumento de exame Papanicolau sempre foi atingida a\ntodo momento. A previsão é de que essa meta não seja atingida até 2022.","B":"desde o lançamento do Plano, a meta de aumento de exame Papanicolau não foi atingida em\nnenhum momento. A previsão é de que essa meta\nseja atingida até 2022.","C":"desde o lançamento do Plano, a meta de aumento de exame Papanicolau não foi atingida em\nnenhum momento. A previsão é de que essa meta não\nseja atingida até 2022.","D":"desde o lançamento do Plano, a meta de redução de exame Papanicolau não foi atingida em\nnenhum momento. A previsão é de que essa meta não\nseja atingida até 2022."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-320414","number":"320414","sourceNumber":"320414","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a Lei n° 8.142, de 28 de dezembro de 1990, que dispõe sobre a\nparticipação da comunidade na gestão do\nSistema Único de Saúde (SUS) e sobre as transferências\nintergovernamentais de recursos financeiros na área da saúde, para receberem os recursos de que\ntrata o art. 3° desta lei, os Municípios, os Estados e o Distrito Federal deverão contar com:","options":{"A":"Serviço de auditoria interna.","B":"Estratégia de saúde da família.","C":"Seguridade social.","D":"Serviço de vigilância em saúde.","E":"Plano de saúde."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-320415","number":"320415","sourceNumber":"320415","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei nº 8.142, de 28 de dezembro de 1990, que dispõe sobre a participação da\ncomunidade na gestão do Sistema Único de\nSaúde (SUS) estabelece que a representação dos\nusuários nos Conselhos de Saúde e Conferências será paritária em relação ao conjunto dos demais\nsegmentos. Essa participação corresponderá a(ao):","options":{"A":"25% de delegados indicados pela Conferência Municipal de Saúde + 25% de eleitos.","B":"50% de delegados indicados pela Conferência Municipal de Saúde.","C":"50% do total de membros do conselho indicados pelo segmento.","D":"Percentual igual de membros entre todos os segmentos que compõem o Conselho.","E":"Número par de Conselheiros para manutenção do poder de voto do segmento."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-320416","number":"320416","sourceNumber":"320416","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei nº 8080, de 19 de setembro de 1990, quando trata da gestão financeira do SUS,\ndefine que para o estabelecimento de valores a serem transferidos a Estados, Distrito Federal e\nMunicípios, segundo análise técnica de programas e projetos, será utilizada a combinação de\ncritérios, entre eles a(o):","options":{"A":"Existência de Equidade no Sistema e a alinhamento conceitual dentro da rede de atenção.","B":"Previsão do plano quinquenal de investimentos da rede e o perfil demográfico da região.","C":"Rede parametrizada capaz de fiscalizar alinhado com o investimento hospitalar público e\nprivado.","D":"Rede bancária local e pública e um programa de administração de recursos próprios que\ninteragem.","E":"Desempenho técnico, econômico e financeiro previsto para o período anual posterior e Fundo de\nSaúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-320417","number":"320417","sourceNumber":"320417","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei nº 8080, de 19 de setembro de 1990, define as competências da direção estadual\ndo Sistema Único de Saúde (SUS). Assinale a\nalternativa correta:","options":{"A":"Participar das ações de controle e avaliação das condições e dos ambientes de trabalho.","B":"Coordenar e participar na execução das ações de vigilância epidemiológica com o\ndesenvolvimento de cartilhas e panfletos com linguagem simples.","C":"Coordenar os serviços de referência nacional com padrões técnicos de assistência à saúde e\ncomunicar ao Ministério da Saúde.","D":"Controlar e fiscalizar procedimentos, produtos e substâncias de interesse para a saúde e\ndespoluentes ao meio ambiente.","E":"Formar Consórcios Administrativos Municipais."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-320421","number":"320421","sourceNumber":"320421","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Primária à Saúde (APS) deve ser orientada por quatro princípios essenciais\nsegundo Bárbara Starfield. Qual é o significado do Princípio da Integralidade na Atenção Primária à\nSaúde?","options":{"A":"Orientar e coordenar as referências dos pacientes.","B":"O acesso primordial das pessoas aos serviços de saúde.","C":"Capacidade de atender os pacientes em suas necessidades de saúde.","D":"Disponibilidade como fonte regular de atenção.","E":"Informar sistematicamente sobre a totalidade das ações realizadas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-320422","number":"320422","sourceNumber":"320422","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Registro de Saúde Orientado por Problemas (ReSOAP) tem como finalidade\nproporcionar informações sobre a pessoa que busca\ncuidado, prestando atenção aos componentes\nbiológicos, psicológicos, sociais e quaisquer outros aspectos relevantes ao manejo da situação\n(Gusso e Lopes, 2012). A avaliação (A) é o local, na evolução ReSOAP, para se colocar a lista de\nproblemas da consulta de acompanhamento. Assinale a alternativa que representa o correto\npreenchimento do A:","options":{"A":"Hipertensão arterial sistêmica (HAS), apendicite, alergia alimentar.","B":"Descartar gravidez, descartar hipotireoidismo, descartar anemia.","C":"Suspeita de depressão, provável hepatite, possível sífilis latente.","D":"Hemopatia, processo respiratório, desconforto.","E":"Idoso morando sozinho, diabetes mellitus tipo 2 descompensado."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-320423","number":"320423","sourceNumber":"320423","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Existem vários modelos de abordagem à consulta a serem utilizados pelos médicos.\nConsidera-se que o método que engloba e sistematiza os diversos aspectos positivos das\ndiferentes formas de abordagem aos problemas de saúde é o método da abordagem centrada na\npessoa. Esse método utiliza como proposta metodológica que uma consulta atenda às\nnecessidades e às expectativas de médicos e pessoas, abrindo caminho para um atendimento\nadequado em Atenção Primária à Saúde (APS) (Gusso e Lopes, 2012). Assinale a alternativa que\ncontenha 2 (dois) componentes do método clínico de abordagem à pessoa:","options":{"A":"Incorporando a prevenção quaternária e a promoção de saúde.","B":"Elaborando um projeto de manejo centrado na opinião do médico e sendo realista.","C":"Elaborando um plano conjunto de manejo de problemas e promoção de saúde.","D":"Explorando a saúde, doença e a experiência da doença e entendendo a pessoa como um todo.","E":"Intensificando a relação entre pessoa e médico e sendo otimista."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-336268","number":"336268","sourceNumber":"336268","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre as características dos conselhos de saúde, marque a correta:","options":{"A":"Tem caráter permanente e deliberativo com funções de formular estratégias, controlar e fiscalizar\na execução da política de saúde","B":"Tem caráter prevalente e deliberativo com funções de controlar e fiscalizar a execução da\npolítica de saúde","C":"Tem caráter provisório e deliberativo com funções de formular estratégias, controlar e\nfiscalizar a\nexecução da política de saúde.","D":"Tem caráter provisório e comunicativo com funções de formular políticas de provimentos,\ncontrolar e fiscalizar a execução da política\nde saúde."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-336269","number":"336269","sourceNumber":"336269","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"José, 24 anos, vítima de acidente automobilístico, chega ao pronto-socorro e é atendido\nprontamente. João, 38 anos, com quadro de diarréia, está a espera de atendimento médico há 2\nhoras e fica nervoso quando José passa em sua frente no atendimento. Qual o príncipio do SUS\nque vigora no atendimento de José?:","options":{"A":"Universalidade","B":"Integralidade","C":"Equidade","D":"Autonomia"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-336270","number":"336270","sourceNumber":"336270","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Homem, 42 anos, sapateiro, procura unidade básica de saúde (UBS) pedindo\nencaminhamento para cardiologia. Relata que foi\nna UPA devido à palpitação e temia ser problema\nmais sério no coração e foi percebido valor alterado da pressão arterial (PA). O mesmo se intitula\nhipertenso, após esse episódio de única aferição da PA. Ao passar pela consulta com médico da\nUBS o mesmo explica que isso não é suficiente para diagnosticá-lo e orienta aferir a pressão\narterial na UBS 3 vezes por semana, durante 3 semanas e retornar em nova consulta na quarta\nsemana. Qual atributo da Atenção Primária a Saúde, esse médico está exercendo quando dá essa\norientação?","options":{"A":"Longitudinalidade","B":"Orientação familiar","C":"Integralidade","D":"Competência cultural"},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-336271","number":"336271","sourceNumber":"336271","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Alexandre tem nefropatia e retinopatia por diabetes. Muitas vezes, fica confuso com as\nrecomendações dos especialistas focais. Confia muito na sua equipe de saúde da Unidade Básica\nde Saúde próximo à sua casa para organizar seus tratamentos. Qual atributo da Atenção Primária a\nSaúde representa esse relato?","options":{"A":"Acesso de primeiro contato","B":"Coordenação","C":"Integralidade","D":"Longitudinalidade"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-336274","number":"336274","sourceNumber":"336274","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um dinamarquês de 31 anos que está passando férias no Brasil é mordido por um\ncachorro de rua há poucos minutos e procura\na Unidade Básica de Saúde (UBS), que é referência\nem aplicação de vacina e soro anti-rábicos, para ser avaliado e orientado quanto aos cuidados\nnecessários. O agente comunitário de saúde que está na recepção da unidade solicita os seus\ndocumentos e comprovante de endereço para realizar o cadastro e abertura da ficha para\natendimento, porém o paciente informa ser estrangeiro e não ter comprovante de endereço do\nBrasil, estando hospedado em um hotel nas proximidades da unidade. Nesse momento, o agente\nde saúde o orienta a procurar uma unidade de Pronto Atendimento, pois ele, por não morar na\nregião, não faz parte da área de abrangência daquela UBS e não poderá ser atendido por ela.\n\nNesse contexto, qual dos princípios éticos do SUS não foi respeitado?","options":{"A":"Integralidade","B":"Equidade","C":"Regionalização","D":"Universalidade"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-336276","number":"336276","sourceNumber":"336276","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Constituição Federal de 1988 estabelece que ?A saúde é direito de todos e dever do\nEstado?. A garantia desse direito foi fundamental para superar a condição anterior a esse período\nque se caracterizava por:","options":{"A":"assegurar esse direito aos trabalhadores urbanos por meio de empresas de medicina de grupo e\nde seguro-saúde.","B":"garantir à população residente em centros urbanos esse direito após a criação do Instituto\nNacional da Previdência Social (INPS).","C":"garantir à população urbana esse direito desde a criação das Caixas de Aposentadoria e\nPensões (CAPs).","D":"restrição desse direito à população trabalhadora com vínculo formal de emprego."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-335094","number":"335094","sourceNumber":"335094","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paciente do sexo feminino, 14 anos de idade, comparece à consulta com queixa de\nacompanhamento de cardiopatia congênita. Durante a anamnese, relatou presença de corrimento\nvaginal de odor fétido e coloração acinzentada. Refere também início da atividade sexual. São\nrealizadas, além das orientações, tratamento do corrimento vaginal e proposta para iniciar uso de\nmétodo contraceptivo. O atributo da Atenção Primária à Saúde exemplificado é","options":{"A":"acesso e Primeiro Contato.","B":"integralidade.","C":"coordenação.","D":"longitudinalidade."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-335095","number":"335095","sourceNumber":"335095","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Homem, 82 anos de idade, portador de insuficiência cardíaca congestiva, arritmia\ncardíaca, Diabetes mellitus e hipotireoidismo,\nfoi internado por um IAM. Ao planejar a alta\nhospitalar, decidiu-se pela realização de um Projeto Terapêutico Singular (PTS). Sendo assim,\nconsidere as afirmativas a seguir. I. O PTS é composto por quatro momentos: o diagnóstico, a\nelaboração, a pactuação e a reavaliação. No diagnóstico, o objetivo é descrever as necessidades\ndo sujeito (indivíduo ou coletivo), geralmente em situação complexa. II. O PTS deve ser elaborado\npela equipe de saúde, apresentado e validado pela pessoa e pela família. III. A pactuação deve\ncontemplar metas factíveis, prazos adequados e responsáveis por cada ação. Estão corretas as\nafirmativas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-335096","number":"335096","sourceNumber":"335096","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O casal João e Helena é acompanhado por hipertensão arterial e outras comorbidades.\nAmbos estão apresentando piora dos níveis\npressóricos, apesar de manterem o tratamento. Assim,\npara uma melhor avaliação, é decidido utilizar ferramentas de abordagem familiar. A partir do\ngenograma, analise as afirmativas a seguir. I. A pessoa índice é o Sr. João. II. Moram na mesma\ncasa João, Helena, Bruna, Vinícius, Luíza, Letícia e Vitória. III. O relacionamento das irmãs\nCarolina e Bruna é distante. Estão corretas as afirmativas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-346867","number":"346867","sourceNumber":"346867","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Como corolário do movimento da Reforma Sanitária, a Constituição Federal de 1988\ndefiniu três grandes referenciais para o\nsistema de saúde brasileiro: o conceito ampliado de saúde;\na saúde como direito do cidadão e dever do Estado e a instituição do SUS. Esse sistema, calcado\nnos princípios de universalidade, integralidade, descentralização e participação da comunidade, foi\nresultado de um intenso movimento social, que teve como objetivo construir um sistema universal\nde saúde para o país. São princípios que nortearam a reforma: I- Princípio ético-normativo, que\ninsere a saúde como parte dos direitos humanos. II- Princípio científico, que compreende a\ndeterminação social do processo saúde/doença. III- Princípio político, que assume a saúde como\ndireito universal inerente à cidadania em uma sociedade democrática. IV- Princípio sanitário, que\nentende a proteção à saúde de forma integral, desde a promoção, passando pela ação curativa até\na reabilitação. Estão CORRETAS as afirmativas:","options":{"A":"I, II e III apenas.","B":"II e IV apenas.","C":"I e III apenas.","D":"I, II, III e IV."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-346868","number":"346868","sourceNumber":"346868","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a Lei Orgânica da Saúde, estão incluídas ainda no campo de atuação\ndo Sistema Único de Saúde (SUS): I- A execução\nde ações de vigilância epidemiológica e sanitária,\nde saúde do trabalhador e de assistência terapêutica integral, inclusive farmacêutica. II- A\nparticipação na formulação da política e na execução de ações de saneamento básico. III- A\nordenação da formação de recursos humanos na área de saúde. IV- O incremento do\ndesenvolvimento científico e tecnológico. Estão CORRETAS as afirmativas:","options":{"A":"I, II, III e IV.","B":"I, II e III apenas.","C":"II e IV apenas.","D":"I e III apenas."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334748","number":"334748","sourceNumber":"334748","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paciente de 70 anos, diabético e hipertenso, comparece à consulta na Unidade de\nSaúde da Família para acompanhamento\nregular. O médico de família identificou alguns problemas\nna alimentação. Como era novo no território, refletiu com o paciente sobre as bases culturais de\nalguns hábitos alimentares que observou na entrevista. Comentou com o paciente que já havia\npercebido as mesmas coisas em várias outras pessoas que residem no local. A partir disso, o\npaciente relatou algumas questões familiares que influenciam sua alimentação e reconheceu certas\nheranças culturais em seus hábitos. Qual componente do Método Clínico Centrado na Pessoa é\nilustrado no caso acima?","options":{"A":"Explorando a saúde, a doença e a experiência da doença.","B":"Entendendo a pessoa como um todo.","C":"Elaborando um plano conjunto de manejo dos problemas.","D":"Intensificando a relação entre a pessoa e o médico."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-346869","number":"346869","sourceNumber":"346869","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Analise as ações da equipe da estratégia de saúde da família a seguir: I- Realizar\nações de gerenciamento na unidade de saúde.\nII- Realizar o cuidado em saúde da população\nadscrita, prioritariamente no âmbito da unidade de saúde, no domicílio e nos demais espaços\ncomunitários (escolas, associações, entre outros), quando necessário. III- Fazer uma busca ativa e\na notificação de doenças e agravos de notificação compulsória e de outros agravos e situações de\nimportância para o grupo. IV- Participar das atividades de planejamento e avaliação das ações da\nequipe, a partir da utilização dos dados disponíveis. É CORRETO afirmar que são atribuições de\ntodos os membros da ESF as afirmativas previstas em:","options":{"A":"I e II apenas.","B":"I, II, III e IV.","C":"III e IV apenas.","D":"II, III e IV apenas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334749","number":"334749","sourceNumber":"334749","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paciente de 20 anos buscou a Unidade de Saúde da Família com queixa de dispepsia,\nsem fatores de risco ou sinais de alerta, há\naproximadamente 2 semanas. Foi utilizado o modelo\nSOAP para o registro clínico dessa consulta. Marque a alternativa que apresenta uma relação\nincorreta entre a dimensão SOAP e seu registro.","options":{"A":"S - Dispepsia há 2 semanas. Sem vômitos. História familiar de neoplasia de cólon.","B":"O - Dor leve à palpação de região epigástrica. Sem sinais de alerta ao exame. Medo de\nneoplasia.","C":"A - Dispepsia sem sinais de alerta.","D":"P - Proposto mudança de estilo de vida. Prescrito omeprazol por 6 semanas. Avaliar\nnecessidade de endoscopia na consulta de retorno."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334750","number":"334750","sourceNumber":"334750","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em um relatório de gestão, consta que 30% das Unidades de Saúde da Família de um\nmunicípio ofertam inserção de DIU, pequenos procedimentos cirúrgicos e eletrocardiograma. Esse\npercentual é superior à média dos municípios do estado, o que foi considerado positivo para a\ngestão. Qual atributo da Atenção Primária à Saúde foi avaliado no enunciado?","options":{"A":"Acesso de Primeiro Contato.","B":"Longitudinalidade do Cuidado.","C":"Integralidade.","D":"Coordenação do Cuidado."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334751","number":"334751","sourceNumber":"334751","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Uma das estratégias que o Brasil adotou para a organização do sistema de saúde foi\nfortalecer redes de atenção à saúde, tendo sido definido algumas áreas prioritárias (redes\ntemáticas). Estão dentre as redes temáticas prioritárias pactuadas pelos diferentes níveis de gestão\ndo SUS:","options":{"A":"Rede Cegonha, Rede de Atenção às Urgências e Emergências, Rede de Cuidado à Pessoa com\nDeficiência.","B":"Rede de Internação Domiciliar, Rede de Atenção à População em Situação de Rua, Rede\nCegonha.","C":"Rede de Atenção às Urgências e Emergências, Rede de Atenção às Doenças Raras, Rede de\nAtenção Psicossocial.","D":"Rede de Atenção à Vítima de Violência, Rede de Atenção às Doenças e Condições Agudas e\nCrônicas, Rede de Atenção Odontológica."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-346872","number":"346872","sourceNumber":"346872","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre a Política Nacional de Atenção Básica (PNAB), assinale a alternativa\nINCORRETA:","options":{"A":"A PNAB tem na longitudinalidade sua estratégia prioritária para expansão e consolidação da\nAtenção Básica.","B":"A Atenção Básica será a principal porta de entrada e o centro de comunicação da Rede de\nAtenção à Saúde (RAS), coordenadora do cuidado e ordenadora das ações e serviços.","C":"A integração entre a Vigilância em Saúde e a Atenção Básica é condição essencial para o\nalcance de resultados que atendam às necessidades de saúde da população.","D":"A resolutividade e a territorialização são diretrizes do Sistema Único de Saúde e da rede de\natenção à saúde a serem operacionalizadas na atenção básica."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334752","number":"334752","sourceNumber":"334752","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em 2019 foi instituído o Programa Previne Brasil, que estabelece novo modelo de\nfinanciamento de custeio da Atenção Primária à Saúde no âmbito do Sistema Único de Saúde.\nDentre os dispositivos elencados nas alternativas abaixo, qual foi inserido pelo Programa Previne\nBrasil?","options":{"A":"Piso da Atenção Básica Fixo.","B":"Pagamento por equipe NASF (Núcleo de Apoio à Saúde da Família).","C":"Componente Qualidade e Desempenho do Piso de Atenção Básica Variável.","D":"Capitação ponderada."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-334753","number":"334753","sourceNumber":"334753","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a Lei 8080/90, que regula as ações e serviços de saúde no Brasil, à\ndireção estadual do Sistema Único de Saúde (SUS) não compete:","options":{"A":"Prestar apoio técnico e financeiro aos municípios.","B":"Executar a totalidade das ações de saúde das redes hierarquizadas do SUS.","C":"Coordenar e, em caráter complementar, executar ações e serviços de saúde do trabalhador.","D":"Gerir sistemas públicos de saúde de alta complexidade."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-346874","number":"346874","sourceNumber":"346874","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre a participação da comunidade na gestão do Sistema Único de Saúde (SUS),\nassinale a alternativa INCORRETA:","options":{"A":"A Conferência de Saúde se reunirá a cada quatro anos com a representação dos vários\nsegmentos sociais.","B":"A representação dos usuários nos Conselhos de Saúde e Conferências será paritária em relação\nao conjunto dos demais segmentos.","C":"As Conferências de Saúde e os Conselhos de Saúde terão sua organização e normas de\nfuncionamento definidas em regimento próprio, aprovadas pelo respectivo conselho.","D":"O Conselho de Saúde, em caráter findável e randômico, atua na formulação de estratégias e no\ncontrole da execução da política de saúde na instância correspondente."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-337653","number":"337653","sourceNumber":"337653","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O movimento da Reforma Sanitária nasceu no contexto da luta contra a ditadura, no\ninício da década de 1970. A expressão foi usada para se referir ao conjunto de ideias que se tinha\nem relação às mudanças e transformações necessárias na área da saúde. Quatro princípios\nnortearam a reforma, sendo eles, EXCETO:","options":{"A":"Princípio ético-normativo, que insere a saúde como parte dos direitos humanos.","B":"Princípio científico, que compreende a medicina baseada em evidências para a formulação de\ntodas as políticas públicas.","C":"Princípio político, que assume a saúde como um direito universal, inerente à cidadania em uma\nsociedade democrática.","D":"Princípio sanitário, que compreende a proteção da saúde de forma integral, desde a promoção\naté a reabilitação."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321193","number":"321193","sourceNumber":"321193","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre território e comunidade adscrita, assinale a alternativa INCORRETA:","options":{"A":"A territorialização e a definição do território como responsabilidade de cada equipe estão entre\nas diretrizes da Política Nacional de Atenção\nBásica (PNAB).","B":"Em áreas de grande dispersão territorial, áreas de risco e vulnerabilidade social, recomenda-se a\ncobertura de 70% da população com número máximo de 1.000 pessoas por ACS.","C":"O processo de territorialização deve ser considerado um meio operacional para o\ndesenvolvimento do vínculo entre os serviços\nde saúde e a população, permitindo aproximação\npara o entendimento dos problemas e necessidades de saúde do território.","D":"Um exemplo da importância de se conhecer o território para atuação nos principais problemas\nde saúde da comunidade é o caso da região\nAmazônica, que concentra mais de 99% dos casos de\nmalária do Brasil, e a atuação integrada da Vigilância em Saúde com a Atenção Básica é\nfundamental para o controle da doença."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-337654","number":"337654","sourceNumber":"337654","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Sistema Único de Saúde (SUS), foi criado em 1988 com a Constituição Federal. A Lei\nFederal nº 8.080, de 19 de setembro de 1990, dispõe sobre as condições para o funcionamento dos\nserviços de saúde. Nesse contexto, assinale a alternativa CORRETA sobre a Lei Federal nº\n8.080/1990:","options":{"A":"A iniciativa privada poderá participar do SUS, em caráter basilar, devendo seguir os princípios\néticos e normas expedidas pelas sociedades\nmédicas.","B":"Estão incluídas no campo de atuação do SUS a execução de ações de: vigilância sanitária,\nvigilância epidemiológica, saúde do trabalhador e previdência privada.","C":"A identificação e divulgação dos fatores condicionantes e determinantes da saúde e a\nassistência às pessoas por intermédio de ações\nde promoção, proteção e recuperação da saúde,\nsão objetivos do SUS.","D":"A universalidade de acesso, preservação da autonomia das pessoas, participação da\ncomunidade e centralização político-administrativa, são alguns dos princípios do SUS."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-337655","number":"337655","sourceNumber":"337655","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As ações de Vigilância em Saúde, incluindo-se a promoção da saúde, devem estar\ninseridas no cotidiano das equipes de Atenção Primária. É CORRETO afirmar que uma das\nestratégias indutoras para fortalecer as ações junto às equipes de saúde da família é a\nincorporação do:","options":{"A":"Conselho regional de saúde.","B":"Técnico de enfermagem.","C":"Enfermeiro de saúde da família.","D":"Agente de combate às endemias."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321195","number":"321195","sourceNumber":"321195","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre o disposto na Lei no 8.080, de 19 de setembro de 1990 e suas alterações,\nassinale a alternativa CORRETA:","options":{"A":"Um dos princípios do SUS é a igualdade de assistência, entendida como conjunto articulado e\ncontínuo das ações e serviços preventivos e curativos, individuais e coletivos, com amplo acesso.","B":"Estão incluídas no campo de atuação do SUS a execução de ações de vigilância sanitária, de\nvigilância epidemiológica, de saúde do trabalhador, e de assistência terapêutica integral.","C":"O SUS promoverá a articulação do subsistema de Atenção à Saúde Indígena, com os órgãos\nresponsáveis pela Política Indígena do País; e caberá aos municípios, com seus recursos próprios,\nfinancia o subsistema existente em seu território.","D":"A assistência à saúde é livre à iniciativa privada. Na prestação de serviços privados de\nassistência à saúde, serão observados os princípios éticos e as normas expedidas pelo gestor\nprivado, quanto às condições para seu funcionamento."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-337656","number":"337656","sourceNumber":"337656","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"No Brasil, a territorialização é um pressuposto básico do Programa de Saúde da\nFamília (PSF). Sobre a territorialização, assinale a alternativa CORRETA:","options":{"A":"As ações de vigilância em saúde, primordialmente, deverão ser estabelecidas sobre uma base\nterritorial local de saúde.","B":"O território microárea é a unidade operacional pela qual uma equipe de saúde da família é\nresponsável.","C":"A territorialização é uma ferramenta utilizada pelos países subdesenvolvidos para a promoção\nda saúde.","D":"O distrito sanitário deve ser resolutivo na promoção e prevenção do cuidado a nível primário,\ndirecionando demais questões às regionais."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321199","number":"321199","sourceNumber":"321199","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A participação popular compreende as múltiplas ações que diferentes forças sociais\ndesenvolvem para influenciar a formulação, a execução, a fiscalização e a avaliação das políticas\npúblicas e/ou dos serviços básicos na área social, como a saúde. Nesse contexto, assinale a\nalternativa CORRETA sobre a participação popular no SUS:","options":{"A":"Os conselhos e as conferências de saúde são expressivas formas de centralização do poder,\nconsiderando suas finalidades e sua forma de estruturação.","B":"As conferências de saúde são espaços de debates, ocorrem a cada 2 anos e têm natureza\ndeliberativa. Sua composição é diferente da paridade dos conselhos.","C":"Os conselhos de saúde são compostos de forma paritária por 50% de usuários, 25% de\ntrabalhadores CLT e 25% de gerentes de centros de saúde.","D":"Os conselhos gestores são os mecanismos mais importantes de participação popular e têm\nfunção expressiva na formulação de políticas públicas."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-321201","number":"321201","sourceNumber":"321201","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"São objetivos e princípios da Medicina Baseada em Evidências (MBE), EXCETO:","options":{"A":"Reconhecimento do papel da evidência na tomada de decisão clínica efetiva.","B":"Descrição de uma abordagem sistemática no processo de solução do problema clínico.","C":"Não há necessidade de identificar hierarquias de evidências para a tomada de decisão, existem\num mesmo nível de evidências.","D":"Somente o nível de evidências nunca é suficiente ? necessidade de fazer um contrabalanço\nentre o risco e o benefício das estratégias\nalternativas no contexto dos valores e preferências das\npessoas."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-306700","number":"306700","sourceNumber":"306700","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Com relação aos aspectos legais associados ao sistema único de saúde (SUS),\nassinale a alternativa correta:","options":{"A":"A lei 8.142 dispõe sobre as condições para a promoção, proteção e recuperação da saúde, a\norganização e o funcionamento dos serviços correspondentes.","B":"A lei orgânica da saúde é composta pela união das leis 8.080 e 8.142, que foram editadas em\n1990, após a instituição constitucional do SUS e 1988.","C":"A lei 8.080 dispõe sobre a participação da comunidade na gestão do Sistema Único de Saúde\n(SUS) e sobre as transferências\nintergovernamentais de recursos financeiros na área de saúde.","D":"?A saúde é um direito de todos e dever do Estado? esta frase é citada na Lei 8.080 de 1990,\nque instituiu o SUS."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291613","number":"291613","sourceNumber":"291613","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"\"Historicamente, a ideia de atenção primária foi utilizada como forma de organização\ndos sistemas de saúde pela primeira vez no\nchamado Relatório Dawson, em 1920. Esse\ndocumento do governo inglês procurou, de um lado, contrapor-se ao modelo flexneriano americano\nde cunho curativo, fundado no reducionismo biológico e na atenção individual, e por outro,\nconstituir-se numa referência para a organização do modelo de atenção inglês, que começava a\npreocupar as autoridades daquele país, devido ao elevado custo, à crescente complexidade da\natenção médica e à baixa resolutividade. O referido relatório organizava o modelo de atenção em\ncentros de saúde primários e secundários, serviços domiciliares, serviços suplementares e\nhospitais de ensino\" (MATTA, MOROSINI, 2009). Assinale a alternativa com os quatro atributos\npeculiares à Atenção Primária à Saúde:","options":{"A":"Universalidade, integralidade, equidade e participação popular.","B":"Integralidade, longitudinalidade, porta de entrada e coordenação do cuidado.","C":"Descentralização, integralidade, equidade e participação popular.","D":"Integralidade, coordenação do cuidado, descentralização e porta de entrada.","E":"Longitudinalidade, universalidade, equidade e porta de entrada."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-306707","number":"306707","sourceNumber":"306707","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre a saúde do trabalhador, assinale a alternativa CORRETA:","options":{"A":"A forma de inserção das pessoas nos espaços de trabalho contribui decisivamente para o\nprocesso saúde-doença do trabalhador.","B":"A saúde do trabalhador é de responsabilidade do Ministério do Trabalho e Emprego.","C":"A saúde do trabalhador visa compreender a infraestrutura do local de trabalho e o processo de\nadoecimento do trabalhador.","D":"A saúde do trabalhador é de responsabilidade dos médicos junto com os sindicatos patronais."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-306714","number":"306714","sourceNumber":"306714","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Norma Operacional Básica 96 (NOB) estimulou a ocorrência de mudanças a partir do\nfortalecimento de um novo modelo de Atenção à Saúde com a instituição do Piso da Atenção\nBásica (PAB). Essa norma determina que o (a):","options":{"A":"PAB fixo é calculado pelo número de equipes de saúde da família implantadas no município.","B":"PAB fixo garantiu os repasses automáticos do nível federal para o municipal com base no\nnúmero de habitantes.","C":"PAB variável é dependente da capacidade dos municípios realizarem procedimentos de\ndiagnóstico e tratamento pelas unidades básicas.","D":"PAB variável desacelerou o ritmo de expansão da Atenção Básica/Primária no país."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-313301","number":"313301","sourceNumber":"313301","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Política Nacional de Atenção Básica ? PNAB discorre que a Atenção Básica é o\nconjunto de ações de saúde individuais,\nfamiliares e coletivas que envolvem promoção, prevenção,\nproteção, diagnóstico, tratamento, reabilitação, redução de danos, cuidados paliativos e vigilância\nem saúde, desenvolvida por meio de práticas de cuidado integrado e gestão qualificada, realizada\ncom equipe multiprofissional e:","options":{"A":"Dirigida à população em território definido, sobre as quais as equipes assumem responsabilidade\nsanitária.","B":"Considerando os determinantes e condicionantes de saúde.","C":"Baseada em idade, gênero, raça/cor, etnia, crença, nacionalidade, orientação sexual, identidade\nde gênero, estado de saúde, condição\nsocioeconômica, escolaridade, limitação física, intelectual,\nfuncional e outras.","D":"Atividades que visam garantir a atenção, a defesa e a proteção às pessoas em situação de risco\npessoal.","E":"Visando a estabelecer processos de trabalho que consideremos determinantes, os riscos e\ndanos à saúde, na perspectivada intra e\nintersetorialidade."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-313302","number":"313302","sourceNumber":"313302","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"É correto afirmar que a Atenção Básica considera a pessoa:","options":{"A":"Enquanto estiverem no território.","B":"Como primeiro ponto de atenção e porta de entrada preferencial.","C":"Realizando classificação de risco e identificando as necessidades de intervenções de cuidado.","D":"Em sua singularidade e inserção sociocultural.","E":"Para a proteção da saúde, a prevenção e o controle de riscos."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-313305","number":"313305","sourceNumber":"313305","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Universidade Aberta do SUS ? UnaSUS relata que para trilhar um caminho correto\ndiante dos diversos dilemas éticos que\npodemos encontrar na nossa atividade profissional,\nprecisamos de uma ?base sólida?, de um fundamento que nos oriente nos momentos de decisão;\nesse fundamento, segundo o documento, é a pessoa humana. Discorrendo sobre o tema, o\ndocumento traz conceitos essenciais ligados ao enfrentamento de questões bioéticas na prática\nprofissional, sendo eles: I- A pessoa é única. Isso significa que as pessoas são diferentes (mesmo\nos gêmeos idênticos são diferentes), têm suas características, seus anseios, suas necessidades, e\nesse patrimônio, essa identidade, merece ser respeitado (para que as pessoas não sejam tratadas\ncomo números); II- A pessoa humana é provida de uma ?dignidade?. Isso significa que a pessoa\ntem valor pelo simples fato de ser pessoa; III- A pessoa é composta de diversas dimensões:\ndimensão biológica (que as ciências da saúde, medicina, enfermagem, odontologia, fisioterapia e\noutras estão acostumadas a estudar), dimensão psicológica (que os psicólogos estudam\ndetalhadamente), dimensão social ou moral (estudada pelas ciências sociais) e dimensão espiritual\n(estudada pelas teologias). Por isso, falamos que a pessoa é uma totalidade, pois todas essas\ndimensões juntas compõem a pessoa. Dos itens acima: (Fonte:\nhttps://www.unasus.unifesp.br/biblioteca_virtual/esf/2/unidades_conteudos/unidade18/unidade18.pd\nf)","options":{"A":"Apenas o item II está correto.","B":"Apenas os itens I e II estão corretos.","C":"Apenas os itens I e III estão corretos.","D":"Apenas os itens II e III estão corretos.","E":"Todos os itens estão corretos."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314046","number":"314046","sourceNumber":"314046","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a Lei nº 8.080/1990 - SUS, as ações e os serviços públicos de saúde e\nos serviços privados contratados ou\nconveniados que integram o Sistema Único de Saúde (SUS)\ndevem obedecer, entre outros, aos seguintes princípios: I. Igualdade da assistência à saúde, sem\npreconceitos ou privilégios de qualquer espécie. II. Preservação da dependência das pessoas na\ndefesa de sua integridade física e moral. III. Utilização da epidemiologia para o estabelecimento de\nprioridades, a alocação de recursos e a orientação programática. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305022","number":"305022","sourceNumber":"305022","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Analise o genograma a seguir e considere as afirmativas a respeito dele: I. João e Leila\nsão casados desde 1985 e têm três filhas: Cláudia, Bruna e Luiza. II. Leila tem um relacionamento\nconflituoso com Marcus Vinícius. III. Cláudia, Pedro e a filha Cecília não moram com João e Leila.\nEstão corretas as afirmativas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314047","number":"314047","sourceNumber":"314047","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo a Lei nº 8.142/1990, os recursos do Fundo Nacional de Saúde (FNS)\ndestinados à cobertura de ações e serviços\nde saúde a serem implementados pelos Municípios,\nEstados e Distrito Federal: I. Destinar-se-ão a investimentos na rede de serviços, à cobertura\nassistencial ambulatorial e hospitalar e às demais ações de saúde. II. Serão destinados, na mesma\nproporção, a Municípios e a Estados. III. Poderão ser remanejadas entre os Municípios que\nestabelecerem consórcio para execução de ações e serviços de saúde. Estão CORRETOS:","options":{"A":"Somente os itens I e II.","B":"Somente os itens I e III.","C":"Somente os itens I, III e IV.","D":"Somente os itens II, III e IV.","E":"Todos os itens."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-306727","number":"306727","sourceNumber":"306727","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei 8.142 de 28 de dezembro de 1990 dispõe sobre a participação da comunidade na\ngestão do Sistema Único de Saúde (SUS) e sobre as transferências intergovernamentais de\nrecursos financeiros na área da saúde e dá outras providências. Uma das resoluções apresentadas\nnessa lei é que ?a Conferência de Saúde reunir-se-á a cada quatro anos com a representação dos\nvários segmentos sociais, para avaliar a situação de saúde e propor as diretrizes para a formulação\nda política de saúde nos níveis correspondentes, convocada pelo Poder Executivo ou,\nextraordinariamente, por esta ou pelo Conselho de Saúde?. Qual das alternativas abaixo apresenta\numa resolução que não é abordada na Lei 8.142/90?","options":{"A":"As Conferências de Saúde e os Conselhos de Saúde terão sua organização e normas de\nfuncionamento definidas em regimento próprio, aprovadas pelo respectivo conselho","B":"O Conselho Nacional de Secretários de Saúde (Conass) e o Conselho Nacional de Secretários\nMunicipais de Saúde (Conasems) terão representação no Conselho Nacional de Saúde.","C":"A descentralização político-administrativa é um princípio do SUS, com direção única em cada\nesfera de governo e ênfase na descentralização dos serviços para os municípios","D":"Os recursos do Fundo Nacional de Saúde (FNS) serão alocados, entre outras maneiras, como\ndespesas de custeio e de capital do\nMinistério da Saúde, seus órgãos e entidades, da\nadministração direta e indireta"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314048","number":"314048","sourceNumber":"314048","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em conformidade com o decreto nº 7.508/2011 - SUS, sobre as disposições\npreliminares, numerar a 2ª coluna de acordo\ncom a 1ª e, após, assinalar a alternativa que\napresenta a sequência CORRETA: (1) Região de Saúde. (2) Mapa da Saúde. (3) Rede de atenção\nà saúde. (4) Serviços especiais de acesso aberto. ( ) Conjunto de ações e serviços de Saúde\narticulados em níveis de complexidade crescente, com a finalidade de garantir a integralidade da\nassistência à saúde. ( ) Descrição geográfica da distribuição de recursos humanos e de ações e\nserviços de Saúde ofertados pelo sistema único de saúde e pela iniciativa privada, considerando-se\na capacidade instalada existente, os investimentos e o desempenho aferido a partir dos indicadores\nde saúde do sistema. ( ) Espaço geográfico continuo, constituído por agrupamentos de municípios\nlimítrofes, delimitado a partir de identidades culturais, econômicas e sociais e de redes de\ncomunicação e infraestrutura de transportes compartilhados, com a finalidade de integrar a\norganização, o planejamento e a execução de ações e serviços de Saúde. ( ) Serviços de Saúde\nespecíficos para o atendimento da pessoa que, em razão de agravo ou de situação laboral,\nnecessita de atendimento especial.","options":{"A":"3 - 2 - 1 - 4.","B":"1 - 3 - 4 - 2.","C":"2 - 4 - 3 - 1.","D":"4 - 1 - 2 - 3.","E":"4 - 3 - 2 - 1."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314049","number":"314049","sourceNumber":"314049","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com o Decreto nº 7.508/2011, analisar os itens abaixo: I. Os Serviços\nEspeciais de Acesso Aberto são serviços de\nSaúde específicos para o atendimento da pessoa que,\nem razão de agravo ou de situação laboral, necessita de atendimento especial. II. A rede de\natenção à saúde é o conjunto de ações e serviços de Saúde articulados em níveis de complexidade\ncrescente, com a finalidade de garantir a integralidade da assistência à saúde. III. O SUS é\nconstituído pela setorização das ações e dos serviços de promoção, proteção e recuperação da\nsaúde executados pelos entes federativos. Está (ão) CORRETO(s):","options":{"A":"Todos os itens.","B":"Somente os itens I e II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Nenhum dos itens."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314051","number":"314051","sourceNumber":"314051","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com BORGHI, OLIVEIRA e SEVALHO, o determinismo é ressaltado como\ntraço fundamental da concepção de determinantes\nsociais da Saúde da OMS. Os autores recorrem\na uma perspectiva histórica para entender como o determinismo veio a posicionar-se no cerne da\nciência moderna, sintetizando algumas das principais observações feitas por Peñaranda e Rendón\n(2013) ao explorarem filosoficamente atenção determinismo/indeterminismo dos gregos até à\natualidade. Sobre esse assunto assinale a alternativa que preenche as lacunas abaixo\nCORRETAMENTE: Os autores identificam duas visões contrárias entre os pré-socráticos: a\nmonista, na qual se propõe a do ser e o pensar e se concebe a realidade\n\ncomo e determinada em todos os aspectos; e a pluralista, para qual existem\nvários princípios e um universo","options":{"A":"unidade I dinâmica I estático","B":"dualidade | dinâmica | estático","C":"unidade | estática | em movimento","D":"dualidade | estática | em movimento","E":"unidade | estática | estático"},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314052","number":"314052","sourceNumber":"314052","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo BORGHI, OLIVEIRA e SEVALHO, sobre o modelo teórico de determinantes\nsociais de saúde associado a orientação da\nOrganização Mundial de Saúde, analisar os itens\nabaixo: I. Nota-se que \"estilo de vida dos indivíduos\" aparece como determinante, sem que haja\numa explanação clara de como ele se concatena com dimensões históricas e sociais. II.\n\nPercebe-se que sua centralidade não recai sobre coletividades, mas sim sobre indivíduos,\ndestacando, como suas únicas características,\nidade, sexo (e não gênero) e fatores hereditários,\nsem menção a raça/etnia ou à maneira como essas particularidades transcendem a individualidade,\nna medida em que são significados de acordo com as experiências sociais. III. Ausência da\nnomeação da estrutura ou de classes sociais, mal substituídas por algo tão vago como \"condições\nsócioeconômicas, culturais e ambientais gerais\", \"condições de vida e de trabalho\" e \"redes sociais\ne comunitárias\". Está(ão) CORRETO(S):","options":{"A":"Somente os itens I e II.","B":"Todos os itens.","C":"Somente o item I.","D":"Somente o item II.","E":"Nenhum dos itens."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305029","number":"305029","sourceNumber":"305029","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considere que, em uma reunião com sua nova equipe de saúde da família, o Dr. Flávio\nrecebeu a demanda de quatro visitas domiciliares. Foi decidido que a priorização das visitas seria\nfeita a partir da escala de vulnerabilidade familiar de Coelho e Savassi. Dentre as quatro famílias\na\nseguir, qual deverá receber a primeira visita?","options":{"A":"Senhora Débora, 72 anos de idade, diabética e senhor Leonardo, 75 anos de idade, hipertenso e\ndiabético, moram em casa de quatro cômodos com saneamento básico.","B":"Senhora Andreia, 24 anos de idade, desempregada, mora com o avô, Rodrigo, de 70 anos de\nidade, acamado; e com três filhos de 2, 4 e 6 anos de idade, em casa de quatro cômodos.","C":"Senhora Carla, 68 anos de idade, mora com o esposo, Eduardo, de 70 anos de idade,\nhipertenso, ambos analfabetos, moram em casa de dois cômodos.","D":"Senhor Helvécio, 80 anos de idade, diabético, teve ambas as pernas amputadas, por isso,\nacamado; mora com esposa, Alice, de 68 anos de idade, em casa de três cômodos."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-306733","number":"306733","sourceNumber":"306733","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Ao longo da evolução do Sistema Único de Saúde, com o objetivo de facilitar a\nautonomia dos municípios em relação à gestão, diferentes regras de financiamento foram\naplicadas. Assinale, dentre as alternativas abaixo, a medida implementada pela Emenda\nConstitucional no95, de 15 de dezembro de 2016:","options":{"A":"Os municípios e o Distrito Federal aplicarão anualmente, em ações e serviços públicos de\nsaúde, no mínimo 15% da arrecadação dos impostos municipais.","B":"Os estados e o Distrito Federal aplicarão anualmente, em ações e serviços públicos de saúde,\nno mínimo 12% da arrecadação dos impostos\nestaduais","C":"No Distrito Federal, dos impostos que não entram na base municipal ou estadual será aplicado,\nno mínimo, 12% anualmente","D":"Os limites mínimos de transferência de recursos passam a ter correção anual com base no IPCA"},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314054","number":"314054","sourceNumber":"314054","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando-se as Diretrizes Nacionais da Vigilância em Saúde, analisar os itens\nabaixo: I. A vigilância em Saúde, visando à\nintegralidade do cuidado, deve inserir-se na construção\ndas redes de atenção à saúde, coordenadas pela Atenção Primária à Saúde. II. A incorporação do\nAgente de Combate às Endemias (ACE) nas equipes de saúde da família pressupõe a\nreorganização dos processos de trabalho, com integração das bases territoriais dos Agentes\nComunitários de Saúde (ACS) e dos ACE, com definição de papéis e responsabilidades, e a\nsupervisão dos ACE pelos profissionais de nível superior da Equipe de Saúde da Família. III. As\nações de Vigilância em Saúde, incluindo-se a promoção da saúde, devem estar inseridas no\ncotidiano das equipes de Atenção Primária - Saúde da Família, com atribuições e\nresponsabilidades definidas em território único de atuação, integrando os processos de trabalho,\nplanejamento, monitoramento e avaliação dessas ações. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente os itens I e II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-305030","number":"305030","sourceNumber":"305030","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As situações a seguir são exemplos dos atributos da APS. Assinale a situação que\nrepresenta a coordenação de cuidados.","options":{"A":"Joana está realizando o pré-natal de sua primeira filha, que, após o nascimento, terá seu\ncrescimento e desenvolvimento acompanhado por meio das consultas de puericultura, será\norientada sobre métodos contraceptivos e prevenção do câncer de colo de útero na juventude;\nreceberá os mesmos cuidados de pré-natal na própria gestação e será rastreada para prevenção\nde câncer de mama após os 50 anos de idade.","B":"Maria, 18 anos de idade, vem à consulta para trazer resultado de hemograma para controle de\ncura de anemia e, durante a anamnese, relata vida sexual ativa, mas nega uso de métodos\nanticoncepcionais. São realizadas orientações e prescrições relativas à anemia e também sobre o\nplanejamento familiar.","C":"Numa pequena cidade do litoral do Espírito Santo, em reunião local de saúde, o senhor Marcelo,\nrepresentante da comunidade, solicita a alteração do horário de funcionamento do centro de saúde,\nem alguns dias da semana, para facilitar as consultas dos pescadores.","D":"José, 63 anos de idade, portador de diabetes mellitus tipo 2, há seis anos, comparece em\nconsulta com queixa de piora da visão e é encaminhado para avaliação oftalmológica e para a\navaliação dos pés."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314055","number":"314055","sourceNumber":"314055","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com o Guia de Vigilância em Saúde, sobre a investigação epidemiológica de\ncasos, surtos e epidemias, assinalar a alternativa INCORRETA:","options":{"A":"A investigação epidemiológica não se distingue da pesquisa epidemiológica, visto que ambas\ndecorrem da necessidade de uma resposta rápida para que as medidas de controle possam ser\ninstituídas.","B":"A investigação epidemiológica de campo, muitas vezes, não permite que se cumpra todo o rigor\nmetodológico científico necessário para o planejamento e execução da pesquisa epidemiológica.","C":"A gravidade do evento representa um fator que condiciona a urgência no curso da investigação\nepidemiológica e na implementação de medidas de controle.","D":"As investigações epidemiológicas de campo iniciam-se, com frequência, sem hipótese clara.\n\nGeralmente, requerem o uso de estudos descritivos para a formulação de hipótese que,\nposteriormente, deverão ser testadas por meio de estudos analíticos.","E":"Uma investigação epidemiológica normalmente é uma ação coordenada de resposta que\nenvolve diferentes setores para cumprimento de todas as suas necessidades."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291954","number":"291954","sourceNumber":"291954","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"J.M.F, sexo feminino, 35 anos, procura a unidade básica de saúde, pois iniciou quadro\nde tosse, febre, odinofagia e mialgia. Logo\nna recepção, foi negado atendimento já que não era\nmoradora do município. Após muita insistência, conseguiu passar na triagem com a equipe de\nenfermagem e foi orientada que poderia ser atendida, porém seria avaliada apenas após todas as\npessoas que estavam na unidade, já que não pertencia a equipe. Após aguardar 4 horas, foi\natendida e encaminhada para sala de medicações, sem que lhe fosse explicado o motivo dos seus\nsintomas e o objetivo da medicação. Diante do quadro descrito, são princípios e diretrizes do SUS\nque foram descumpridos no atendimento dessa paciente, EXCETO:","options":{"A":"Utilização da epidemiologia para o estabelecimento de prioridades.","B":"Universalidade de acesso aos serviços de saúde.","C":"Igualdade da assistência à saúde.","D":"Direito à informação."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-306735","number":"306735","sourceNumber":"306735","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em qual das alternativas abaixo apresenta-se um dos princípios do movimento de\nreforma sanitária no Brasil?","options":{"A":"Estimular a prevenção dos agravos à saúde de modo que o paciente tenha pronto acesso aos\nhospitais logo no início do processo de adoecimento","B":"Promover a participação juntamente com o controle social das ações de saúde desenvolvidas no\npaís","C":"Integrar de maneira coordenada as ações desenvolvidas pelos ministérios da saúde e\nassistência social","D":"Universalização do direito de acesso à educação e transportes, para melhorar um pouco o\nacesso à saúde que era precário"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314056","number":"314056","sourceNumber":"314056","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em relação à história natural da doença, assinalar a alternativa que preenche a lacuna\nabaixo CORRETAMENTE: Para entender as relações entre os diferentes elementos que levam ao\naparecimento de uma doença transmissível, o esquema tradicional é denominado(a)\n\n. O esquema procura organizar os chamados elos, que identificam os pontos\nprincipais da sequência continua da interação entre possível hospedador, meio ambiente e\npatógeno.","options":{"A":"período de latência","B":"período de incubação","C":"diagnóstico de infecção","D":"modo de transmissão da infecção","E":"cadeia epidemiológica"},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-306736","number":"306736","sourceNumber":"306736","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Qual é a ferramenta da medicina de família que, para ser utilizada, exige a realização\nde uma conferência familiar:","options":{"A":"Ciclo de vida familiar","B":"Practice","C":"Ecomapa","D":"Firo"},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314058","number":"314058","sourceNumber":"314058","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando-se Estratégias para o cuidado da pessoa com doença crônica, numerar a\n2ª coluna de acordo com a 1ª e, após, assinalar a alternativa que apresenta a sequência\nCORRETA: (1) Determinantes distais. (2) Determinantes intermediários. (3) Determinantes\nproximais. ( ) São representados pelas condições de vida e de trabalho, acesso à alimentação, à\neducação, à produção cultural, ao emprego, à habitação, ao saneamento e aos serviços de saúde\n(e a forma como se organizam). ( ) São aqueles relacionados às características dos indivíduos, que\nexercem influência sobre seu potencial, sua condição de saúde (idade, sexo, herança genética) e\nsuas relações, formais e informais, de confiança, de cooperação, de apoio nas famílias, na\nvizinhança e nas redes de apoio, onde acontecem as decisões dos comportamentos e estilos de\nvida, determinados socialmente pela interação de todos os níveis aqui apresentados. ( ) São as\ncondições socioeconômicas, culturais e ambientais em que as pessoas, as suas famílias e as redes\nsociais estão inseridas; são o desenvolvimento e a riqueza de um País, uma região ou um\nMunicípio, e a forma como essa riqueza é distribuída, resultando em distintas condições de vida de\numa dada população.","options":{"A":"2 - 3 - 1.","B":"1 - 2 - 3.","C":"3 - 1 - 2.","D":"2 - 1 - 3.","E":"1 - 3 - 2."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-304884","number":"304884","sourceNumber":"304884","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Um médico que atua na Atenção Primária à Saúde percebeu, após conversar com\nalguns colegas, que tinha grande dificuldade de\ncompartilhar algumas decisões terapêuticas com\nseus pacientes. Na visão dele, a determinação da conduta a ser adotada nas consultas era uma\nação exclusiva do médico. Ao perceber que essa sua dificuldade em estabelecer uma relação mais\nhorizontal com as pessoas prejudicava o cuidado prestado a certos tipos de pacientes, resolveu\nprocurar ajuda profissional para lidar de outra forma com suas emoções. Em qual componente do\nMétodo Clínico Centrado na Pessoa a atitude do médico melhor se enquadra?","options":{"A":"Explorando a saúde, a doença e a experiência da doença.","B":"Entendendo a pessoa como um todo (individuo, família e contexto).","C":"Elaborando um plano conjunto de manejo dos problemas.","D":"Fortalecendo a relação entre a pessoa e o médico."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314059","number":"314059","sourceNumber":"314059","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando-se a Portaria de Consolidação nº 4/2017, sobre as ações de Vigilância\nem Saúde, analisar a sentença abaixo: A\nvigilância, a prevenção e o controle, exclusivamente, das\ndoenças transmissíveis (1ª parte). A vigilância sanitária dos riscos decorrentes da produção e do\nuso de produtos de interesse à saúde, com exceção dos serviços e tecnologias (2ª parte). A\nvigilância de populações expostas a riscos ambientais em saúde (3ª parte). A sentença está:","options":{"A":"Correta somente em suas 1ª e 2ª partes.","B":"Correta somente em sua 3ª parte.","C":"Correta somente em sua 2ª parte.","D":"Correta somente em sua 1ª parte.","E":"Totalmente correta."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-304885","number":"304885","sourceNumber":"304885","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre a Política Nacional de Atenção Básica, em sua versão mais recente publicada\nem 2017, considere as afirmações abaixo e\nassinale a alternativa correta. I.Os cuidados paliativos\nestão incluídos no conjunto das ações da saúde que definem a atenção básica. II.A Política\nNacional de Atenção Básica dá grande ênfase na integração entre a Vigilância em Saúde e a\nAtenção Básica. III.A Política Nacional de Atenção Básica retira a obrigatoriedade de o Agente\nComunitário de Saúde compor a Equipe de Saúde da Família.","options":{"A":"Apenas II está correta.","B":"Apenas I e II estão corretas.","C":"Apenas II e III estão corretas.","D":"I, II e III estão corretas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-314060","number":"314060","sourceNumber":"314060","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Considerando-se a Portaria de Consolidação nº 5/2017, sobre o Programa Nacional de\nAtenção Comunitária Integrada a Usuários de Álcool e Outras Drogas, analisar os itens abaixo: I.\nCompete ao Ministério da Saúde definir e implementar ações de vigilância epidemiológica e\nsanitária no que se refere aos transtornos causados pelo uso prejudicial e/ou dependência de\nálcool e drogas. II. Compete à Secretaria Municipal de Saúde executar programas de treinamento e\ncapacitação de recursos humanos nas áreas de prevenção, vigilância e assistência aos pacientes\ncom dependência e/ou uso prejudicial de álcool e outras drogas. III. Objetiva aperfeiçoar as\nintervenções paliativas como forma de prolongar os danos sociais e à saúde representados pelo\nuso prejudicial de álcool e outras drogas. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Somente os itens II e III."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-304886","number":"304886","sourceNumber":"304886","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O decreto nº 7.508, de 28 de junho de 2011, regulamenta a Lei Orgânica da Saúde e\ndispõe sobre a organização do Sistema Único de Saúde. Neste decreto, define-se que, para ser\ninstituída, uma região de saúde deve conter, obrigatoriamente, as seguintes ações e serviços de\nsaúde, exceto:","options":{"A":"Atenção primária à saúde.","B":"Urgência e emergência.","C":"Atenção psicossocial.","D":"Telemedicina."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291960","number":"291960","sourceNumber":"291960","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre vigilância em saúde, assinale a alternativa INCORRETA:","options":{"A":"A vigilância em saúde do trabalhador caracteriza-se por ser um conjunto de atividades\ndestinadas à promoção e proteção, recuperação e reabilitação da saúde dos trabalhadores\nsubmetidos aos riscos e agravos advindos das condições de trabalho.","B":"O Sistema Nacional de Vigilância Sanitária, dentro do seu campo de competência, detecta\nemergências em saúde pública e define ações de intervenção.","C":"A vigilância em saúde, visando a integralidade do cuidado, deve inserir-se na construção das\nredes de atenção à saúde, coordenadas pela Atenção Primária à Saúde.","D":"Uma das estratégias indutoras do fortalecimento das ações de vigilância em saúde junto às\nequipes de saúde da família é a incorporação dos técnicos de enfermagem e de saúde bucal."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-304887","number":"304887","sourceNumber":"304887","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Médica atende mulher de 25 anos com queixa de ansiedade, dificuldade para dormir e\nleve dor abdominal. História clínica e exame físico sem achados de relevância ou sinais de alerta\npara o caso. Ao realizar a abordagem familiar, descobre que a paciente se casou há poucos meses\ne está tendo dificuldade para organizar as tarefas do cotidiano com seu parceiro, o que tem\naumentado seu nível de estresse e prejudicado seu trabalho. Qual ferramenta de abordagem\nfamiliar foi utilizada no caso?","options":{"A":"Ciclo de Vida da Família.","B":"Genograma.","C":"Ecomapa.","D":"PRACTICE."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-291961","number":"291961","sourceNumber":"291961","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Pacto pela Vida é constituído por um conjunto de compromissos sanitários,\ntraduzidos em objetivos de processos e\nresultados, derivados da análise da situação de saúde do\npaís e das prioridades definidas pelos governos federal, estadual e municipal. São prioridades do\nPacto pela vida, EXCETO:","options":{"A":"Erradicação da tuberculose e hanseníase.","B":"Atenção à saúde do idoso.","C":"Controle de câncer de colo de útero e mama.","D":"Fortalecimento da atenção básica."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-304889","number":"304889","sourceNumber":"304889","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Médica atende um paciente de 30 anos com dor lombar inespecífica, sem ciatalgia ou\nsinais de alerta e fica em dúvida entre prescrever ibuprofeno ou ciclobenzaprina. Qual alternativa\nindica uma forma adequada de estruturar uma questão PICO para busca de evidências cientificas\npara embasar a tomada de decisão no caso?","options":{"A":"P: adulto com dor lombar inespecífica sem ciatalgia; I: anti-inflamatórios não esteroides; C:\nrelaxantes musculares; O: redução da dor.","B":"P: adulto; I: dor lombar; C: tratamento medicamentoso; O: redução da dor.","C":"P: dor lombar inespecífica; I: ibuprofeno; C: ciclobenzaprina; O: redução da mortalidade.","D":"P: redução da dor; I: relaxantes musculares; C: anti-inflamatórios não esteroides; O: adulto com\ndor lombar inespecífica sem ciatalgia."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-304890","number":"304890","sourceNumber":"304890","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Analise as afirmativas abaixo e assinale a alternativa correta: I. A população indígena,\nem decorrência do alto grau de integração social\ne cultural observada nas últimas décadas,\napresenta necessidades de saúde muito semelhantes à população geral do Brasil, não havendo\nqualquer justificativa para se estabelecer intervenções especificas para esta população. II. O\nDistrito Sanitário Especial Indígena (DSEI) é a unidade gestora descentralizada do Subsistema de\nAtenção à Saúde Indígena, sendo que os DSEIs se limitam às fronteiras estaduais e são\nfinanciados e gerenciados de forma unipartite pelas Secretarias Estaduais de Saúde. III. Devido a\nsuas particularidades, as populações indígenas não têm direito a participar dos dispositivos de\ncontrole social do SUS, como é o caso do Conselho Nacional de Saúde e dos Conselhos Estaduais\ne Municipais de Saúde.","options":{"A":"Apenas as afirmativas I e II estão corretas.","B":"Apenas as afirmativas II e III estão corretas.","C":"Apenas as afirmativas I e III estão corretas.","D":"Nenhuma está correta."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-260670","number":"260670","sourceNumber":"260670","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Na atenção básica destaca-se o cuidado integral ao paciente diabético. Uma das\nmedidas a serem adotadas é:","options":{"A":"Identificação e tratamento medicamentoso precoce de indivíduos de alto risco para diabetes\n(prevenção primária).","B":"Identificação de casos não diagnosticados de diabetes (prevenção secundária) para tratamento.","C":"Intensificação do controle de pacientes já diagnosticados, visando prevenir complicações agudas\ne crônicas (prevenção quaternária).","D":"Realizar a contrarreferência dos casos que necessitam de medicamentos orais e insulina.","E":"Estimular a prática de atividade física regular como medida de prevenção e controle."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266388","number":"266388","sourceNumber":"266388","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Conforme a Lei Orgânica da Saúde do Brasil (Lei 8080/92), a iniciativa privada poderá\nparticipar do Sistema Único de Saúde (SUS), em caráter:","options":{"A":"Substitutivo.","B":"Complementar.","C":"Competitivo.","D":"Definitivo."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-287869","number":"287869","sourceNumber":"287869","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em conformidade com BORGHI, OLIVEIRA e SEVALHO, em relação aos\ndeterminantes sociais de saúde na América\nLatina, analisar a sentença a seguir: A determinação\nsocial do processo saúde-doença é um constructo acadêmico herdeiro do modelo histórico-social,\nenquanto os determinantes sociais da saúde são as concepções que derivam dos outros modelos\nteóricos (1ª parte). López-Arellano e Saint Martin identificam que os três momentos de\ndesenvolvimento do modelo histórico-social na América Latina e Brasil não estão relacionados com\no desenvolvimento histórico e econômico, pois a transição de um modelo para o outro se processou\nde modo dirigido à manutenção do status quo (2ª parte). Na segunda fase do desenvolvimento do\nmodelo histórico-social, tem-se, no plano epidemiológico, o acréscimo das doenças\n\ncrônico-degenerativas às ainda prevalentes infectocontagiosas (3ª parte). A sentença está:","options":{"A":"Totalmente correta.","B":"Correta somente em suas 1ª e 2ª partes.","C":"Correta somente em suas 1ª e 3ª partes.","D":"Correta comente em suas 2ª e 3ª partes.","E":"Totalmente incorreta."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266389","number":"266389","sourceNumber":"266389","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Na Lei 8142, de 1990, define-se que a representação dos usuários do sistema de\nsaúde nos Conselhos e Conferências de Saúde,\nem relação ao conjunto dos demais segmentos,\nserá:","options":{"A":"Minoritária.","B":"Majoritária.","C":"Paritária.","D":"Única."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-287356","number":"287356","sourceNumber":"287356","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Marque a alternativa que é mais compatível com o conceito de Integralidade:","options":{"A":"É o conjunto de serviços executados pela equipe de saúde que atendam às necessidades da\npopulação adscrita, incluindo a promoção da saúde, a prevenção de agravos e a cura.","B":"É a ideia de que a saúde humana é determinada principalmente pela genética e pela biologia do\ncorpo entendido como máquina.","C":"É a organização de políticas específicas e delimitadas ao setor saúde com vistas à eliminação\ndos fatores de risco sociais e econômicos que\nacometem a população.","D":"É a organização do trabalho dos profissionais de saúde com base em protocolos rigorosos e\ntecnologias que padronizam e controlam a solicitação de exames e procedimentos."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-287357","number":"287357","sourceNumber":"287357","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Conforme a Lei Federal no 8.080, de setembro de 1990, um dos princípios que regem o\nSistema Único de Saúde (SUS) é a participação da comunidade. Qual alternativa apresenta um dos\nsignificados deste princípio na organização do SUS?","options":{"A":"A participação em caráter complementar de organizações privadas da sociedade civil na\nprestação de serviços de saúde.","B":"A participação de órgãos de defesa do consumidor na auditoria dos gastos e investimentos dos\ngovernos na saúde.","C":"O pagamento em espécie de parte dos custos da atenção à saúde recebida no SUS pelos\nempregadores e pelos trabalhadores.","D":"A participação dos cidadãos e usuários do SUS, por meio de organizações e instituições\nrepresentativas, em conselhos e conferências de saúde."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-287359","number":"287359","sourceNumber":"287359","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"As principais Portas de Entrada às ações e aos serviços de saúde nas Redes de\nAtenção à Saúde são os serviços de:","options":{"A":"Atenção primária à saúde.","B":"Atenção de urgência e emergência.","C":"Atenção psicossocial.","D":"Atenção médica especializada."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-287360","number":"287360","sourceNumber":"287360","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Em Vitória-ES, há prontuário eletrônico disponível em todos os serviços de saúde. Nele,\no profissional da Unidade de Saúde da Família\nconsegue encaminhar o paciente a outro\nprofissional, monitorar o agendamento e, em caso de necessidade, trocar informações com o\nprofissional regulador (exemplo: médico). Além disso, consegue consultar os registros clínicos\nrealizados pelo profissional a quem o paciente foi encaminhado. Qual diretriz do SUS é fortalecida\ncom essas características do prontuário eletrônico?","options":{"A":"Programação em saúde.","B":"Acesso de primeiro contato.","C":"Coordenação do cuidado.","D":"Orientação comunitária."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266395","number":"266395","sourceNumber":"266395","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"São princípios, características e eixos da Reforma Psiquiátrica Brasileira, exceto:","options":{"A":"Deslocamento da intervenção dos hospitais psiquiátricos para as comunidades terapêuticas.","B":"Território como eixo organizador da rede de atenção à saúde mental.","C":"Promoção da autonomia, protagonismo, inserção social e dignidade das pessoas.","D":"Compreensão do processo saúde-doença de forma complexa e socialmente condicionada."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-266396","number":"266396","sourceNumber":"266396","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Paciente recém diagnosticada com diabetes mellitus tipo 2 consulta sua médica.\nInforma que não conseguiu incorporar todas as\nrecomendações nutricionais. A médica então diz,\nolhando diretamente para a paciente com postura acolhedora: \"Acho que consigo entender o que\nvocê está passando. Eu também vivenciei algo parecido no passado. Não pense nisso como um\nfracasso. Temos tempo para ajustar o que for necessário\". Tendo em vista o método clínico\ncentrado na pessoa, qual de seus componentes é ilustrado nesta situação?","options":{"A":"Explorando a saúde, a doença e a experiência da doença.","B":"Entendendo a pessoa como um todo - o indivíduo, a família e o contexto.","C":"Elaborando um plano conjunto de manejo dos problemas.","D":"Intensificando a relação entre a pessoa e o médico."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-287877","number":"287877","sourceNumber":"287877","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre a Política Nacional de Educação em Saúde (PNEPS), analisar os itens abaixo: I.\nTem como princípios o diálogo, a amorosidade, a problematização, a construção compartilhada do\nconhecimento, a emancipação e o compromisso com a construção do projeto democrático e\npopular. II. Visa reconhecer e valorizar o conhecimento técnico-científico no âmbito do SUS como\ncomponente único das práticas de cuidado, gestão, formação, controle social e práticas educativas\nem saúde. III. Objetiva assegurar a participação popular no planejamento, acompanhamento,\nmonitoramento e avaliação das ações e estratégias para a implementação da Política. Está(ão)\nCORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-257383","number":"257383","sourceNumber":"257383","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Secretaria de Vigilância em Saúde do Ministério da Saúde (SVS/MS) tem, no Centro\nde Informações Estratégicas e Respostas em\nVigilância em Saúde (CIEVS), o seu ponto focal para\nmanejo de crises agudas. São objetivos da rede CIEVS: I- Identificar emergências epidemiológicas,\nde modo contínuo e sistemático. II- Prestar apoio técnico, presencial e/ou virtual nas respostas às\nemergências em saúde pública. III- Financiar as estratégias para contenção de possíveis crises. IV-\nColetar, consolidar, monitorar e selecionar as informações que devem ser disseminadas entre a\npopulação geral. Estão CORRETOS os objetivos previstos em:","options":{"A":"I, III e IV apenas.","B":"II e IV apenas.","C":"II e III apenas.","D":"I e II apenas."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-257387","number":"257387","sourceNumber":"257387","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Criança de 6 anos é levada pela avó a unidade básica de saúde após mordedura de\ncão. Observada lesões de arranhadura em região de pernas e braços e mordedura em palma da\nmão direita e região frontal. O cão é da vizinha e passível de observação. Com base no caso\ndescrito, é CORRETO afirmar que:","options":{"A":"A sutura dos ferimentos é recomendada se necessário, após limpeza com água corrente e\nsabão.","B":"O acidente causado na criança pelo cão é considerado acidente grave, devido as características\ne locais dos ferimentos.","C":"Iniciar esquema profilático com três doses, nos dias 0, 3 e 7; e observar o animal por 15 dias é\nrecomendado.","D":"Iniciar imediatamente o esquema profilático com soro e 5 doses de vacina, é recomendado."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283930","number":"283930","sourceNumber":"283930","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Mulher, 51 anos, procura atendimento com seu médico de família com queixas de\naumento de diurese à noite e emagrecimento\nde 8 Kg nos últimos dois meses. Identificou-se hábito\nde tomar chimarrão ao entardecer. Durante o transcorrer do ano não conseguiu manter atividade\nfísica regular e controle dietético. Relata ansiedade por suspeitar que tenha desenvolvido diabetes.\nForam solicitados exames. Paciente retorna à consulta portando glicemia de jejum=148 mg/dL;\nTSH US=0,22 mU/L (0,4-4,5); T4 livre=2,5 ng/dl (0,7-1,8); EQU e urocultura sem particularidades.\nQuais hipóteses diagnósticas e condutas são mais apropriadas entre as alternativas a seguir?","options":{"A":"Diabetes mellitus e repetir glicemia de jejum/Hipertireoidismo e investigar etiologia.","B":"Intolerância à glicose e repetir glicemia de jejum/Hipotireoidismo e investigar etiologia.","C":"Diabetes insipidus e solicitar HbA1C/Hipertireoidismo subclínico e solicitar anticorpos\nantitireoperoxidase.","D":"Intolerância à glicose e iniciar metformina/Hipertireoidismo e investigar e iniciar medicação.","E":"Diabetes mellitus e solicitar teste de tolerância oral à glicose/Hipotireoidismo subclínico e\ninvestigar a possibilidade de tireoidite silenciosa."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-257388","number":"257388","sourceNumber":"257388","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Lei no 8.080, de 19 de setembro de 1990, dispõe sobre as condições para a\npromoção, proteção e recuperação da saúde, a organização e o funcionamento dos serviços\ncorrespondentes e dá outras providências. De acordo com essa lei, assinale a alternativa\nINCORRETA:","options":{"A":"A iniciativa privada poderá participar do Sistema Único de Saúde (SUS), em caráter\ncomplementar.","B":"São objetivos do SUS: a identificação e divulgação de fatores condicionantes e determinantes da\nsaúde; formulação de política de saúde e; assistência às pessoas.","C":"As ações e serviços de saúde, executados pelo SUS serão organizados de forma regionalizada\ne hierarquizada em níveis de complexidade crescente.","D":"A descentralização político-administrativa prevista pelo SUS enfatiza a descentralização dos\nserviços para os estados."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283935","number":"283935","sourceNumber":"283935","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Segundo o Ministério da Saúde e Organização Pan-americana de Saúde, analise as\nassertivas abaixo referentes à integração dos sistemas de saúde: I. Deve ser entendida como um\ncontínuo e não como uma situação de extremos opostos entre integração e não integração. II. É um\nmeio para melhorar o desempenho do sistema, de modo que os esforços se justificam na medida\nem que conduzam a serviços mais acessíveis, de maior qualidade e com melhor desempenho. III.\n\nNo caso de integração, especificamente, não se pode justificar serviços que tenham relação\ncusto-benefício. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas I e II.","C":"Apenas I e III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-283941","number":"283941","sourceNumber":"283941","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre princípios da Rede de Atenção à Saúde das Pessoas com Doenças Crônicas\nsegundo o Ministério da Saúde, analise as\nassertivas abaixo e assinale V, se verdadeiras, ou F, se\nfalsas. ( ) Acesso e acolhimento aos usuários com doenças crônicas em todos os pontos de\natenção. ( ) Humanização da atenção, buscando-se a efetivação de um modelo centrado no\nusuário, baseado nas suas necessidades de saúde. ( ) Respeito às diversidades étnico-raciais,\nculturais, sociais e religiosas e aos hábitos e cultura locais. ( ) Autonomia dos usuários, com\nconstituição de estratégias de apoio ao autocuidado. A ordem correta de preenchimento dos\nparênteses, de cima para baixo, é:","options":{"A":"V - V - V - F.","B":"F - F - F - V.","C":"V - F - F - V.","D":"F - V - V - F.","E":"V - V - V - V."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242985","number":"242985","sourceNumber":"242985","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a lei no 8.142 de 28 de dezembro de 1990, os recursos do Fundo\nNacional de Saúde - FNS serão alocados como: (...). Assinale a alternativa INCORRETA:","options":{"A":"despesas de custeio e de capital do Ministério da Saúde, seus órgãos e entidades, da\nadministração direta e indireta.","B":"fundo de reservas para ações de saneamento básico, serviços de saúde nos municípios,\nestados e Distrito Federal.","C":"investimentos previstos em lei orçamentária, de iniciativa do Poder Legislativo e aprovados pelo\nCongresso Nacional.","D":"investimentos previstos no Plano Quinquenal do Ministério da Saúde.","E":"cobertura das ações e serviços de saúde a serem implementados pelos municípios, estados e\nDistrito Federal."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242986","number":"242986","sourceNumber":"242986","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A lei nº 8.080, de 19 de setembro de 1990 dispõe sobre as condições para a promoção,\nproteção e recuperação da saúde, a\norganização e o funcionamento dos serviços correspondentes\ne dá outras providências. São objetivos e atribuições do Sistema Único de Saúde - SUS, EXCETO:","options":{"A":"participação no desenvolvimento infanto juvenil em saúde, educação e saneamento básico.","B":"a vigilância nutricional e a orientação alimentar.","C":"a colaboração na proteção do meio ambiente, nele compreendido e do trabalho.","D":"o incremento, em sua área de atuação, do desenvolvimento científico e tecnológico.","E":"a participação na formulação da política e na execução de ações de saneamento básico."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242987","number":"242987","sourceNumber":"242987","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Pacto pela Saúde divulgado em 2006 através da portaria no 399 foi constituído por\num conjunto de compromissos sanitários, expressos em objetivos de processos e resultados e\nderivados da análise da situação de saúde do País e das prioridades definidas pelos governos\nfederal, estaduais e municipais. Sobre as prioridades do Pacto Pela Vida e seus objetivos para\n2006 assinale a alternativa INCORRETA:","options":{"A":"atenção básica à saúde: consolidar e qualificar a estratégia da Saúde da Família como modelo\nde atenção básica à saúde como centro ordenador\ndas redes de atenção à saúde do SUS.","B":"mortalidade infantil e materna: reduzir a mortalidade materna, infantil neonatal, infantil por\ndoença diarreica e por pneumonias.","C":"câncer de colo de útero e de mama: contribuir para a redução da mortalidade por câncer de colo\ndo útero e de mama.","D":"saúde do idoso: implantar a Política Nacional de Saúde da Pessoa Idosa, buscando a atenção\nintegral.","E":"câncer de próstata: contribuir para a redução da mortalidade por câncer de próstata."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242988","number":"242988","sourceNumber":"242988","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O pacto em defesa do Sistema Único de Saúde - SUS deve se firmar através de\niniciativas que busquem a repolitização da\nsaúde, como um movimento que retoma a Reforma\nsanitária Brasileira; a promoção da cidadania como estratégia de mobilização social e a garantia de\nfinanciamento de acordo com as necessidades do Sistema. São Ações do Pacto em Defesa do\nSUS, EXCETO:","options":{"A":"estabelecimento de diálogo com a sociedade, além dos limites institucionais do SUS.","B":"ampliação e fortalecimento das relações com os movimentos sociais, em especial os que lutam\npelos direitos da saúde e cidadania.","C":"articulação e apoio à mobilização social pela promoção e desenvolvimento da cidadania, tendo a\nquestão da saúde como um direito.","D":"descentralização dos processos administrativos relativos à gestão para as Comissões\nIntergestores Bipartite.","E":"elaboração e publicação da Carta dos Direitos dos Usuários do SUS."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242989","number":"242989","sourceNumber":"242989","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Conforme a portaria nº 399 de 22 de fevereiro de 2006, um dos princípios gerais do\nfinanciamento para o Sistema Único de Saúde ? SUS é o financiamento de custeio com recursos\nfederais constituído, organizados e transferidos em blocos de recursos. O uso dos recursos federais\npara o custeio fica restrito a cada bloco, atendendo as especificidades previstas nos mesmos,\nconforme regulamentação específica. O financiamento para a Gestão do Sistema Único de Saúde\ndeverá apoiar iniciativas de fortalecimento da gestão, sendo composto pelos seguintes sub-blocos,\nEXCETO:","options":{"A":"planejamento e orçamento.","B":"campanhas de vacinação.","C":"regionalização.","D":"participação e controle social.","E":"incentivo à implementação de políticas específicas."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242990","number":"242990","sourceNumber":"242990","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a lei nº 8.080, de 19 de setembro de 1990, é competência da direção\nnacional do Sistema Único de Saúde - SUS:","options":{"A":"organização e coordenação do sistema de informação de saúde.","B":"elaboração da proposta orçamentária do Sistema Único de Saúde (SUS), de conformidade com\no plano de saúde.","C":"formular, avaliar e apoiar políticas de alimentação e nutrição.","D":"elaboração e atualização periódica do plano de saúde.","E":"definição das instâncias e mecanismos de controle, avaliação e de fiscalização das ações e\nserviços de saúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242992","number":"242992","sourceNumber":"242992","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Pela constituição federal de 1988, as ações e os serviços públicos de saúde constituem\num sistema único, que tem como uma de suas\ndiretrizes o(a):","options":{"A":"atendimento integral, com prioridade para as atividades emergenciais.","B":"participação da comunidade.","C":"atendimento integral, com prioridade para os serviços assistenciais.","D":"rede regionalizada e sem hierarquia ou precedência. governo federal.","E":"centralização da direção em uma esfera."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242996","number":"242996","sourceNumber":"242996","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"De acordo com a Constituição Federal de 1988, ao Sistema Único de Saúde:","options":{"A":"participar somente da execução das ações de saneamento básico.","B":"participar somente da formulação da política de saneamento básico.","C":"participar da formulação da política e da execução das ações de saneamento básico.","D":"participar da formulação da política e da execução e financiamento das ações de saneamento\nbásico.","E":"participar da formulação da política e do financiamento das ações de saneamento básico."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242997","number":"242997","sourceNumber":"242997","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A redução das relações de poder hierarquizadas, reconhecendo as diferentes\nespecialidades e práticas de saúde tanto dos\nprofissionais quanto da população, é uma definição\npara:","options":{"A":"equidade.","B":"universalidade.","C":"horizontalidade.","D":"transversalidade.","E":"Igualdade."},"answer":"D","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242998","number":"242998","sourceNumber":"242998","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Básica será ofertada integralmente e gratuitamente a todas as pessoas, de\nacordo com suas necessidades e demandas do\nterritório, considerando os determinantes e\ncondicionantes de saúde. São Princípios e Diretrizes do SUS e da Rede de Atenção à Saúde (RAS)\na serem operacionalizados na Atenção Básica, EXCETO:","options":{"A":"equidade.","B":"hierarquização.","C":"cuidado centrado na doença.","D":"resolutividade.","E":"integralidade."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-242999","number":"242999","sourceNumber":"242999","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"Sobre o campo de atuação do Sistema Único de Saúde (SUS) NÃO está incluído:","options":{"A":"a formulação e execução da política de sangue e seus derivados.","B":"a execução de ações de saúde do trabalhador.","C":"a fiscalização e a inspeção de alimentos, água e bebidas para animal.","D":"a formulação da política de medicamentos.","E":"ações em saúde como promoção de saúde e proteção em saúde."},"answer":"C","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-246733","number":"246733","sourceNumber":"246733","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Termo de Consentimento Livre e Esclarecido (TCLE) para pesquisa:","options":{"A":"é um resumo do Termo de Assentimento para menores de 18 anos.","B":"é obrigatório para pesquisa clínica.","C":"mantém em sigilo o nome do pesquisador responsável pelo projeto, a fim de preservar sua\nprivacidade.","D":"tem como objetivo garantir que o paciente não abandone o projeto de pesquisa antes de sua\nconclusão.","E":"é escrito em linguagem científica de modo a garantir que as denominações técnicas sejam\npreservadas no texto."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-243002","number":"243002","sourceNumber":"243002","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A participação da comunidade, como diretriz constitucional do Sistema Único de Saúde,\npermitiu inserção de diversos segmentos da sociedade na gestão desse sistema. Considerando\nessa diretriz, é CORRETO afirmar que:","options":{"A":"os Conselhos Municipais de Saúde devem submeter suas deliberações ao Conselho Estadual de\nSaúde para serem posteriormente\nhomologadas.","B":"as Conferências de Saúde acontecem a cada quatro anos, sendo comum ocorrerem\nConferências temáticas nas esferas de governo.","C":"as Conferências de Saúde Mental deixaram de ser realizadas após a Reforma Psiquiátrica\nBrasileira.","D":"a igreja não pode participar das reuniões dos Conselhos de Saúde por conta da laicidade.","E":"a sociedade civil e a sociedade política não participam das Conferências Regionais de Saúde,\nmas atuam com destaque no Conselho Nacional de\nSaúde."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-246736","number":"246736","sourceNumber":"246736","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"O Pacto pela Saúde previsto no Sistema Único de Saúde (SUS), em suas diretrizes\noperacionais, tem:","options":{"A":"três componentes: Pacto pela Vida, Pacto pela Defesa do SUS e Pacto de Gestão do SUS.","B":"como objetivo exclusivo, o tratamento de câncer de colo de útero e de mama.","C":"como objetivo único, a promoção à saúde.","D":"disposição que prioriza epidemias e não as doenças endêmicas do Brasil.","E":"dois componentes exclusivos: Pacto pela Vida e Pacto pela Defesa do SUS."},"answer":"A","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-246738","number":"246738","sourceNumber":"246738","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"A Atenção Primária à Saúde orienta-se pelos seguintes princípios, exceto:","options":{"A":"Integralidade.","B":"Acessibilidade.","C":"Vínculo.","D":"Humanização.","E":"Gratuidade."},"answer":"E","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-4-246739","number":"246739","sourceNumber":"246739","collectionBlock":"medcurso:medcurso-preventiva-pre-4","collectionLabel":"Medcurso · PRE 4","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 4","subtopic":"","stem":"?Um conjunto de ações que proporcionam o conhecimento, a detecção ou prevenção\nde qualquer mudança nos fatores determinantes e\ncondicionantes de saúde individual ou coletiva,\ncom finalidade de recomendar e adotar as medidas de prevenção e controle das doenças ou\nagravos? corresponde ao conceito de:","options":{"A":"vigilância sanitária.","B":"vigilância epidemiológica.","C":"planejamento em saúde.","D":"medicina preventiva.","E":"saúde coletiva."},"answer":"B","source":"Preventiva/PRE 4/PRE 4.txt","sourceLabel":"Medcurso · PRE 4","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 4","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
